# Controller-generation boundary. The first v0.2.5 boot intentionally retires any legacy Home
# demo. After that, presentation successors are loaded as verified assets through the resident
# controller and do not replace the Gradio demo/tunnel.
_previous_home_version = str(globals().get("__ORFMOS_HOME_LOADED_VERSION__") or "")
_previous_controller_schema = str(globals().get("__ORFMOS_HOME_SURFACE_CONTROLLER_SCHEMA__") or "")
if _previous_controller_schema != ORFMOS_HOME_SURFACE_CONTROLLER_SCHEMA:
    _stale_home_demo = globals().get("__ORFMOS_HOME_DEMO__")
    if _stale_home_demo is not None:
        try:
            close_fn = getattr(_stale_home_demo, "close", None)
            if callable(close_fn):
                close_fn()
        except Exception:
            pass
    globals()["__ORFMOS_HOME_DEMO__"] = None
    globals()["__ORFMOS_HOME_ACTIVE__"] = {}
globals()["__ORFMOS_HOME_LOADED_VERSION__"] = ORFMOS_HOME_MODULE_VERSION
globals()["__ORFMOS_HOME_SURFACE_CONTROLLER_SCHEMA__"] = ORFMOS_HOME_SURFACE_CONTROLLER_SCHEMA

# Record the exact immutable 050 generation loaded by the BIOS manifest. The mutable selector
# may later point at a successor manifest; reload compares against this observed hash.
def _home_loaded_050_entry():
    active_manifest = globals().get("manifest")
    if not isinstance(active_manifest, dict):
        return {}
    for item in active_manifest.get("modules") or []:
        try:
            if int(item.get("order", -1)) == 50:
                return dict(item)
        except Exception:
            pass
    return {}

_initial_home_entry = _home_loaded_050_entry()
if _initial_home_entry.get("sha256") and not str(globals().get("__ORFMOS_HOME_PRESENTATION_SHA__") or "").strip():
    globals()["__ORFMOS_HOME_PRESENTATION_SHA__"] = str(_initial_home_entry["sha256"])
    globals()["__ORFMOS_HOME_PRESENTATION_FILE_ID__"] = str(_initial_home_entry.get("drive_file_id") or "")
    globals()["__ORFMOS_HOME_PRESENTATION_REVISION__"] = str((globals().get("manifest") or {}).get("revision") or "")

# IMPORTANT: Home v0.2.5 keeps presentation content out of Gradio-native visible components. The previous
# gr.HTML wallpaper path triggered Gradio 6.20 custom-event introspection failures
