def _home_active_bios_url():
    active = globals().get("__ORF_BIOS_ACTIVE_PRESENTATION__") or {}
    if not isinstance(active, dict):
        return ""
    return str(active.get("active_url") or active.get("share_url") or active.get("local_url") or "").strip()


def _home_desktop_js():
    return (
        HOME_DESKTOP_JS
        .replace("__ORFMOS_GITHUB_PUBLISHER_URL__", ORFMOS_GITHUB_PUBLISHER_NOTEBOOK_URL)
        .replace("__ORFMOS_UI_LAB_DEVELOPMENT_NOTEBOOK_URL__", ORFMOS_UI_LAB_DEVELOPMENT_NOTEBOOK_URL)
        .replace("__ORFMOS_APP_FACTORY_NOTEBOOK_URL__", ORFMOS_APP_FACTORY_NOTEBOOK_URL)
        .replace("__ORFMOS_GAME_LAB_NOTEBOOK_URL__", ORFMOS_GAME_LAB_NOTEBOOK_URL)
        .replace("__ORFMOS_ACTIVE_BIOS_URL__", _home_active_bios_url())
    )




def _home_sha256(data):
    return hashlib.sha256(bytes(data)).hexdigest()



_ORFMOS_HOME_HOST_SERVICE_KEYS = (
    "_drive_read_bytes",
    "_bios_drive_service",
    "DRIVE",
    "_drive_list_children",
    "_drive_upsert_bytes",
    "_drive_ensure_folder",
    "ORFMOS_BIOS_RESTART",
    "_extract_launch_urls",
)


def _home_capture_host_service_context(app=None):
    """Recover resident host services for hot-reloaded successor route functions.

    Successor Home modules are intentionally executed in an isolated namespace.  Server-side
    route functions retained that isolated globals mapping, so shared BIOS services could vanish
    even though the resident FastAPI application still owned them.  Capture only the narrow
    provider/control handles that Home is allowed to use, preferring already-bound local values
    and then resident route endpoint globals.
    """
    context = dict(globals().get("__ORFMOS_HOST_SERVICE_CONTEXT__") or {})

    def absorb(mapping):
        if not isinstance(mapping, dict):
            return
        for key in _ORFMOS_HOME_HOST_SERVICE_KEYS:
            if key in context and context.get(key) is not None:
                continue
            value = mapping.get(key)
            if value is not None:
                context[key] = value

    absorb(globals())

    candidate_routes = []
    if app is not None:
        router = getattr(app, "router", None)
        routes = getattr(router, "routes", None) if router is not None else None
        if isinstance(routes, list):
            candidate_routes.extend(list(routes))
        direct_routes = getattr(app, "routes", None)
        if isinstance(direct_routes, list):
            candidate_routes.extend(list(direct_routes))

    for route in candidate_routes:
        endpoint = getattr(route, "endpoint", None)
        endpoint_globals = getattr(endpoint, "__globals__", None)
        absorb(endpoint_globals)

    globals()["__ORFMOS_HOST_SERVICE_CONTEXT__"] = context
    return context


def _home_host_service(name, default=None):
    value = globals().get(name)
    if value is not None:
        return value
    context = globals().get("__ORFMOS_HOST_SERVICE_CONTEXT__") or {}
    if isinstance(context, dict):
        value = context.get(name)
        if value is not None:
            return value
    return default


def _home_drive_read_bytes(file_id):
    """Read Drive bytes through the strongest currently available provider.

    Provider order:
      1. Shared verified _drive_read_bytes helper when present.
      2. BIOS thread-safe Drive-service factory.
      3. Resident DRIVE service.

    This prevents a cold-start/hot-reload namespace transition from making Drive selections
    unreadable merely because the convenience helper was not exported into the active globals.
    The file identity and SHA verification contracts remain unchanged.
    """
    file_id = str(file_id or "").strip()
    if not file_id or file_id == "root":
        raise RuntimeError("DRIVE_FILE_ID_REQUIRED")

    helper_error = None
    read_bytes = _home_host_service("_drive_read_bytes")
    if callable(read_bytes):
        try:
            try:
                import inspect
                signature = inspect.signature(read_bytes)
                positional = [
                    p for p in signature.parameters.values()
                    if p.kind in (p.POSITIONAL_ONLY, p.POSITIONAL_OR_KEYWORD)
                    and p.default is p.empty
                ]
                if len(positional) <= 1:
                    return bytes(read_bytes(file_id) or b"")
            except (TypeError, ValueError):
                pass

            drive = _home_host_service("DRIVE")
            if drive is not None:
                return bytes(read_bytes(drive, file_id) or b"")
        except Exception as exc:
            helper_error = exc

    service_error = None
    try:
        factory = _home_host_service("_bios_drive_service")
        drive = factory() if callable(factory) else _home_host_service("DRIVE")
        if drive is None:
            raise RuntimeError("DRIVE_API_CONTEXT_UNAVAILABLE")
        payload = drive.files().get_media(fileId=file_id).execute()
        if hasattr(payload, "read"):
            payload = payload.read()
        payload = bytes(payload or b"")
        if not payload:
            raise RuntimeError("DRIVE_READ_EMPTY")
        return payload
    except Exception as exc:
        service_error = exc

    detail = []
    if helper_error is not None:
        detail.append(f"HELPER={type(helper_error).__name__}:{helper_error}")
    elif not callable(read_bytes):
        detail.append("HELPER=UNAVAILABLE")
    if service_error is not None:
        detail.append(f"SERVICE={type(service_error).__name__}:{service_error}")
    raise RuntimeError("DRIVE_READ_PROVIDER_UNAVAILABLE:" + ";".join(detail))




def _home_drive_list_children(parent_id):
    reader = _home_host_service("_drive_list_children")
    if not callable(reader):
        raise RuntimeError("DRIVE_LIST_CHILDREN_HELPER_UNAVAILABLE")
    return list(reader(parent_id) or [])


def _home_drive_upsert_bytes(parent_id, name, data, mime_type="application/json"):
    writer = _home_host_service("_drive_upsert_bytes")
    if not callable(writer):
        raise RuntimeError("DRIVE_UPSERT_HELPER_UNAVAILABLE")
    return writer(parent_id, name, bytes(data), mime_type)


def _home_drive_ensure_folder(parent_id, name):
    ensure = _home_host_service("_drive_ensure_folder")
    if not callable(ensure):
        raise RuntimeError("DRIVE_ENSURE_FOLDER_HELPER_UNAVAILABLE")
    return ensure(parent_id, name)


def _home_safe_device_component(value):
    value = re.sub(r"[^A-Za-z0-9._-]+", "_", str(value or "UNRESOLVED"))
    return value[:120] or "UNRESOLVED"


def _home_default_device_state(device_id=None, client_instance_id=None):
    return {
        "schema": ORFMOS_HOME_DEVICE_STATE_SCHEMA,
        "state_version": 2,
        "device_id": str(device_id or "") or None,
        "client_instance_id": str(client_instance_id or "") or None,
        "layout": {
            "portrait": {"order": ["developer_tools", "game_lab_library", "files"], "hidden": []},
            "landscape": {"order": ["developer_tools", "game_lab_library", "files"], "hidden": []},
        },
        "theme": {"pack_id": "ORFMOS_DEFAULT"},
        "presentation": {"time_display": False, "date_display": False},
        "modified_utc": None,
    }


def _home_folder_modified_key(folder):
    return str((folder or {}).get("modifiedTime") or (folder or {}).get("createdTime") or "")


def _home_observation_matches_device(folder_id, device_id):
    """Best-effort migration resolver for the existing ORF_CLIENT_* folders."""
    device_id = str(device_id or "").strip()
    if not device_id:
        return False, "NO_DEVICE_ID"
    try:
        children = _home_drive_list_children(folder_id)
    except Exception:
        return False, "CHILDREN_UNAVAILABLE"

    bindings = [c for c in children if str(c.get("name") or "") == ORFMOS_HOME_DEVICE_BINDING_FILE_NAME]
    for item in bindings[:1]:
        try:
            payload = json.loads(_home_drive_read_bytes(item["id"]).decode("utf-8"))
            if str(payload.get("device_id") or "").strip() == device_id:
                return True, "BINDING"
        except Exception:
            pass

    observations = [
        c for c in children
        if str(c.get("name") or "").startswith("ORF_DEVICE_OBS_")
        and str(c.get("name") or "").endswith(".json")
    ]
    observations.sort(key=lambda item: str(item.get("modifiedTime") or ""), reverse=True)
    for item in observations[:3]:
        try:
            payload = json.loads(_home_drive_read_bytes(item["id"]).decode("utf-8"))
            observed_id = str(payload.get("device_id") or ((payload.get("session") or {}).get("device_id")) or "").strip()
            if observed_id == device_id:
                return True, "OBSERVATION"
        except Exception:
            continue
    return False, "NO_MATCH"


def _home_resolve_device_folder(client_instance_id, device_id=None, create=False):
    client_instance_id = str(client_instance_id or "").strip()
    device_id = str(device_id or "").strip()
    folder_name = "ORF_CLIENT_" + _home_safe_device_component(client_instance_id or "UNRESOLVED")
    root_children = _home_drive_list_children(ORFMOS_DEVICE_OBSERVATIONS_ROOT_FOLDER_ID)
    folders = [
        item for item in root_children
        if item.get("mimeType") == "application/vnd.google-apps.folder"
        and str(item.get("name") or "").startswith("ORF_CLIENT_")
    ]
    exact = [item for item in folders if str(item.get("name") or "") == folder_name]
    if len(exact) > 1:
        raise RuntimeError(f"AMBIGUOUS_CLIENT_FOLDER:{folder_name}")

    matches = []
    if device_id:
        for folder in folders:
            matched, evidence = _home_observation_matches_device(folder.get("id"), device_id)
            if matched:
                candidate = dict(folder)
                candidate["device_match_evidence"] = evidence
                matches.append(candidate)

    if matches:
        matches.sort(key=_home_folder_modified_key, reverse=True)
        selected = matches[0]
        return {
            "folder_id": selected.get("id"),
            "folder_name": selected.get("name"),
            "resolution_state": "KNOWN" if len(matches) == 1 else "CONFLICTING",
            "resolution_basis": "DEVICE_ID_" + str(selected.get("device_match_evidence") or "MATCH"),
            "candidate_folder_ids": [m.get("id") for m in matches],
        }

    if exact:
        return {
            "folder_id": exact[0].get("id"),
            "folder_name": exact[0].get("name"),
            "resolution_state": "OBSERVED",
            "resolution_basis": "CLIENT_INSTANCE_ID",
            "candidate_folder_ids": [exact[0].get("id")],
        }

    if create and client_instance_id:
        folder_id = _home_drive_ensure_folder(ORFMOS_DEVICE_OBSERVATIONS_ROOT_FOLDER_ID, folder_name)
        return {
            "folder_id": folder_id,
            "folder_name": folder_name,
            "resolution_state": "SPECIFIED",
            "resolution_basis": "CREATED_CURRENT_CLIENT_FOLDER",
            "candidate_folder_ids": [folder_id],
        }

    return {
        "folder_id": None,
        "folder_name": folder_name if client_instance_id else None,
        "resolution_state": "UNKNOWN",
        "resolution_basis": "NO_EXISTING_DEVICE_FOLDER",
        "candidate_folder_ids": [],
    }


def _home_read_device_state(client_instance_id, device_id=None):
    resolved = _home_resolve_device_folder(client_instance_id, device_id=device_id, create=False)
    state = _home_default_device_state(device_id=device_id, client_instance_id=client_instance_id)
    status = "DEFAULT"
    state_file_id = None
    if resolved.get("folder_id"):
        children = _home_drive_list_children(resolved["folder_id"])
        matches = [c for c in children if str(c.get("name") or "") == ORFMOS_HOME_DEVICE_STATE_FILE_NAME]
        if len(matches) > 1:
            raise RuntimeError("AMBIGUOUS_HOME_DEVICE_STATE_FILE")
        if matches:
            raw = _home_drive_read_bytes(matches[0]["id"])
            loaded = json.loads(raw.decode("utf-8"))
            if loaded.get("schema") != ORFMOS_HOME_DEVICE_STATE_SCHEMA:
                raise RuntimeError(f"DEVICE_STATE_SCHEMA_UNEXPECTED:{loaded.get('schema')!r}")
            state = loaded
            if not isinstance(state.get("presentation"), dict):
                state["presentation"] = {}
            state["presentation"].setdefault("time_display", False)
            state["presentation"].setdefault("date_display", False)
            state["state_version"] = max(int(state.get("state_version") or 1), 3)
            state_file_id = matches[0]["id"]
            status = "LOADED"
    return {
        "schema": ORFMOS_HOME_DEVICE_CONTINUITY_SCHEMA,
        "status": status,
        "resolution_state": resolved.get("resolution_state"),
        "resolution_basis": resolved.get("resolution_basis"),
        "candidate_folder_ids": resolved.get("candidate_folder_ids") or [],
        "client_instance_id": str(client_instance_id or "") or None,
        "device_id": str(device_id or "") or None,
        "folder_id": resolved.get("folder_id"),
        "folder_name": resolved.get("folder_name"),
        "state_file_id": state_file_id,
        "state": state,
    }


def _home_write_device_state(client_instance_id, device_id, state):
    if not isinstance(state, dict) or state.get("schema") != ORFMOS_HOME_DEVICE_STATE_SCHEMA:
        raise RuntimeError("DEVICE_STATE_SCHEMA_INVALID")
    resolved = _home_resolve_device_folder(client_instance_id, device_id=device_id, create=True)
    folder_id = resolved.get("folder_id")
    if not folder_id:
        raise RuntimeError("DEVICE_FOLDER_UNRESOLVED")

    payload = json.loads(json.dumps(state))
    payload["schema"] = ORFMOS_HOME_DEVICE_STATE_SCHEMA
    payload["device_id"] = str(device_id or payload.get("device_id") or "") or None
    payload["client_instance_id"] = str(client_instance_id or payload.get("client_instance_id") or "") or None
    payload["modified_utc"] = datetime.now(timezone.utc).isoformat()
    data = (json.dumps(payload, indent=2, sort_keys=True, ensure_ascii=False) + "\n").encode("utf-8")
    result = _home_drive_upsert_bytes(folder_id, ORFMOS_HOME_DEVICE_STATE_FILE_NAME, data, "application/json")

    if payload.get("device_id"):
        binding = {
            "schema": "ORFMOS_DEVICE_FOLDER_BINDING_V0_1",
            "device_id": payload.get("device_id"),
            "client_instance_id": payload.get("client_instance_id"),
            "bound_utc": payload.get("modified_utc"),
            "authority": "DEVICE_REPORTED_ID_PLUS_EXISTING_ORF_CLIENT_FOLDER",
        }
        _home_drive_upsert_bytes(
            folder_id,
            ORFMOS_HOME_DEVICE_BINDING_FILE_NAME,
            (json.dumps(binding, indent=2, sort_keys=True) + "\n").encode("utf-8"),
            "application/json",
        )
    return {
        "schema": ORFMOS_HOME_DEVICE_CONTINUITY_SCHEMA,
        "status": "SAVED",
        "resolution_state": resolved.get("resolution_state"),
        "resolution_basis": resolved.get("resolution_basis"),
        "client_instance_id": payload.get("client_instance_id"),
        "device_id": payload.get("device_id"),
        "folder_id": folder_id,
        "folder_name": resolved.get("folder_name"),
        "state_file_id": result.get("id"),
        "state": payload,
    }


def _home_device_state_http(client_instance_id: str = "", device_id: str = ""):
    try:
        if not str(client_instance_id or "").strip():
            raise RuntimeError("CLIENT_INSTANCE_ID_REQUIRED")
        return _home_read_device_state(client_instance_id, device_id=device_id)
    except Exception as exc:
        return {
            "schema": ORFMOS_HOME_DEVICE_CONTINUITY_SCHEMA,
            "status": "FAILED",
            "resolution_state": "UNKNOWN",
            "client_instance_id": str(client_instance_id or "") or None,
            "device_id": str(device_id or "") or None,
            "message": f"{type(exc).__name__}: {exc}",
        }


async def _home_device_state_write_http(request: Request):
    try:
        body = await request.json()
        if not isinstance(body, dict):
            raise RuntimeError("JSON_BODY_REQUIRED")
        client_instance_id = str(body.get("client_instance_id") or "").strip()
        device_id = str(body.get("device_id") or "").strip()
        state = body.get("state")
        if not client_instance_id:
            raise RuntimeError("CLIENT_INSTANCE_ID_REQUIRED")
        return _home_write_device_state(client_instance_id, device_id, state)
    except Exception as exc:
        return {
            "schema": ORFMOS_HOME_DEVICE_CONTINUITY_SCHEMA,
            "status": "FAILED",
            "resolution_state": "UNKNOWN",
            "message": f"{type(exc).__name__}: {exc}",
        }


def _home_restart_http():
    restarter = globals().get("ORFMOS_BIOS_RESTART")
    if not callable(restarter):
        return {
            "schema": ORFMOS_HOME_RESTART_HTTP_SCHEMA,
            "status": "UNAVAILABLE",
            "message": "ORFMOS_BIOS_RESTART callable is not present; boot with Development Control v1.9+.",
        }
    result = restarter(reason="SETTINGS_RESTART")
    if isinstance(result, dict):
        return result
    return {"schema": ORFMOS_HOME_RESTART_HTTP_SCHEMA, "status": "FAILED", "message": "INVALID_RESTART_RESULT"}


def _home_restart_state_http(request_id: str = ""):
    state = dict(globals().get("__ORF_BIOS_RESTART_STATE__") or {})
    if not state:
        return {"schema": "ORFMOS_BIOS_RESTART_STATE_V0_1", "status": "IDLE", "request_id": request_id or None}
    if request_id and str(state.get("request_id") or "") != str(request_id):
        return {
            "schema": "ORFMOS_BIOS_RESTART_STATE_V0_1",
            "status": "UNKNOWN_REQUEST",
            "request_id": request_id,
            "active_request_id": state.get("request_id"),
        }
    return state


def _home_version_key(value):
    numbers = re.findall(r"\d+", str(value or ""))
    return tuple(int(x) for x in numbers[:4]) if numbers else (0,)


def _home_resident_source_candidate():
    """Resolve exact staged bytes for the Home generation currently resident in this kernel."""
    version = str(globals().get("ORFMOS_HOME_MODULE_VERSION") or "")
    generation = str(globals().get("ORFMOS_HOME_PRESENTATION_GENERATION") or "")
    js_builder = globals().get("_home_desktop_js")
    if not callable(js_builder):
        return None

    filename = str(getattr(getattr(js_builder, "__code__", None), "co_filename", "") or "")
    candidates = []
    if filename and not filename.startswith("<"):
        candidates.extend((Path(filename), Path("/content") / os.path.basename(filename)))
    expected_name = "050_ORFMOS_HOME_DESKTOP_V0_2_84_R90_3_CHATGPT_CONNECTOR_LANDING_SURFACE.py"
    candidates.extend((Path("/content") / expected_name, Path(expected_name)))

    path = next((p for p in candidates if p.is_file()), None)
    if path is None:
        return None
    source_raw = path.read_bytes()
    if f'ORFMOS_HOME_MODULE_VERSION = "{version}"' not in source_raw.decode("utf-8", errors="replace"):
        return None

    css = str(globals().get("HOME_CSS") or "")
    js = str(js_builder() or "")
    if not css or not js:
        return None
    return {
        "path": str(path),
        "file_name": path.name,
        "bytes": len(source_raw),
        "sha256": _home_sha256(source_raw),
        "version": version,
        "generation": generation,
        "revision": generation,
        "css": css,
        "js": js,
    }


def _home_manifest_reload_payload():
    """CURRENT selector is durable development authority; SHA identity prevents silent downgrade."""
    try:
        selector_raw = _home_drive_read_bytes(ORFMOS_HOME_DEVELOPMENT_SELECTOR_ID)
        selector = json.loads(selector_raw.decode("utf-8"))
        validated = _home_runtime_recovery_validate_selector(selector)

        home = dict(validated.get("home") or {})
        manifest = dict(validated.get("manifest") or {})
        target_file_id = str(home.get("drive_file_id") or "")
        expected_home_sha = str(home.get("sha256") or "")
        expected_bytes = int(home.get("bytes") or 0)
        target_filename = str(home.get("file_name") or f"050_HOME_{expected_home_sha[:12]}.py")
        selector_version = str(home.get("version") or "")
        target_revision = str(home.get("revision") or home.get("generation") or "")
        manifest_id = str(manifest.get("drive_file_id") or "")
        observed_manifest_sha = str(manifest.get("sha256") or "")

        selector_source_raw = _home_drive_read_bytes(target_file_id)
        if expected_bytes and len(selector_source_raw) != expected_bytes:
            raise RuntimeError("HOME_BYTE_COUNT_MISMATCH")
        observed_home_sha = _home_sha256(selector_source_raw)
        if observed_home_sha != expected_home_sha:
            raise RuntimeError("HOME_SHA256_MISMATCH")

        host_service_context = _home_capture_host_service_context(globals().get("__ORFMOS_HOME_FASTAPI_APP__"))
        successor_globals = {
            "__builtins__": __builtins__,
            "__ORF_BIOS_ACTIVE_PRESENTATION__": globals().get("__ORF_BIOS_ACTIVE_PRESENTATION__"),
            "__ORFMOS_HOST_SERVICE_CONTEXT__": dict(host_service_context),
        }
        for name, value in host_service_context.items():
            successor_globals.setdefault(name, value)

        exec(
            compile(selector_source_raw.decode("utf-8"), target_filename, "exec"),
            successor_globals,
            successor_globals,
        )

        selector_js_builder = successor_globals.get("_home_desktop_js")
        if not callable(selector_js_builder):
            raise RuntimeError("SUCCESSOR_HOME_JS_BUILDER_MISSING")
        selector_css = str(successor_globals.get("HOME_CSS") or "")
        selector_js = str(selector_js_builder() or "")
        if not selector_css or not selector_js:
            raise RuntimeError("SUCCESSOR_PRESENTATION_ASSETS_EMPTY")

        resident = _home_resident_source_candidate()
        current_sha = str(globals().get("__ORFMOS_HOME_PRESENTATION_SHA__") or "").lower()
        current_version = str(globals().get("__ORFMOS_HOME_PRESENTATION_VERSION__") or "")

        # Resident development generation ahead of durable selector: serve resident presentation.
        if resident and _home_version_key(resident["version"]) > _home_version_key(selector_version):
            if current_sha != resident["sha256"]:
                globals()["__ORFMOS_HOME_PRESENTATION_SHA__"] = resident["sha256"]
                globals()["__ORFMOS_HOME_PRESENTATION_FILE_ID__"] = "runtime://" + resident["path"]
                globals()["__ORFMOS_HOME_PRESENTATION_REVISION__"] = resident["revision"]
                globals()["__ORFMOS_HOME_PRESENTATION_VERSION__"] = resident["version"]
                globals()["__ORFMOS_HOME_RESIDENT_PRESENTATION_CANDIDATE__"] = {
                    k: v for k, v in resident.items() if k not in {"css", "js"}
                }
                return json.dumps({
                    "schema": "ORFMOS_HOME_PRESENTATION_RELOAD_RESULT_V0_1",
                    "status": "UPDATED",
                    "revision": resident["revision"],
                    "version": resident["version"],
                    "home_file_id": "runtime://" + resident["path"],
                    "home_sha256": resident["sha256"],
                    "css": resident["css"],
                    "js": resident["js"],
                    "source": "RESIDENT_VERIFIED_AHEAD_OF_SELECTOR",
                    "selector_target_version": selector_version,
                    "selector_target_sha256": expected_home_sha,
                    "selector_mutated": False,
                    "anti_downgrade": "ACTIVE",
                    "message": f"HOME PRESENTATION HOT-RELOADED → {resident['version']} · SELECTOR REMAINS {selector_version}",
                })

            globals()["__ORFMOS_HOME_PRESENTATION_VERSION__"] = resident["version"]
            globals()["__ORFMOS_HOME_PRESENTATION_REVISION__"] = resident["revision"]
            return json.dumps({
                "schema": "ORFMOS_HOME_PRESENTATION_RELOAD_RESULT_V0_1",
                "status": "UPDATED",
                "revision": resident["revision"],
                "version": resident["version"],
                "home_file_id": "runtime://" + resident["path"],
                "home_sha256": resident["sha256"],
                "css": resident["css"],
                "js": resident["js"],
                "source": "RESIDENT_VERIFIED_CLIENT_SYNC",
                "selector_target_version": selector_version,
                "selector_target_sha256": expected_home_sha,
                "selector_mutated": False,
                "anti_downgrade": "ACTIVE",
                "message": f"CLIENT SYNCHRONIZED → RESIDENT HOME {resident['version']}",
            })

        # If browser presentation is already known newer, selector cannot implicitly roll it back.
        if current_version and _home_version_key(current_version) > _home_version_key(selector_version):
            return json.dumps({
                "schema": "ORFMOS_HOME_PRESENTATION_RELOAD_RESULT_V0_1",
                "status": "NO_CHANGE",
                "revision": str(globals().get("__ORFMOS_HOME_PRESENTATION_REVISION__") or ""),
                "version": current_version,
                "home_sha256": current_sha,
                "source": "ACTIVE_PRESENTATION_ANTI_DOWNGRADE_GUARD",
                "selector_target_version": selector_version,
                "selector_target_sha256": expected_home_sha,
                "anti_downgrade": "ACTIVE",
                "message": f"SELECTOR DOWNGRADE BLOCKED · ACTIVE {current_version} > SELECTOR {selector_version}",
            })

        if current_sha == expected_home_sha:
            globals()["__ORFMOS_HOME_PRESENTATION_VERSION__"] = current_version or selector_version
            return json.dumps({
                "schema": "ORFMOS_HOME_PRESENTATION_RELOAD_RESULT_V0_1",
                "status": "UPDATED",
                "revision": target_revision,
                "version": selector_version,
                "manifest_id": manifest_id,
                "manifest_sha256": observed_manifest_sha,
                "home_file_id": target_file_id,
                "home_sha256": expected_home_sha,
                "css": selector_css,
                "js": selector_js,
                "source": "SELECTOR_VERIFIED_CLIENT_SYNC",
                "anti_downgrade": "CLEAR",
                "message": f"CLIENT SYNCHRONIZED → HOME {selector_version or target_revision}",
            })

        # Selector is same/newer: normal durable path.
        active_app = globals().get("__ORFMOS_HOME_FASTAPI_APP__")
        successor_vm_routes = successor_globals.get("_home_install_vm_lab_routes")
        if active_app is not None and callable(successor_vm_routes):
            successor_vm_routes(active_app)
        successor_installer_routes = successor_globals.get("_home_install_installer_routes")
        if active_app is not None and callable(successor_installer_routes):
            successor_installer_routes(active_app)

        globals()["__ORFMOS_HOME_PRESENTATION_SHA__"] = expected_home_sha
        globals()["__ORFMOS_HOME_PRESENTATION_FILE_ID__"] = target_file_id
        globals()["__ORFMOS_HOME_PRESENTATION_REVISION__"] = target_revision
        globals()["__ORFMOS_HOME_PRESENTATION_VERSION__"] = selector_version

        return json.dumps({
            "schema": "ORFMOS_HOME_PRESENTATION_RELOAD_RESULT_V0_1",
            "status": "UPDATED",
            "revision": target_revision,
            "version": selector_version,
            "manifest_id": manifest_id,
            "manifest_sha256": observed_manifest_sha,
            "home_file_id": target_file_id,
            "home_sha256": observed_home_sha,
            "css": selector_css,
            "js": selector_js,
            "source": "SELECTOR_VERIFIED_DURABLE_SUCCESSOR",
            "anti_downgrade": "CLEAR",
            "message": f"HOME PRESENTATION HOT-RELOADED → {selector_version or target_revision}",
        })
    except Exception as exc:
        return json.dumps({
            "schema": "ORFMOS_HOME_PRESENTATION_RELOAD_RESULT_V0_1",
            "status": "FAILED",
            "message": f"{type(exc).__name__}: {exc}",
        })


ORFMOS_FILE_NAVIGATOR_SCHEMA = "ORFMOS_FILE_NAVIGATOR_RESULT_V0_1"
ORFMOS_NORMALIZED_FILE_OBJECT_SCHEMA = "ORFMOS_NORMALIZED_FILE_OBJECT_V0_1"
ORFMOS_APK_PROFILE_SCHEMA = "ORFMOS_APK_CAPABILITY_PROFILE_V0_1"
ORFMOS_APK_PROFILE_MAX_BYTES = 128 * 1024 * 1024
ORFMOS_DRIVE_FOLDER_MIME = "application/vnd.google-apps.folder"
ORFMOS_RUNTIME_ROOT = "/content"
ORFMOS_GITHUB_REPOSITORY = "hadrex83/ORFMOS"
ORFMOS_GITHUB_REF = "main"
ORFMOS_GITHUB_ROOT_URI = "github://hadrex83/ORFMOS@main/"


def _home_github_uri_to_path(uri):
    value = str(uri or ORFMOS_GITHUB_ROOT_URI).strip()
    if not value.startswith(ORFMOS_GITHUB_ROOT_URI):
        raise RuntimeError("GITHUB_URI_OUTSIDE_BOUND_AUTHORITY")
    tail = urllib.parse.unquote(value[len(ORFMOS_GITHUB_ROOT_URI):]).strip("/")
    if not tail:
        return ""
    parts = [part for part in tail.split("/") if part not in ("", ".")]
    if any(part == ".." for part in parts):
        raise RuntimeError("GITHUB_PATH_TRAVERSAL_REJECTED")
    normalized = posixpath.normpath("/".join(parts)).strip("/")
    if normalized in ("", "."):
        return ""
    if normalized.startswith("../") or normalized == "..":
        raise RuntimeError("GITHUB_PATH_TRAVERSAL_REJECTED")
    return normalized


def _home_github_path_to_uri(path):
    clean = _home_github_uri_to_path(
        ORFMOS_GITHUB_ROOT_URI + urllib.parse.quote(str(path or "").strip("/"), safe="/-._~")
    )
    if not clean:
        return ORFMOS_GITHUB_ROOT_URI
    return ORFMOS_GITHUB_ROOT_URI + urllib.parse.quote(clean, safe="/-._~")


def _home_github_api_json(path=""):
    clean = _home_github_uri_to_path(_home_github_path_to_uri(path))
    repo = urllib.parse.quote(ORFMOS_GITHUB_REPOSITORY, safe="/")
    encoded_path = urllib.parse.quote(clean, safe="/")
    url = f"https://api.github.com/repos/{repo}/contents"
    if encoded_path:
        url += "/" + encoded_path
    url += "?" + urllib.parse.urlencode({"ref": ORFMOS_GITHUB_REF})
    headers = {
        "Accept": "application/vnd.github+json",
        "User-Agent": "ORFMOS-File-Navigator/0.3",
        "X-GitHub-Api-Version": "2022-11-28",
    }
    token = str(os.environ.get("GITHUB_TOKEN") or os.environ.get("GH_TOKEN") or "").strip()
    if token:
        headers["Authorization"] = "Bearer " + token
    request = urllib.request.Request(url, headers=headers, method="GET")
    try:
        with urllib.request.urlopen(request, timeout=15.0) as response:
            payload = response.read()
    except urllib.error.HTTPError as exc:
        detail = ""
        try:
            detail = exc.read(1024).decode("utf-8", errors="ignore")
        except Exception:
            pass
        raise RuntimeError(f"GITHUB_API_HTTP_{exc.code}:{detail[:240]}") from exc
    except urllib.error.URLError as exc:
        raise RuntimeError(f"GITHUB_API_UNREACHABLE:{exc}") from exc
    try:
        return json.loads(payload.decode("utf-8"))
    except Exception as exc:
        raise RuntimeError("GITHUB_API_JSON_INVALID") from exc


def _home_files_github_list(uri, query=""):
    current_path = _home_github_uri_to_path(uri or ORFMOS_GITHUB_ROOT_URI)
    payload = _home_github_api_json(current_path)
    if not isinstance(payload, list):
        raise RuntimeError("GITHUB_TARGET_NOT_FOLDER")
    q = str(query or "").strip().casefold()
    rows = []
    for item in payload:
        if not isinstance(item, dict):
            continue
        name = str(item.get("name") or "")
        if q and q not in name.casefold():
            continue
        rows.append(item)
    rows.sort(key=lambda x: (0 if str(x.get("type") or "") == "dir" else 1, str(x.get("name") or "").casefold()))
    entries = []
    for item in rows:
        item_type = str(item.get("type") or "file")
        is_folder = item_type == "dir"
        item_path = str(item.get("path") or item.get("name") or "")
        mime = "inode/directory" if is_folder else (mimetypes.guess_type(str(item.get("name") or ""))[0] or "application/octet-stream")
        entries.append(_home_normalized_file_object(
            provider="GITHUB",
            authority=f"{ORFMOS_GITHUB_REPOSITORY}@{ORFMOS_GITHUB_REF}",
            uri=_home_github_path_to_uri(item_path),
            identity=item.get("sha") or item_path,
            name=item.get("name"),
            kind="FOLDER" if is_folder else "FILE",
            mime_type=mime,
            size=None if is_folder else item.get("size"),
            modified_utc=None,
            capabilities=["BROWSE"] if is_folder else ["READ", "SELECT", "INSPECT"],
            metadata={
                "repository": ORFMOS_GITHUB_REPOSITORY,
                "ref": ORFMOS_GITHUB_REF,
                "path": item_path,
                "sha": item.get("sha"),
                "html_url": item.get("html_url"),
                "download_url": item.get("download_url"),
                "git_url": item.get("git_url"),
                "github_type": item_type,
            },
        ))
    parent_uri = None
    if current_path:
        parent_path = posixpath.dirname(current_path)
        parent_uri = _home_github_path_to_uri(parent_path)
    return {
        "schema": ORFMOS_FILE_NAVIGATOR_SCHEMA,
        "status": "READY",
        "provider": "GITHUB",
        "current_uri": _home_github_path_to_uri(current_path),
        "current_name": f"{ORFMOS_GITHUB_REPOSITORY} @ {ORFMOS_GITHUB_REF}" if not current_path else posixpath.basename(current_path),
        "parent_uri": parent_uri,
        "entries": entries,
        "query": str(query or "") or None,
        "message": "GITHUB_FOLDER_READY",
    }


def _home_file_reader_handler(name, mime_type=""):
    lower = str(name or "").lower()
    ext = lower.rsplit(".", 1)[-1] if "." in lower else ""
    for item in ORFMOS_FILE_READER_HANDLERS:
        if ext in tuple(item.get("extensions") or ()):
            return str(item.get("handler") or "GENERIC_FILE_INSPECTOR")
    if str(mime_type or "") == "application/vnd.android.package-archive":
        return "ANDROID_PACKAGE_INSPECT_INSTALL_LAUNCH"
    return "GENERIC_FILE_INSPECTOR"


def _home_normalized_file_object(provider, uri, name, kind, mime_type=None, size=None,
                                 modified_utc=None, identity=None, authority=None,
                                 resolution_state="OBSERVED", capabilities=None, metadata=None):
    return {
        "schema": ORFMOS_NORMALIZED_FILE_OBJECT_SCHEMA,
        "provider": str(provider or "UNKNOWN"),
        "authority": str(authority or provider or "UNKNOWN"),
        "kind": str(kind or "FILE").upper(),
        "uri": str(uri) if uri is not None else None,
        "identity": str(identity) if identity is not None else None,
        "name": str(name or "UNNAMED"),
        "mime_type": str(mime_type or "application/octet-stream"),
        "bytes": int(size) if str(size or "").isdigit() else None,
        "modified_utc": str(modified_utc) if modified_utc else None,
        "reader_handler": None if str(kind or "").upper() == "FOLDER" else _home_file_reader_handler(name, mime_type),
        "resolution_state": str(resolution_state or "OBSERVED"),
        "capabilities": list(capabilities or []),
        "metadata": dict(metadata or {}),
    }


def _home_drive_service_for_files():
    factory = _home_host_service("_bios_drive_service")
    if callable(factory):
        return factory()
    drive = _home_host_service("DRIVE")
    if drive is not None:
        return drive
    raise RuntimeError("DRIVE_API_CONTEXT_UNAVAILABLE")


def _home_drive_folder_meta(folder_id):
    if str(folder_id) == "root":
        return {"id": "root", "name": "My Drive", "parents": []}
    return _home_drive_service_for_files().files().get(
        fileId=str(folder_id),
        fields="id,name,mimeType,modifiedTime,parents,size",
    ).execute()


def _home_drive_uri_to_id(uri):
    value = str(uri or "drive://").strip()
    if not value.startswith("drive://"):
        raise RuntimeError("DRIVE_URI_REQUIRED")
    tail = value[len("drive://"):].strip().strip("/")
    return tail or "root"


def _home_files_drive_list(uri, query=""):
    folder_id = _home_drive_uri_to_id(uri)
    meta = _home_drive_folder_meta(folder_id)
    if folder_id != "root" and meta.get("mimeType") != ORFMOS_DRIVE_FOLDER_MIME:
        raise RuntimeError("DRIVE_TARGET_NOT_FOLDER")
    children = _home_drive_list_children(folder_id)
    q = str(query or "").strip().casefold()
    if q:
        children = [c for c in children if q in str(c.get("name") or "").casefold()]
    children.sort(key=lambda x: (0 if x.get("mimeType") == ORFMOS_DRIVE_FOLDER_MIME else 1, str(x.get("name") or "").casefold()))
    entries = []
    for item in children:
        is_folder = item.get("mimeType") == ORFMOS_DRIVE_FOLDER_MIME
        entries.append(_home_normalized_file_object(
            provider="GOOGLE_DRIVE",
            authority="GOOGLE_DRIVE_API",
            uri="drive://" + str(item.get("id") or ""),
            identity=item.get("id"),
            name=item.get("name"),
            kind="FOLDER" if is_folder else "FILE",
            mime_type=item.get("mimeType"),
            size=item.get("size"),
            modified_utc=item.get("modifiedTime"),
            capabilities=["BROWSE"] if is_folder else ["READ", "SELECT", "INSPECT"],
            metadata={"md5_checksum": item.get("md5Checksum"), "version": item.get("version")},
        ))
    parents = list(meta.get("parents") or [])
    parent_uri = None if folder_id == "root" or not parents else "drive://" + str(parents[0])
    return {
        "schema": ORFMOS_FILE_NAVIGATOR_SCHEMA,
        "status": "READY",
        "provider": "DRIVE",
        "current_uri": "drive://" if folder_id == "root" else "drive://" + folder_id,
        "current_name": str(meta.get("name") or ("My Drive" if folder_id == "root" else folder_id)),
        "parent_uri": parent_uri,
        "entries": entries,
        "query": str(query or "") or None,
        "message": "DRIVE_FOLDER_READY",
    }


def _home_runtime_uri_to_path(uri):
    value = str(uri or "runtime:///content/").strip()
    prefix = "runtime://"
    if not value.startswith(prefix):
        raise RuntimeError("RUNTIME_URI_REQUIRED")
    path = value[len(prefix):]
    if not path.startswith("/"):
        path = "/" + path
    root = os.path.realpath(ORFMOS_RUNTIME_ROOT)
    target = os.path.realpath(path)
    if target != root and not target.startswith(root + os.sep):
        raise RuntimeError("RUNTIME_PATH_OUTSIDE_CONTENT")
    return target


def _home_runtime_path_to_uri(path):
    value = os.path.realpath(path)
    return "runtime://" + value + ("/" if os.path.isdir(value) and not value.endswith("/") else "")


def _home_files_runtime_list(uri, query=""):
    target = _home_runtime_uri_to_path(uri)
    root = os.path.realpath(ORFMOS_RUNTIME_ROOT)
    if not os.path.exists(target):
        raise RuntimeError("RUNTIME_PATH_NOT_FOUND")
    if not os.path.isdir(target):
        raise RuntimeError("RUNTIME_TARGET_NOT_FOLDER")
    q = str(query or "").strip().casefold()
    entries = []
    try:
        rows = list(os.scandir(target))[:400]
    except PermissionError as exc:
        raise RuntimeError("RUNTIME_FOLDER_PERMISSION_DENIED") from exc
    rows.sort(key=lambda e: (0 if e.is_dir(follow_symlinks=False) else 1, e.name.casefold()))
    for entry in rows:
        if q and q not in entry.name.casefold():
            continue
        try:
            st = entry.stat(follow_symlinks=False)
            size = None if entry.is_dir(follow_symlinks=False) else int(st.st_size)
            modified = datetime.fromtimestamp(st.st_mtime, tz=timezone.utc).isoformat()
        except Exception:
            size = None
            modified = None
        is_folder = entry.is_dir(follow_symlinks=False)
        mime = "inode/directory" if is_folder else (mimetypes.guess_type(entry.name)[0] or "application/octet-stream")
        entries.append(_home_normalized_file_object(
            provider="COLAB_RUNTIME",
            authority="LOCAL_RUNTIME_FILESYSTEM",
            uri=_home_runtime_path_to_uri(entry.path),
            identity=os.path.relpath(entry.path, root),
            name=entry.name,
            kind="FOLDER" if is_folder else "FILE",
            mime_type=mime,
            size=size,
            modified_utc=modified,
            capabilities=["BROWSE"] if is_folder else ["READ", "SELECT", "INSPECT"],
        ))
    parent_uri = None
    if target != root:
        parent = os.path.dirname(target)
        if parent == root or parent.startswith(root + os.sep):
            parent_uri = _home_runtime_path_to_uri(parent)
    return {
        "schema": ORFMOS_FILE_NAVIGATOR_SCHEMA,
        "status": "READY",
        "provider": "RUNTIME",
        "current_uri": _home_runtime_path_to_uri(target),
        "current_name": "/content" if target == root else os.path.basename(target),
        "parent_uri": parent_uri,
        "entries": entries,
        "query": str(query or "") or None,
        "message": "RUNTIME_FOLDER_READY",
    }


def _home_apk_fetch_github_bytes(uri):
    path = _home_github_uri_to_path(uri)
    payload = _home_github_api_json(path)
    if not isinstance(payload, dict) or str(payload.get("type") or "") != "file":
        raise RuntimeError("GITHUB_APK_TARGET_NOT_FILE")
    download_url = str(payload.get("download_url") or "").strip()
    if not download_url:
        raise RuntimeError("GITHUB_APK_DOWNLOAD_URL_UNAVAILABLE")
    request = urllib.request.Request(
        download_url,
        headers={"User-Agent": "ORFMOS-APK-Profiler/0.1"},
        method="GET",
    )
    with urllib.request.urlopen(request, timeout=30.0) as response:
        data = response.read(ORFMOS_APK_PROFILE_MAX_BYTES + 1)
    if len(data) > ORFMOS_APK_PROFILE_MAX_BYTES:
        raise RuntimeError("APK_PROFILE_SIZE_LIMIT_EXCEEDED")
    return data


def _home_read_normalized_file_bytes(provider, uri, identity=None):
    p = str(provider or "").strip().upper()
    if p in ("DRIVE", "GOOGLE_DRIVE"):
        file_id = str(identity or _home_drive_uri_to_id(uri)).strip()
        if not file_id or file_id == "root":
            raise RuntimeError("DRIVE_APK_FILE_ID_REQUIRED")
        data = _home_drive_read_bytes(file_id)
    elif p in ("RUNTIME", "COLAB_RUNTIME"):
        path = _home_runtime_uri_to_path(uri)
        if not os.path.isfile(path):
            raise RuntimeError("RUNTIME_APK_TARGET_NOT_FILE")
        if os.path.getsize(path) > ORFMOS_APK_PROFILE_MAX_BYTES:
            raise RuntimeError("APK_PROFILE_SIZE_LIMIT_EXCEEDED")
        with open(path, "rb") as handle:
            data = handle.read(ORFMOS_APK_PROFILE_MAX_BYTES + 1)
    elif p == "GITHUB":
        data = _home_apk_fetch_github_bytes(uri)
    else:
        raise RuntimeError(f"APK_PROFILE_PROVIDER_UNSUPPORTED:{p or 'UNKNOWN'}")
    data = bytes(data or b"")
    if len(data) > ORFMOS_APK_PROFILE_MAX_BYTES:
        raise RuntimeError("APK_PROFILE_SIZE_LIMIT_EXCEEDED")
    if not data:
        raise RuntimeError("APK_PROFILE_EMPTY_FILE")
    return data


def _home_apk_dex_contracts(dex_payloads):
    rules = (
        (b"Landroid/app/Activity", "ACTIVITY_LIFECYCLE", "SHIM", "Android Activity lifecycle → ORFMOS application/presentation lifecycle candidate"),
        (b"Landroid/content/Intent", "INTENT_ROUTING", "SHIM", "Android Intent routing → ORFMOS launch/message contract candidate"),
        (b"Landroid/content/SharedPreferences", "PREFERENCE_STATE", "ORFMOS_NATIVE", "Preferences can map to device/application state storage"),
        (b"Landroid/database/sqlite", "SQLITE_STORAGE", "LINUX_NATIVE", "SQLite contract has a native Linux userspace implementation candidate"),
        (b"Ljava/io/", "JAVA_FILE_IO", "LINUX_NATIVE", "Java file I/O does not inherently require Android framework semantics"),
        (b"Ljava/net/", "JAVA_NETWORK", "LINUX_NATIVE", "Java networking does not inherently require Android framework semantics"),
        (b"Landroid/net/", "ANDROID_NETWORK", "SHIM", "Android networking API requires capability/interface translation"),
        (b"Landroid/view/", "ANDROID_VIEW_UI", "SHIM", "Android View/UI semantics require presentation translation"),
        (b"Landroid/widget/", "ANDROID_WIDGET_UI", "SHIM", "Android widget semantics require presentation translation"),
        (b"Landroid/webkit/", "ANDROID_WEBVIEW", "SHIM", "WebView can potentially map to an ORFMOS browser/web surface"),
        (b"Landroid/os/Binder", "BINDER_IPC", "ANDROID_REQUIRED", "Direct Binder dependency requires Android IPC semantics or a compatibility implementation"),
        (b"Landroid/hardware/", "ANDROID_HARDWARE", "ANDROID_REQUIRED", "Android hardware framework dependency needs a provider or Android compatibility layer"),
        (b"Landroid/bluetooth/", "ANDROID_BLUETOOTH", "ANDROID_REQUIRED", "Bluetooth framework dependency needs a provider or Android compatibility layer"),
        (b"Landroid/location/", "ANDROID_LOCATION", "ANDROID_REQUIRED", "Location framework dependency needs a provider or Android compatibility layer"),
        (b"Landroid/telephony/", "ANDROID_TELEPHONY", "ANDROID_REQUIRED", "Telephony framework dependency is Android-specific"),
        (b"Lcom/google/android/gms/", "GOOGLE_PLAY_SERVICES", "ANDROID_REQUIRED", "Google Play Services dependency is not currently an ORFMOS-native contract"),
    )
    results = []
    seen = set()
    for payload_name, payload in dex_payloads:
        sample = payload[:32 * 1024 * 1024]
        for pattern, contract, state, note in rules:
            if contract in seen:
                continue
            if pattern in sample:
                seen.add(contract)
                results.append({"contract": contract, "state": state, "evidence": f"{payload_name}: {note}"})
    return results


def _home_apk_elf_machine(blob):
    if len(blob) < 20 or blob[:4] != b"\x7fELF":
        return None
    endian = "<" if blob[5:6] == b"\x01" else ">" if blob[5:6] == b"\x02" else None
    if not endian:
        return None
    try:
        machine = struct.unpack(endian + "H", blob[18:20])[0]
    except Exception:
        return None
    return {3:"x86", 40:"ARM", 62:"x86_64", 183:"AARCH64", 243:"RISC-V"}.get(machine, f"EM_{machine}")


def _home_profile_apk_bytes(data, *, provider, uri, identity, name):
    data = bytes(data or b"")
    if len(data) > ORFMOS_APK_PROFILE_MAX_BYTES:
        raise RuntimeError("APK_PROFILE_SIZE_LIMIT_EXCEEDED")
    sha = hashlib.sha256(data).hexdigest()
    try:
        archive = zipfile.ZipFile(io.BytesIO(data), "r")
    except zipfile.BadZipFile as exc:
        raise RuntimeError("APK_NOT_VALID_ZIP_CONTAINER") from exc
    infos = archive.infolist()
    names = [item.filename for item in infos]
    manifest_name = next((n for n in names if n == "AndroidManifest.xml"), None)
    manifest = {"present": bool(manifest_name), "format": "MISSING", "bytes": None, "sha256": None, "decode_state": "UNAVAILABLE"}
    if manifest_name:
        raw = archive.read(manifest_name)
        manifest.update({"bytes": len(raw), "sha256": hashlib.sha256(raw).hexdigest()})
        stripped = raw.lstrip()
        if stripped.startswith(b"<"):
            manifest.update({"format": "TEXT_XML", "decode_state": "TEXT_XML_READABLE"})
        elif raw[:4] == b"\x03\x00\x08\x00":
            manifest.update({"format": "ANDROID_BINARY_AXML", "decode_state": "BINARY_AXML_DECODER_REQUIRED"})
        else:
            manifest.update({"format": "BINARY_OR_UNKNOWN", "decode_state": "FORMAT_REQUIRES_DECODER"})

    dex_files = []
    dex_payloads = []
    for info in infos:
        base = posixpath.basename(info.filename)
        if not re.fullmatch(r"classes(?:\d+)?\.dex", base):
            continue
        payload = archive.read(info)
        magic = payload[:8].decode("latin1", errors="replace")
        declared_size = None
        if len(payload) >= 36 and payload[:4] == b"dex\n":
            try: declared_size = struct.unpack("<I", payload[32:36])[0]
            except Exception: pass
        dex_files.append({
            "name": info.filename,
            "bytes": len(payload),
            "sha256": hashlib.sha256(payload).hexdigest(),
            "magic": magic.replace("\x00", "\\0"),
            "declared_file_size": declared_size,
        })
        dex_payloads.append((info.filename, payload))

    native_libraries = []
    native_abis = set()
    for info in infos:
        match = re.fullmatch(r"lib/([^/]+)/([^/]+\.so)", info.filename)
        if not match:
            continue
        abi, libname = match.groups()
        native_abis.add(abi)
        with archive.open(info, "r") as handle:
            head = handle.read(64)
        native_libraries.append({
            "path": info.filename,
            "abi": abi,
            "name": libname,
            "bytes": int(info.file_size),
            "machine": _home_apk_elf_machine(head),
        })

    contracts = _home_apk_dex_contracts(dex_payloads)
    if native_libraries:
        contracts.append({
            "contract": "ANDROID_NATIVE_LIBRARIES",
            "state": "SHIM",
            "evidence": "Native .so libraries are Linux ELF but Android ABI/Bionic compatibility and CPU architecture must be resolved",
        })
    if manifest.get("format") == "ANDROID_BINARY_AXML":
        contracts.append({
            "contract": "ANDROID_MANIFEST_AXML",
            "state": "SHIM",
            "evidence": "Manifest exists as Android binary XML; decoder is required before permissions/components can be translated",
        })

    state_rank = {"LINUX_NATIVE":0, "ORFMOS_NATIVE":0, "SHIM":1, "ANDROID_REQUIRED":2, "UNKNOWN":3}
    worst = max((state_rank.get(str(c.get("state")), 3) for c in contracts), default=3 if not dex_files else 0)
    if not dex_files:
        posture = "PROFILE_INCOMPLETE_NO_DEX"
    elif worst >= 2:
        posture = "ANDROID_RUNTIME_OR_PROVIDER_REQUIRED"
    elif worst == 1:
        posture = "COMPATIBILITY_TRANSLATION_CANDIDATE"
    else:
        posture = "LINUX_OR_ORFMOS_TRANSLATION_CANDIDATE"

    signing_v1 = any(n.upper().startswith("META-INF/") and n.upper().endswith((".RSA", ".DSA", ".EC", ".SF")) for n in names)
    signing_v2_magic = b"APK Sig Block 42" in data[-8*1024*1024:]
    signing_state = "PRESENT" if signing_v1 or signing_v2_magic else "NOT_DETECTED_BY_PROFILE"

    result = {
        "schema": ORFMOS_APK_PROFILE_SCHEMA,
        "status": "READY",
        "file": {
            "provider": str(provider or "UNKNOWN"),
            "uri": str(uri or "") or None,
            "identity": str(identity or "") or None,
            "name": str(name or "selected.apk"),
            "bytes": len(data),
            "sha256": sha,
        },
        "archive": {
            "entry_count": len(infos),
            "compressed_bytes": sum(int(i.compress_size) for i in infos),
            "uncompressed_bytes": sum(int(i.file_size) for i in infos),
            "resource_entry_count": sum(1 for n in names if n.startswith("res/") or n == "resources.arsc"),
            "asset_entry_count": sum(1 for n in names if n.startswith("assets/")),
            "meta_inf_entry_count": sum(1 for n in names if n.upper().startswith("META-INF/")),
        },
        "manifest": manifest,
        "dex_files": dex_files,
        "native_libraries": native_libraries[:250],
        "native_abis": sorted(native_abis),
        "signing": {"state": signing_state, "v1_meta_inf_detected": signing_v1, "v2_v3_magic_detected": signing_v2_magic},
        "contracts": contracts,
        "translation_posture": posture,
        "profile_limits": [
            "READ_ONLY: source APK bytes are never modified or installed by this profiler.",
            "Binary AndroidManifest.xml is detected but not decoded in v0.1; component/permission translation waits for an AXML decoder.",
            "DEX contract detection is heuristic byte-signature profiling, not full bytecode/data-flow analysis.",
            "LINUX_NATIVE / ORFMOS_NATIVE identifies a candidate operational analogue, not proof that application behavior is already compatible.",
        ],
        "generated_utc": datetime.now(timezone.utc).isoformat(),
    }
    archive.close()
    return result


async def _home_apk_profile_http(request: Request, provider: str = "", uri: str = "", identity: str = "", name: str = ""):
    try:
        p = str(provider or "").strip().upper()
        if p == "ANDROID_ORF_DRIVE":
            data = await request.body()
            header_name = str(request.headers.get("x-orf-file-name") or "").strip()
            if header_name:
                name = header_name
            if not data:
                raise RuntimeError("ANDROID_BROWSER_APK_BYTES_EMPTY")
            if len(data) > ORFMOS_APK_PROFILE_MAX_BYTES:
                raise RuntimeError("APK_PROFILE_SIZE_LIMIT_EXCEEDED")
            source_uri = "browser-file-object://selected"
        else:
            data = _home_read_normalized_file_bytes(p, uri, identity=identity)
            source_uri = uri
        return _home_profile_apk_bytes(data, provider=p, uri=source_uri, identity=identity, name=name)
    except Exception as exc:
        return {
            "schema": ORFMOS_APK_PROFILE_SCHEMA,
            "status": "FAILED",
            "message": f"{type(exc).__name__}: {exc}",
            "translation_posture": "UNRESOLVED",
        }




