def _home_vm_lab_event(event_type, detail=""):
    with _ORFMOS_VM_LAB_LOCK:
        events = list(globals().get("__ORFMOS_VM_LAB_EVENTS__") or [])
        events.append({
            "utc": datetime.now(timezone.utc).isoformat(),
            "type": str(event_type or "EVENT"),
            "detail": str(detail or ""),
        })
        globals()["__ORFMOS_VM_LAB_EVENTS__"] = events[-96:]


def _home_vm_lab_sdk_root():
    candidates = [
        os.environ.get("ANDROID_SDK_ROOT"),
        os.environ.get("ANDROID_HOME"),
        "/content/orf_android_sdk/orf_android_sdk",
        "/content/android-sdk",
        "/content/android_sdk",
        os.path.expanduser("~/Android/Sdk"),
    ]
    for candidate in candidates:
        value = str(candidate or "").strip()
        if value and os.path.isdir(value):
            return value
    return ""


def _home_vm_lab_tool(sdk_root, relative, fallback=None):
    candidate = os.path.join(sdk_root, *relative) if sdk_root else ""
    if candidate and os.path.isfile(candidate):
        return candidate
    return shutil.which(fallback) if fallback else None


def _home_vm_lab_run(args, timeout=30, input_text=None, env=None):
    result = subprocess.run(
        list(args),
        input=input_text,
        text=True,
        capture_output=True,
        timeout=timeout,
        check=False,
        env=env,
    )
    text = ((result.stdout or "") + "\n" + (result.stderr or "")).strip()
    return result.returncode, text


def _home_vm_lab_guest_channel_reset(channel_name, reason=""):
    name = re.sub(r"[^A-Z0-9_:-]+", "_", str(channel_name or "CONTROL").upper())[:48] or "CONTROL"
    with _ORFMOS_VM_GUEST_CHANNEL_LOCK:
        channels = globals().get("__ORFMOS_VM_GUEST_COMMAND_CHANNELS__")
        if not isinstance(channels, dict):
            channels = {}
        entry = channels.pop(name, None)
        globals()["__ORFMOS_VM_GUEST_COMMAND_CHANNELS__"] = channels
    process = entry.get("process") if isinstance(entry, dict) else None
    if process is not None:
        try:
            process.terminate()
            process.wait(timeout=1.5)
        except Exception:
            try:
                process.kill()
            except Exception:
                pass
    if entry:
        _home_vm_lab_event("GUEST_COMMAND_CHANNEL_RESET", f"channel={name} reason={reason or 'UNSPECIFIED'}")


def _home_vm_lab_guest_channel_reset_all(reason=""):
    with _ORFMOS_VM_GUEST_CHANNEL_LOCK:
        names = list((globals().get("__ORFMOS_VM_GUEST_COMMAND_CHANNELS__") or {}).keys())
    for name in names:
        _home_vm_lab_guest_channel_reset(name, reason=reason)


def _home_vm_lab_guest_channel_get(adb, channel_name="CONTROL"):
    name = re.sub(r"[^A-Z0-9_:-]+", "_", str(channel_name or "CONTROL").upper())[:48] or "CONTROL"
    with _ORFMOS_VM_GUEST_CHANNEL_LOCK:
        channels = globals().get("__ORFMOS_VM_GUEST_COMMAND_CHANNELS__")
        if not isinstance(channels, dict):
            channels = {}
        entry = channels.get(name)
        process = entry.get("process") if isinstance(entry, dict) else None
        same_provider = bool(entry and entry.get("adb") == adb and entry.get("serial") == ORFMOS_VM_LAB_SERIAL)
        if process is not None and process.poll() is None and same_provider:
            return entry
        if entry:
            channels.pop(name, None)
        process = subprocess.Popen(
            [adb, "-s", ORFMOS_VM_LAB_SERIAL, "shell", "sh"],
            stdin=subprocess.PIPE,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            bufsize=0,
        )
        entry = {
            "schema": ORFMOS_VM_GUEST_COMMAND_CHANNEL_SCHEMA,
            "name": name,
            "adb": adb,
            "serial": ORFMOS_VM_LAB_SERIAL,
            "process": process,
            "lock": threading.RLock(),
            "created_epoch": time.time(),
            "command_count": 0,
            "last_elapsed_seconds": None,
            "last_state": "OPEN",
        }
        channels[name] = entry
        globals()["__ORFMOS_VM_GUEST_COMMAND_CHANNELS__"] = channels
    _home_vm_lab_event("GUEST_COMMAND_CHANNEL_OPENED", f"channel={name} pid={process.pid} serial={ORFMOS_VM_LAB_SERIAL}")
    return entry


def _home_vm_lab_guest_channel_exec(adb, shell_command, timeout=8, channel_name="CONTROL", dispatched_event=None):
    """Carry one shell command over a resident ADB guest shell.

    The command is framed with a unique completion marker. A timeout resets only
    that channel so a wedged guest command cannot poison future transactions.
    """
    entry = _home_vm_lab_guest_channel_get(adb, channel_name=channel_name)
    lock = entry.get("lock")
    started = time.time()
    marker = f"__ORFMOS_DONE_{time.time_ns()}_{threading.get_ident()}__"
    command = str(shell_command or "").strip()
    if not command:
        command = ":"
    payload = (
        f"{{ {command}; }} 2>&1\n"
        f"__orfmos_rc=$?\n"
        f"printf '\\n{marker}:%s\\n' \"$__orfmos_rc\"\n"
    ).encode("utf-8")
    with lock:
        process = entry.get("process")
        if process is None or process.poll() is not None or process.stdin is None or process.stdout is None:
            _home_vm_lab_guest_channel_reset(channel_name, reason="PROCESS_NOT_ALIVE")
            entry = _home_vm_lab_guest_channel_get(adb, channel_name=channel_name)
            process = entry.get("process")
        try:
            process.stdin.write(payload)
            process.stdin.flush()
            if dispatched_event is not None:
                try:
                    dispatched_event.set()
                except Exception:
                    pass
        except Exception:
            _home_vm_lab_guest_channel_reset(channel_name, reason="WRITE_FAILED")
            raise

        fd = process.stdout.fileno()
        collected = bytearray()
        marker_bytes = marker.encode("utf-8") + b":"
        deadline = time.time() + max(0.2, float(timeout))
        rc = None
        while time.time() < deadline:
            remaining = max(0.0, deadline - time.time())
            ready, _, _ = select.select([fd], [], [], min(0.25, remaining))
            if not ready:
                if process.poll() is not None:
                    break
                continue
            chunk = os.read(fd, 65536)
            if not chunk:
                if process.poll() is not None:
                    break
                continue
            collected.extend(chunk)
            if len(collected) > 2_000_000:
                del collected[:-1_500_000]
            pos = collected.find(marker_bytes)
            if pos >= 0:
                line_end = collected.find(b"\n", pos)
                if line_end >= 0:
                    rc_raw = bytes(collected[pos + len(marker_bytes):line_end]).strip()
                    try:
                        rc = int(rc_raw or b"0")
                    except Exception:
                        rc = 1
                    output = bytes(collected[:pos]).decode("utf-8", errors="replace").strip()
                    elapsed = round(max(0.0, time.time() - started), 3)
                    entry["command_count"] = int(entry.get("command_count") or 0) + 1
                    entry["last_elapsed_seconds"] = elapsed
                    entry["last_state"] = "RETURNED"
                    return rc, output, elapsed
        elapsed = round(max(0.0, time.time() - started), 3)
        entry["last_elapsed_seconds"] = elapsed
        entry["last_state"] = "TIMEOUT"
        _home_vm_lab_guest_channel_reset(channel_name, reason=f"COMMAND_TIMEOUT_{elapsed}s")
        raise subprocess.TimeoutExpired(cmd=f"ORFMOS_GUEST_CHANNEL:{channel_name}:{command[:120]}", timeout=timeout)


def _home_vm_lab_guest_channel_snapshot():
    result = []
    with _ORFMOS_VM_GUEST_CHANNEL_LOCK:
        channels = dict(globals().get("__ORFMOS_VM_GUEST_COMMAND_CHANNELS__") or {})
    for name, entry in sorted(channels.items()):
        process = entry.get("process") if isinstance(entry, dict) else None
        result.append({
            "name": name,
            "alive": bool(process is not None and process.poll() is None),
            "pid": getattr(process, "pid", None),
            "command_count": int(entry.get("command_count") or 0) if isinstance(entry, dict) else 0,
            "last_elapsed_seconds": entry.get("last_elapsed_seconds") if isinstance(entry, dict) else None,
            "last_state": str(entry.get("last_state") or "") if isinstance(entry, dict) else "",
            "age_seconds": round(max(0.0, time.time() - float(entry.get("created_epoch") or time.time())), 1) if isinstance(entry, dict) else None,
        })
    return result


def _home_vm_lab_guest_stimulus_probe(adb, domain="GENERIC"):
    """Issue one bounded, non-mutating stimulus when a guest service goes quiescent."""
    domain_name = re.sub(r"[^A-Z0-9_:-]+", "_", str(domain or "GENERIC").upper())[:48] or "GENERIC"
    if domain_name == "PACKAGE":
        command = "cmd package list packages -3 | head -n 1"
    else:
        command = "getprop sys.boot_completed"
    started = time.time()
    try:
        rc, output, elapsed = _home_vm_lab_guest_channel_exec(
            adb,
            command,
            timeout=ORFMOS_VM_GUEST_STIMULUS_TIMEOUT_SECONDS,
            channel_name="PROBE",
        )
        state = "RETURNED" if rc == 0 else "REJECTED"
        result = {"domain": domain_name, "state": state, "returncode": rc, "elapsed_seconds": elapsed, "output": str(output or "")[-300:]}
    except subprocess.TimeoutExpired:
        elapsed = round(max(0.0, time.time() - started), 3)
        result = {"domain": domain_name, "state": "TIMEOUT", "returncode": 124, "elapsed_seconds": elapsed, "output": ""}
    except Exception as exc:
        elapsed = round(max(0.0, time.time() - started), 3)
        result = {"domain": domain_name, "state": "ERROR", "returncode": None, "elapsed_seconds": elapsed, "output": f"{type(exc).__name__}:{exc}"[-300:]}
    _home_vm_lab_event("GUEST_STIMULUS_PROBE", f"domain={domain_name} state={result['state']} elapsed={result['elapsed_seconds']}s")
    return result


def _home_vm_lab_pid_matches(pid):
    try:
        pid = int(pid)
        if pid <= 1:
            return False
        cmdline_path = f"/proc/{pid}/cmdline"
        raw = Path(cmdline_path).read_bytes().replace(b"\x00", b" ").decode("utf-8", "ignore")
        return (
            ORFMOS_VM_LAB_AVD_NAME in raw
            and ("emulator" in raw.lower() or "qemu" in raw.lower())
            and ("5554" in raw or ORFMOS_VM_LAB_SERIAL in raw)
        )
    except Exception:
        return False


def _home_vm_lab_recover_process_pid():
    candidates = []
    try:
        if os.path.isfile(ORFMOS_VM_LAB_PID_PATH):
            value = Path(ORFMOS_VM_LAB_PID_PATH).read_text(encoding="utf-8").strip()
            if value:
                candidates.append(int(value))
    except Exception:
        pass
    try:
        for item in os.listdir("/proc"):
            if item.isdigit():
                candidates.append(int(item))
    except Exception:
        pass
    seen = set()
    for pid in candidates:
        if pid in seen:
            continue
        seen.add(pid)
        if _home_vm_lab_pid_matches(pid):
            try:
                os.makedirs(ORFMOS_VM_LAB_RUNTIME_ROOT, exist_ok=True)
                Path(ORFMOS_VM_LAB_PID_PATH).write_text(str(pid) + "\n", encoding="utf-8")
            except Exception:
                pass
            return pid
    return None

def _home_vm_lab_process_alive_pid(pid):
    if not pid:
        return False
    try:
        os.kill(int(pid), 0)
        return _home_vm_lab_pid_matches(int(pid))
    except Exception:
        return False


def _home_vm_lab_sha256_file(path):
    digest = hashlib.sha256()
    with open(path, "rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _home_vm_lab_cmdline_provider_inventory():
    root = ORFMOS_VM_LAB_CMDLINE_PROVIDER_ROOT
    sdkmanager = os.path.join(root, "bin", "sdkmanager")
    avdmanager = os.path.join(root, "bin", "avdmanager")
    marker_path = os.path.join(root, "ORFMOS_PROVIDER_AUTHORITY.json")
    marker_ok = False
    if os.path.isfile(marker_path):
        try:
            marker = json.loads(Path(marker_path).read_text(encoding="utf-8"))
            marker_ok = (
                str(marker.get("revision") or "") == ORFMOS_VM_LAB_CMDLINE_TOOLS_REVISION
                and str(marker.get("archive_sha256") or "").lower() == ORFMOS_VM_LAB_CMDLINE_TOOLS_SHA256.lower()
            )
        except Exception:
            marker_ok = False
    ready = marker_ok and os.path.isfile(sdkmanager) and os.path.isfile(avdmanager)
    return {
        "ready": ready,
        "root": root,
        "sdkmanager": sdkmanager if ready else None,
        "avdmanager": avdmanager if ready else None,
        "marker": marker_path,
        "revision": ORFMOS_VM_LAB_CMDLINE_TOOLS_REVISION,
        "archive_sha256": ORFMOS_VM_LAB_CMDLINE_TOOLS_SHA256,
    }


def _home_vm_lab_bootstrap_cmdline_provider():
    current = _home_vm_lab_cmdline_provider_inventory()
    if current.get("ready"):
        return current

    tooling_root = os.path.dirname(ORFMOS_VM_LAB_CMDLINE_PROVIDER_ROOT)
    os.makedirs(tooling_root, exist_ok=True)
    archive_path = os.path.join(tooling_root, f"commandlinetools-linux-{ORFMOS_VM_LAB_CMDLINE_TOOLS_REVISION}_latest.zip")
    partial_path = archive_path + ".partial"
    extract_root = ORFMOS_VM_LAB_CMDLINE_PROVIDER_ROOT + ".extracting"
    _home_vm_lab_event(
        "CMDLINE_TOOLS_BOOTSTRAP_BEGIN",
        f"revision={ORFMOS_VM_LAB_CMDLINE_TOOLS_REVISION} authority_sha256={ORFMOS_VM_LAB_CMDLINE_TOOLS_SHA256}",
    )

    archive_ok = False
    if os.path.isfile(archive_path):
        try:
            archive_ok = _home_vm_lab_sha256_file(archive_path).lower() == ORFMOS_VM_LAB_CMDLINE_TOOLS_SHA256.lower()
        except Exception:
            archive_ok = False
    if not archive_ok:
        try:
            if os.path.exists(partial_path):
                os.remove(partial_path)
        except Exception:
            pass
        request = urllib.request.Request(
            ORFMOS_VM_LAB_CMDLINE_TOOLS_URL,
            headers={"User-Agent": "ORFMOS-VM-LAB/0.2.37"},
        )
        with urllib.request.urlopen(request, timeout=120) as response, open(partial_path, "wb") as handle:
            total = 0
            while True:
                chunk = response.read(1024 * 1024)
                if not chunk:
                    break
                handle.write(chunk)
                total += len(chunk)
                if total and total % (32 * 1024 * 1024) < (1024 * 1024):
                    _home_vm_lab_event("CMDLINE_TOOLS_DOWNLOAD", f"bytes={total}")
        observed = _home_vm_lab_sha256_file(partial_path)
        if observed.lower() != ORFMOS_VM_LAB_CMDLINE_TOOLS_SHA256.lower():
            raise RuntimeError(f"CMDLINE_TOOLS_HASH_MISMATCH:{observed}")
        os.replace(partial_path, archive_path)
        _home_vm_lab_event("CMDLINE_TOOLS_HASH_VERIFIED", f"sha256={observed}")

    if os.path.isdir(extract_root):
        shutil.rmtree(extract_root, ignore_errors=True)
    os.makedirs(extract_root, exist_ok=True)
    with zipfile.ZipFile(archive_path, "r") as bundle:
        bundle.extractall(extract_root)
    extracted = os.path.join(extract_root, "cmdline-tools")
    if not os.path.isfile(os.path.join(extracted, "bin", "sdkmanager")):
        raise RuntimeError("CMDLINE_TOOLS_ARCHIVE_LAYOUT_UNEXPECTED")
    if os.path.isdir(ORFMOS_VM_LAB_CMDLINE_PROVIDER_ROOT):
        shutil.rmtree(ORFMOS_VM_LAB_CMDLINE_PROVIDER_ROOT, ignore_errors=True)
    shutil.move(extracted, ORFMOS_VM_LAB_CMDLINE_PROVIDER_ROOT)
    shutil.rmtree(extract_root, ignore_errors=True)
    for tool_name in ("sdkmanager", "avdmanager"):
        tool_path = os.path.join(ORFMOS_VM_LAB_CMDLINE_PROVIDER_ROOT, "bin", tool_name)
        try:
            os.chmod(tool_path, os.stat(tool_path).st_mode | 0o111)
        except Exception:
            pass
    marker = {
        "schema": "ORFMOS_DEPENDENCY_PROVIDER_AUTHORITY_V0_1",
        "provider": "VM_LOCAL_ANDROID_CMDLINE_TOOLS",
        "revision": ORFMOS_VM_LAB_CMDLINE_TOOLS_REVISION,
        "archive_url": ORFMOS_VM_LAB_CMDLINE_TOOLS_URL,
        "archive_sha256": ORFMOS_VM_LAB_CMDLINE_TOOLS_SHA256,
        "installed_utc": datetime.now(timezone.utc).isoformat(),
    }
    Path(os.path.join(ORFMOS_VM_LAB_CMDLINE_PROVIDER_ROOT, "ORFMOS_PROVIDER_AUTHORITY.json")).write_text(
        json.dumps(marker, sort_keys=True, indent=2) + "\n", encoding="utf-8"
    )
    current = _home_vm_lab_cmdline_provider_inventory()
    if not current.get("ready"):
        raise RuntimeError("CMDLINE_TOOLS_PROVIDER_READBACK_FAILED")
    _home_vm_lab_event("CMDLINE_TOOLS_PROVIDER_READY", f"revision={ORFMOS_VM_LAB_CMDLINE_TOOLS_REVISION}")
    return current



def _home_vm_lab_read_instance():
    value = globals().get("__ORFMOS_VM_LAB_INSTANCE__")
    if isinstance(value, dict):
        return dict(value)
    try:
        path = Path(ORFMOS_VM_LAB_INSTANCE_PATH)
        if path.is_file():
            value = json.loads(path.read_text(encoding="utf-8"))
            if isinstance(value, dict) and value.get("serial") == ORFMOS_VM_LAB_SERIAL and value.get("avd_name") == ORFMOS_VM_LAB_AVD_NAME:
                globals()["__ORFMOS_VM_LAB_INSTANCE__"] = dict(value)
                return dict(value)
    except Exception:
        pass
    return {}


def _home_vm_lab_write_instance(pid):
    os.makedirs(ORFMOS_VM_LAB_RUNTIME_ROOT, exist_ok=True)
    generation = f"{int(time.time() * 1000)}-{int(pid or 0)}"
    value = {
        "schema": "ORFMOS_VM_LAB_INSTANCE_V0_1",
        "serial": ORFMOS_VM_LAB_SERIAL,
        "avd_name": ORFMOS_VM_LAB_AVD_NAME,
        "generation": generation,
        "host_pid": int(pid or 0),
        "started_utc": datetime.now(timezone.utc).isoformat(),
    }
    temp = Path(ORFMOS_VM_LAB_INSTANCE_PATH + ".tmp")
    final = Path(ORFMOS_VM_LAB_INSTANCE_PATH)
    temp.write_text(json.dumps(value, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    os.replace(str(temp), str(final))
    globals()["__ORFMOS_VM_LAB_INSTANCE__"] = dict(value)
    return value


def _home_vm_lab_clear_instance(reason=""):
    prior = globals().pop("__ORFMOS_VM_LAB_INSTANCE__", None)
    try:
        if os.path.isfile(ORFMOS_VM_LAB_INSTANCE_PATH):
            os.remove(ORFMOS_VM_LAB_INSTANCE_PATH)
    except Exception:
        pass
    if prior:
        try:
            _home_vm_lab_event("VM_INSTANCE_CLEARED", f"generation={prior.get('generation')} reason={reason or 'UNSPECIFIED'}")
        except Exception:
            pass


def _home_vm_lab_runtime_identity(inv):
    """Return a menu-independent identity for the currently running guest instance."""
    guest_boot_id = str((inv or {}).get("guest_boot_id") or "").strip()
    if guest_boot_id:
        return f"{ORFMOS_VM_LAB_SERIAL}:boot:{guest_boot_id}"
    instance = _home_vm_lab_read_instance()
    if instance.get("generation"):
        return f"{ORFMOS_VM_LAB_SERIAL}:generation:{instance.get('generation')}"
    try:
        pid = int((inv or {}).get("process_pid") or 0)
    except Exception:
        pid = 0
    if pid > 0:
        return f"{ORFMOS_VM_LAB_SERIAL}:pid:{pid}"
    return None

def _home_vm_lab_clear_readiness_latch(reason=""):
    prior = globals().pop("__ORFMOS_VM_LAB_READINESS_LATCH__", None)
    if prior:
        try:
            _home_vm_lab_event(
                "VM_READINESS_LATCH_CLEARED",
                f"identity={prior.get('identity')} reason={reason or 'UNSPECIFIED'}",
            )
        except Exception:
            pass


def _home_vm_lab_apply_readiness_latch(inv):
    """
    Make verified readiness monotonic for one emulator process.

    Live probes remain observable, but transient getprop / PackageManager /
    ActivityManager probe failures cannot revoke readiness after the same
    emulator instance has already been verified ready.
    """
    inv = dict(inv or {})
    live_boot = bool(inv.get("boot_completed"))
    live_framework = bool(inv.get("framework_ready"))
    inv["boot_completed_live"] = live_boot
    inv["framework_ready_live"] = live_framework

    identity = _home_vm_lab_runtime_identity(inv)
    inv["readiness_identity"] = identity
    live_guest = bool(inv.get("running") or inv.get("process_alive"))

    if not identity or not live_guest:
        inv["readiness_latched"] = False
        return inv

    prior = globals().get("__ORFMOS_VM_LAB_READINESS_LATCH__")
    if not isinstance(prior, dict) or prior.get("identity") != identity:
        prior = {
            "identity": identity,
            "boot_verified": False,
            "framework_verified": False,
            "first_verified_utc": None,
            "last_verified_utc": None,
        }

    changed = False
    now_utc = datetime.now(timezone.utc).isoformat()

    if live_framework and not prior.get("framework_verified"):
        prior["framework_verified"] = True
        changed = True
    if live_boot and not prior.get("boot_verified"):
        prior["boot_verified"] = True
        # A verified sys.boot_completed=1 is also sufficient evidence that the
        # Android framework reached an operational boot state for this instance.
        prior["framework_verified"] = True
        changed = True

    if live_framework or live_boot:
        if not prior.get("first_verified_utc"):
            prior["first_verified_utc"] = now_utc
        prior["last_verified_utc"] = now_utc

    globals()["__ORFMOS_VM_LAB_READINESS_LATCH__"] = prior

    latched_boot = bool(prior.get("boot_verified"))
    latched_framework = bool(prior.get("framework_verified"))
    inv["boot_completed"] = live_boot or latched_boot
    inv["framework_ready"] = live_framework or latched_framework
    inv["readiness_latched"] = bool(
        (not live_boot and latched_boot) or (not live_framework and latched_framework)
    )
    inv["readiness_latch"] = dict(prior)

    if changed:
        try:
            _home_vm_lab_event(
                "VM_READINESS_LATCH_VERIFIED",
                f"identity={identity} boot={bool(prior.get('boot_verified'))} framework={bool(prior.get('framework_verified'))}",
            )
        except Exception:
            pass
    elif inv["readiness_latched"]:
        # Avoid flooding the event trace; record only when the transition into
        # fallback/latch ownership changes.
        last_reported = str(globals().get("__ORFMOS_VM_LAB_READINESS_LATCH_REPORTED__") or "")
        report_key = f"{identity}:{int(live_boot)}:{int(live_framework)}"
        if last_reported != report_key:
            globals()["__ORFMOS_VM_LAB_READINESS_LATCH_REPORTED__"] = report_key
            try:
                _home_vm_lab_event(
                    "VM_READINESS_LATCH_USED",
                    f"identity={identity} live_boot={live_boot} live_framework={live_framework} effective_boot={inv['boot_completed']} effective_framework={inv['framework_ready']}",
                )
            except Exception:
                pass
    return inv


def _home_vm_lab_inventory(include_packages=False):
    sdk_root = _home_vm_lab_sdk_root()
    vm_tools = _home_vm_lab_cmdline_provider_inventory()
    sdk_root_avdmanager = _home_vm_lab_tool(sdk_root, ("cmdline-tools", "latest", "bin", "avdmanager"), None)
    if not sdk_root_avdmanager:
        sdk_root_avdmanager = _home_vm_lab_tool(sdk_root, ("tools", "bin", "avdmanager"), None)
    if vm_tools.get("ready"):
        sdkmanager = vm_tools.get("sdkmanager")
        # avdmanager must be able to infer the SDK root that owns the installed
        # system image. Prefer the SDK-root-local tool; the isolated current
        # provider remains a fallback but is not authoritative for AVD creation.
        avdmanager = sdk_root_avdmanager or vm_tools.get("avdmanager")
        sdkmanager_provider = f"VM_LOCAL_CURRENT_{ORFMOS_VM_LAB_CMDLINE_TOOLS_REVISION}"
        avdmanager_provider = "SDK_ROOT_LOCAL" if sdk_root_avdmanager else f"VM_LOCAL_CURRENT_{ORFMOS_VM_LAB_CMDLINE_TOOLS_REVISION}"
    else:
        sdkmanager = _home_vm_lab_tool(sdk_root, ("cmdline-tools", "latest", "bin", "sdkmanager"), "sdkmanager")
        avdmanager = sdk_root_avdmanager or shutil.which("avdmanager")
        sdkmanager_provider = "SDK_ROOT_LATEST_LEGACY" if sdkmanager else "MISSING"
        avdmanager_provider = "SDK_ROOT_LOCAL" if sdk_root_avdmanager else ("PATH" if avdmanager else "MISSING")
    emulator = _home_vm_lab_tool(sdk_root, ("emulator", "emulator"), "emulator")
    adb = _home_vm_lab_tool(sdk_root, ("platform-tools", "adb"), "adb")
    installed_image = None
    image_dir = ""
    if sdk_root:
        for image_id in ORFMOS_VM_LAB_SYSTEM_IMAGE_CANDIDATES:
            parts = image_id.split(";")
            candidate_dir = os.path.join(sdk_root, *parts)
            if os.path.isdir(candidate_dir):
                try:
                    if any(Path(candidate_dir).iterdir()):
                        installed_image = image_id
                        image_dir = candidate_dir
                        break
                except Exception:
                    pass
    selected_image = installed_image or ORFMOS_VM_LAB_SYSTEM_IMAGE
    avd_home = os.path.expanduser(os.environ.get("ANDROID_AVD_HOME") or "~/.android/avd")
    avd_dir = os.path.join(avd_home, ORFMOS_VM_LAB_AVD_NAME + ".avd")
    avd_ini = os.path.join(avd_home, ORFMOS_VM_LAB_AVD_NAME + ".ini")
    kvm = os.path.exists("/dev/kvm") and os.access("/dev/kvm", os.R_OK | os.W_OK)
    free_disk_gb = None
    try:
        root = "/content" if os.path.isdir("/content") else "/"
        free_disk_gb = round(shutil.disk_usage(root).free / (1024 ** 3), 2)
    except Exception:
        pass

    running = False
    adb_state = "OFFLINE"
    boot_completed = False
    guest_boot_id = ""
    # Generic VM polling must never exercise PackageManager or ActivityManager.
    # Those are separately resolved capabilities and may be slow/degraded under TCG.
    package_service_state = str(globals().get("__ORFMOS_VM_PACKAGE_SERVICE_STATE__") or "UNKNOWN").upper()
    package_manager_ready = package_service_state == "READY"
    activity_manager_ready = False
    framework_ready = False
    user_packages = []
    if adb:
        try:
            rc, text = _home_vm_lab_run([adb, "devices"], timeout=8)
            for line in text.splitlines():
                if line.startswith(ORFMOS_VM_LAB_SERIAL + "\t"):
                    adb_state = line.split("\t", 1)[-1].strip().upper() or "UNKNOWN"
                    break
            running = rc == 0 and adb_state == "DEVICE"
            if running:
                try:
                    rc_bid, boot_id_text = _home_vm_lab_run([adb, "-s", ORFMOS_VM_LAB_SERIAL, "shell", "cat", "/proc/sys/kernel/random/boot_id"], timeout=5)
                    candidate = str(boot_id_text or "").strip().splitlines()[0] if str(boot_id_text or "").strip() else ""
                    if rc_bid == 0 and re.fullmatch(r"[0-9a-fA-F-]{16,64}", candidate):
                        guest_boot_id = candidate.lower()
                except Exception:
                    guest_boot_id = ""
                try:
                    rc, boot = _home_vm_lab_run([adb, "-s", ORFMOS_VM_LAB_SERIAL, "shell", "getprop", "sys.boot_completed"], timeout=8)
                    boot_completed = rc == 0 and boot.strip().endswith("1")
                except Exception:
                    boot_completed = False
                # sys.boot_completed is the generic Android framework lifecycle gate.
                # PackageManager readiness is intentionally independent.
                framework_ready = boot_completed
                if boot_completed and include_packages:
                    query_provider, packages, _trace = _home_vm_lab_guest_query_user_packages(adb)
                    user_packages = sorted(set(packages))[:160] if query_provider else []
        except Exception:
            pass

    proc = globals().get("__ORFMOS_VM_LAB_PROCESS__")
    process_pid = getattr(proc, "pid", None) if proc is not None else None
    process_returncode = None
    process_alive = False
    process_source = "NONE"
    if proc is not None:
        try:
            process_returncode = proc.poll()
            process_alive = process_returncode is None
            if process_pid:
                process_source = "PYTHON_PROCESS"
        except Exception:
            process_returncode = None
            process_alive = False
    if not process_alive:
        recovered_pid = _home_vm_lab_recover_process_pid()
        if recovered_pid and _home_vm_lab_process_alive_pid(recovered_pid):
            process_pid = recovered_pid
            process_alive = True
            process_returncode = None
            process_source = "RECOVERED_PROCFS"
    if running and not process_alive:
        # ADB transport is stronger evidence of a live guest than a lost Python
        # Popen object. Keep process semantics truthful across Home successor loads.
        process_alive = True
        process_source = "ADB_TRANSPORT"

    system_image_ready = bool(image_dir and os.path.isdir(image_dir) and any(Path(image_dir).iterdir()))
    avd_ready = os.path.isdir(avd_dir) or os.path.isfile(avd_ini)
    acceleration = "KVM" if kvm else "SOFTWARE_TCG"
    inventory = {
        "sdk_root": sdk_root or None,
        "sdkmanager": sdkmanager,
        "sdkmanager_provider": sdkmanager_provider,
        "cmdline_tools_revision": ORFMOS_VM_LAB_CMDLINE_TOOLS_REVISION if vm_tools.get("ready") else None,
        "avdmanager": avdmanager,
        "avdmanager_provider": avdmanager_provider,
        "emulator": emulator,
        "adb": adb,
        "system_image": selected_image,
        "system_image_candidates": list(ORFMOS_VM_LAB_SYSTEM_IMAGE_CANDIDATES),
        "system_image_dir": image_dir or None,
        "system_image_ready": system_image_ready,
        "avd_name": ORFMOS_VM_LAB_AVD_NAME,
        "avd_dir": avd_dir,
        "avd_ready": avd_ready,
        "serial": ORFMOS_VM_LAB_SERIAL,
        "kvm": kvm,
        "acceleration": acceleration,
        "running": running,
        "adb_state": adb_state,
        "guest_boot_id": guest_boot_id or None,
        "package_service_state": package_service_state,
        "process_alive": process_alive,
        "process_pid": process_pid,
        "process_returncode": process_returncode,
        "process_source": process_source,
        "boot_completed": boot_completed,
        "package_manager_ready": package_manager_ready,
        "activity_manager_ready": activity_manager_ready,
        "framework_ready": framework_ready,
        "user_packages": user_packages,
        "free_disk_gb": free_disk_gb,
        "home_surface_source": "02_HOME_ROLE_AND_LAUNCHER_PROBE_SOURCE_FOUND",
        "home_surface_drive_id": ORFMOS_VM_LAB_HOME_SOURCE_DRIVE_ID,
        "home_package": ORFMOS_VM_LAB_HOME_PACKAGE,
    }
    return _home_vm_lab_apply_readiness_latch(inventory)


def _home_vm_lab_state_from_inventory(inv=None):
    inv = dict(inv or _home_vm_lab_inventory(include_packages=False))
    busy = bool(globals().get("__ORFMOS_VM_LAB_BUSY__"))
    operation = str(globals().get("__ORFMOS_VM_LAB_OPERATION__") or "")
    provision_thread = globals().get("__ORFMOS_VM_LAB_PROVISION_THREAD__")
    boot_thread = globals().get("__ORFMOS_VM_LAB_BOOT_THREAD__")
    worker_active = False
    for worker in (provision_thread, boot_thread):
        try:
            if worker is not None and worker.is_alive():
                worker_active = True
                break
        except Exception:
            pass

    events = list(globals().get("__ORFMOS_VM_LAB_EVENTS__") or [])
    latest_event = events[-1] if events else {}
    started = globals().get("__ORFMOS_VM_LAB_OPERATION_STARTED_EPOCH__")
    completed = globals().get("__ORFMOS_VM_LAB_OPERATION_COMPLETED_EPOCH__")
    if started is None and (busy or worker_active):
        for item in reversed(events):
            if str(item.get("type") or "") in {"VM_START", "PROVISION_BEGIN"}:
                try:
                    started = datetime.fromisoformat(str(item.get("utc") or "").replace("Z", "+00:00")).timestamp()
                    break
                except Exception:
                    pass
    elapsed = 0.0
    try:
        if started is not None:
            end_epoch = time.time() if (busy or worker_active) else (completed or time.time())
            elapsed = max(0.0, float(end_epoch) - float(started))
    except Exception:
        elapsed = 0.0

    last_result = str(globals().get("__ORFMOS_VM_LAB_LAST_RESULT__") or "")
    if not last_result and latest_event:
        inferred = str(latest_event.get("type") or "")
        if inferred in {"PROVISION_VERIFIED", "PROVISION_FAILED", "VM_READY", "VM_FRAMEWORK_READY", "VM_BOOT_WAIT_EXCEEDED", "VM_BOOT_FAILED", "VM_STOP"}:
            last_result = inferred

    if inv.get("boot_completed") and last_result != "VM_READY":
        last_result = "VM_READY"
        globals()["__ORFMOS_VM_LAB_LAST_RESULT__"] = "VM_READY"
        globals()["__ORFMOS_VM_LAB_MESSAGE__"] = "ANDROID GUEST BOOT COMPLETE; INSTALLER PROVIDER RESOLVES INDEPENDENTLY"
        if not events or str(events[-1].get("type") or "") != "VM_READY":
            _home_vm_lab_event("VM_READY", f"serial={ORFMOS_VM_LAB_SERIAL} recovered_by=STATE_POLL")
            events = list(globals().get("__ORFMOS_VM_LAB_EVENTS__") or [])
            latest_event = events[-1] if events else latest_event
    elif inv.get("framework_ready") and not inv.get("boot_completed") and last_result not in {"VM_FRAMEWORK_READY", "VM_BOOT_WAIT_EXCEEDED"}:
        last_result = "VM_FRAMEWORK_READY"
        globals()["__ORFMOS_VM_LAB_LAST_RESULT__"] = "VM_FRAMEWORK_READY"
        globals()["__ORFMOS_VM_LAB_MESSAGE__"] = "ANDROID FRAMEWORK LIFECYCLE READY; PACKAGE SERVICES RESOLVE INDEPENDENTLY"
        if not events or str(events[-1].get("type") or "") != "VM_FRAMEWORK_READY":
            _home_vm_lab_event("VM_FRAMEWORK_READY", f"serial={ORFMOS_VM_LAB_SERIAL}")
            events = list(globals().get("__ORFMOS_VM_LAB_EVENTS__") or [])
            latest_event = events[-1] if events else latest_event

    effective_operation = operation
    if not effective_operation and not inv.get("boot_completed") and (inv.get("running") or inv.get("process_alive")):
        effective_operation = "VM_BOOTING"

    if busy and not worker_active:
        state = "STALE_OPERATION"
    elif busy:
        state = effective_operation or "BUSY"
    elif inv.get("boot_completed"):
        state = "VM_READY"
    elif inv.get("framework_ready"):
        state = "VM_FRAMEWORK_READY"
    elif inv.get("process_alive") or inv.get("running"):
        state = "VM_BOOTING"
    elif not inv.get("sdkmanager") or not inv.get("avdmanager"):
        state = "ANDROID_SDK_MANAGER_MISSING"
    elif not inv.get("emulator"):
        state = "EMULATOR_COMPONENT_MISSING"
    elif not inv.get("system_image_ready"):
        state = "SYSTEM_IMAGE_MISSING"
    elif not inv.get("avd_ready"):
        state = "AVD_MISSING"
    else:
        state = "VM_PROVISIONED_STOPPED"
    return {
        "schema": ORFMOS_VM_LAB_SCHEMA,
        "state": state,
        "busy": busy,
        "worker_active": worker_active,
        "operation": effective_operation or None,
        "operation_elapsed_seconds": round(elapsed, 1),
        "last_result": last_result or None,
        "latest_event": latest_event or None,
        "route_revision": ORFMOS_VM_LAB_ROUTE_REVISION,
        "inventory": inv,
        "message": str(globals().get("__ORFMOS_VM_LAB_MESSAGE__") or "ANDROID VM HOST DISCOVERED"),
        "events": events,
    }


def _home_vm_lab_provider_state():
    try:
        inv = _home_vm_lab_inventory(include_packages=False)
        if inv.get("boot_completed"):
            return "READY"
        if inv.get("avd_ready") and inv.get("emulator") and inv.get("adb"):
            return "PROVISIONED_STOPPED"
        return "PROVISIONING_REQUIRED"
    except Exception:
        return "UNRESOLVED"


def _home_vm_lab_state_http():
    return _home_vm_lab_state_from_inventory()


def _home_vm_lab_provision_worker():
    try:
        globals()["__ORFMOS_VM_LAB_OPERATION__"] = "PROVISIONING"
        globals()["__ORFMOS_VM_LAB_MESSAGE__"] = "RESOLVING + INSTALLING ANDROID API27 SYSTEM IMAGE"
        inv = _home_vm_lab_inventory(include_packages=False)
        sdk_root = inv.get("sdk_root")
        if not sdk_root:
            raise RuntimeError("ANDROID_SDK_ROOT_NOT_READY")
        if inv.get("free_disk_gb") is not None and float(inv.get("free_disk_gb")) < 4.0:
            raise RuntimeError("INSUFFICIENT_FREE_DISK_FOR_ANDROID_VM")

        # VM provisioning owns its command-line frontend.  Do not mutate or replace the
        # known-good build-toolchain cmdline-tools tree merely because Google repository
        # metadata advanced to a newer XML schema.
        vm_tools = _home_vm_lab_bootstrap_cmdline_provider()
        sdkmanager = vm_tools.get("sdkmanager")
        if not sdkmanager:
            raise RuntimeError("VM_CMDLINE_TOOLS_PROVIDER_NOT_READY")
        sdk_root_avdmanager = _home_vm_lab_tool(sdk_root, ("cmdline-tools", "latest", "bin", "avdmanager"), None)
        if not sdk_root_avdmanager:
            sdk_root_avdmanager = _home_vm_lab_tool(sdk_root, ("tools", "bin", "avdmanager"), None)
        avdmanager_candidates = []
        if sdk_root_avdmanager:
            avdmanager_candidates.append(("SDK_ROOT_LOCAL", sdk_root_avdmanager))
        if vm_tools.get("avdmanager") and vm_tools.get("avdmanager") != sdk_root_avdmanager:
            avdmanager_candidates.append((f"VM_LOCAL_CURRENT_{ORFMOS_VM_LAB_CMDLINE_TOOLS_REVISION}", vm_tools.get("avdmanager")))
        if not avdmanager_candidates:
            raise RuntimeError("AVDMANAGER_PROVIDER_NOT_READY")
        vm_env = os.environ.copy()
        vm_env["ANDROID_SDK_ROOT"] = sdk_root
        vm_env["ANDROID_HOME"] = sdk_root

        _home_vm_lab_event(
            "PROVISION_BEGIN",
            f"candidates={'|'.join(ORFMOS_VM_LAB_SYSTEM_IMAGE_CANDIDATES)} sdk_root={sdk_root} cmdline_tools={ORFMOS_VM_LAB_CMDLINE_TOOLS_REVISION}",
        )
        try:
            rc, license_output = _home_vm_lab_run(
                [sdkmanager, f"--sdk_root={sdk_root}", "--licenses"],
                timeout=240, input_text="y\n" * 160, env=vm_env,
            )
            _home_vm_lab_event("LICENSE_PREPASS", f"rc={rc} tail={license_output[-500:]}")
        except Exception as exc:
            _home_vm_lab_event("LICENSE_PREPASS", f"{type(exc).__name__}: {exc}")
        # Install the common host components first, then resolve API 27 through
        # ordered provider candidates.  Android 8.1 Google APIs historically
        # exposes x86 rather than the unavailable google_apis/x86_64 identity.
        rc, output = _home_vm_lab_run(
            [sdkmanager, f"--sdk_root={sdk_root}", "platform-tools", "emulator"],
            timeout=2400, env=vm_env,
        )
        _home_vm_lab_event("SDKMANAGER_HOST_COMPONENTS", f"rc={rc} tail={output[-800:]}")
        if rc != 0:
            if "only understands SDK XML versions up to" in output or "SDK XML file of version" in output:
                raise RuntimeError("SDKMANAGER_XML_SCHEMA_INCOMPATIBLE_AFTER_PROVIDER_BOOTSTRAP")
            raise RuntimeError("SDKMANAGER_VM_HOST_COMPONENT_INSTALL_FAILED")

        resolved_image = None
        for image_id in ORFMOS_VM_LAB_SYSTEM_IMAGE_CANDIDATES:
            _home_vm_lab_event("SYSTEM_IMAGE_TRY", f"candidate={image_id}")
            rc, output = _home_vm_lab_run(
                [sdkmanager, f"--sdk_root={sdk_root}", image_id],
                timeout=2400, env=vm_env,
            )
            _home_vm_lab_event("SDKMANAGER_SYSTEM_IMAGE", f"candidate={image_id} rc={rc} tail={output[-800:]}")
            if rc == 0:
                inv_try = _home_vm_lab_inventory(include_packages=False)
                if inv_try.get("system_image_ready"):
                    resolved_image = inv_try.get("system_image") or image_id
                    _home_vm_lab_event("SYSTEM_IMAGE_ACCEPTED", f"resolved={resolved_image}")
                    break
            else:
                _home_vm_lab_event("SYSTEM_IMAGE_REJECTED", f"candidate={image_id} rc={rc}")
        if not resolved_image:
            raise RuntimeError("ANDROID_API27_SYSTEM_IMAGE_UNRESOLVED")

        inv = _home_vm_lab_inventory(include_packages=False)
        if not inv.get("system_image_ready") or not inv.get("emulator"):
            raise RuntimeError("VM_COMPONENT_READBACK_FAILED")
        resolved_image = inv.get("system_image") or resolved_image
        if not inv.get("avd_ready"):
            avd_created = False
            for avd_provider, avdmanager_path in avdmanager_candidates:
                _home_vm_lab_event("AVDMANAGER_TRY", f"provider={avd_provider} image={resolved_image}")
                try:
                    avd_path = Path(avdmanager_path)
                    if not avd_path.is_file():
                        _home_vm_lab_event("AVDMANAGER_REJECTED", f"provider={avd_provider} reason=FILE_MISSING path={avdmanager_path}")
                        continue
                    if not os.access(str(avd_path), os.X_OK):
                        before_mode = oct(avd_path.stat().st_mode & 0o777)
                        avd_path.chmod(avd_path.stat().st_mode | 0o111)
                        after_mode = oct(avd_path.stat().st_mode & 0o777)
                        _home_vm_lab_event("AVDMANAGER_EXECUTABLE_FIX", f"provider={avd_provider} mode={before_mode}->{after_mode} path={avdmanager_path}")
                    if not os.access(str(avd_path), os.X_OK):
                        _home_vm_lab_event("AVDMANAGER_REJECTED", f"provider={avd_provider} reason=NOT_EXECUTABLE path={avdmanager_path}")
                        continue
                    _home_vm_lab_event("AVDMANAGER_EXECUTABLE_VERIFIED", f"provider={avd_provider} path={avdmanager_path}")
                except Exception as exc:
                    _home_vm_lab_event("AVDMANAGER_REJECTED", f"provider={avd_provider} reason=EXECUTABLE_PREFLIGHT_FAILED error={type(exc).__name__}:{exc}")
                    continue
                rc, output = _home_vm_lab_run(
                    [avdmanager_path, "create", "avd", "--force", "--name", ORFMOS_VM_LAB_AVD_NAME, "--package", resolved_image],
                    timeout=120,
                    input_text="no\n",
                    env=vm_env,
                )
                _home_vm_lab_event("AVDMANAGER", f"provider={avd_provider} image={resolved_image} rc={rc} tail={output[-800:]}")
                if rc == 0:
                    avd_created = True
                    _home_vm_lab_event("AVDMANAGER_ACCEPTED", f"provider={avd_provider} image={resolved_image}")
                    break
                _home_vm_lab_event("AVDMANAGER_REJECTED", f"provider={avd_provider} rc={rc}")
            if not avd_created:
                raise RuntimeError("AVD_CREATE_FAILED_ALL_PROVIDERS")
        inv = _home_vm_lab_inventory(include_packages=False)
        if not inv.get("avd_ready"):
            raise RuntimeError("AVD_READBACK_FAILED")
        globals()["__ORFMOS_VM_LAB_MESSAGE__"] = "ANDROID VM HOST PROVISIONED; START VM WHEN READY"
        globals()["__ORFMOS_VM_LAB_LAST_RESULT__"] = "PROVISIONED"
        _home_vm_lab_event("PROVISION_VERIFIED", f"avd={ORFMOS_VM_LAB_AVD_NAME} image={resolved_image}")
    except Exception as exc:
        globals()["__ORFMOS_VM_LAB_MESSAGE__"] = f"{type(exc).__name__}: {exc}"
        globals()["__ORFMOS_VM_LAB_LAST_RESULT__"] = "PROVISION_FAILED"
        _home_vm_lab_event("PROVISION_FAILED", globals()["__ORFMOS_VM_LAB_MESSAGE__"])
    finally:
        globals()["__ORFMOS_VM_LAB_OPERATION_COMPLETED_EPOCH__"] = time.time()
        globals()["__ORFMOS_VM_LAB_BUSY__"] = False
        globals()["__ORFMOS_VM_LAB_OPERATION__"] = ""


def _home_vm_lab_provision_http():
    with _ORFMOS_VM_LAB_LOCK:
        if globals().get("__ORFMOS_VM_LAB_BUSY__"):
            return _home_vm_lab_state_from_inventory()
        globals()["__ORFMOS_VM_LAB_BUSY__"] = True
        globals()["__ORFMOS_VM_LAB_OPERATION__"] = "PROVISIONING"
        globals()["__ORFMOS_VM_LAB_OPERATION_STARTED_EPOCH__"] = time.time()
        globals()["__ORFMOS_VM_LAB_OPERATION_COMPLETED_EPOCH__"] = None
        globals()["__ORFMOS_VM_LAB_LAST_RESULT__"] = ""
        thread = threading.Thread(target=_home_vm_lab_provision_worker, name="orfmos-vm-lab-provision", daemon=True)
        globals()["__ORFMOS_VM_LAB_PROVISION_THREAD__"] = thread
        thread.start()
        return _home_vm_lab_state_from_inventory()


def _home_vm_lab_boot_monitor():
    try:
        inv = _home_vm_lab_inventory(include_packages=False)
        adb = inv.get("adb")
        if not adb:
            raise RuntimeError("ADB_NOT_AVAILABLE_AFTER_VM_START")
        deadline = time.time() + 360
        framework_announced = False
        while time.time() < deadline:
            inv = _home_vm_lab_inventory(include_packages=False)
            if inv.get("boot_completed"):
                globals()["__ORFMOS_VM_LAB_MESSAGE__"] = "ANDROID GUEST BOOT COMPLETE; INSTALLER PROVIDER RESOLVES INDEPENDENTLY"
                globals()["__ORFMOS_VM_LAB_LAST_RESULT__"] = "VM_READY"
                _home_vm_lab_event("VM_READY", f"serial={ORFMOS_VM_LAB_SERIAL} acceleration={inv.get('acceleration')}")
                return
            if inv.get("framework_ready") and not framework_announced:
                framework_announced = True
                globals()["__ORFMOS_VM_LAB_MESSAGE__"] = "ANDROID FRAMEWORK LIFECYCLE OBSERVED; WAITING FOR SYS.BOOT_COMPLETED"
                globals()["__ORFMOS_VM_LAB_LAST_RESULT__"] = "VM_FRAMEWORK_READY"
                _home_vm_lab_event("VM_FRAMEWORK_READY", f"serial={ORFMOS_VM_LAB_SERIAL}")
            if not inv.get("process_alive") and not inv.get("running"):
                raise RuntimeError("EMULATOR_PROCESS_AND_ADB_LOST")
            time.sleep(3)
        inv = _home_vm_lab_inventory(include_packages=False)
        if inv.get("running") or inv.get("process_alive"):
            globals()["__ORFMOS_VM_LAB_MESSAGE__"] = "BOOT WAIT WINDOW EXCEEDED; GUEST STILL ALIVE AND WILL CONTINUE TO BE OBSERVED"
            globals()["__ORFMOS_VM_LAB_LAST_RESULT__"] = "VM_BOOT_WAIT_EXCEEDED"
            _home_vm_lab_event(
                "VM_BOOT_WAIT_EXCEEDED",
                f"serial={ORFMOS_VM_LAB_SERIAL} adb={inv.get('adb_state')} framework_ready={inv.get('framework_ready')} boot_completed={inv.get('boot_completed')}",
            )
            return
        raise RuntimeError("ANDROID_VM_BOOT_TIMEOUT_GUEST_NOT_ALIVE")
    except Exception as exc:
        globals()["__ORFMOS_VM_LAB_MESSAGE__"] = f"{type(exc).__name__}: {exc}"
        globals()["__ORFMOS_VM_LAB_LAST_RESULT__"] = "VM_BOOT_FAILED"
        _home_vm_lab_event("VM_BOOT_FAILED", globals()["__ORFMOS_VM_LAB_MESSAGE__"])
    finally:
        globals()["__ORFMOS_VM_LAB_OPERATION_COMPLETED_EPOCH__"] = time.time()
        globals()["__ORFMOS_VM_LAB_BUSY__"] = False
        globals()["__ORFMOS_VM_LAB_OPERATION__"] = ""


def _home_vm_lab_start_http():
    with _ORFMOS_VM_LAB_LOCK:
        inv = _home_vm_lab_inventory(include_packages=False)
        if inv.get("boot_completed") or inv.get("running"):
            return _home_vm_lab_state_from_inventory(inv)
        if globals().get("__ORFMOS_VM_LAB_BUSY__"):
            return _home_vm_lab_state_from_inventory(inv)
        if not inv.get("emulator") or not inv.get("adb") or not inv.get("avd_ready"):
            globals()["__ORFMOS_VM_LAB_MESSAGE__"] = "VM NOT PROVISIONED; RUN PROVISION API27 FIRST"
            _home_vm_lab_event("VM_START_BLOCKED", globals()["__ORFMOS_VM_LAB_MESSAGE__"])
            return _home_vm_lab_state_from_inventory(inv)

        _home_vm_lab_clear_readiness_latch("VM_START_NEW_PROCESS")
        globals()["__ORFMOS_VM_LAB_READINESS_LATCH_REPORTED__"] = ""
        os.makedirs(ORFMOS_VM_LAB_RUNTIME_ROOT, exist_ok=True)
        log_path = os.path.join(ORFMOS_VM_LAB_RUNTIME_ROOT, "emulator.log")
        cmd = [
            inv["emulator"], "-avd", ORFMOS_VM_LAB_AVD_NAME,
            "-port", "5554", "-no-window", "-no-audio", "-no-boot-anim",
            "-gpu", "swiftshader_indirect", "-no-snapshot-save", "-memory", "1536",
        ]
        if not inv.get("kvm"):
            cmd += ["-accel", "off"]
        log_handle = open(log_path, "ab", buffering=0)
        process = subprocess.Popen(cmd, stdout=log_handle, stderr=subprocess.STDOUT, start_new_session=True)
        log_handle.close()
        globals()["__ORFMOS_VM_LAB_PROCESS__"] = process
        try:
            Path(ORFMOS_VM_LAB_PID_PATH).write_text(str(process.pid) + "\n", encoding="utf-8")
        except Exception:
            pass
        try:
            instance = _home_vm_lab_write_instance(process.pid)
            _home_vm_lab_event("VM_INSTANCE_CREATED", f"generation={instance.get('generation')} pid={process.pid} serial={ORFMOS_VM_LAB_SERIAL}")
        except Exception as exc:
            _home_vm_lab_event("VM_INSTANCE_PERSIST_FAILED", f"{type(exc).__name__}: {exc}")
        globals()["__ORFMOS_VM_LAB_BUSY__"] = True
        globals()["__ORFMOS_VM_LAB_OPERATION__"] = "VM_BOOTING"
        globals()["__ORFMOS_VM_LAB_OPERATION_STARTED_EPOCH__"] = time.time()
        globals()["__ORFMOS_VM_LAB_OPERATION_COMPLETED_EPOCH__"] = None
        globals()["__ORFMOS_VM_LAB_LAST_RESULT__"] = ""
        globals()["__ORFMOS_VM_LAB_MESSAGE__"] = "ANDROID GUEST STARTED; WAITING FOR SYS.BOOT_COMPLETED"
        _home_vm_lab_event("VM_START", f"pid={process.pid} accel={'KVM' if inv.get('kvm') else 'SOFTWARE_TCG'} log={log_path}")
        thread = threading.Thread(target=_home_vm_lab_boot_monitor, name="orfmos-vm-lab-boot", daemon=True)
        globals()["__ORFMOS_VM_LAB_BOOT_THREAD__"] = thread
        thread.start()
        return _home_vm_lab_state_from_inventory(_home_vm_lab_inventory(include_packages=False))


def _home_vm_lab_stop_http():
    with _ORFMOS_VM_LAB_LOCK:
        inv = _home_vm_lab_inventory(include_packages=False)
        adb = inv.get("adb")
        if adb and inv.get("running"):
            try:
                rc, output = _home_vm_lab_run([adb, "-s", ORFMOS_VM_LAB_SERIAL, "emu", "kill"], timeout=15)
                _home_vm_lab_event("VM_STOP_ADB", f"rc={rc} tail={output[-400:]}")
            except Exception as exc:
                _home_vm_lab_event("VM_STOP_ADB_FAILED", f"{type(exc).__name__}: {exc}")
        proc = globals().get("__ORFMOS_VM_LAB_PROCESS__")
        if proc is not None and getattr(proc, "poll", lambda: 0)() is None:
            try:
                proc.terminate()
            except Exception:
                pass
        recovered_pid = inv.get("process_pid")
        if recovered_pid and inv.get("process_alive") and not inv.get("running"):
            try:
                os.kill(int(recovered_pid), 15)
            except Exception:
                pass
        globals()["__ORFMOS_VM_LAB_PROCESS__"] = None
        _home_vm_lab_guest_channel_reset_all("VM_STOP")
        _home_vm_lab_clear_readiness_latch("VM_STOP")
        _home_vm_lab_clear_instance("VM_STOP")
        globals()["__ORFMOS_VM_LAB_READINESS_LATCH_REPORTED__"] = ""
        try:
            if os.path.isfile(ORFMOS_VM_LAB_PID_PATH):
                os.remove(ORFMOS_VM_LAB_PID_PATH)
        except Exception:
            pass
        globals()["__ORFMOS_VM_LAB_BUSY__"] = False
        globals()["__ORFMOS_VM_LAB_OPERATION__"] = ""
        globals()["__ORFMOS_VM_LAB_OPERATION_COMPLETED_EPOCH__"] = time.time()
        globals()["__ORFMOS_VM_LAB_LAST_RESULT__"] = "VM_STOPPED"
        globals()["__ORFMOS_VM_LAB_MESSAGE__"] = "ANDROID VM STOP REQUESTED"
        _home_vm_lab_event("VM_STOP", f"serial={ORFMOS_VM_LAB_SERIAL}")
        return _home_vm_lab_state_from_inventory(_home_vm_lab_inventory(include_packages=False))


ORFMOS_VM_GUEST_REGISTRY_SCHEMA = "ORFMOS_VM_GUEST_APPLICATION_REGISTRY_V0_1"
ORFMOS_VM_GUEST_APP_MANIFEST_SCHEMA = "ORFMOS_GUEST_APPLICATION_MANIFEST_V0_1"
ORFMOS_VM_GUEST_PRESENTATION_SCHEMA = "ORFMOS_VM_GUEST_PRESENTATION_STATE_V0_2"
ORFMOS_VM_DEVICE_PRESENTATION_MANIFEST_SCHEMA = "ORFMOS_VIRTUAL_DEVICE_PRESENTATION_MANIFEST_V0_1"
ORFMOS_VM_GUEST_PRESENTATION_ROOT = os.path.join(ORFMOS_VM_LAB_RUNTIME_ROOT, "presentation")
_ORFMOS_VM_GUEST_REGISTRY_LOCK = threading.RLock()
_ORFMOS_VM_GUEST_LAUNCH_LOCK = globals().get("_ORFMOS_VM_GUEST_LAUNCH_LOCK") or threading.RLock()
globals()["_ORFMOS_VM_GUEST_LAUNCH_LOCK"] = _ORFMOS_VM_GUEST_LAUNCH_LOCK
if not isinstance(globals().get("__ORFMOS_VM_GUEST_LAUNCH_STATES__"), dict):
    globals()["__ORFMOS_VM_GUEST_LAUNCH_STATES__"] = {}


def _home_vm_lab_virtual_device_presentation_manifest():
    return {
        "schema": ORFMOS_VM_DEVICE_PRESENTATION_MANIFEST_SCHEMA,
        "device_class": "ANDROID_VIRTUAL_DEVICE",
        "runtime_provider": "ANDROID_VM_LAB",
        "input_method": {
            "capability": "VARIABLE_INPUT_METHOD",
            "provider": "ANDROID_ADB_INPUT",
            "resolved_from": "ADB_SHELL_INPUT",
            "actions": ["TAP", "SWIPE", "BACK", "HOME", "RECENTS"],
        },
        "output_method": {
            "capability": "VARIABLE_OUTPUT_METHOD",
            "provider": "ANDROID_ADB_SCREENCAP",
            "resolved_from": "ADB_EXEC_OUT_SCREEN_CAPTURE",
            "modes": ["FRAME_SNAPSHOT"],
        },
        "presentation_shell": {
            "provider": "ORFMOS_PRESENTATION_SHELL",
            "controls": ["FULL_VIEWPORT", "RESTORE", "MINIMIZE", "BACK", "HOME", "RECENTS"],
            "ownership": "ORFMOS",
        },
    }


def _home_vm_lab_guest_default_launch_state(package_name=""):
    return {
        "schema": ORFMOS_VM_GUEST_PRESENTATION_SCHEMA,
        "package_name": str(package_name or ""),
        "state": "IDLE",
        "component": "",
        "activity_verified": False,
        "foreground_component": "",
        "presentation_state": "NOT_PRESENTED",
        "presentation_provider": "NONE",
        "presentation_generation": 0,
        "presentation_path": "",
        "frame_width": 0,
        "frame_height": 0,
        "input_state": "READY",
        "input_action": "",
        "input_provider": "ANDROID_ADB_INPUT",
        "input_delivery_state": "READY",
        "input_frame_changed": None,
        "last_input_epoch": None,
        "device_manifest": _home_vm_lab_virtual_device_presentation_manifest(),
        "started_epoch": None,
        "updated_epoch": time.time(),
        "message": "READY TO LAUNCH",
        "last_error": "",
        "launch_result": "",
    }


def _home_vm_lab_guest_launch_state(package_name):
    package_name = str(package_name or "").strip()
    with _ORFMOS_VM_GUEST_LAUNCH_LOCK:
        states = globals().get("__ORFMOS_VM_GUEST_LAUNCH_STATES__") or {}
        value = states.get(package_name)
        result = dict(value) if isinstance(value, dict) else _home_vm_lab_guest_default_launch_state(package_name)
        result.setdefault("input_state", "READY")
        result.setdefault("input_action", "")
        result.setdefault("input_provider", "ANDROID_ADB_INPUT")
        result.setdefault("input_delivery_state", "READY")
        result.setdefault("input_frame_changed", None)
        result.setdefault("frame_width", 0)
        result.setdefault("frame_height", 0)
        result["device_manifest"] = _home_vm_lab_virtual_device_presentation_manifest()
        return result


def _home_vm_lab_guest_set_launch_state(package_name, **updates):
    package_name = str(package_name or "").strip()
    with _ORFMOS_VM_GUEST_LAUNCH_LOCK:
        states = dict(globals().get("__ORFMOS_VM_GUEST_LAUNCH_STATES__") or {})
        value = states.get(package_name)
        value = dict(value) if isinstance(value, dict) else _home_vm_lab_guest_default_launch_state(package_name)
        value.update(updates)
        value["package_name"] = package_name
        value["updated_epoch"] = time.time()
        states[package_name] = value
        globals()["__ORFMOS_VM_GUEST_LAUNCH_STATES__"] = states
        return dict(value)


def _home_vm_lab_guest_manifest_from_registry(package_name):
    package_name = str(package_name or "").strip()
    for cache_key in ("__ORFMOS_VM_GUEST_REGISTRY_CACHE__", "__ORFMOS_VM_GUEST_REGISTRY_LAST_READY_CACHE__"):
        cache = globals().get(cache_key)
        if not isinstance(cache, dict):
            continue
        for app_manifest in cache.get("apps") or []:
            if isinstance(app_manifest, dict) and app_manifest.get("package_name") == package_name:
                return dict(app_manifest)
    return None


def _home_vm_lab_guest_attach_runtime_states(payload):
    result = dict(payload or {})
    apps = []
    for app_manifest in result.get("apps") or []:
        item = dict(app_manifest or {})
        item["runtime_state"] = _home_vm_lab_guest_launch_state(item.get("package_name"))
        apps.append(item)
    result["apps"] = apps
    return result


def _home_vm_lab_guest_resolve_activity(adb, package_name):
    package_name = str(package_name or "").strip()
    if not package_name:
        return None
    commands = (
        [adb, "-s", ORFMOS_VM_LAB_SERIAL, "shell", "cmd", "package", "resolve-activity", "--brief", "-a", "android.intent.action.MAIN", "-c", "android.intent.category.LAUNCHER", package_name],
        [adb, "-s", ORFMOS_VM_LAB_SERIAL, "shell", "cmd", "package", "resolve-activity", "--brief", package_name],
    )
    for command in commands:
        try:
            rc, output = _home_vm_lab_run(command, timeout=10)
        except Exception:
            continue
        if rc != 0:
            continue
        for line in reversed(str(output or "").splitlines()):
            candidate = line.strip()
            if not candidate or "/" not in candidate or "No activity" in candidate:
                continue
            if re.fullmatch(r"[A-Za-z0-9_.$]+/[A-Za-z0-9_.$]+", candidate):
                return candidate
    return None


def _home_vm_lab_guest_package_manifest(adb, package_name):
    package_name = str(package_name or "").strip()
    package_paths = []
    version_name = None
    version_code = None
    try:
        rc, output = _home_vm_lab_run([adb, "-s", ORFMOS_VM_LAB_SERIAL, "shell", "pm", "path", package_name], timeout=10)
        if rc == 0:
            package_paths = [line.split("package:", 1)[-1].strip() for line in output.splitlines() if line.strip().startswith("package:")]
    except Exception:
        pass
    try:
        rc, output = _home_vm_lab_run([adb, "-s", ORFMOS_VM_LAB_SERIAL, "shell", "dumpsys", "package", package_name], timeout=12)
        if rc == 0:
            m = re.search(r"\\bversionName=([^\\s]+)", output)
            if m:
                version_name = m.group(1).strip()
            m = re.search(r"\\bversionCode=(\\d+)", output)
            if m:
                version_code = m.group(1).strip()
    except Exception:
        pass
    launch_activity = _home_vm_lab_guest_resolve_activity(adb, package_name)
    return {
        "schema": ORFMOS_VM_GUEST_APP_MANIFEST_SCHEMA,
        "object_type": "APPLICATION",
        "container": "ANDROID_INSTALLED_PACKAGE",
        "package_name": package_name,
        "version_name": version_name,
        "version_code": version_code,
        "provider": "ANDROID_VM_LAB",
        "resolved_from": "ANDROID_PACKAGE_MANAGER",
        "package_paths": package_paths,
        "launch_activity": launch_activity,
        "launchable": bool(launch_activity),
        "linked_resources": [
            {"role": "PACKAGE_PATH", "uri": p, "provider": "ANDROID_GUEST_FILESYSTEM"}
            for p in package_paths
        ] + ([{"role": "LAUNCH_COMPONENT", "uri": launch_activity, "provider": "ANDROID_ACTIVITY_MANAGER"}] if launch_activity else []),
        "capabilities": ["PACKAGE_QUERY"] + (["EXPLICIT_LAUNCH"] if launch_activity else []),
    }



def _home_vm_lab_guest_registry_status_payload():
    cache = globals().get("__ORFMOS_VM_GUEST_REGISTRY_CACHE__")
    if isinstance(cache, dict) and cache.get("state") in {"READY", "READY_STALE"} and not globals().get("__ORFMOS_VM_GUEST_REGISTRY_ACTIVE__", False):
        return _home_vm_lab_guest_attach_runtime_states(cache)
    started = globals().get("__ORFMOS_VM_GUEST_REGISTRY_STARTED_EPOCH__")
    elapsed = max(0.0, time.time() - float(started)) if started else 0.0
    return {
        "schema": ORFMOS_VM_GUEST_REGISTRY_SCHEMA,
        "state": "RESOLVING" if globals().get("__ORFMOS_VM_GUEST_REGISTRY_ACTIVE__", False) else "IDLE",
        "route_revision": ORFMOS_VM_LAB_ROUTE_REVISION,
        "provider": "ANDROID_PACKAGE_MANAGER",
        "resolved_from": "ANDROID_VM_LAB",
        "apps": [],
        "package_index": int(globals().get("__ORFMOS_VM_GUEST_REGISTRY_PACKAGE_INDEX__", 0) or 0),
        "package_total": int(globals().get("__ORFMOS_VM_GUEST_REGISTRY_PACKAGE_TOTAL__", 0) or 0),
        "current_package": str(globals().get("__ORFMOS_VM_GUEST_REGISTRY_CURRENT_PACKAGE__", "") or ""),
        "elapsed_seconds": round(elapsed, 1),
        "message": str(globals().get("__ORFMOS_VM_GUEST_REGISTRY_MESSAGE__", "PACKAGE REGISTRY IDLE") or ""),
    }


def _home_vm_lab_guest_query_user_packages(adb):
    """Resolve user-package enumeration through bounded, observable providers.

    PackageManager on the API27 software-TCG guest can legitimately take far longer
    than 15 seconds after boot/install.  This function only runs in the background
    registry worker, so its time budgets do not hold an HTTP request open.
    """
    attempts = []
    providers = (
        ("ANDROID_CMD_PACKAGE", "cmd package list packages -3", 60),
        ("ANDROID_PM_WRAPPER", "pm list packages -3", 120),
    )
    for provider, command, timeout_seconds in providers:
        globals()["__ORFMOS_VM_GUEST_REGISTRY_MESSAGE__"] = f"QUERYING USER PACKAGES · {provider}"
        started = time.time()
        try:
            rc, output, channel_elapsed = _home_vm_lab_guest_channel_exec(adb, command, timeout=timeout_seconds, channel_name="PACKAGE")
        except subprocess.TimeoutExpired:
            elapsed = round(max(0.0, time.time() - started), 1)
            stimulus = _home_vm_lab_guest_stimulus_probe(adb, domain="PACKAGE")
            attempts.append({"provider": provider, "state": "TIMEOUT", "timeout_seconds": timeout_seconds, "elapsed_seconds": elapsed, "transport": "PERSISTENT_GUEST_SHELL", "stimulus": stimulus})
            _home_vm_lab_event("GUEST_PACKAGE_QUERY_PROVIDER_TIMEOUT", f"provider={provider} timeout={timeout_seconds}s transport=PERSISTENT_GUEST_SHELL stimulus={stimulus.get('state')}")
            continue
        except Exception as exc:
            elapsed = round(max(0.0, time.time() - started), 1)
            attempts.append({"provider": provider, "state": "ERROR", "elapsed_seconds": elapsed, "detail": f"{type(exc).__name__}: {exc}"[-300:]})
            _home_vm_lab_event("GUEST_PACKAGE_QUERY_PROVIDER_ERROR", f"provider={provider} error={type(exc).__name__}")
            continue
        elapsed = round(max(0.0, time.time() - started), 1)
        if rc == 0:
            packages = sorted({line.split("package:", 1)[-1].strip() for line in str(output or "").splitlines() if line.strip().startswith("package:")})[:80]
            attempts.append({"provider": provider, "state": "ACCEPTED", "elapsed_seconds": elapsed, "package_count": len(packages), "transport": "PERSISTENT_GUEST_SHELL"})
            _home_vm_lab_event("GUEST_PACKAGE_QUERY_PROVIDER_ACCEPTED", f"provider={provider} packages={len(packages)} elapsed={elapsed}s transport=PERSISTENT_GUEST_SHELL")
            return provider, packages, attempts
        detail = str(output or "")[-400:].replace("\n", " ")
        attempts.append({"provider": provider, "state": "REJECTED", "returncode": rc, "elapsed_seconds": elapsed, "detail": detail})
        _home_vm_lab_event("GUEST_PACKAGE_QUERY_PROVIDER_REJECTED", f"provider={provider} rc={rc}")
    summary = "; ".join(f"{item.get('provider')}={item.get('state')}" for item in attempts) or "NO_PROVIDER_ATTEMPTED"
    raise RuntimeError("PACKAGE_QUERY_UNRESOLVED: " + summary)


def _home_vm_lab_guest_registry_worker():
    try:
        inv = _home_vm_lab_inventory(include_packages=False)
        if not (inv.get("boot_completed") or inv.get("framework_ready")):
            raise RuntimeError("ANDROID_FRAMEWORK_NOT_READY")
        adb = inv.get("adb")
        if not adb:
            raise RuntimeError("ADB_UNAVAILABLE")
        globals()["__ORFMOS_VM_GUEST_REGISTRY_MESSAGE__"] = "QUERYING USER PACKAGES"
        query_provider, packages, query_trace = _home_vm_lab_guest_query_user_packages(adb)
        globals()["__ORFMOS_VM_GUEST_REGISTRY_PACKAGE_TOTAL__"] = len(packages)
        apps = []
        for index, package_name in enumerate(packages, 1):
            globals()["__ORFMOS_VM_GUEST_REGISTRY_PACKAGE_INDEX__"] = index
            globals()["__ORFMOS_VM_GUEST_REGISTRY_CURRENT_PACKAGE__"] = package_name
            globals()["__ORFMOS_VM_GUEST_REGISTRY_MESSAGE__"] = f"RESOLVING {package_name}"
            apps.append(_home_vm_lab_guest_package_manifest(adb, package_name))
        result = {
            "schema": ORFMOS_VM_GUEST_REGISTRY_SCHEMA,
            "state": "READY",
            "route_revision": ORFMOS_VM_LAB_ROUTE_REVISION,
            "provider": query_provider,
            "resolved_from": "ANDROID_VM_LAB",
            "query_trace": query_trace,
            "apps": apps,
            "package_index": len(packages),
            "package_total": len(packages),
            "current_package": "",
            "elapsed_seconds": round(max(0.0, time.time() - float(globals().get("__ORFMOS_VM_GUEST_REGISTRY_STARTED_EPOCH__") or time.time())), 1),
            "message": f"{len(apps)} USER PACKAGES DISCOVERED",
        }
        globals()["__ORFMOS_VM_GUEST_REGISTRY_CACHE__"] = result
        globals()["__ORFMOS_VM_GUEST_REGISTRY_LAST_READY_CACHE__"] = dict(result)
        globals()["__ORFMOS_VM_GUEST_REGISTRY_MESSAGE__"] = result["message"]
        globals()["__ORFMOS_VM_GUEST_REGISTRY_LAST_ERROR__"] = ""
        _home_vm_lab_event("GUEST_APP_REGISTRY", f"packages={len(apps)} launchable={sum(1 for app in apps if app.get('launchable'))} async=YES")
    except Exception as exc:
        message = f"{type(exc).__name__}: {exc}"
        globals()["__ORFMOS_VM_GUEST_REGISTRY_LAST_ERROR__"] = message
        globals()["__ORFMOS_VM_GUEST_REGISTRY_MESSAGE__"] = message
        last_ready = globals().get("__ORFMOS_VM_GUEST_REGISTRY_LAST_READY_CACHE__")
        if isinstance(last_ready, dict) and last_ready.get("state") == "READY":
            stale = dict(last_ready)
            stale["state"] = "READY_STALE"
            stale["route_revision"] = ORFMOS_VM_LAB_ROUTE_REVISION
            stale["warning"] = message
            stale["message"] = "LAST VERIFIED REGISTRY PRESERVED · REFRESH FAILED: " + message
            globals()["__ORFMOS_VM_GUEST_REGISTRY_CACHE__"] = stale
            _home_vm_lab_event("GUEST_APP_REGISTRY_STALE_PRESERVED", message[-600:])
        else:
            globals()["__ORFMOS_VM_GUEST_REGISTRY_CACHE__"] = {
                "schema": ORFMOS_VM_GUEST_REGISTRY_SCHEMA,
                "state": "FAILED",
                "route_revision": ORFMOS_VM_LAB_ROUTE_REVISION,
                "provider": "ANDROID_PACKAGE_MANAGER",
                "resolved_from": "ANDROID_VM_LAB",
                "apps": [],
                "message": message,
            }
            _home_vm_lab_event("GUEST_APP_REGISTRY_FAILED", message[-600:])
    finally:
        globals()["__ORFMOS_VM_GUEST_REGISTRY_ACTIVE__"] = False
        globals()["__ORFMOS_VM_GUEST_REGISTRY_COMPLETED_EPOCH__"] = time.time()
        globals()["__ORFMOS_VM_GUEST_REGISTRY_CURRENT_PACKAGE__"] = ""


def _home_vm_lab_guest_apps_http(refresh: bool = False):
    inv = _home_vm_lab_inventory(include_packages=False)
    if not (inv.get("boot_completed") or inv.get("framework_ready")):
        return {"schema": ORFMOS_VM_GUEST_REGISTRY_SCHEMA, "state": "ANDROID_FRAMEWORK_NOT_READY", "route_revision": ORFMOS_VM_LAB_ROUTE_REVISION, "apps": [], "message": "ANDROID FRAMEWORK / PACKAGE MANAGER NOT READY"}
    if not inv.get("adb"):
        return {"schema": ORFMOS_VM_GUEST_REGISTRY_SCHEMA, "state": "ADB_UNAVAILABLE", "route_revision": ORFMOS_VM_LAB_ROUTE_REVISION, "apps": [], "message": "ADB UNAVAILABLE"}
    with _ORFMOS_VM_GUEST_REGISTRY_LOCK:
        active = bool(globals().get("__ORFMOS_VM_GUEST_REGISTRY_ACTIVE__", False))
        cache = globals().get("__ORFMOS_VM_GUEST_REGISTRY_CACHE__")
        if refresh and not active:
            globals()["__ORFMOS_VM_GUEST_REGISTRY_CACHE__"] = None
            cache = None
        if isinstance(cache, dict) and cache.get("state") in {"READY", "READY_STALE", "FAILED"} and not active:
            return _home_vm_lab_guest_attach_runtime_states(cache)
        if not active:
            globals()["__ORFMOS_VM_GUEST_REGISTRY_ACTIVE__"] = True
            globals()["__ORFMOS_VM_GUEST_REGISTRY_STARTED_EPOCH__"] = time.time()
            globals()["__ORFMOS_VM_GUEST_REGISTRY_COMPLETED_EPOCH__"] = None
            globals()["__ORFMOS_VM_GUEST_REGISTRY_PACKAGE_INDEX__"] = 0
            globals()["__ORFMOS_VM_GUEST_REGISTRY_PACKAGE_TOTAL__"] = 0
            globals()["__ORFMOS_VM_GUEST_REGISTRY_CURRENT_PACKAGE__"] = ""
            globals()["__ORFMOS_VM_GUEST_REGISTRY_MESSAGE__"] = "STARTING PACKAGE REGISTRY RESOLUTION"
            thread = threading.Thread(target=_home_vm_lab_guest_registry_worker, name="orfmos-vm-guest-registry", daemon=True)
            globals()["__ORFMOS_VM_GUEST_REGISTRY_THREAD__"] = thread
            thread.start()
            _home_vm_lab_event("GUEST_APP_REGISTRY_STARTED", f"refresh={bool(refresh)}")
        return _home_vm_lab_guest_registry_status_payload()


def _home_vm_lab_guest_foreground_component(adb):
    providers = (
        ("ANDROID_ACTIVITY_MANAGER", [adb, "-s", ORFMOS_VM_LAB_SERIAL, "shell", "dumpsys", "activity", "activities"], 18),
        ("ANDROID_WINDOW_MANAGER", [adb, "-s", ORFMOS_VM_LAB_SERIAL, "shell", "dumpsys", "window", "windows"], 18),
        ("ANDROID_ACTIVITY_TOP", [adb, "-s", ORFMOS_VM_LAB_SERIAL, "shell", "dumpsys", "activity", "top"], 18),
    )
    patterns = (
        r"mResumedActivity:\s+ActivityRecord\{[^}]*\s([A-Za-z0-9_.$]+/[A-Za-z0-9_.$]+)",
        r"mFocusedActivity:\s+ActivityRecord\{[^}]*\s([A-Za-z0-9_.$]+/[A-Za-z0-9_.$]+)",
        r"mCurrentFocus=Window\{[^}]*\s([A-Za-z0-9_.$]+/[A-Za-z0-9_.$]+)\}",
        r"\bACTIVITY\s+([A-Za-z0-9_.$]+/[A-Za-z0-9_.$]+)",
    )
    trace = []
    for provider, command, timeout in providers:
        try:
            rc, output = _home_vm_lab_run(command, timeout=timeout)
        except subprocess.TimeoutExpired:
            trace.append({"provider": provider, "state": "TIMEOUT"})
            continue
        except Exception as exc:
            trace.append({"provider": provider, "state": "ERROR", "detail": f"{type(exc).__name__}: {exc}"})
            continue
        text = str(output or "")
        if rc != 0:
            trace.append({"provider": provider, "state": "REJECTED", "returncode": rc})
            continue
        for pattern in patterns:
            match = re.search(pattern, text)
            if match:
                component = match.group(1).strip()
                trace.append({"provider": provider, "state": "ACCEPTED", "component": component})
                return component, provider, trace
        trace.append({"provider": provider, "state": "NO_COMPONENT"})
    return "", "NONE", trace


def _home_vm_lab_guest_capture_presentation(adb, package_name):
    os.makedirs(ORFMOS_VM_GUEST_PRESENTATION_ROOT, exist_ok=True)
    safe_name = re.sub(r"[^A-Za-z0-9_.-]+", "_", str(package_name or "package"))
    generation = int(time.time() * 1000)
    path = os.path.join(ORFMOS_VM_GUEST_PRESENTATION_ROOT, f"{safe_name}_{generation}.png")
    result = subprocess.run(
        [adb, "-s", ORFMOS_VM_LAB_SERIAL, "exec-out", "screencap", "-p"],
        capture_output=True,
        timeout=45,
        check=False,
    )
    payload = bytes(result.stdout or b"")
    if result.returncode != 0 or not payload.startswith(b"\x89PNG\r\n\x1a\n") or len(payload) < 1024:
        detail = bytes(result.stderr or b"")[-300:].decode("utf-8", errors="replace")
        raise RuntimeError(f"ANDROID_ADB_SCREENCAP_REJECTED rc={result.returncode} bytes={len(payload)} detail={detail}")
    width = int.from_bytes(payload[16:20], "big") if len(payload) >= 24 else 0
    height = int.from_bytes(payload[20:24], "big") if len(payload) >= 24 else 0
    if width <= 0 or height <= 0:
        raise RuntimeError("ANDROID_ADB_SCREENCAP_INVALID_DIMENSIONS")
    with open(path, "wb") as handle:
        handle.write(payload)
    return path, generation, len(payload), width, height


def _home_vm_lab_guest_launch_worker(package_name, manifest, adb):
    component = str((manifest or {}).get("launch_activity") or "").strip()
    try:
        _home_vm_lab_guest_set_launch_state(
            package_name,
            state="GUEST_APP_LAUNCHING",
            component=component,
            activity_verified=False,
            foreground_component="",
            presentation_state="NOT_PRESENTED",
            presentation_provider="NONE",
            presentation_generation=0,
            presentation_path="",
            frame_width=0,
            frame_height=0,
            input_state="READY",
            input_action="",
            device_manifest=_home_vm_lab_virtual_device_presentation_manifest(),
            started_epoch=time.time(),
            message=f"STARTING {component}",
            last_error="",
            launch_result="",
        )
        rc, output = _home_vm_lab_run(
            [adb, "-s", ORFMOS_VM_LAB_SERIAL, "shell", "am", "start", "-n", component],
            timeout=25,
        )
        text = str(output or "")
        accepted = rc == 0 and ("Starting: Intent" in text or "Activity not started" in text or "cmp=" in text)
        if not accepted:
            raise RuntimeError(text[-400:] or f"ACTIVITY_MANAGER_RC={rc}")
        _home_vm_lab_event("GUEST_APP_LAUNCH_ACCEPTED", f"package={package_name} component={component} tail={text[-300:].replace(chr(10),' ')}")
        _home_vm_lab_guest_set_launch_state(
            package_name,
            state="WAITING_FOR_FOREGROUND",
            launch_result=text.strip(),
            message="ACTIVITY START ACCEPTED · VERIFYING FOREGROUND",
        )

        verified_component = ""
        verified_provider = "NONE"
        verify_trace = []
        deadline = time.time() + 45.0
        while time.time() < deadline:
            foreground, provider, trace = _home_vm_lab_guest_foreground_component(adb)
            verify_trace.extend(trace)
            if foreground and foreground.split("/", 1)[0] == package_name:
                verified_component = foreground
                verified_provider = provider
                break
            time.sleep(1.5)
        if not verified_component:
            raise RuntimeError("FOREGROUND_VERIFICATION_TIMEOUT")
        _home_vm_lab_event("GUEST_APP_FOREGROUND_VERIFIED", f"package={package_name} component={verified_component} provider={verified_provider}")
        _home_vm_lab_guest_set_launch_state(
            package_name,
            state="WAITING_FOR_PRESENTATION",
            activity_verified=True,
            foreground_component=verified_component,
            foreground_provider=verified_provider,
            foreground_trace=verify_trace[-12:],
            presentation_state="CAPTURING",
            message="FOREGROUND VERIFIED · CAPTURING GUEST PRESENTATION",
        )

        path, generation, frame_bytes, frame_width, frame_height = _home_vm_lab_guest_capture_presentation(adb, package_name)
        _home_vm_lab_guest_set_launch_state(
            package_name,
            state="PRESENTED",
            presentation_state="PRESENTED",
            presentation_provider="ANDROID_ADB_SCREENCAP",
            presentation_generation=generation,
            presentation_path=path,
            frame_bytes=frame_bytes,
            frame_width=frame_width,
            frame_height=frame_height,
            input_state="READY",
            input_action="",
            input_provider="ANDROID_ADB_INPUT",
            device_manifest=_home_vm_lab_virtual_device_presentation_manifest(),
            message="APPLICATION FOREGROUND VERIFIED · GUEST FRAME PRESENTED",
        )
        _home_vm_lab_event("GUEST_APP_PRESENTED", f"package={package_name} component={verified_component} provider=ANDROID_ADB_SCREENCAP bytes={frame_bytes} generation={generation}")
        _home_vm_lab_event("GUEST_APP_LAUNCHED", f"package={package_name} component={component} foreground={verified_component} presentation=VERIFIED")
    except Exception as exc:
        message = f"{type(exc).__name__}: {exc}"
        _home_vm_lab_guest_set_launch_state(
            package_name,
            state="FAILED",
            presentation_state="FAILED",
            message=message,
            last_error=message,
        )
        _home_vm_lab_event("GUEST_APP_LAUNCH_FAILED", f"package={package_name} component={component} detail={message[-500:]}")


def _home_vm_lab_launch_http(package: str = ""):
    package_name = str(package or "").strip()
    if not re.fullmatch(r"[A-Za-z0-9_.]+", package_name):
        return {"schema": ORFMOS_VM_GUEST_REGISTRY_SCHEMA, "state": "INVALID_PACKAGE_ID", "message": "INVALID PACKAGE IDENTIFIER"}
    inv = _home_vm_lab_inventory(include_packages=False)
    if not (inv.get("boot_completed") or inv.get("framework_ready")):
        return {"schema": ORFMOS_VM_GUEST_REGISTRY_SCHEMA, "state": "ANDROID_FRAMEWORK_NOT_READY", "message": "ANDROID FRAMEWORK / ACTIVITY MANAGER NOT READY"}
    adb = inv.get("adb")
    if not adb:
        return {"schema": ORFMOS_VM_GUEST_REGISTRY_SCHEMA, "state": "ADB_UNAVAILABLE", "message": "ADB UNAVAILABLE"}
    manifest = _home_vm_lab_guest_manifest_from_registry(package_name) or _home_vm_lab_guest_package_manifest(adb, package_name)
    component = manifest.get("launch_activity")
    if not component:
        _home_vm_lab_event("GUEST_APP_LAUNCH_REJECTED", f"package={package_name} reason=NO_LAUNCHABLE_ACTIVITY")
        return {"schema": ORFMOS_VM_GUEST_REGISTRY_SCHEMA, "state": "NO_LAUNCHABLE_ACTIVITY", "manifest": manifest, "message": "NO MAIN/LAUNCHER ACTIVITY RESOLVED"}
    current = _home_vm_lab_guest_launch_state(package_name)
    if current.get("state") in {"GUEST_APP_LAUNCHING", "WAITING_FOR_FOREGROUND", "WAITING_FOR_PRESENTATION"}:
        return dict(current)
    thread = threading.Thread(
        target=_home_vm_lab_guest_launch_worker,
        args=(package_name, dict(manifest), adb),
        name=f"orfmos-vm-launch-{package_name}",
        daemon=True,
    )
    _home_vm_lab_guest_set_launch_state(
        package_name,
        state="GUEST_APP_LAUNCHING",
        component=component,
        activity_verified=False,
        presentation_state="NOT_PRESENTED",
        presentation_provider="NONE",
        presentation_generation=0,
        presentation_path="",
        frame_width=0,
        frame_height=0,
        input_state="READY",
        input_action="",
        device_manifest=_home_vm_lab_virtual_device_presentation_manifest(),
        started_epoch=time.time(),
        message="LAUNCH REQUEST ACCEPTED · BACKGROUND ACTIVITY START",
        last_error="",
    )
    thread.start()
    _home_vm_lab_event("GUEST_APP_LAUNCH_STARTED", f"package={package_name} component={component} async=YES")
    return _home_vm_lab_guest_launch_state(package_name)


def _home_vm_lab_presentation_http(package: str = ""):
    package_name = str(package or "").strip()
    if not re.fullmatch(r"[A-Za-z0-9_.]+", package_name):
        return Response(content=b"INVALID PACKAGE IDENTIFIER", status_code=400, media_type="text/plain")
    state = _home_vm_lab_guest_launch_state(package_name)
    path = str(state.get("presentation_path") or "")
    if state.get("state") != "PRESENTED" or not path or not os.path.isfile(path):
        return Response(content=b"PRESENTATION NOT READY", status_code=404, media_type="text/plain")
    try:
        with open(path, "rb") as handle:
            payload = handle.read()
    except Exception as exc:
        return Response(content=str(exc).encode("utf-8", errors="replace"), status_code=500, media_type="text/plain")
    return Response(
        content=payload,
        media_type="image/png",
        headers={"Cache-Control": "no-store", "X-ORFMOS-Presentation-Provider": str(state.get("presentation_provider") or "ANDROID_ADB_SCREENCAP")},
    )


def _home_vm_lab_presentation_state_http(package: str = ""):
    package_name = str(package or "").strip()
    if not re.fullmatch(r"[A-Za-z0-9_.]+", package_name):
        return {"schema": ORFMOS_VM_GUEST_PRESENTATION_SCHEMA, "state": "INVALID_PACKAGE_ID", "message": "INVALID PACKAGE IDENTIFIER"}
    return _home_vm_lab_guest_launch_state(package_name)


def _home_vm_lab_guest_post_input_foreground_worker(package_name, adb, action, generation):
    """Best-effort metadata enrichment. Never owns the presentation refresh critical path."""
    try:
        foreground, foreground_provider, foreground_trace = _home_vm_lab_guest_foreground_component(adb)
        current = _home_vm_lab_guest_launch_state(package_name)
        if int(current.get("presentation_generation") or 0) != int(generation or 0):
            _home_vm_lab_event("GUEST_INPUT_FOREGROUND_STALE", f"package={package_name} action={action} generation={generation}")
            return
        _home_vm_lab_guest_set_launch_state(
            package_name,
            foreground_component=foreground or current.get("foreground_component") or "",
            foreground_provider=foreground_provider or current.get("foreground_provider") or "NONE",
            foreground_trace=foreground_trace[-8:] if foreground_trace else current.get("foreground_trace", []),
        )
        _home_vm_lab_event(
            "GUEST_INPUT_FOREGROUND_OBSERVED",
            f"package={package_name} action={action} generation={generation} foreground={foreground or 'UNRESOLVED'} provider={foreground_provider or 'NONE'}",
        )
    except Exception as exc:
        _home_vm_lab_event("GUEST_INPUT_FOREGROUND_DEFERRED", f"package={package_name} action={action} detail={type(exc).__name__}:{exc}")


def _home_vm_lab_guest_post_input_ack_worker(package_name, action, generation, ack_result, ack_done):
    """Attach late command acknowledgement without delaying visible reaction.

    The successor frame is authoritative for the interaction critical path. This
    worker only enriches that already-presented state when CONTROL acknowledgement
    or the bounded stimulus probe finishes later.
    """
    try:
        ack_done.wait(timeout=max(12.0, float(ORFMOS_VM_GUEST_INPUT_ACK_TIMEOUT_SECONDS) + 8.0))
        result = dict(ack_result or {})
        current = _home_vm_lab_guest_launch_state(package_name)
        if int(current.get("presentation_generation") or 0) != int(generation or 0):
            _home_vm_lab_event("GUEST_INPUT_ACK_METADATA_STALE", f"package={package_name} action={action} generation={generation}")
            return
        ack_state = str(result.get("state") or "ACK_PENDING")
        ack_elapsed = result.get("elapsed")
        stimulus = result.get("stimulus")
        frame_changed = bool(current.get("input_frame_changed"))
        reaction_state = str(current.get("input_reaction_state") or "")
        delivery_state = str(current.get("input_delivery_state") or "")
        if frame_changed and ack_state == "ACK_STALLED":
            reaction_state = "INPUT_APPLIED_ACK_STALLED"
            delivery_state = "FRAME_VERIFIED_ACK_STALLED"
        elif frame_changed and ack_state in {"ACK_ERROR", "ACK_REJECTED"}:
            reaction_state = "INPUT_APPLIED_ACK_ANOMALOUS"
            delivery_state = "FRAME_VERIFIED_ACK_ANOMALOUS"
        elif frame_changed and ack_state == "ACKNOWLEDGED":
            reaction_state = "INPUT_VERIFIED"
            delivery_state = "CHANNEL_ACCEPTED_FRAME_VERIFIED"
        _home_vm_lab_guest_set_launch_state(
            package_name,
            input_delivery_state=delivery_state,
            input_reaction_state=reaction_state,
            input_ack_state=ack_state,
            input_ack_elapsed_seconds=ack_elapsed,
            input_stimulus_probe=stimulus,
            guest_command_channels=_home_vm_lab_guest_channel_snapshot(),
        )
        _home_vm_lab_event(
            "GUEST_INPUT_ACK_METADATA_FINALIZED",
            f"package={package_name} action={action} generation={generation} ack={ack_state} ack_elapsed={ack_elapsed}s stimulus={(stimulus or {}).get('state','NONE')} reaction={reaction_state or 'UNRESOLVED'}",
        )
    except Exception as exc:
        _home_vm_lab_event("GUEST_INPUT_ACK_METADATA_DEFERRED", f"package={package_name} action={action} detail={type(exc).__name__}:{exc}")


def _home_vm_lab_guest_input_worker(package_name, action, adb, x=-1, y=-1, x2=-1, y2=-1, duration=250):
    action = str(action or "").upper().strip()
    transaction_started = time.time()
    try:
        state = _home_vm_lab_guest_launch_state(package_name)
        manifest = state.get("device_manifest") or _home_vm_lab_virtual_device_presentation_manifest()
        allowed = set(((manifest.get("input_method") or {}).get("actions") or []))
        if action not in allowed:
            raise RuntimeError(f"UNSUPPORTED_INPUT_ACTION:{action}")
        if action == "TAP":
            shell_command = f"input tap {int(x)} {int(y)}"
        elif action == "SWIPE":
            shell_command = f"input swipe {int(x)} {int(y)} {int(x2)} {int(y2)} {max(50, min(2000, int(duration)))}"
        elif action == "BACK":
            shell_command = "input keyevent 4"
        elif action == "HOME":
            shell_command = "input keyevent 3"
        elif action == "RECENTS":
            shell_command = "input keyevent 187"
        else:
            raise RuntimeError(f"UNBOUND_INPUT_ACTION:{action}")

        prior_path = str(state.get("presentation_path") or "")
        prior_sha = ""
        if prior_path and os.path.isfile(prior_path):
            try:
                with open(prior_path, "rb") as handle:
                    prior_sha = hashlib.sha256(handle.read()).hexdigest()
            except Exception:
                prior_sha = ""

        coord_detail = ""
        if action == "TAP":
            coord_detail = f" x={int(x)} y={int(y)} frame={int(state.get('frame_width') or 0)}x{int(state.get('frame_height') or 0)}"
        elif action == "SWIPE":
            coord_detail = f" x={int(x)} y={int(y)} x2={int(x2)} y2={int(y2)} duration={int(duration)} frame={int(state.get('frame_width') or 0)}x{int(state.get('frame_height') or 0)}"

        # R77: dispatch acknowledgement and visual reaction are independent
        # observations of one state-changing command. Send the command once,
        # then begin frame acquisition as soon as the resident shell flushes it.
        command_started = time.time()
        dispatched = threading.Event()
        ack_done = threading.Event()
        ack_result = {"state": "ACK_PENDING", "elapsed": None, "stimulus": None, "detail": ""}

        def _ack_worker():
            try:
                rc, output, elapsed = _home_vm_lab_guest_channel_exec(
                    adb,
                    shell_command,
                    timeout=ORFMOS_VM_GUEST_INPUT_ACK_TIMEOUT_SECONDS,
                    channel_name="CONTROL",
                    dispatched_event=dispatched,
                )
                ack_result["elapsed"] = elapsed
                if rc == 0:
                    ack_result["state"] = "ACKNOWLEDGED"
                    _home_vm_lab_event(
                        "GUEST_INPUT_ACKNOWLEDGED",
                        f"package={package_name} action={action} provider=ANDROID_ADB_PERSISTENT_SHELL elapsed={elapsed}s{coord_detail}",
                    )
                else:
                    ack_result["state"] = "ACK_REJECTED"
                    ack_result["detail"] = str(output or "")[-300:]
                    _home_vm_lab_event(
                        "GUEST_INPUT_ACK_REJECTED",
                        f"package={package_name} action={action} rc={rc} elapsed={elapsed}s tail={ack_result['detail']}",
                    )
            except subprocess.TimeoutExpired:
                elapsed = round(max(0.0, time.time() - command_started), 3)
                ack_result["elapsed"] = elapsed
                ack_result["state"] = "ACK_STALLED"
                _home_vm_lab_event(
                    "GUEST_INPUT_ACK_STALLED",
                    f"package={package_name} action={action} elapsed={elapsed}s frame_observation=PARALLEL stimulus=STARTING",
                )
                # Never replay the state-changing command. A separate bounded,
                # non-mutating probe can stimulate a sluggish guest in parallel
                # with screencap acquisition.
                ack_result["stimulus"] = _home_vm_lab_guest_stimulus_probe(adb, domain="INPUT")
            except Exception as exc:
                ack_result["elapsed"] = round(max(0.0, time.time() - command_started), 3)
                ack_result["state"] = "ACK_ERROR"
                ack_result["detail"] = f"{type(exc).__name__}: {exc}"
                _home_vm_lab_event(
                    "GUEST_INPUT_ACK_ERROR",
                    f"package={package_name} action={action} elapsed={ack_result['elapsed']}s detail={ack_result['detail'][-300:]}",
                )
            finally:
                ack_done.set()

        threading.Thread(
            target=_ack_worker,
            name=f"orfmos-vm-input-ack-{package_name}-{action.lower()}",
            daemon=True,
        ).start()

        # Wait only for evidence that the input bytes were flushed into the
        # resident guest shell. Do not wait for command completion.
        dispatch_wait_started = time.time()
        dispatch_seen = dispatched.wait(timeout=2.5)
        dispatch_elapsed = round(max(0.0, time.time() - transaction_started), 3)
        if not dispatch_seen:
            _home_vm_lab_event(
                "GUEST_INPUT_DISPATCH_OBSERVATION_DELAYED",
                f"package={package_name} action={action} elapsed={round(time.time()-dispatch_wait_started,3)}s ack_state={ack_result.get('state')}",
            )

        _home_vm_lab_guest_set_launch_state(
            package_name,
            input_state="OBSERVING_REACTION",
            input_action=action,
            input_delivery_state="DISPATCHED_REACTION_PARALLEL" if dispatch_seen else "DISPATCH_UNCONFIRMED_REACTION_PARALLEL",
            input_provider="ANDROID_ADB_PERSISTENT_SHELL",
            input_ack_state=str(ack_result.get("state") or "ACK_PENDING"),
            input_ack_elapsed_seconds=ack_result.get("elapsed"),
            input_frame_observation_mode="FRAME_FIRST_PARALLEL",
            input_dispatch_elapsed_seconds=dispatch_elapsed,
            last_input_epoch=time.time(),
            message=f"INPUT {action} DISPATCHED · FRAME-FIRST REACTION OBSERVATION",
            last_error="",
        )
        _home_vm_lab_event(
            "GUEST_INPUT_FRAME_OBSERVATION_STARTED",
            f"package={package_name} action={action} provider=ANDROID_ADB_SCREENCAP mode=FRAME_FIRST_PARALLEL dispatch_seen={'YES' if dispatch_seen else 'NO'} dispatch_elapsed={dispatch_elapsed}s{coord_detail}",
        )

        # Frame observation begins immediately after dispatch rather than after
        # the acknowledgement/stimulus chain. This is the user-visible critical
        # path and may overlap both the 6s CONTROL timeout and INPUT stimulus.
        frame_started = time.time()
        time.sleep(0.05)
        path, generation, frame_bytes, frame_width, frame_height = _home_vm_lab_guest_capture_presentation(adb, package_name)
        with open(path, "rb") as handle:
            successor_sha = hashlib.sha256(handle.read()).hexdigest()
        frame_changed = bool(prior_sha and successor_sha != prior_sha)
        first_frame_elapsed = round(max(0.0, time.time() - frame_started), 3)

        if prior_sha and not frame_changed:
            time.sleep(0.35)
            retry_path, retry_generation, retry_bytes, retry_width, retry_height = _home_vm_lab_guest_capture_presentation(adb, package_name)
            with open(retry_path, "rb") as handle:
                retry_sha = hashlib.sha256(handle.read()).hexdigest()
            if retry_sha != prior_sha:
                path, generation, frame_bytes, frame_width, frame_height, successor_sha = retry_path, retry_generation, retry_bytes, retry_width, retry_height, retry_sha
                frame_changed = True

        frame_elapsed = round(max(0.0, time.time() - frame_started), 3)
        reaction_elapsed = round(max(0.0, time.time() - transaction_started), 3)

        # The visible reaction is not held hostage by acknowledgement. Snapshot
        # whatever ACK evidence exists now and allow late metadata enrichment.
        ack_state = str(ack_result.get("state") or "ACK_PENDING") if ack_done.is_set() else "ACK_PENDING"
        ack_elapsed = ack_result.get("elapsed") if ack_done.is_set() else None
        stimulus = ack_result.get("stimulus") if ack_done.is_set() else None
        if frame_changed and ack_state == "ACK_STALLED":
            delivery_state = "FRAME_VERIFIED_ACK_STALLED"
            reaction_state = "INPUT_APPLIED_ACK_STALLED"
        elif frame_changed and ack_state in {"ACK_ERROR", "ACK_REJECTED"}:
            delivery_state = "FRAME_VERIFIED_ACK_ANOMALOUS"
            reaction_state = "INPUT_APPLIED_ACK_ANOMALOUS"
        elif frame_changed and ack_state == "ACKNOWLEDGED":
            delivery_state = "CHANNEL_ACCEPTED_FRAME_VERIFIED"
            reaction_state = "INPUT_VERIFIED"
        elif frame_changed:
            delivery_state = "FRAME_VERIFIED_ACK_PENDING"
            reaction_state = "INPUT_APPLIED_ACK_PENDING"
        elif ack_state == "ACK_STALLED":
            delivery_state = "ACK_STALLED_NO_VISIBLE_CHANGE"
            reaction_state = "INPUT_REACTION_UNRESOLVED"
        elif ack_state == "ACKNOWLEDGED":
            delivery_state = "CHANNEL_ACCEPTED_NO_VISIBLE_CHANGE"
            reaction_state = "INPUT_ACCEPTED_NO_VISIBLE_CHANGE"
        else:
            delivery_state = "ACK_PENDING_NO_VISIBLE_CHANGE"
            reaction_state = "INPUT_REACTION_PENDING"

        _home_vm_lab_guest_set_launch_state(
            package_name,
            state="PRESENTED",
            presentation_state="PRESENTED",
            presentation_provider="ANDROID_ADB_SCREENCAP",
            presentation_generation=generation,
            presentation_path=path,
            frame_bytes=frame_bytes,
            frame_width=frame_width,
            frame_height=frame_height,
            input_state="READY",
            input_action="",
            input_delivery_state=delivery_state,
            input_reaction_state=reaction_state,
            input_frame_changed=frame_changed,
            input_provider="ANDROID_ADB_PERSISTENT_SHELL",
            input_ack_state=ack_state,
            input_ack_elapsed_seconds=ack_elapsed,
            input_dispatch_elapsed_seconds=dispatch_elapsed,
            input_first_frame_elapsed_seconds=first_frame_elapsed,
            input_frame_elapsed_seconds=frame_elapsed,
            input_reaction_elapsed_seconds=reaction_elapsed,
            input_total_elapsed_seconds=reaction_elapsed,
            input_frame_observation_mode="FRAME_FIRST_PARALLEL",
            input_stimulus_probe=stimulus,
            guest_command_channels=_home_vm_lab_guest_channel_snapshot(),
            last_input_epoch=time.time(),
            device_manifest=_home_vm_lab_virtual_device_presentation_manifest(),
            message=f"INPUT {action} REACTION={reaction_state} · CHANGED={'YES' if frame_changed else 'NO'} · REACTION={reaction_elapsed}s",
            last_error="",
        )
        _home_vm_lab_event(
            "GUEST_INPUT_REACTION_VERIFIED" if frame_changed else "GUEST_INPUT_REACTION_OBSERVED",
            f"package={package_name} action={action} reaction={reaction_state} mode=FRAME_FIRST_PARALLEL ack={ack_state} ack_elapsed={ack_elapsed}s dispatch_elapsed={dispatch_elapsed}s first_frame_elapsed={first_frame_elapsed}s frame_elapsed={frame_elapsed}s reaction_elapsed={reaction_elapsed}s bytes={frame_bytes} generation={generation} changed={'YES' if frame_changed else 'NO'} sha={successor_sha[:16]}",
        )

        if not ack_done.is_set():
            threading.Thread(
                target=_home_vm_lab_guest_post_input_ack_worker,
                args=(package_name, action, generation, ack_result, ack_done),
                name=f"orfmos-vm-input-ack-meta-{package_name}-{action.lower()}",
                daemon=True,
            ).start()

        threading.Thread(
            target=_home_vm_lab_guest_post_input_foreground_worker,
            args=(package_name, adb, action, generation),
            name=f"orfmos-vm-input-meta-{package_name}-{action.lower()}",
            daemon=True,
        ).start()
    except Exception as exc:
        message = f"{type(exc).__name__}: {exc}"
        _home_vm_lab_guest_set_launch_state(
            package_name,
            input_state="FAILED",
            input_action=action,
            input_delivery_state="FAILED",
            last_error=message,
            message=message,
        )
        _home_vm_lab_event("GUEST_INPUT_FAILED", f"package={package_name} action={action} detail={message[-500:]}")

def _home_vm_lab_input_http(package: str = "", action: str = "", x: int = -1, y: int = -1, x2: int = -1, y2: int = -1, duration: int = 250):
    package_name = str(package or "").strip()
    action_name = str(action or "").upper().strip()
    if not re.fullmatch(r"[A-Za-z0-9_.]+", package_name):
        return {"schema": ORFMOS_VM_GUEST_PRESENTATION_SCHEMA, "state": "INVALID_PACKAGE_ID", "message": "INVALID PACKAGE IDENTIFIER"}
    current = _home_vm_lab_guest_launch_state(package_name)
    manifest = current.get("device_manifest") or _home_vm_lab_virtual_device_presentation_manifest()
    allowed = set(((manifest.get("input_method") or {}).get("actions") or []))
    if action_name not in allowed:
        return {"schema": ORFMOS_VM_GUEST_PRESENTATION_SCHEMA, "state": "INVALID_INPUT_ACTION", "message": f"INPUT ACTION NOT EXPOSED BY DEVICE MANIFEST: {action_name}"}
    if current.get("state") != "PRESENTED":
        return {"schema": ORFMOS_VM_GUEST_PRESENTATION_SCHEMA, "state": "INPUT_REJECTED", "message": "GUEST PRESENTATION NOT READY"}
    if current.get("input_state") == "DISPATCHING":
        return current
    width, height = int(current.get("frame_width") or 0), int(current.get("frame_height") or 0)
    if action_name in {"TAP", "SWIPE"}:
        if width <= 0 or height <= 0 or not (0 <= int(x) < width and 0 <= int(y) < height):
            return {"schema": ORFMOS_VM_GUEST_PRESENTATION_SCHEMA, "state": "INPUT_REJECTED", "message": "INPUT COORDINATES OUTSIDE PRESENTED FRAME"}
        if action_name == "SWIPE" and not (0 <= int(x2) < width and 0 <= int(y2) < height):
            return {"schema": ORFMOS_VM_GUEST_PRESENTATION_SCHEMA, "state": "INPUT_REJECTED", "message": "SWIPE END COORDINATES OUTSIDE PRESENTED FRAME"}
    inv = _home_vm_lab_inventory(include_packages=False)
    if not (inv.get("boot_completed") or inv.get("framework_ready")):
        return {"schema": ORFMOS_VM_GUEST_PRESENTATION_SCHEMA, "state": "ANDROID_FRAMEWORK_NOT_READY", "message": "ANDROID FRAMEWORK NOT READY"}
    adb = inv.get("adb")
    if not adb:
        return {"schema": ORFMOS_VM_GUEST_PRESENTATION_SCHEMA, "state": "ADB_UNAVAILABLE", "message": "ADB UNAVAILABLE"}
    _home_vm_lab_guest_set_launch_state(package_name, input_state="DISPATCHING", input_action=action_name, input_delivery_state="DISPATCHING", input_frame_changed=None, input_provider="ANDROID_ADB_PERSISTENT_SHELL", message=f"DISPATCHING {action_name}", last_error="")
    thread = threading.Thread(
        target=_home_vm_lab_guest_input_worker,
        args=(package_name, action_name, adb, int(x), int(y), int(x2), int(y2), int(duration)),
        name=f"orfmos-vm-input-{package_name}-{action_name.lower()}",
        daemon=True,
    )
    thread.start()
    _home_vm_lab_event("GUEST_INPUT_STARTED", f"package={package_name} action={action_name} async=YES provider=ANDROID_ADB_PERSISTENT_SHELL x={int(x)} y={int(y)} x2={int(x2)} y2={int(y2)} duration={int(duration)} frame={width}x{height}")
    return _home_vm_lab_guest_launch_state(package_name)


ORFMOS_MPS_SCHEMA = "ORFMOS_MANIFEST_PACKAGE_SERVICE_V0_1"
ORFMOS_MPS_PROVIDER = "ORFMOS"
ORFMOS_MPS_SERVICE = "MPS"
ORFMOS_MPS_INSTALL_INTENT = "INSTALL"
ORFMOS_MPS_INSTALL_SEQUENCE = ("LOCATE", "READ", "VALIDATE", "WRITE")
ORFMOS_MPS_ANDROID_REALIZATION_PROVIDER = "ANDROID_VM_PACKAGE_REALIZATION_V0_1"
ORFMOS_MPS_GUEST_STAGE_ROOT = "/data/local/tmp/orfmos-mps"
ORFMOS_MPS_PACKAGE_QUERY_TIMEOUT_SECONDS = 12
ORFMOS_MPS_GUEST_STAGE_TIMEOUT_SECONDS = 90
ORFMOS_MPS_INSTALL_TIMEOUT_SECONDS = 120
ORFMOS_MPS_MAX_INSTALL_ATTEMPTS = 2


def _home_vm_lab_package_service_probe(adb):
    """Bounded capability profile for the Android package-realization provider.

    Generic VM readiness never calls this function. MPS invokes it only while an
    INSTALL intent needs Android package realization. One functional package query
    is performed per probe cycle so the health check cannot itself hammer PMS.
    """
    trace = []
    capabilities = {
        "adb_transport": "READY",
        "package_binder": "UNKNOWN",
        "installd_binder": "UNKNOWN",
        "guest_stage": "UNKNOWN",
        "package_query": "UNKNOWN",
    }

    def run_probe(provider, command, timeout_seconds, accepted=None):
        started = time.time()
        try:
            rc, output = _home_vm_lab_run(command, timeout=timeout_seconds)
        except subprocess.TimeoutExpired:
            elapsed = round(max(0.0, time.time() - started), 1)
            item = {"provider": provider, "state": "TIMEOUT", "elapsed_seconds": elapsed}
            trace.append(item)
            _home_vm_lab_event("PACKAGE_CAPABILITY_PROBE_TIMEOUT", f"provider={provider} timeout={timeout_seconds}s")
            return False, "", item
        except Exception as exc:
            elapsed = round(max(0.0, time.time() - started), 1)
            detail = f"{type(exc).__name__}: {exc}"[-240:]
            item = {"provider": provider, "state": "ERROR", "elapsed_seconds": elapsed, "detail": detail}
            trace.append(item)
            _home_vm_lab_event("PACKAGE_CAPABILITY_PROBE_ERROR", f"provider={provider} error={type(exc).__name__}")
            return False, detail, item
        elapsed = round(max(0.0, time.time() - started), 1)
        normalized = str(output or "").strip()
        ok = bool(accepted(rc, normalized)) if callable(accepted) else rc == 0
        item = {
            "provider": provider,
            "state": "ACCEPTED" if ok else "REJECTED",
            "returncode": rc,
            "elapsed_seconds": elapsed,
            "detail": normalized[-220:].replace("\n", " "),
        }
        trace.append(item)
        return ok, normalized, item

    ok, output, _ = run_probe(
        "ANDROID_SERVICE_CHECK_PACKAGE",
        [adb, "-s", ORFMOS_VM_LAB_SERIAL, "shell", "service", "check", "package"],
        6,
        lambda rc, out: rc == 0 and ("found" in out.lower() or "service package:" in out.lower()) and "not found" not in out.lower(),
    )
    capabilities["package_binder"] = "READY" if ok else "NOT_READY"

    # Diagnostic only: some Android builds expose installd differently. Do not make
    # this service-name observation the authoritative install gate.
    ok_installd, output_installd, _ = run_probe(
        "ANDROID_SERVICE_CHECK_INSTALLD",
        [adb, "-s", ORFMOS_VM_LAB_SERIAL, "shell", "service", "check", "installd"],
        6,
        lambda rc, out: rc == 0 and ("found" in out.lower() or "service installd:" in out.lower()) and "not found" not in out.lower(),
    )
    capabilities["installd_binder"] = "READY" if ok_installd else "UNCONFIRMED"

    ok_stage, _, _ = run_probe(
        "ANDROID_MPS_GUEST_STAGE",
        [adb, "-s", ORFMOS_VM_LAB_SERIAL, "shell", "sh", "-c", f"mkdir -p {ORFMOS_MPS_GUEST_STAGE_ROOT} && test -w {ORFMOS_MPS_GUEST_STAGE_ROOT} && echo READY"],
        8,
        lambda rc, out: rc == 0 and "READY" in out,
    )
    capabilities["guest_stage"] = "READY" if ok_stage else "NOT_READY"

    # Exactly one functional PMS query. If this blocks, do not immediately stack
    # alternate pm/cmd probes behind it.
    ok_query, output_query, _ = run_probe(
        "ANDROID_PM_PATH",
        [adb, "-s", ORFMOS_VM_LAB_SERIAL, "shell", "pm", "path", "android"],
        ORFMOS_MPS_PACKAGE_QUERY_TIMEOUT_SECONDS,
        lambda rc, out: rc == 0 and ("package:" in out.lower() or "/system/" in out.lower() or out.lower().endswith(".apk")),
    )
    capabilities["package_query"] = "READY" if ok_query else "NOT_READY"

    ready = bool(ok and ok_stage and ok_query)
    state = "READY" if ready else ("DEGRADED" if ok or ok_stage else "NOT_READY")
    globals()["__ORFMOS_VM_PACKAGE_SERVICE_STATE__"] = state
    globals()["__ORFMOS_VM_PACKAGE_SERVICE_LAST_DETAIL__"] = "; ".join(
        f"{key}={value}" for key, value in capabilities.items()
    )[-500:]
    globals()["__ORFMOS_VM_PACKAGE_SERVICE_LAST_EPOCH__"] = time.time()
    _home_vm_lab_event(
        "PACKAGE_REALIZATION_PROFILE",
        f"state={state} package_binder={capabilities['package_binder']} installd={capabilities['installd_binder']} stage={capabilities['guest_stage']} query={capabilities['package_query']}",
    )
    return {
        "ready": ready,
        "provider": ORFMOS_MPS_ANDROID_REALIZATION_PROVIDER if ready else "NONE",
        "state": state,
        "capabilities": capabilities,
        "trace": trace,
    }


def _home_mps_guest_stage_apk(adb, path, expected_sha256, progress=None):
    """READ + VALIDATE: stage immutable APK bytes inside the guest before PMS use.

    R85.1 replaces compound guest-shell validation with direct argv calls.
    Semantic OXML/ACF validation remains layered by the R85 MPS wrapper after
    this byte/hash identity gate succeeds.
    """
    expected_sha256 = str(expected_sha256 or "").lower().strip()
    path = str(path or "")
    if not path or not os.path.isfile(path):
        raise RuntimeError("MPS_GUEST_STAGE_LOCAL_TARGET_MISSING")

    local_size = os.path.getsize(path)
    with open(path, "rb") as handle:
        local_sha256 = hashlib.sha256(handle.read()).hexdigest()
    if expected_sha256 and local_sha256 != expected_sha256:
        raise RuntimeError(
            f"MPS_GUEST_STAGE_LOCAL_HASH_MISMATCH:"
            f"expected={expected_sha256}:observed={local_sha256}"
        )
    expected_sha256 = expected_sha256 or local_sha256

    safe_name = re.sub(
        r"[^A-Za-z0-9._-]+",
        "_",
        os.path.basename(path),
    ) or "package.apk"
    guest_path = (
        f"{ORFMOS_MPS_GUEST_STAGE_ROOT}/"
        f"{expected_sha256[:16]}_{safe_name}"
    )

    def report(status, detail=""):
        if callable(progress):
            try:
                progress(status, detail)
            except Exception:
                pass

    report(
        "MPS_READ",
        f"exchange=ADB_PUSH guest_path={guest_path} bytes={local_size}",
    )
    rc_mkdir, out_mkdir = _home_vm_lab_run(
        [
            adb, "-s", ORFMOS_VM_LAB_SERIAL,
            "shell", "mkdir", "-p", ORFMOS_MPS_GUEST_STAGE_ROOT,
        ],
        timeout=10,
    )
    if rc_mkdir != 0:
        raise RuntimeError(
            f"MPS_GUEST_STAGE_CREATE_FAILED:{str(out_mkdir or '')[-500:]}"
        )

    try:
        rc_push, out_push = _home_vm_lab_run(
            [
                adb, "-s", ORFMOS_VM_LAB_SERIAL,
                "push", path, guest_path,
            ],
            timeout=ORFMOS_MPS_GUEST_STAGE_TIMEOUT_SECONDS,
        )
    except subprocess.TimeoutExpired:
        raise RuntimeError("MPS_GUEST_STAGE_PUSH_TIMEOUT")
    if rc_push != 0:
        raise RuntimeError(
            f"MPS_GUEST_STAGE_PUSH_FAILED:{str(out_push or '')[-700:]}"
        )

    report(
        "MPS_VALIDATE",
        (
            "interaction=GUEST_STAGE_VALIDATE_ARGV "
            f"expected_sha256={expected_sha256} "
            f"expected_bytes={local_size}"
        ),
    )

    # Direct argv size validation: no compound shell parsing.
    rc_size, out_size = _home_vm_lab_run(
        [
            adb, "-s", ORFMOS_VM_LAB_SERIAL,
            "shell", "wc", "-c", guest_path,
        ],
        timeout=12,
    )
    remote_size = None
    if rc_size == 0:
        match = re.match(
            r"^\s*(\d+)(?:\s|$)",
            str(out_size or "").strip(),
        )
        if match:
            remote_size = int(match.group(1))
    if remote_size != int(local_size):
        raise RuntimeError(
            "MPS_GUEST_STAGE_SIZE_MISMATCH:"
            f"expected={local_size}:observed={remote_size}:"
            f"output={str(out_size or '')[-300:]}"
        )

    # Direct argv SHA validation: toybox first, direct sha256sum fallback.
    hash_provider = "TOYBOX_SHA256SUM"
    rc_hash, out_hash = _home_vm_lab_run(
        [
            adb, "-s", ORFMOS_VM_LAB_SERIAL,
            "shell", "toybox", "sha256sum", guest_path,
        ],
        timeout=30,
    )
    remote_sha = ""
    if rc_hash == 0:
        match = re.match(
            r"^\s*([0-9a-fA-F]{64})(?:\s|$)",
            str(out_hash or "").strip(),
        )
        if match:
            remote_sha = match.group(1).lower()

    if not remote_sha:
        hash_provider = "SHA256SUM"
        rc_hash, out_hash = _home_vm_lab_run(
            [
                adb, "-s", ORFMOS_VM_LAB_SERIAL,
                "shell", "sha256sum", guest_path,
            ],
            timeout=30,
        )
        if rc_hash == 0:
            match = re.match(
                r"^\s*([0-9a-fA-F]{64})(?:\s|$)",
                str(out_hash or "").strip(),
            )
            if match:
                remote_sha = match.group(1).lower()

    if not remote_sha:
        raise RuntimeError(
            "MPS_GUEST_STAGE_HASH_PROVIDER_UNAVAILABLE:"
            + str(out_hash or "")[-400:]
        )
    if remote_sha != expected_sha256:
        raise RuntimeError(
            "MPS_GUEST_STAGE_HASH_MISMATCH:"
            f"expected={expected_sha256}:observed={remote_sha}"
        )

    _home_vm_lab_event(
        "MPS_GUEST_STAGE_VALIDATED",
        (
            f"path={guest_path} bytes={remote_size} "
            f"validation=SHA256 provider={hash_provider} "
            f"sha256={remote_sha} argv_safe=YES"
        ),
    )
    report(
        "MPS_VALIDATED",
        (
            f"guest_path={guest_path} bytes={remote_size} "
            f"validation=SHA256 provider={hash_provider} "
            f"sha256={remote_sha} argv_safe=YES"
        ),
    )
    return guest_path

def _home_mps_guest_cleanup(adb, guest_path):
    if not adb or not guest_path:
        return
    try:
        _home_vm_lab_run([adb, "-s", ORFMOS_VM_LAB_SERIAL, "shell", "rm", "-f", str(guest_path)], timeout=10)
    except Exception:
        pass


def _home_vm_lab_install_apk(path, progress=None, cancelled=None):
    """ORFMOS MPS INSTALL using Android VM as a bounded realization provider.

    PROVIDER ORFMOS / SERVICE MPS / INTENT INSTALL
    LOCATE -> READ -> VALIDATE -> WRITE

    READ stages the immutable APK into guest-local storage. WRITE invokes guest
    PackageManager against that local object, avoiding host-streamed `adb install`
    as the transaction boundary. Package-provider failure never revokes VM liveness.
    """
    target_name = os.path.basename(str(path))
    with open(path, "rb") as handle:
        expected_sha256 = hashlib.sha256(handle.read()).hexdigest()
    transient_markers = (
        "broken pipe",
        "failure calling service package",
        "can't find service: package",
        "service package: not found",
        "device offline",
        "closed",
        "package service",
        "timeout",
    )
    install_attempt = 0
    wait_cycle = 0
    transient_failures = 0
    guest_path = ""

    def report(status, detail=""):
        if callable(progress):
            try:
                progress(str(status or ""), str(detail or ""))
            except Exception:
                pass

    report("MPS_LOCATE", f"provider={ORFMOS_MPS_PROVIDER} service={ORFMOS_MPS_SERVICE} intent={ORFMOS_MPS_INSTALL_INTENT} target={target_name}")
    _home_vm_lab_event(
        "MPS_INSTALL_INVOKED",
        f"provider={ORFMOS_MPS_PROVIDER} service={ORFMOS_MPS_SERVICE} intent={ORFMOS_MPS_INSTALL_INTENT} target={target_name} sha256={expected_sha256}",
    )

    try:
        while True:
            if callable(cancelled):
                try:
                    if cancelled():
                        raise RuntimeError("ANDROID_VM_LAB_INSTALL_ORPHANED")
                except RuntimeError:
                    raise
                except Exception:
                    pass

            inv = _home_vm_lab_inventory(include_packages=False)
            if not (inv.get("running") or inv.get("process_alive")):
                raise RuntimeError("ANDROID_VM_LAB_GUEST_LOST_DURING_INSTALL")
            if not (inv.get("boot_completed") or inv.get("framework_ready")):
                wait_cycle += 1
                detail = f"VM_LIVE_WAITING_BOOT cycle={wait_cycle} adb={inv.get('adb_state')}"
                globals()["__ORFMOS_VM_PACKAGE_SERVICE_STATE__"] = "WAITING_FOR_BOOT"
                globals()["__ORFMOS_VM_PACKAGE_SERVICE_LAST_DETAIL__"] = detail
                _home_vm_lab_event("MPS_INSTALL_WAITING_FOR_BOOT", detail)
                report("WAITING_FOR_VM_READY", detail)
                time.sleep(min(20, 4 + wait_cycle * 2))
                continue

            adb = inv.get("adb")
            if not adb:
                raise RuntimeError("ANDROID_VM_LAB_ADB_UNAVAILABLE")

            # READ and VALIDATE are independent of PackageManager. Do them once.
            if not guest_path:
                guest_path = _home_mps_guest_stage_apk(adb, path, expected_sha256, progress=progress)

            probe = _home_vm_lab_package_service_probe(adb)
            if not probe.get("ready"):
                wait_cycle += 1
                caps = probe.get("capabilities") or {}
                summary = ";".join(f"{key}={value}" for key, value in caps.items())[-500:]
                globals()["__ORFMOS_VM_PACKAGE_SERVICE_STATE__"] = "WAITING"
                globals()["__ORFMOS_VM_PACKAGE_SERVICE_LAST_DETAIL__"] = summary
                globals()["__ORFMOS_VM_PACKAGE_SERVICE_LAST_EPOCH__"] = time.time()
                _home_vm_lab_event("MPS_WRITE_WAITING_FOR_PACKAGE_PROVIDER", f"cycle={wait_cycle} target={target_name} profile={summary}")
                report("WAITING_FOR_PACKAGE_SERVICE", summary)
                # The transaction remains live, but a probe cycle is deliberately
                # slow enough to avoid turning observation into package-service load.
                time.sleep(min(30, 6 + wait_cycle * 3))
                continue

            install_attempt += 1
            wait_cycle = 0
            provider = str(probe.get("provider") or ORFMOS_MPS_ANDROID_REALIZATION_PROVIDER)
            report("MPS_WRITE", f"attempt={install_attempt} provider={provider} guest_path={guest_path}")
            _home_vm_lab_event("MPS_PACKAGE_WRITE_ATTEMPT", f"attempt={install_attempt} target={target_name} provider={provider} guest_path={guest_path}")
            try:
                rc, output = _home_vm_lab_run(
                    [adb, "-s", ORFMOS_VM_LAB_SERIAL, "shell", "pm", "install", "-r", guest_path],
                    timeout=ORFMOS_MPS_INSTALL_TIMEOUT_SECONDS,
                )
            except subprocess.TimeoutExpired:
                rc, output = 124, "MPS_PM_INSTALL_TIMEOUT"
            output = str(output or "")
            success = rc == 0 and "success" in output.lower()
            tail = output[-800:].replace("\n", " ")
            _home_vm_lab_event("MPS_PACKAGE_WRITE_RESULT", f"attempt={install_attempt} rc={rc} success={success} target={target_name} tail={tail}")
            if success:
                globals()["__ORFMOS_VM_PACKAGE_SERVICE_STATE__"] = "READY"
                globals()["__ORFMOS_VM_PACKAGE_SERVICE_LAST_DETAIL__"] = f"MPS_INSTALL_SUCCESS_ATTEMPT_{install_attempt}"
                globals()["__ORFMOS_VM_PACKAGE_SERVICE_LAST_EPOCH__"] = time.time()
                report("MPS_REACTION_INSTALLED", f"attempt={install_attempt} provider={provider}")
                _home_vm_lab_event("MPS_INSTALL_REACTION", f"reaction=INSTALLED attempt={install_attempt} provider={provider} target={target_name}")
                return output

            low = output.lower()
            transient = rc == 124 or any(marker in low for marker in transient_markers)
            if transient:
                transient_failures += 1
                globals()["__ORFMOS_VM_PACKAGE_SERVICE_STATE__"] = "DEGRADED"
                globals()["__ORFMOS_VM_PACKAGE_SERVICE_LAST_DETAIL__"] = tail[-500:]
                globals()["__ORFMOS_VM_PACKAGE_SERVICE_LAST_EPOCH__"] = time.time()
                detail = f"attempt={install_attempt} transient={transient_failures} rc={rc} tail={tail[-300:]}"
                _home_vm_lab_event("MPS_PACKAGE_PROVIDER_STALLED", detail)
                report("MPS_WRITE_STALLED", detail)
                if install_attempt >= ORFMOS_MPS_MAX_INSTALL_ATTEMPTS:
                    raise RuntimeError(f"MPS_ANDROID_PACKAGE_PROVIDER_STALLED:{detail}")
                time.sleep(min(30, 6 + transient_failures * 6))
                continue

            raise RuntimeError(f"MPS_ANDROID_PACKAGE_WRITE_FAILED:{output[-1200:]}")
    finally:
        # MPS owns its staged exchange object even if PackageManager fails.
        try:
            inv = _home_vm_lab_inventory(include_packages=False)
            _home_mps_guest_cleanup(inv.get("adb"), guest_path)
        except Exception:
            pass


ORFMOS_RUNTIME_PROBE_SCHEMA = "ORFMOS_RESIDENT_RUNTIME_PROBE_V0_3"
ORFMOS_RUNTIME_PROBE_ROUTE_REVISION = "R84_VM_MODULE_SETTINGS_PERMISSIONS"


def _home_runtime_probe_command(args, timeout=8):
    started = time.time()
    try:
        rc, output = _home_vm_lab_run(list(args), timeout=timeout)
        return {
            "state": "RETURNED" if rc != 124 else "TIMEOUT",
            "returncode": int(rc),
            "elapsed_seconds": round(time.time() - started, 3),
            "output": str(output or "")[-4000:],
        }
    except Exception as exc:
        return {
            "state": "ERROR",
            "returncode": None,
            "elapsed_seconds": round(time.time() - started, 3),
            "output": f"{type(exc).__name__}: {exc}",
        }


def _home_runtime_probe_staged_apk():
    state = globals().get("__ORFMOS_INSTALLER_STATE__")
    if not isinstance(state, dict):
        return {"present": False, "reason": "INSTALLER_STATE_UNAVAILABLE"}
    path = str(state.get("staged_path") or "")
    if not path or not os.path.isfile(path):
        return {"present": False, "reason": "NO_STAGED_APK"}
    result = {
        "present": True,
        "path": path,
        "name": os.path.basename(path),
        "bytes": os.path.getsize(path),
        "sha256": _home_vm_lab_sha256_file(path),
        "dex_entries": [],
        "native_libraries": [],
        "manifest_present": False,
        "resource_table_present": False,
    }
    try:
        with zipfile.ZipFile(path, "r") as archive:
            names = archive.namelist()
            result["manifest_present"] = "AndroidManifest.xml" in names
            result["resource_table_present"] = "resources.arsc" in names
            for name in names:
                if re.fullmatch(r"classes(?:\d+)?\.dex", name):
                    payload = archive.read(name)
                    result["dex_entries"].append({
                        "name": name,
                        "bytes": len(payload),
                        "sha256": hashlib.sha256(payload).hexdigest(),
                    })
                elif name.startswith("lib/") and name.endswith(".so"):
                    result["native_libraries"].append(name)
    except Exception as exc:
        result["archive_error"] = f"{type(exc).__name__}: {exc}"
    return result


def _home_runtime_probe_next_invocation():
    counter = int(globals().get("__ORFMOS_RUNTIME_PROBE_INVOCATION_COUNTER__") or 0) + 1
    globals()["__ORFMOS_RUNTIME_PROBE_INVOCATION_COUNTER__"] = counter
    return f"R78-{counter:06d}"


def _home_runtime_probe_vm_package_dex_contract(cause="USER_PROBE"):
    """Read-only package/DEX contract observation inside the resident Colab runtime.

    R78 preserves the R75 PackageManager path comparison and R76 resident command-channel latency evidence. This probe is
    explicit diagnostic work, so multiple bounded package queries are permitted here;
    generic VM readiness remains package-service-free.
    """
    inv = _home_vm_lab_inventory(include_packages=False)
    adb = inv.get("adb")
    cause = re.sub(r"[^A-Z0-9_:-]+", "_", str(cause or "USER_PROBE").strip().upper())[:80] or "USER_PROBE"
    invocation_id = _home_runtime_probe_next_invocation()
    result = {
        "schema": ORFMOS_RUNTIME_PROBE_SCHEMA,
        "probe_id": "VM_PACKAGE_DEX_CONTRACT",
        "invocation_id": invocation_id,
        "cause": cause,
        "provider": "ORFMOS",
        "service": "ORFVM",
        "intent": "OBSERVE",
        "runtime_provider": "COLAB_RESIDENT_RUNTIME",
        "route_revision": ORFMOS_RUNTIME_PROBE_ROUTE_REVISION,
        "contract_generation": ORFMOS_HOME_PRESENTATION_GENERATION,
        "vm_identity": str(inv.get("vm_identity") or inv.get("serial") or ORFMOS_VM_LAB_SERIAL),
        "timestamp_utc": datetime.now(timezone.utc).isoformat(),
        "state": "OBSERVED",
        "checks": {},
        "summary": {},
        "staged_target": _home_runtime_probe_staged_apk(),
        "guest_command_channels": _home_vm_lab_guest_channel_snapshot(),
    }
    if not adb:
        result["state"] = "ADB_PROVIDER_UNAVAILABLE"
        result["summary"] = {
            "adb_alive": False,
            "boot_completed": bool(inv.get("boot_completed")),
            "package_binder_visible": False,
            "installd_visible": False,
            "cmd_package_list_ready": False,
            "cmd_package_path_ready": False,
            "pm_package_path_ready": False,
            "package_query_ready": False,
            "package_path_diagnosis": "ADB_PROVIDER_UNAVAILABLE",
            "dex_art_provider_visible": False,
        }
        _home_vm_lab_event("RUNTIME_PROBE", f"probe=VM_PACKAGE_DEX_CONTRACT invocation={invocation_id} cause={cause} state={result['state']}")
        return result

    serial = ORFMOS_VM_LAB_SERIAL
    checks = result["checks"]
    checks["adb_get_state"] = _home_runtime_probe_command([adb, "-s", serial, "get-state"], timeout=5)
    checks["sys_boot_completed"] = _home_runtime_probe_command([adb, "-s", serial, "shell", "getprop", "sys.boot_completed"], timeout=5)
    checks["service_check_package"] = _home_runtime_probe_command([adb, "-s", serial, "shell", "service", "check", "package"], timeout=6)
    checks["service_check_installd"] = _home_runtime_probe_command([adb, "-s", serial, "shell", "service", "check", "installd"], timeout=6)
    checks["runtime_processes"] = _home_runtime_probe_command([
        adb, "-s", serial, "shell", "sh", "-c",
        "ps -A 2>/dev/null | grep -E 'system_server|installd|dex2oat|zygote' || ps 2>/dev/null | grep -E 'system_server|installd|dex2oat|zygote' || true",
    ], timeout=8)
    checks["dex_art_paths"] = _home_runtime_probe_command([
        adb, "-s", serial, "shell", "sh", "-c",
        "for x in /system/bin/dalvikvm /system/bin/dex2oat /system/bin/app_process32 /system/bin/app_process64; do [ -e \"$x\" ] && ls -l \"$x\"; done",
    ], timeout=6)

    # Explicit path comparison. The first command is already known to be accepted
    # by the guest app registry; the two path commands isolate wrapper vs service
    # operation behavior without performing a package mutation.
    checks["cmd_package_list_3p"] = _home_runtime_probe_command(
        [adb, "-s", serial, "shell", "cmd", "package", "list", "packages", "-3"],
        timeout=15,
    )
    checks["cmd_package_path_android"] = _home_runtime_probe_command(
        [adb, "-s", serial, "shell", "cmd", "package", "path", "android"],
        timeout=12,
    )
    checks["pm_path_android"] = _home_runtime_probe_command(
        [adb, "-s", serial, "shell", "pm", "path", "android"],
        timeout=12,
    )

    def returned(name):
        item = checks.get(name) or {}
        return item.get("state") == "RETURNED" and item.get("returncode") == 0

    def path_ready(name):
        if not returned(name):
            return False
        output = str((checks.get(name) or {}).get("output") or "").lower()
        return "package:" in output or "/system/" in output or output.rstrip().endswith(".apk")

    adb_alive = returned("adb_get_state") and "device" in str(checks["adb_get_state"].get("output") or "").lower()
    boot_completed = returned("sys_boot_completed") and str(checks["sys_boot_completed"].get("output") or "").strip() == "1"
    package_output = str(checks["service_check_package"].get("output") or "").lower()
    package_binder_visible = returned("service_check_package") and "not found" not in package_output
    process_output = str(checks["runtime_processes"].get("output") or "").lower()
    installd_output = str(checks["service_check_installd"].get("output") or "").lower()
    installd_visible = "installd" in process_output or (returned("service_check_installd") and "not found" not in installd_output)
    cmd_package_list_ready = returned("cmd_package_list_3p")
    cmd_package_path_ready = path_ready("cmd_package_path_android")
    pm_package_path_ready = path_ready("pm_path_android")
    package_query_ready = bool(cmd_package_list_ready or cmd_package_path_ready or pm_package_path_ready)
    dex_output = str(checks["dex_art_paths"].get("output") or "").lower() + " " + process_output
    dex_art_provider_visible = any(token in dex_output for token in ("dalvikvm", "dex2oat", "zygote"))

    if cmd_package_path_ready and not pm_package_path_ready:
        path_diagnosis = "PM_WRAPPER_STALLED"
    elif cmd_package_list_ready and not cmd_package_path_ready and not pm_package_path_ready:
        path_diagnosis = "PACKAGE_PATH_OPERATION_STALLED"
    elif cmd_package_list_ready and (cmd_package_path_ready or pm_package_path_ready):
        path_diagnosis = "PACKAGE_PROVIDER_RESPONSIVE"
    elif (cmd_package_path_ready or pm_package_path_ready) and not cmd_package_list_ready:
        path_diagnosis = "PACKAGE_LIST_OPERATION_STALLED"
    else:
        path_diagnosis = "PACKAGE_QUERY_STALLED"

    result["summary"] = {
        "adb_alive": adb_alive,
        "boot_completed": boot_completed,
        "package_binder_visible": package_binder_visible,
        "installd_visible": installd_visible,
        "cmd_package_list_ready": cmd_package_list_ready,
        "cmd_package_path_ready": cmd_package_path_ready,
        "pm_package_path_ready": pm_package_path_ready,
        "package_query_ready": package_query_ready,
        "package_path_diagnosis": path_diagnosis,
        "dex_art_provider_visible": dex_art_provider_visible,
    }
    if not adb_alive:
        result["state"] = "ADB_TRANSPORT_UNAVAILABLE"
    elif not boot_completed:
        result["state"] = "ANDROID_BOOT_INCOMPLETE"
    elif not package_binder_visible:
        result["state"] = "PACKAGE_BINDER_UNAVAILABLE"
    elif not installd_visible:
        result["state"] = "INSTALLD_NOT_OBSERVED"
    elif path_diagnosis == "PM_WRAPPER_STALLED":
        result["state"] = "PM_WRAPPER_STALLED"
    elif path_diagnosis == "PACKAGE_PATH_OPERATION_STALLED":
        result["state"] = "PACKAGE_PATH_OPERATION_STALLED"
    elif not package_query_ready:
        result["state"] = "PACKAGE_QUERY_STALLED"
    else:
        result["state"] = "PACKAGE_DEX_CONTRACT_OBSERVED"

    _home_vm_lab_event(
        "RUNTIME_PROBE_PATH_DIAGNOSTIC",
        f"invocation={invocation_id} cause={cause} cmd_list={cmd_package_list_ready} cmd_path={cmd_package_path_ready} pm_path={pm_package_path_ready} diagnosis={path_diagnosis}",
    )
    _home_vm_lab_event("RUNTIME_PROBE", f"probe=VM_PACKAGE_DEX_CONTRACT invocation={invocation_id} cause={cause} state={result['state']}")
    return result



def _home_runtime_probe_vm_framework_responsiveness(cause="USER_PROBE"):
    """Read-only framework-provider tomography for a live Android guest.

    This probe does not own VM lifecycle and does not mutate guest state.  It
    distinguishes core binder/service responsiveness from SystemUI process/ANR
    state so a blocked visual interaction can be attributed to the target
    provider instead of being misclassified as VM or input-transport failure.
    """
    inv = _home_vm_lab_inventory(include_packages=False)
    adb = inv.get("adb")
    cause = re.sub(r"[^A-Z0-9_:-]+", "_", str(cause or "USER_PROBE").strip().upper())[:80] or "USER_PROBE"
    invocation_id = _home_runtime_probe_next_invocation()
    result = {
        "schema": ORFMOS_RUNTIME_PROBE_SCHEMA,
        "probe_id": "VM_FRAMEWORK_RESPONSIVENESS",
        "invocation_id": invocation_id,
        "cause": cause,
        "provider": "ORFMOS",
        "service": "ORFVM",
        "intent": "OBSERVE",
        "runtime_provider": "COLAB_RESIDENT_RUNTIME",
        "route_revision": ORFMOS_RUNTIME_PROBE_ROUTE_REVISION,
        "contract_generation": ORFMOS_HOME_PRESENTATION_GENERATION,
        "vm_identity": str(inv.get("vm_identity") or inv.get("serial") or ORFMOS_VM_LAB_SERIAL),
        "timestamp_utc": datetime.now(timezone.utc).isoformat(),
        "state": "OBSERVED",
        "checks": {},
        "summary": {},
        "guest_command_channels": _home_vm_lab_guest_channel_snapshot(),
    }
    if not adb:
        result["state"] = "ADB_PROVIDER_UNAVAILABLE"
        result["summary"] = {
            "adb_alive": False,
            "activity_manager_ready": False,
            "window_manager_ready": False,
            "input_service_ready": False,
            "surfaceflinger_ready": False,
            "package_binder_visible": False,
            "systemui_process_visible": False,
            "systemui_anr_evidence": False,
            "slow_checks": [],
            "target_provider": "ANDROID_SYSTEM_UI",
            "reaction_boundary": "ADB_PROVIDER_UNAVAILABLE",
        }
        _home_vm_lab_event("RUNTIME_PROBE", f"probe=VM_FRAMEWORK_RESPONSIVENESS invocation={invocation_id} cause={cause} state={result['state']}")
        return result

    serial = ORFMOS_VM_LAB_SERIAL
    checks = result["checks"]
    checks["adb_get_state"] = _home_runtime_probe_command([adb, "-s", serial, "get-state"], timeout=5)
    # Service-manager checks are intentionally cheap.  Each is separately bounded
    # so one degraded Android provider cannot block the entire contract forever.
    checks["service_check_activity"] = _home_runtime_probe_command([adb, "-s", serial, "shell", "service", "check", "activity"], timeout=6)
    checks["service_check_window"] = _home_runtime_probe_command([adb, "-s", serial, "shell", "service", "check", "window"], timeout=6)
    checks["service_check_input"] = _home_runtime_probe_command([adb, "-s", serial, "shell", "service", "check", "input"], timeout=6)
    checks["service_check_surfaceflinger"] = _home_runtime_probe_command([adb, "-s", serial, "shell", "service", "check", "SurfaceFlinger"], timeout=6)
    checks["service_check_package"] = _home_runtime_probe_command([adb, "-s", serial, "shell", "service", "check", "package"], timeout=6)

    checks["framework_processes"] = _home_runtime_probe_command([
        adb, "-s", serial, "shell", "sh", "-c",
        "ps -A 2>/dev/null | grep -E 'system_server|com.android.systemui|surfaceflinger|installd|dex2oat' || ps 2>/dev/null | grep -E 'system_server|com.android.systemui|surfaceflinger|installd|dex2oat' || true",
    ], timeout=8)
    checks["foreground_window"] = _home_runtime_probe_command([
        adb, "-s", serial, "shell", "sh", "-c",
        "dumpsys window windows 2>/dev/null | grep -m 1 -E 'mCurrentFocus|mFocusedApp' || true",
    ], timeout=8)
    checks["systemui_anr_log"] = _home_runtime_probe_command([
        adb, "-s", serial, "shell", "sh", "-c",
        "logcat -d -t 260 2>/dev/null | grep -Ei 'ANR in com\\.android\\.systemui|am_anr.*systemui|System UI.*not responding|systemui.*not responding' | tail -n 12 || true",
    ], timeout=8)
    checks["scheduler_pressure"] = _home_runtime_probe_command([
        adb, "-s", serial, "shell", "sh", "-c",
        "cat /proc/loadavg 2>/dev/null; grep -E 'MemAvailable|MemFree|SwapFree' /proc/meminfo 2>/dev/null | head -n 4",
    ], timeout=6)

    def returned(name):
        item = checks.get(name) or {}
        return item.get("state") == "RETURNED" and item.get("returncode") == 0

    def service_ready(name):
        if not returned(name):
            return False
        output = str((checks.get(name) or {}).get("output") or "").lower()
        return "not found" not in output and ("found:" in output or "service" in output or bool(output.strip()))

    adb_alive = returned("adb_get_state") and "device" in str(checks["adb_get_state"].get("output") or "").lower()
    activity_manager_ready = service_ready("service_check_activity")
    window_manager_ready = service_ready("service_check_window")
    input_service_ready = service_ready("service_check_input")
    surfaceflinger_ready = service_ready("service_check_surfaceflinger")
    package_binder_visible = service_ready("service_check_package")
    process_output = str((checks.get("framework_processes") or {}).get("output") or "").lower()
    systemui_process_visible = "com.android.systemui" in process_output
    anr_output = str((checks.get("systemui_anr_log") or {}).get("output") or "").strip()
    systemui_anr_evidence = bool(anr_output)
    foreground_output = str((checks.get("foreground_window") or {}).get("output") or "").strip()
    scheduler_output = str((checks.get("scheduler_pressure") or {}).get("output") or "").strip()
    loadavg = scheduler_output.splitlines()[0].strip() if scheduler_output else ""
    slow_checks = []
    for name, item in checks.items():
        elapsed = float((item or {}).get("elapsed_seconds") or 0.0)
        if (item or {}).get("state") == "TIMEOUT" or elapsed >= 5.0:
            slow_checks.append(name)

    core_ready = all((activity_manager_ready, window_manager_ready, input_service_ready, surfaceflinger_ready))
    if not adb_alive:
        state = "ADB_TRANSPORT_UNAVAILABLE"
        reaction_boundary = "ADB_PROVIDER"
    elif not core_ready:
        state = "CORE_FRAMEWORK_PROVIDER_DEGRADED"
        reaction_boundary = "ANDROID_FRAMEWORK_BINDER"
    elif not systemui_process_visible:
        state = "SYSTEM_UI_PROCESS_UNAVAILABLE"
        reaction_boundary = "ANDROID_SYSTEM_UI_PROCESS"
    elif systemui_anr_evidence:
        state = "SYSTEM_UI_ANR_OBSERVED"
        reaction_boundary = "ANDROID_SYSTEM_UI_ANR"
    elif any(name in slow_checks for name in ("service_check_input", "service_check_window", "service_check_surfaceflinger")):
        state = "PRESENTATION_INPUT_PROVIDER_SLOW"
        reaction_boundary = "ANDROID_PRESENTATION_INPUT"
    else:
        state = "FRAMEWORK_RESPONSIVENESS_OBSERVED"
        reaction_boundary = "NO_BLOCKING_PROVIDER_OBSERVED"

    result["state"] = state
    result["summary"] = {
        "adb_alive": adb_alive,
        "activity_manager_ready": activity_manager_ready,
        "window_manager_ready": window_manager_ready,
        "input_service_ready": input_service_ready,
        "surfaceflinger_ready": surfaceflinger_ready,
        "package_binder_visible": package_binder_visible,
        "systemui_process_visible": systemui_process_visible,
        "systemui_anr_evidence": systemui_anr_evidence,
        "foreground_component": foreground_output[-240:] if foreground_output else "UNRESOLVED",
        "loadavg": loadavg,
        "slow_checks": slow_checks,
        "target_provider": "ANDROID_SYSTEM_UI",
        "reaction_boundary": reaction_boundary,
    }
    _home_vm_lab_event(
        "RUNTIME_PROBE_FRAMEWORK_DIAGNOSTIC",
        f"invocation={invocation_id} cause={cause} activity={activity_manager_ready} window={window_manager_ready} input={input_service_ready} surface={surfaceflinger_ready} systemui={systemui_process_visible} anr={systemui_anr_evidence} boundary={reaction_boundary}",
    )
    _home_vm_lab_event("RUNTIME_PROBE", f"probe=VM_FRAMEWORK_RESPONSIVENESS invocation={invocation_id} cause={cause} state={state}")
    return result

def _home_runtime_probe_vm_system_ui_guard(cause="PRESENTATION_GUARD"):
    """Fast read-only guard used by the ORFMOS-owned compatibility prompt.

    The checks run in parallel and never mutate or restart Android.  The guard
    answers only whether the guest SystemUI provider is currently/recently ANR
    while core presentation providers remain observable.
    """
    inv = _home_vm_lab_inventory(include_packages=False)
    adb = inv.get("adb")
    cause = re.sub(r"[^A-Z0-9_:-]+", "_", str(cause or "PRESENTATION_GUARD").strip().upper())[:80] or "PRESENTATION_GUARD"
    invocation_id = _home_runtime_probe_next_invocation()
    result = {
        "schema": ORFMOS_RUNTIME_PROBE_SCHEMA,
        "probe_id": "VM_SYSTEM_UI_GUARD",
        "invocation_id": invocation_id,
        "cause": cause,
        "provider": "ORFMOS",
        "service": "ORFVM",
        "intent": "OBSERVE",
        "runtime_provider": "COLAB_RESIDENT_RUNTIME",
        "route_revision": ORFMOS_RUNTIME_PROBE_ROUTE_REVISION,
        "contract_generation": ORFMOS_HOME_PRESENTATION_GENERATION,
        "vm_identity": str(inv.get("vm_identity") or inv.get("serial") or ORFMOS_VM_LAB_SERIAL),
        "timestamp_utc": datetime.now(timezone.utc).isoformat(),
        "state": "OBSERVED",
        "checks": {},
        "summary": {},
    }
    if not adb:
        result["state"] = "ADB_PROVIDER_UNAVAILABLE"
        result["summary"] = {"adb_alive": False, "target_provider": "ANDROID_SYSTEM_UI", "reaction_boundary": "ADB_PROVIDER_UNAVAILABLE"}
        return result

    serial = ORFMOS_VM_LAB_SERIAL
    specs = {
        "adb_get_state": ([adb, "-s", serial, "get-state"], 3),
        "service_check_activity": ([adb, "-s", serial, "shell", "service", "check", "activity"], 4),
        "service_check_window": ([adb, "-s", serial, "shell", "service", "check", "window"], 4),
        "service_check_input": ([adb, "-s", serial, "shell", "service", "check", "input"], 4),
        "service_check_surfaceflinger": ([adb, "-s", serial, "shell", "service", "check", "SurfaceFlinger"], 4),
        "systemui_process": ([adb, "-s", serial, "shell", "sh", "-c", "ps -A 2>/dev/null | grep -F 'com.android.systemui' || ps 2>/dev/null | grep -F 'com.android.systemui' || true"], 4),
        "systemui_process_flags": ([adb, "-s", serial, "shell", "sh", "-c", "dumpsys activity processes 2>/dev/null | grep -i -A 18 'com.android.systemui' | grep -Ei 'notResponding|not responding|crashing|ANR' | head -n 8 || true"], 4),
        "systemui_anr_events": ([adb, "-s", serial, "shell", "sh", "-c", "logcat -v epoch -b events -d -t 160 2>/dev/null | grep -Ei 'am_anr.*com\\.android\\.systemui|am_anr.*systemui' | tail -n 4 || true"], 4),
    }
    checks = result["checks"]
    threads = []
    def worker(name, command, timeout):
        try:
            checks[name] = _home_runtime_probe_command(command, timeout=timeout)
        except Exception as exc:
            checks[name] = {"state": "FAILED", "returncode": None, "output": "", "error": f"{type(exc).__name__}: {exc}", "elapsed_seconds": 0.0}
    for name, (command, timeout) in specs.items():
        thread = threading.Thread(target=worker, args=(name, command, timeout), daemon=True, name=f"ORFMOS-SYSUI-{name}")
        thread.start(); threads.append(thread)
    for thread in threads:
        thread.join(timeout=5.0)

    def returned(name):
        item = checks.get(name) or {}
        return item.get("state") == "RETURNED" and item.get("returncode") == 0
    def service_ready(name):
        if not returned(name): return False
        output = str((checks.get(name) or {}).get("output") or "").lower()
        return "not found" not in output and ("found:" in output or "service" in output or bool(output.strip()))

    adb_alive = returned("adb_get_state") and "device" in str((checks.get("adb_get_state") or {}).get("output") or "").lower()
    activity_manager_ready = service_ready("service_check_activity")
    window_manager_ready = service_ready("service_check_window")
    input_service_ready = service_ready("service_check_input")
    surfaceflinger_ready = service_ready("service_check_surfaceflinger")
    systemui_process_visible = "com.android.systemui" in str((checks.get("systemui_process") or {}).get("output") or "").lower()
    flag_output = str((checks.get("systemui_process_flags") or {}).get("output") or "").strip().lower()
    current_anr_true = bool(re.search(r"notresponding\s*[=:]\s*true|not responding|\banr\b", flag_output))
    current_anr_false = bool(re.search(r"notresponding\s*[=:]\s*false", flag_output))
    event_output = str((checks.get("systemui_anr_events") or {}).get("output") or "").strip()
    event_age_seconds = None
    if event_output:
        stamps = re.findall(r"(?m)^\s*(\d{9,12}(?:\.\d+)?)", event_output)
        if stamps:
            try: event_age_seconds = max(0.0, time.time() - float(stamps[-1]))
            except Exception: event_age_seconds = None
    recent_anr_event = bool(event_output) and (event_age_seconds is None or event_age_seconds <= 300.0)
    if current_anr_true:
        systemui_anr_evidence = True
        anr_source = "PROCESS_FLAG"
    elif current_anr_false:
        systemui_anr_evidence = False
        anr_source = "PROCESS_FLAG_CLEAR"
    else:
        systemui_anr_evidence = recent_anr_event
        anr_source = "RECENT_EVENT" if recent_anr_event else "NONE"

    core_ready = all((activity_manager_ready, window_manager_ready, input_service_ready, surfaceflinger_ready))
    if not adb_alive:
        state, boundary = "ADB_TRANSPORT_UNAVAILABLE", "ADB_PROVIDER"
    # Direct target-provider evidence outranks auxiliary service-check timeouts. On
    # software TCG several parallel service checks may miss their bounded window even
    # while Input/Surface continue reacting; a positive SystemUI notResponding flag is
    # therefore the stronger classification for this presentation guard.
    elif systemui_process_visible and systemui_anr_evidence:
        state, boundary = "SYSTEM_UI_ANR_OBSERVED", "ANDROID_SYSTEM_UI_ANR"
    elif not systemui_process_visible:
        state, boundary = "SYSTEM_UI_PROCESS_UNAVAILABLE", "ANDROID_SYSTEM_UI_PROCESS"
    elif not core_ready:
        state, boundary = "CORE_FRAMEWORK_PROVIDER_DEGRADED", "ANDROID_FRAMEWORK_BINDER"
    else:
        state, boundary = "SYSTEM_UI_RESPONSIVE_OR_UNBLOCKED", "NO_BLOCKING_PROVIDER_OBSERVED"

    result["state"] = state
    result["summary"] = {
        "adb_alive": adb_alive,
        "activity_manager_ready": activity_manager_ready,
        "window_manager_ready": window_manager_ready,
        "input_service_ready": input_service_ready,
        "surfaceflinger_ready": surfaceflinger_ready,
        "systemui_process_visible": systemui_process_visible,
        "systemui_anr_evidence": systemui_anr_evidence,
        "systemui_anr_source": anr_source,
        "systemui_anr_event_age_seconds": event_age_seconds,
        "target_provider": "ANDROID_SYSTEM_UI",
        "reaction_boundary": boundary,
    }
    _home_vm_lab_event("SYSTEM_UI_GUARD", f"invocation={invocation_id} cause={cause} state={state} input={input_service_ready} surface={surfaceflinger_ready} anr={systemui_anr_evidence} source={anr_source}")
    return result







# ========================================================================================================
# R90 — DEVICE COMPATIBILITY / DEPLOYABLE SYSTEM PROBE LIBRARY
# ========================================================================================================

ORFMOS_DEVICE_COMPATIBILITY_SCHEMA = "ORFMOS_DEVICE_COMPATIBILITY_V0_1"
ORFMOS_DEVICE_PROBE_SCHEMA = "ORFMOS_DEPLOYABLE_SYSTEM_PROBE_V0_1"

_ORFMOS_DEVICE_PROBE_PAYLOADS = {
    "OPTIPLEX_LINUX_READINESS_WINDOWS": b'# ORFMOS DEVICE COMPATIBILITY PROBE\n# Probe: OPTIPLEX_LINUX_READINESS\n# Version: 0.1\n# Authority: READ_ONLY_OBSERVATION\n# Purpose: Collect hardware/browser facts needed to choose a Linux distribution for ORFMOS/Colab browser access.\n# This probe does not install, remove, or configure software.\n\n$ErrorActionPreference = "SilentlyContinue"\n\nfunction Get-SafeCim {\n    param([string]$ClassName)\n    try { return @(Get-CimInstance -ClassName $ClassName -ErrorAction Stop) }\n    catch { return @() }\n}\n\nfunction Get-BrowserVersion {\n    param(\n        [string]$Name,\n        [string[]]$Paths\n    )\n    foreach ($p in $Paths) {\n        if ($p -and (Test-Path $p)) {\n            try {\n                $v = (Get-Item $p).VersionInfo.ProductVersion\n                if ($v) {\n                    return [ordered]@{ name=$Name; path=$p; version=$v; present=$true }\n                }\n            } catch {}\n        }\n    }\n    return [ordered]@{ name=$Name; path=""; version=""; present=$false }\n}\n\n$computer = (Get-SafeCim "Win32_ComputerSystem" | Select-Object -First 1)\n$cpu = (Get-SafeCim "Win32_Processor" | Select-Object -First 1)\n$bios = (Get-SafeCim "Win32_BIOS" | Select-Object -First 1)\n$os = (Get-SafeCim "Win32_OperatingSystem" | Select-Object -First 1)\n$video = Get-SafeCim "Win32_VideoController"\n$disks = Get-SafeCim "Win32_DiskDrive"\n$logical = Get-SafeCim "Win32_LogicalDisk"\n$net = Get-SafeCim "Win32_NetworkAdapter" | Where-Object { $_.PhysicalAdapter -eq $true }\n\n$secureBoot = $null\ntry { $secureBoot = [bool](Confirm-SecureBootUEFI -ErrorAction Stop) } catch {}\n\n$firmwareType = ""\ntry {\n    $fw = Get-ItemProperty -Path "HKLM:\\SYSTEM\\CurrentControlSet\\Control" -Name PEFirmwareType -ErrorAction Stop\n    if ($fw.PEFirmwareType -eq 2) { $firmwareType = "UEFI" }\n    elseif ($fw.PEFirmwareType -eq 1) { $firmwareType = "BIOS" }\n} catch {}\n\n$arch = $env:PROCESSOR_ARCHITECTURE\nif ($env:PROCESSOR_ARCHITEW6432) { $arch = $env:PROCESSOR_ARCHITEW6432 }\n\n$ramBytes = 0\ntry { $ramBytes = [int64]$computer.TotalPhysicalMemory } catch {}\n$ramGiB = if ($ramBytes -gt 0) { [math]::Round($ramBytes / 1GB, 2) } else { $null }\n\n$diskRows = @()\nforeach ($d in $disks) {\n    $sizeGiB = $null\n    try { $sizeGiB = [math]::Round(([int64]$d.Size) / 1GB, 2) } catch {}\n    $diskRows += [ordered]@{\n        model = [string]$d.Model\n        interface = [string]$d.InterfaceType\n        media_type = [string]$d.MediaType\n        size_gib = $sizeGiB\n    }\n}\n\n$volumeRows = @()\nforeach ($v in $logical | Where-Object { $_.DriveType -eq 3 }) {\n    $sizeGiB = $null\n    $freeGiB = $null\n    try { $sizeGiB = [math]::Round(([int64]$v.Size) / 1GB, 2) } catch {}\n    try { $freeGiB = [math]::Round(([int64]$v.FreeSpace) / 1GB, 2) } catch {}\n    $volumeRows += [ordered]@{\n        device = [string]$v.DeviceID\n        filesystem = [string]$v.FileSystem\n        size_gib = $sizeGiB\n        free_gib = $freeGiB\n    }\n}\n\n$videoRows = @()\nforeach ($g in $video) {\n    $ramGiBVideo = $null\n    try {\n        if ([int64]$g.AdapterRAM -gt 0) {\n            $ramGiBVideo = [math]::Round(([int64]$g.AdapterRAM) / 1GB, 2)\n        }\n    } catch {}\n    $videoRows += [ordered]@{\n        name = [string]$g.Name\n        driver_version = [string]$g.DriverVersion\n        adapter_ram_gib = $ramGiBVideo\n        video_mode = [string]$g.VideoModeDescription\n    }\n}\n\n$netRows = @()\nforeach ($n in $net) {\n    $netRows += [ordered]@{\n        name = [string]$n.Name\n        adapter_type = [string]$n.AdapterType\n        net_connection_id = [string]$n.NetConnectionID\n        status = [string]$n.NetConnectionStatus\n        speed_bps = $n.Speed\n        manufacturer = [string]$n.Manufacturer\n    }\n}\n\n$browserRows = @(\n    (Get-BrowserVersion "Microsoft Edge" @(\n        "$env:ProgramFiles (x86)\\Microsoft\\Edge\\Application\\msedge.exe",\n        "$env:ProgramFiles\\Microsoft\\Edge\\Application\\msedge.exe"\n    )),\n    (Get-BrowserVersion "Google Chrome" @(\n        "$env:ProgramFiles\\Google\\Chrome\\Application\\chrome.exe",\n        "$env:ProgramFiles (x86)\\Google\\Chrome\\Application\\chrome.exe",\n        "$env:LOCALAPPDATA\\Google\\Chrome\\Application\\chrome.exe"\n    )),\n    (Get-BrowserVersion "Mozilla Firefox" @(\n        "$env:ProgramFiles\\Mozilla Firefox\\firefox.exe",\n        "$env:ProgramFiles (x86)\\Mozilla Firefox\\firefox.exe"\n    ))\n)\n\n$cpuName = [string]$cpu.Name\n$cpu64 = ($arch -match "AMD64|ARM64")\n$logicalCpu = $null\n$physicalCpu = $null\ntry { $logicalCpu = [int]$cpu.NumberOfLogicalProcessors } catch {}\ntry { $physicalCpu = [int]$cpu.NumberOfCores } catch {}\n\n$largestDiskGiB = $null\ntry {\n    $vals = @($diskRows | ForEach-Object { $_.size_gib } | Where-Object { $_ -ne $null })\n    if ($vals.Count -gt 0) { $largestDiskGiB = ($vals | Measure-Object -Maximum).Maximum }\n} catch {}\n\n$largestFreeGiB = $null\ntry {\n    $vals = @($volumeRows | ForEach-Object { $_.free_gib } | Where-Object { $_ -ne $null })\n    if ($vals.Count -gt 0) { $largestFreeGiB = ($vals | Measure-Object -Maximum).Maximum }\n} catch {}\n\n$wifiDetected = $false\nforeach ($n in $netRows) {\n    if (($n.name + " " + $n.net_connection_id) -match "Wi-?Fi|Wireless|802\\.11|WLAN") {\n        $wifiDetected = $true\n        break\n    }\n}\n\n$readiness = [ordered]@{\n    architecture_64bit = [bool]$cpu64\n    ram_gib = $ramGiB\n    ram_at_least_4_gib = if ($ramGiB -ne $null) { [bool]($ramGiB -ge 4) } else { $null }\n    ram_at_least_8_gib = if ($ramGiB -ne $null) { [bool]($ramGiB -ge 8) } else { $null }\n    largest_disk_gib = $largestDiskGiB\n    largest_free_volume_gib = $largestFreeGiB\n    uefi_detected = if ($firmwareType) { [bool]($firmwareType -eq "UEFI") } else { $null }\n    secure_boot = $secureBoot\n    ethernet_or_wifi_detected = [bool]($netRows.Count -gt 0)\n    wifi_detected = [bool]$wifiDetected\n    browser_present = [bool](($browserRows | Where-Object { $_.present }).Count -gt 0)\n    target_use_case = "WEB_BROWSER_ONLY_ORFMOS_COLAB"\n}\n\n$report = [ordered]@{\n    schema = "ORFMOS_DEVICE_PROBE_RESULT_V0_1"\n    probe = [ordered]@{\n        id = "OPTIPLEX_LINUX_READINESS"\n        version = "0.1"\n        platform = "WINDOWS_POWERSHELL"\n        authority = "READ_ONLY_OBSERVATION"\n        target_use_case = "WEB_BROWSER_ONLY_ORFMOS_COLAB"\n    }\n    timestamp_utc = (Get-Date).ToUniversalTime().ToString("o")\n    system = [ordered]@{\n        manufacturer = [string]$computer.Manufacturer\n        model = [string]$computer.Model\n        system_type = [string]$computer.SystemType\n    }\n    firmware = [ordered]@{\n        firmware_type = $firmwareType\n        bios_manufacturer = [string]$bios.Manufacturer\n        bios_name = [string]$bios.Name\n        bios_version = [string]$bios.SMBIOSBIOSVersion\n        secure_boot = $secureBoot\n    }\n    cpu = [ordered]@{\n        name = $cpuName\n        architecture = $arch\n        cores = $physicalCpu\n        logical_processors = $logicalCpu\n        virtualization_firmware_enabled = $cpu.VirtualizationFirmwareEnabled\n    }\n    memory = [ordered]@{\n        total_gib = $ramGiB\n    }\n    storage = [ordered]@{\n        disks = $diskRows\n        volumes = $volumeRows\n    }\n    graphics = $videoRows\n    network = $netRows\n    current_os = [ordered]@{\n        caption = [string]$os.Caption\n        version = [string]$os.Version\n        build_number = [string]$os.BuildNumber\n        os_architecture = [string]$os.OSArchitecture\n    }\n    browsers = $browserRows\n    linux_readiness = $readiness\n}\n\n$stamp = (Get-Date).ToUniversalTime().ToString("yyyyMMddTHHmmssZ")\n$outName = "ORFMOS_OPTIPLEX_LINUX_READINESS_$stamp.json"\n$outPath = Join-Path (Get-Location) $outName\n$json = $report | ConvertTo-Json -Depth 8\n[System.IO.File]::WriteAllText($outPath, $json, (New-Object System.Text.UTF8Encoding($false)))\n\nWrite-Host ("=" * 96)\nWrite-Host "ORFMOS DEVICE COMPATIBILITY \xc2\xb7 OPTIPLEX LINUX READINESS v0.1"\nWrite-Host ("=" * 96)\nWrite-Host "Authority       : READ_ONLY_OBSERVATION"\nWrite-Host "Target use case : WEB_BROWSER_ONLY_ORFMOS_COLAB"\nWrite-Host "Manufacturer    : $($report.system.manufacturer)"\nWrite-Host "Model           : $($report.system.model)"\nWrite-Host "CPU             : $($report.cpu.name)"\nWrite-Host "Architecture    : $($report.cpu.architecture)"\nWrite-Host "RAM GiB         : $($report.memory.total_gib)"\nWrite-Host "Firmware        : $($report.firmware.firmware_type)"\nWrite-Host "Wi-Fi detected  : $($report.linux_readiness.wifi_detected)"\nWrite-Host "Report          : $outPath"\nWrite-Host ("=" * 96)\nWrite-Host "Paste or upload the generated JSON report back to ORFMOS / ChatGPT for distro selection."\n',
    "OPTIPLEX_LINUX_READINESS_LINUX": b'#!/usr/bin/env bash\n# ORFMOS DEVICE COMPATIBILITY PROBE\n# Probe: OPTIPLEX_LINUX_READINESS\n# Version: 0.1\n# Authority: READ_ONLY_OBSERVATION\n# Purpose: Run from an installed Linux system or live USB to collect distro-selection facts.\n# This probe does not install, remove, repartition, mount, or configure anything.\n\nset -u\n\nPROBE_ID="OPTIPLEX_LINUX_READINESS"\nPROBE_VERSION="0.1"\nSTAMP="$(date -u +%Y%m%dT%H%M%SZ 2>/dev/null || date +%Y%m%dT%H%M%S)"\nOUT="ORFMOS_OPTIPLEX_LINUX_READINESS_${STAMP}.txt"\n\ncmd() {\n  command -v "$1" >/dev/null 2>&1\n}\n\none_line() {\n  tr \'\\n\' \' \' | sed \'s/[[:space:]][[:space:]]*/ /g; s/^ //; s/ $//\'\n}\n\ndmi_value() {\n  local f="$1"\n  if [ -r "$f" ]; then\n    cat "$f" 2>/dev/null | one_line\n  fi\n}\n\nMANUFACTURER="$(dmi_value /sys/class/dmi/id/sys_vendor)"\nMODEL="$(dmi_value /sys/class/dmi/id/product_name)"\nBIOS_VENDOR="$(dmi_value /sys/class/dmi/id/bios_vendor)"\nBIOS_VERSION="$(dmi_value /sys/class/dmi/id/bios_version)"\nARCH="$(uname -m 2>/dev/null || true)"\nKERNEL="$(uname -srmo 2>/dev/null || true)"\n\nCPU_MODEL=""\nif cmd lscpu; then\n  CPU_MODEL="$(lscpu 2>/dev/null | awk -F: \'/Model name/{sub(/^[ \\t]+/,"",$2); print $2; exit}\')"\nfi\nif [ -z "$CPU_MODEL" ] && [ -r /proc/cpuinfo ]; then\n  CPU_MODEL="$(awk -F: \'/model name/{sub(/^[ \\t]+/,"",$2); print $2; exit}\' /proc/cpuinfo)"\nfi\n\nCPU_THREADS=""\nCPU_CORES=""\nif cmd nproc; then CPU_THREADS="$(nproc 2>/dev/null || true)"; fi\nif cmd lscpu; then\n  CPU_CORES="$(lscpu 2>/dev/null | awk -F: \'/^Core\\(s\\) per socket/{c=$2} /^Socket\\(s\\)/{s=$2} END{gsub(/[ \\t]/,"",c);gsub(/[ \\t]/,"",s); if(c!=""&&s!="") print c*s}\')"\nfi\n\nRAM_MIB=""\nif [ -r /proc/meminfo ]; then\n  RAM_MIB="$(awk \'/MemTotal:/{printf "%.0f", $2/1024}\' /proc/meminfo)"\nfi\n\nUEFI="false"\n[ -d /sys/firmware/efi ] && UEFI="true"\n\nSECURE_BOOT="unknown"\nif [ -d /sys/firmware/efi/efivars ]; then\n  if ls /sys/firmware/efi/efivars/SecureBoot-* >/dev/null 2>&1; then\n    SECURE_BOOT="present"\n  fi\nfi\n\nWIFI="false"\nif [ -d /sys/class/net ]; then\n  for iface in /sys/class/net/*; do\n    [ -d "$iface/wireless" ] && WIFI="true"\n  done\nfi\n\nETHERNET="false"\nif [ -d /sys/class/net ]; then\n  for iface in /sys/class/net/*; do\n    name="$(basename "$iface")"\n    [ "$name" = "lo" ] && continue\n    [ -e "$iface/device" ] && ETHERNET="true"\n  done\nfi\n\n{\n  echo "schema=ORFMOS_DEVICE_PROBE_RESULT_V0_1"\n  echo "probe.id=${PROBE_ID}"\n  echo "probe.version=${PROBE_VERSION}"\n  echo "probe.platform=LINUX_SHELL"\n  echo "probe.authority=READ_ONLY_OBSERVATION"\n  echo "probe.target_use_case=WEB_BROWSER_ONLY_ORFMOS_COLAB"\n  echo "timestamp_utc=$(date -u +%Y-%m-%dT%H:%M:%SZ 2>/dev/null || true)"\n  echo\n  echo "[SYSTEM]"\n  echo "manufacturer=${MANUFACTURER}"\n  echo "model=${MODEL}"\n  echo "architecture=${ARCH}"\n  echo "kernel=${KERNEL}"\n  echo\n  echo "[FIRMWARE]"\n  echo "uefi=${UEFI}"\n  echo "secure_boot=${SECURE_BOOT}"\n  echo "bios_vendor=${BIOS_VENDOR}"\n  echo "bios_version=${BIOS_VERSION}"\n  echo\n  echo "[CPU]"\n  echo "model=${CPU_MODEL}"\n  echo "cores=${CPU_CORES}"\n  echo "threads=${CPU_THREADS}"\n  echo\n  echo "[MEMORY]"\n  echo "total_mib=${RAM_MIB}"\n  echo\n  echo "[NETWORK]"\n  echo "physical_network_detected=${ETHERNET}"\n  echo "wifi_detected=${WIFI}"\n  if cmd ip; then\n    echo\n    echo "--- ip link ---"\n    ip -brief link 2>/dev/null || true\n  fi\n  echo\n  echo "[STORAGE]"\n  if cmd lsblk; then\n    lsblk -b -o NAME,TYPE,SIZE,ROTA,TRAN,MODEL,FSTYPE,MOUNTPOINTS 2>/dev/null || true\n  elif cmd fdisk; then\n    fdisk -l 2>/dev/null || true\n  fi\n  echo\n  echo "[GRAPHICS_AND_PCI]"\n  if cmd lspci; then\n    lspci -nn 2>/dev/null || true\n  else\n    echo "lspci=UNAVAILABLE"\n  fi\n  echo\n  echo "[USB]"\n  if cmd lsusb; then\n    lsusb 2>/dev/null || true\n  else\n    echo "lsusb=UNAVAILABLE"\n  fi\n  echo\n  echo "[CURRENT_OS]"\n  if [ -r /etc/os-release ]; then\n    cat /etc/os-release\n  else\n    echo "os_release=UNAVAILABLE"\n  fi\n  echo\n  echo "[BROWSERS]"\n  for b in google-chrome google-chrome-stable chromium chromium-browser firefox microsoft-edge microsoft-edge-stable; do\n    if cmd "$b"; then\n      echo "$b=$("$b" --version 2>/dev/null | head -n1)"\n    fi\n  done\n  echo\n  echo "[READINESS]"\n  case "$ARCH" in\n    x86_64|amd64) echo "architecture_64bit=true" ;;\n    *) echo "architecture_64bit=unknown_or_non_x86_64" ;;\n  esac\n  if [ -n "$RAM_MIB" ]; then\n    if [ "$RAM_MIB" -ge 4096 ] 2>/dev/null; then echo "ram_at_least_4_gib=true"; else echo "ram_at_least_4_gib=false"; fi\n    if [ "$RAM_MIB" -ge 8192 ] 2>/dev/null; then echo "ram_at_least_8_gib=true"; else echo "ram_at_least_8_gib=false"; fi\n  fi\n  echo "target_use_case=WEB_BROWSER_ONLY_ORFMOS_COLAB"\n} > "$OUT"\n\necho "================================================================================================"\necho "ORFMOS DEVICE COMPATIBILITY \xc2\xb7 OPTIPLEX LINUX READINESS v0.1"\necho "================================================================================================"\necho "Authority       : READ_ONLY_OBSERVATION"\necho "Target use case : WEB_BROWSER_ONLY_ORFMOS_COLAB"\necho "Manufacturer    : ${MANUFACTURER:-UNKNOWN}"\necho "Model           : ${MODEL:-UNKNOWN}"\necho "CPU             : ${CPU_MODEL:-UNKNOWN}"\necho "Architecture    : ${ARCH:-UNKNOWN}"\necho "RAM MiB         : ${RAM_MIB:-UNKNOWN}"\necho "UEFI            : ${UEFI}"\necho "Wi-Fi detected  : ${WIFI}"\necho "Report          : $(pwd)/$OUT"\necho "================================================================================================"\necho "Paste or upload the generated report back to ORFMOS / ChatGPT for distro selection."\n',
}

ORFMOS_DEVICE_PROBE_CATALOG = {'OPTIPLEX_LINUX_READINESS_WINDOWS': {'family': 'OPTIPLEX_LINUX_READINESS', 'title': 'OptiPlex Linux Readiness · Windows', 'version': '0.1', 'platform': 'WINDOWS_POWERSHELL', 'filename': 'ORFMOS_DEVICE_PROBE_OPTIPLEX_LINUX_READINESS_V0_1.ps1', 'media_type': 'text/plain; charset=utf-8', 'bytes': 8505, 'sha256': '79fd46b6a07ce62d74275c2106c2fc7108b33f7ec4eccf21db3fb4a5271a1406', 'authority': 'READ_ONLY_OBSERVATION', 'target_use_case': 'WEB_BROWSER_ONLY_ORFMOS_COLAB', 'description': 'Run on the existing Windows installation. Collects model, firmware, CPU, RAM, storage, graphics, network and browser facts.', 'run_hint': 'PowerShell: powershell -ExecutionPolicy Bypass -File .\\ORFMOS_DEVICE_PROBE_OPTIPLEX_LINUX_READINESS_V0_1.ps1'}, 'OPTIPLEX_LINUX_READINESS_LINUX': {'family': 'OPTIPLEX_LINUX_READINESS', 'title': 'OptiPlex Linux Readiness · Linux / Live USB', 'version': '0.1', 'platform': 'LINUX_SHELL', 'filename': 'ORFMOS_DEVICE_PROBE_OPTIPLEX_LINUX_READINESS_V0_1.sh', 'media_type': 'text/x-shellscript; charset=utf-8', 'bytes': 5516, 'sha256': 'bc119d751c2f298cec9a2d5f974183935bf6ae31acdcec81630757cefec38b28', 'authority': 'READ_ONLY_OBSERVATION', 'target_use_case': 'WEB_BROWSER_ONLY_ORFMOS_COLAB', 'description': 'Run from an installed Linux system or live USB. Collects the same distro-selection facts using standard Linux interfaces.', 'run_hint': 'Linux: chmod +x ./ORFMOS_DEVICE_PROBE_OPTIPLEX_LINUX_READINESS_V0_1.sh && ./ORFMOS_DEVICE_PROBE_OPTIPLEX_LINUX_READINESS_V0_1.sh'}}


def _home_device_compatibility_catalog():
    items = []
    for probe_id, meta in ORFMOS_DEVICE_PROBE_CATALOG.items():
        payload = bytes(_ORFMOS_DEVICE_PROBE_PAYLOADS.get(probe_id) or b"")
        observed_sha = hashlib.sha256(payload).hexdigest()
        observed_bytes = len(payload)
        expected_sha = str(meta.get("sha256") or "")
        expected_bytes = int(meta.get("bytes") or 0)
        state = "READY" if observed_sha == expected_sha and observed_bytes == expected_bytes else "INTEGRITY_MISMATCH"
        item = dict(meta)
        item.update({
            "schema": ORFMOS_DEVICE_PROBE_SCHEMA,
            "probe_id": probe_id,
            "state": state,
            "observed_bytes": observed_bytes,
            "observed_sha256": observed_sha,
            "download_route": f"/orfmos/device-compatibility/probe/download?probe_id={probe_id}",
        })
        items.append(item)
    items.sort(key=lambda item: (str(item.get("family") or ""), str(item.get("platform") or "")))
    return items


def _home_device_compatibility_state_http():
    probes = _home_device_compatibility_catalog()
    return {
        "schema": ORFMOS_DEVICE_COMPATIBILITY_SCHEMA,
        "state": "READY" if probes and all(item.get("state") == "READY" for item in probes) else "DEGRADED",
        "semantic_role": "DEPLOYABLE_SYSTEM_PROBE_LIBRARY",
        "probe_count": len(probes),
        "families": sorted({str(item.get("family") or "") for item in probes}),
        "probes": probes,
        "execution_authority": "EXTERNAL_TARGET_DEVICE",
        "orfmos_write_authority": "NONE",
        "probe_authority": "READ_ONLY_OBSERVATION",
    }


def _home_device_compatibility_probe_download_http(probe_id: str = ""):
    probe_id = str(probe_id or "").strip().upper()
    meta = ORFMOS_DEVICE_PROBE_CATALOG.get(probe_id)
    payload = _ORFMOS_DEVICE_PROBE_PAYLOADS.get(probe_id)
    if not isinstance(meta, dict) or payload is None:
        return Response(content=b"DEVICE PROBE NOT FOUND", status_code=404, media_type="text/plain")

    payload = bytes(payload)
    observed_sha = hashlib.sha256(payload).hexdigest()
    if observed_sha != str(meta.get("sha256") or "") or len(payload) != int(meta.get("bytes") or 0):
        return Response(content=b"DEVICE PROBE INTEGRITY MISMATCH", status_code=500, media_type="text/plain")

    filename = str(meta.get("filename") or (probe_id + ".txt"))
    headers = {
        "Content-Disposition": f'attachment; filename="{filename}"',
        "X-ORFMOS-Probe-ID": probe_id,
        "X-ORFMOS-Probe-SHA256": observed_sha,
        "X-ORFMOS-Probe-Authority": "READ_ONLY_OBSERVATION",
        "Cache-Control": "no-store",
    }
    return Response(
        content=payload,
        status_code=200,
        media_type=str(meta.get("media_type") or "application/octet-stream"),
        headers=headers,
    )



