def _home_special_access_state_http():
    try:
        inv = _home_vm_lab_inventory(include_packages=False)
    except Exception:
        inv = {}
    compatibility_state = "READY" if inv.get("boot_completed") and inv.get("adb") else ("PROVISIONED_STOPPED" if inv.get("avd_ready") else "UNRESOLVED")
    # Do not make the native surface wait on deep Android SystemUI diagnostics. The
    # last trace observation is enough to label the optional compatibility provider.
    systemui_state = "UNRESOLVED"
    events = list(globals().get("__ORFMOS_VM_LAB_EVENTS__") or [])
    for item in reversed(events[-80:]):
        if str(item.get("type") or "") == "SYSTEM_UI_GUARD":
            detail = str(item.get("detail") or "")
            if "anr=True" in detail:
                systemui_state = "DEGRADED_ANR"
            elif "state=READY" in detail:
                systemui_state = "READY"
            else:
                systemui_state = "OBSERVED"
            break
    return {
        "schema": ORFMOS_SPECIAL_ACCESS_SCHEMA,
        "state": "READY",
        "presentation_provider": "ORFMOS_UI",
        "package_name": ORFMOS_SPECIAL_ACCESS_PACKAGE,
        "compatibility_provider": "ANDROID_COMPATIBILITY",
        "compatibility_provider_state": compatibility_state,
        "android_system_ui_state": systemui_state,
        "intents": [dict({"id": key}, **value) for key, value in ORFMOS_SPECIAL_ACCESS_INTENTS.items()],
    }


def _home_special_access_intent_http(intent: str = "", package: str = ORFMOS_SPECIAL_ACCESS_PACKAGE):
    intent_id = re.sub(r"[^A-Z0-9_:-]+", "_", str(intent or "").upper())[:80]
    spec = ORFMOS_SPECIAL_ACCESS_INTENTS.get(intent_id)
    if not spec:
        return {"schema": ORFMOS_SPECIAL_ACCESS_SCHEMA, "state": "UNKNOWN_INTENT", "intent": intent_id, "provider": "NONE", "message": "ORF INTENT IS NOT REGISTERED"}
    package_name = str(package or ORFMOS_SPECIAL_ACCESS_PACKAGE).strip() or ORFMOS_SPECIAL_ACCESS_PACKAGE
    policy_key = str(spec.get("policy_key") or "").strip()
    if policy_key and not _home_vm_module_permission_enabled(package_name, policy_key):
        _home_vm_lab_event("ORF_SPECIAL_ACCESS_POLICY_DENIED", f"intent={intent_id} package={package_name} permission={policy_key}")
        return {
            "schema": ORFMOS_SPECIAL_ACCESS_SCHEMA,
            "state": "ORFMOS_POLICY_DENIED",
            "intent": intent_id,
            "orf_intent": spec["orf_intent"],
            "provider": "ORFMOS_POLICY",
            "permission": policy_key,
            "message": "VM MODULE PERMISSION IS DISABLED; COMPATIBILITY PROVIDER WAS NOT INVOKED",
        }
    try:
        inv = _home_vm_lab_inventory(include_packages=False)
    except Exception as exc:
        return {"schema": ORFMOS_SPECIAL_ACCESS_SCHEMA, "state": "COMPATIBILITY_PROVIDER_UNRESOLVED", "intent": intent_id, "orf_intent": spec["orf_intent"], "provider": "ANDROID_COMPATIBILITY", "message": f"{type(exc).__name__}: {exc}"}
    adb = inv.get("adb")
    if not adb or not inv.get("boot_completed"):
        return {"schema": ORFMOS_SPECIAL_ACCESS_SCHEMA, "state": "COMPATIBILITY_PROVIDER_UNAVAILABLE", "intent": intent_id, "orf_intent": spec["orf_intent"], "provider": "ANDROID_COMPATIBILITY", "message": "ANDROID VM IS NOT READY; ORFMOS INTENT REMAINS VALID"}
    action = str(spec.get("android_action") or "").strip()
    command = f"am start -a {shlex.quote(action)}"
    if spec.get("package_data"):
        command += f" -d {shlex.quote('package:' + package_name)}"
    try:
        rc, output, elapsed = _home_vm_lab_guest_channel_exec(adb, command, timeout=6, channel_name="CONTROL")
        state = "COMPATIBILITY_PROVIDER_ACCEPTED" if int(rc) == 0 else "COMPATIBILITY_PROVIDER_REJECTED"
        _home_vm_lab_event("ORF_SPECIAL_ACCESS_INTENT", f"intent={intent_id} provider=ANDROID_COMPATIBILITY state={state} elapsed={elapsed}s rc={rc}")
        return {
            "schema": ORFMOS_SPECIAL_ACCESS_SCHEMA,
            "state": state,
            "intent": intent_id,
            "orf_intent": spec["orf_intent"],
            "provider": "ANDROID_COMPATIBILITY",
            "elapsed_seconds": elapsed,
            "return_code": rc,
            "message": output[-800:] if output else "ANDROID COMPATIBILITY PROVIDER ACCEPTED THE ORF INTENT" if rc == 0 else "ANDROID COMPATIBILITY PROVIDER RETURNED NONZERO",
        }
    except subprocess.TimeoutExpired as exc:
        _home_vm_lab_event("ORF_SPECIAL_ACCESS_INTENT", f"intent={intent_id} provider=ANDROID_COMPATIBILITY state=PROVIDER_DEGRADED timeout={exc.timeout}s")
        return {
            "schema": ORFMOS_SPECIAL_ACCESS_SCHEMA,
            "state": "COMPATIBILITY_PROVIDER_DEGRADED",
            "intent": intent_id,
            "orf_intent": spec["orf_intent"],
            "provider": "ANDROID_COMPATIBILITY",
            "message": "ANDROID PROVIDER DID NOT ACKNOWLEDGE IN THE BOUNDED WINDOW. ORFMOS NATIVE UI REMAINS RESPONSIVE.",
        }
    except Exception as exc:
        return {
            "schema": ORFMOS_SPECIAL_ACCESS_SCHEMA,
            "state": "COMPATIBILITY_PROVIDER_FAILED",
            "intent": intent_id,
            "orf_intent": spec["orf_intent"],
            "provider": "ANDROID_COMPATIBILITY",
            "message": f"{type(exc).__name__}: {exc}",
        }



ORFMOS_UI_LAB_PROJECTION_SCHEMA = "ORFMOS_UI_LAB_CURRENT_PROJECTION_V0_2"
ORFMOS_UI_LAB_LAYOUT_DELTA_SCHEMA = "ORFMOS_UI_LAB_LAYOUT_DELTA_V0_2"
ORFMOS_UI_LAB_CURRENT_ROOT = os.path.join(ORFMOS_RUNTIME_ROOT, "current", "projections", "ui_lab", "sessions")
_ORFMOS_UI_LAB_PROJECTION_LOCK = globals().get("_ORFMOS_UI_LAB_PROJECTION_LOCK") or threading.RLock()
globals()["_ORFMOS_UI_LAB_PROJECTION_LOCK"] = _ORFMOS_UI_LAB_PROJECTION_LOCK
_ORFMOS_UI_LAB_SURFACES = {
    "DEVELOPER_TOOLS", "APPLICATIONS", "GAME_LAB_LIBRARY", "FILES_RUNTIME",
    "GITHUB_PUBLISHER", "RUNTIME_RECOVERY", "VIRTUALIZATION_LAB", "HOME", "UI_EDITOR",
}
_ORFMOS_UI_LAB_TEMPLATES = {"PORTRAIT", "LANDSCAPE", "DESKTOP"}
_ORFMOS_UI_LAB_VIEWPORTS = {
    "PORTRAIT_GENERIC": ("PORTRAIT", 412, 840),
    "PIXEL_7_PRO": ("PORTRAIT", 412, 840),
    "LANDSCAPE_GENERIC": ("LANDSCAPE", 800, 480),
    "SC4317": ("LANDSCAPE", 800, 480),
    "DESKTOP_GENERIC": ("DESKTOP", 1366, 768),
    "OPTIPLEX_WIN10": ("DESKTOP", 1366, 768),
    "DESKTOP_1440": ("DESKTOP", 1440, 900),
}


def _home_ui_lab_safe_id(value, label, max_len=96):
    normalized = re.sub(r"[^A-Z0-9_-]+", "_", str(value or "").strip().upper()).strip("_")
    if not normalized or len(normalized) > max_len:
        raise ValueError(f"INVALID_{label}")
    return normalized


def _home_ui_lab_projection_target(surface="", template="", viewport="", session=""):
    surface_id = _home_ui_lab_safe_id(surface, "UI_LAB_SURFACE", 64)
    template_id = _home_ui_lab_safe_id(template, "UI_LAB_TEMPLATE", 32)
    viewport_id = _home_ui_lab_safe_id(viewport, "UI_LAB_VIEWPORT", 64)
    session_id = _home_ui_lab_safe_id(session, "UI_LAB_SESSION", 96)
    if surface_id not in _ORFMOS_UI_LAB_SURFACES:
        raise ValueError("INVALID_UI_LAB_SURFACE")
    if template_id not in _ORFMOS_UI_LAB_TEMPLATES:
        raise ValueError("INVALID_UI_LAB_TEMPLATE")
    if viewport_id not in _ORFMOS_UI_LAB_VIEWPORTS:
        raise ValueError("INVALID_UI_LAB_VIEWPORT")
    expected_template, expected_w, expected_h = _ORFMOS_UI_LAB_VIEWPORTS[viewport_id]
    if template_id != expected_template:
        raise ValueError("UI_LAB_TEMPLATE_VIEWPORT_MISMATCH")
    path = os.path.join(ORFMOS_UI_LAB_CURRENT_ROOT, session_id, f"{surface_id}__{template_id}__{viewport_id}.json")
    return surface_id, template_id, viewport_id, session_id, expected_w, expected_h, path


def _home_ui_lab_projection_normalize(payload):
    if not isinstance(payload, dict):
        raise ValueError("UI_LAB_PROJECTION_BODY_REQUIRED")
    if str(payload.get("schema") or "") != ORFMOS_UI_LAB_LAYOUT_DELTA_SCHEMA:
        raise ValueError("UI_LAB_LAYOUT_DELTA_SCHEMA_MISMATCH")
    viewport = payload.get("viewport") if isinstance(payload.get("viewport"), dict) else {}
    session = payload.get("session") if isinstance(payload.get("session"), dict) else {}
    surface_id, template_id, viewport_id, session_id, expected_w, expected_h, path = _home_ui_lab_projection_target(
        payload.get("surface"), payload.get("template_space"), viewport.get("id"), session.get("id")
    )
    if str(session.get("scope") or "") != "USER_SESSION":
        raise ValueError("UI_LAB_SESSION_SCOPE_REQUIRED")
    if str(session.get("authorization") or "") != "USER_SELECTED_UI_PROJECTION":
        raise ValueError("UI_LAB_USER_AUTHORIZATION_REQUIRED")
    if int(viewport.get("width") or 0) != expected_w or int(viewport.get("height") or 0) != expected_h:
        raise ValueError("UI_LAB_VIEWPORT_GEOMETRY_MISMATCH")
    nodes_in = payload.get("nodes") if isinstance(payload.get("nodes"), dict) else {}
    if not nodes_in or len(nodes_in) > 64:
        raise ValueError("UI_LAB_NODE_SET_INVALID")
    nodes = {}
    for raw_key, item in nodes_in.items():
        key = _home_ui_lab_safe_id(raw_key, "UI_LAB_NODE", 64)
        if not isinstance(item, dict):
            raise ValueError(f"UI_LAB_NODE_{key}_INVALID")
        normalized = {}
        for source_key in ("x", "y", "width", "height"):
            value = item.get(source_key)
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise ValueError(f"UI_LAB_NODE_{key}_{source_key.upper()}_INVALID")
            normalized[source_key] = int(round(float(value)))
        if normalized["width"] < 32 or normalized["height"] < 32:
            raise ValueError(f"UI_LAB_NODE_{key}_TOO_SMALL")
        if normalized["x"] < 0 or normalized["y"] < 0:
            raise ValueError(f"UI_LAB_NODE_{key}_NEGATIVE_POSITION")
        if normalized["x"] + normalized["width"] > expected_w or normalized["y"] + normalized["height"] > expected_h:
            raise ValueError(f"UI_LAB_NODE_{key}_OUTSIDE_VIEWPORT")
        nodes[key] = normalized
    if "TITLE" not in nodes:
        raise ValueError("UI_LAB_NODE_MISSING_TITLE")
    if surface_id != "HOME" and "BACK" not in nodes:
        raise ValueError("UI_LAB_NODE_MISSING_BACK")
    if not any(key.startswith("SHELL_") for key in nodes):
        raise ValueError("UI_LAB_SHELL_TARGETS_REQUIRED")
    projection = {
        "schema": ORFMOS_UI_LAB_PROJECTION_SCHEMA,
        "state": "CURRENT_PROJECTION",
        "surface": surface_id,
        "template_space": template_id,
        "viewport": {"id": viewport_id, "label": str(viewport.get("label") or viewport_id), "width": expected_w, "height": expected_h},
        "session": {"id": session_id, "scope": "USER_SESSION", "authorization": "USER_SELECTED_UI_PROJECTION", "authority": "PRESENTATION_ONLY"},
        "render_target": str(payload.get("render_target") or ""),
        "guides": {"snap_guides": bool(payload.get("snap_guides")), "grid": bool(payload.get("grid")), "safe_area": bool(payload.get("safe_area")), "shell_reserved_zone": bool(payload.get("shell_reserved_zone")), "touch_targets": bool(payload.get("touch_targets"))},
        "nodes": nodes,
        "source_delta_schema": ORFMOS_UI_LAB_LAYOUT_DELTA_SCHEMA,
        "authority": "USER_AUTHORIZED_SESSION_PRESENTATION_ONLY",
        "durable_selector_mutated": False,
        "committed_utc": datetime.now(timezone.utc).isoformat(),
    }
    return projection, path


def _home_ui_lab_projection_read(surface="", template="", viewport="", session=""):
    try:
        surface_id, template_id, viewport_id, session_id, _w, _h, path = _home_ui_lab_projection_target(surface, template, viewport, session)
    except Exception as exc:
        return {"schema": ORFMOS_UI_LAB_PROJECTION_SCHEMA, "state": "INVALID_TARGET", "message": f"{type(exc).__name__}: {exc}"}
    with _ORFMOS_UI_LAB_PROJECTION_LOCK:
        if not os.path.isfile(path):
            return {"schema": ORFMOS_UI_LAB_PROJECTION_SCHEMA, "state": "NO_CURRENT_PROJECTION", "surface": surface_id, "template_space": template_id, "viewport": viewport_id, "session": session_id, "path": path}
        try:
            data = Path(path).read_bytes(); document = json.loads(data.decode("utf-8"))
        except Exception as exc:
            return {"schema": ORFMOS_UI_LAB_PROJECTION_SCHEMA, "state": "INVALID_CURRENT_PROJECTION", "surface": surface_id, "viewport": viewport_id, "session": session_id, "path": path, "message": f"{type(exc).__name__}: {exc}"}
    if not isinstance(document, dict) or document.get("schema") != ORFMOS_UI_LAB_PROJECTION_SCHEMA:
        return {"schema": ORFMOS_UI_LAB_PROJECTION_SCHEMA, "state": "INVALID_CURRENT_PROJECTION", "surface": surface_id, "viewport": viewport_id, "session": session_id, "path": path, "message": "CURRENT PROJECTION SCHEMA MISMATCH"}
    return {"schema": ORFMOS_UI_LAB_PROJECTION_SCHEMA, "state": "CURRENT_PROJECTION", "surface": surface_id, "template_space": template_id, "viewport": viewport_id, "session": session_id, "path": path, "bytes": len(data), "sha256": hashlib.sha256(data).hexdigest(), "readback_verified": True, "projection": document}


def _home_ui_lab_projection_http(surface: str = "", template: str = "", viewport: str = "", session: str = ""):
    return _home_ui_lab_projection_read(surface, template, viewport, session)


async def _home_ui_lab_projection_commit_http(request: Request):
    try:
        projection, path = _home_ui_lab_projection_normalize(await request.json())
    except Exception as exc:
        return {"schema": ORFMOS_UI_LAB_PROJECTION_SCHEMA, "state": "BLOCKED", "message": f"{type(exc).__name__}: {exc}", "durable_selector_mutated": False}
    os.makedirs(os.path.dirname(path), exist_ok=True)
    data = json.dumps(projection, sort_keys=True, indent=2).encode("utf-8") + b"\n"
    sha256 = hashlib.sha256(data).hexdigest(); temp = path + ".tmp"
    with _ORFMOS_UI_LAB_PROJECTION_LOCK:
        Path(temp).write_bytes(data); readback = Path(temp).read_bytes()
        if len(readback) != len(data) or hashlib.sha256(readback).hexdigest() != sha256:
            try: os.remove(temp)
            except Exception: pass
            return {"schema": ORFMOS_UI_LAB_PROJECTION_SCHEMA, "state": "WRITE_VERIFY_FAILED", "path": path, "durable_selector_mutated": False}
        os.replace(temp, path); final = Path(path).read_bytes()
    final_sha = hashlib.sha256(final).hexdigest()
    if final != data or final_sha != sha256:
        return {"schema": ORFMOS_UI_LAB_PROJECTION_SCHEMA, "state": "FINAL_READBACK_MISMATCH", "path": path, "sha256": final_sha, "durable_selector_mutated": False}
    return {"schema": ORFMOS_UI_LAB_PROJECTION_SCHEMA, "state": "CURRENT_PROJECTION", "path": path, "bytes": len(final), "sha256": final_sha, "readback_verified": True, "durable_selector_mutated": False, "projection": projection}


async def _home_ui_lab_projection_revert_http(request: Request):
    try:
        payload = await request.json()
        if not isinstance(payload, dict):
            raise ValueError("UI_LAB_REVERT_BODY_REQUIRED")
        viewport = payload.get("viewport") if isinstance(payload.get("viewport"), dict) else {}
        session = payload.get("session") if isinstance(payload.get("session"), dict) else {}
        if str(session.get("scope") or "") != "USER_SESSION":
            raise ValueError("UI_LAB_SESSION_SCOPE_REQUIRED")
        if str(session.get("authorization") or "") != "USER_SELECTED_UI_PROJECTION":
            raise ValueError("UI_LAB_USER_AUTHORIZATION_REQUIRED")
        surface_id, template_id, viewport_id, session_id, _w, _h, path = _home_ui_lab_projection_target(
            payload.get("surface"), payload.get("template_space"), viewport.get("id"), session.get("id")
        )
    except Exception as exc:
        return {"schema": ORFMOS_UI_LAB_PROJECTION_SCHEMA, "state": "BLOCKED", "message": f"{type(exc).__name__}: {exc}", "durable_selector_mutated": False}
    removed = False
    with _ORFMOS_UI_LAB_PROJECTION_LOCK:
        if os.path.isfile(path):
            os.remove(path)
            removed = True
        absence_verified = not os.path.exists(path)
    return {
        "schema": ORFMOS_UI_LAB_PROJECTION_SCHEMA,
        "state": "DEFAULT_PROJECTION" if absence_verified else "REVERT_VERIFY_FAILED",
        "surface": surface_id,
        "template_space": template_id,
        "viewport": viewport_id,
        "session": session_id,
        "path": path,
        "removed_current_projection": removed,
        "absence_verified": absence_verified,
        "durable_selector_mutated": False,
    }


def _home_install_vm_lab_routes(app):
    """Bind/rebind all VM Lab routes into the resident FastAPI app.

    This definition is intentionally carried in the immutable Home source so a
    true cold BIOS boot never depends on a route installer left resident by a
    predecessor generation.
    """
    if app is None or not hasattr(app, "add_api_route"):
        return False
    marker = "__ORFMOS_HOME_VM_LAB_ROUTES_V0_1__"
    target_paths = {
        "/orfmos/vm-lab/state",
        "/orfmos/vm-lab/provision",
        "/orfmos/vm-lab/start",
        "/orfmos/vm-lab/stop",
        "/orfmos/vm-lab/apps",
        "/orfmos/vm-lab/launch",
        "/orfmos/vm-lab/presentation",
        "/orfmos/vm-lab/presentation-state",
        "/orfmos/vm-lab/input",
        "/orfmos/runtime/probes",
        "/orfmos/runtime/probe",
        "/orfmos/preflight/upload",
        "/orfmos/preflight/staged",
        "/orfmos/preflight/execute",
        "/orfmos/preflight/send-installer",
        "/orfmos/module-creator/state",
        "/orfmos/module-creator/validate",
        "/orfmos/module-creator/build",
        "/orfmos/manifest-creator/state",
        "/orfmos/manifest-creator/validate",
        "/orfmos/manifest-creator/build",
        "/orfmos/runtime-recovery/state",
        "/orfmos/runtime-recovery/snapshot",
        "/orfmos/runtime-recovery/set-active",
        "/orfmos/runtime-recovery/load-development-head",
        "/orfmos/device-compatibility/state",
        "/orfmos/device-compatibility/probe/download",
        "/orfmos/device-compatibility/android/orf-console/download",
        "/orfmos/special-access/state",
        "/orfmos/special-access/intent",
        "/orfmos/vm-module/policy",
        "/orfmos/ui-lab/projection",
        "/orfmos/ui-lab/projection/commit",
        "/orfmos/ui-lab/projection/revert",
    }
    removed = 0
    router = getattr(app, "router", None)
    routes = getattr(router, "routes", None) if router is not None else None
    if isinstance(routes, list):
        kept = []
        for route in list(routes):
            if getattr(route, "path", None) in target_paths:
                removed += 1
                continue
            kept.append(route)
        routes[:] = kept
    app.add_api_route("/orfmos/vm-lab/state", _home_vm_lab_state_http, methods=["GET"], name="orfmos_vm_lab_state")
    app.add_api_route("/orfmos/vm-lab/provision", _home_vm_lab_provision_http, methods=["POST"], name="orfmos_vm_lab_provision")
    app.add_api_route("/orfmos/vm-lab/start", _home_vm_lab_start_http, methods=["POST"], name="orfmos_vm_lab_start")
    app.add_api_route("/orfmos/vm-lab/stop", _home_vm_lab_stop_http, methods=["POST"], name="orfmos_vm_lab_stop")
    app.add_api_route("/orfmos/vm-lab/apps", _home_vm_lab_guest_apps_http, methods=["GET"], name="orfmos_vm_lab_apps")
    app.add_api_route("/orfmos/vm-lab/launch", _home_vm_lab_launch_http, methods=["POST"], name="orfmos_vm_lab_launch")
    app.add_api_route("/orfmos/vm-lab/presentation", _home_vm_lab_presentation_http, methods=["GET"], name="orfmos_vm_lab_presentation")
    app.add_api_route("/orfmos/vm-lab/presentation-state", _home_vm_lab_presentation_state_http, methods=["GET"], name="orfmos_vm_lab_presentation_state")
    app.add_api_route("/orfmos/vm-lab/input", _home_vm_lab_input_http, methods=["POST"], name="orfmos_vm_lab_input")
    app.add_api_route("/orfmos/runtime/probes", _home_runtime_probes_http, methods=["GET"], name="orfmos_runtime_probes")
    app.add_api_route("/orfmos/runtime/probe", _home_runtime_probe_http, methods=["POST"], name="orfmos_runtime_probe")
    app.add_api_route("/orfmos/preflight/upload", _home_preflight_upload_http, methods=["POST"], name="orfmos_preflight_upload")
    app.add_api_route("/orfmos/preflight/staged", _home_preflight_staged_http, methods=["GET"], name="orfmos_preflight_staged")
    app.add_api_route("/orfmos/preflight/execute", _home_preflight_execute_http, methods=["POST"], name="orfmos_preflight_execute")
    app.add_api_route("/orfmos/preflight/send-installer", _home_preflight_send_installer_http, methods=["POST"], name="orfmos_preflight_send_installer")
    app.add_api_route("/orfmos/module-creator/state", _home_module_creator_state_http, methods=["GET"], name="orfmos_module_creator_state")
    app.add_api_route("/orfmos/module-creator/validate", _home_module_creator_validate_http, methods=["POST"], name="orfmos_module_creator_validate")
    app.add_api_route("/orfmos/module-creator/build", _home_module_creator_build_http, methods=["POST"], name="orfmos_module_creator_build")
    app.add_api_route("/orfmos/manifest-creator/state", _home_manifest_creator_state_http, methods=["GET"], name="orfmos_manifest_creator_state")
    app.add_api_route("/orfmos/manifest-creator/validate", _home_manifest_creator_validate_http, methods=["POST"], name="orfmos_manifest_creator_validate")
    app.add_api_route("/orfmos/manifest-creator/build", _home_manifest_creator_build_http, methods=["POST"], name="orfmos_manifest_creator_build")
    app.add_api_route("/orfmos/runtime-recovery/state", _home_runtime_recovery_state_http, methods=["GET"], name="orfmos_runtime_recovery_state")
    app.add_api_route("/orfmos/runtime-recovery/snapshot", _home_runtime_recovery_snapshot_http, methods=["POST"], name="orfmos_runtime_recovery_snapshot")
    app.add_api_route("/orfmos/runtime-recovery/set-active", _home_runtime_recovery_set_active_http, methods=["POST"], name="orfmos_runtime_recovery_set_active")
    app.add_api_route("/orfmos/runtime-recovery/load-development-head", _home_runtime_recovery_load_development_head_http, methods=["POST"], name="orfmos_runtime_recovery_load_development_head")
    app.add_api_route("/orfmos/device-compatibility/state", _home_device_compatibility_state_http, methods=["GET"], name="orfmos_device_compatibility_state")
    app.add_api_route("/orfmos/device-compatibility/probe/download", _home_device_compatibility_probe_download_http, methods=["GET"], name="orfmos_device_compatibility_probe_download")
    app.add_api_route("/orfmos/device-compatibility/android/orf-console/download", _home_device_compatibility_orf_console_download_http, methods=["GET"], name="orfmos_device_compatibility_orf_console_download")
    app.add_api_route("/orfmos/special-access/state", _home_special_access_state_http, methods=["GET"], name="orfmos_special_access_state")
    app.add_api_route("/orfmos/special-access/intent", _home_special_access_intent_http, methods=["POST"], name="orfmos_special_access_intent")
    app.add_api_route("/orfmos/vm-module/policy", _home_vm_module_policy_http, methods=["GET", "POST"], name="orfmos_vm_module_policy")
    app.add_api_route("/orfmos/ui-lab/projection", _home_ui_lab_projection_http, methods=["GET"], name="orfmos_ui_lab_projection")
    app.add_api_route("/orfmos/ui-lab/projection/commit", _home_ui_lab_projection_commit_http, methods=["POST"], name="orfmos_ui_lab_projection_commit")
    app.add_api_route("/orfmos/ui-lab/projection/revert", _home_ui_lab_projection_revert_http, methods=["POST"], name="orfmos_ui_lab_projection_revert")
    setattr(app, marker, ORFMOS_VM_LAB_ROUTE_REVISION)
    setattr(app, "__ORFMOS_HOME_VM_LAB_ROUTE_REVISION__", ORFMOS_VM_LAB_ROUTE_REVISION)
    _home_vm_lab_event("VM_LAB_ROUTES_REBOUND", f"revision={ORFMOS_VM_LAB_ROUTE_REVISION} removed={removed} bound={len(target_paths)}")
    return True


ORFMOS_INSTALLER_SCHEMA = "ORFMOS_EXECUTABLE_INSTALLER_STATE_V0_1"
ORFMOS_INSTALLER_ROUTE_REVISION = "R79_COMPATIBILITY_SURFACE_OBSERVATION_COMPRESSION"
ORFMOS_EXECUTABLE_MANIFEST_SCHEMA = "ORFMOS_EXECUTABLE_MANIFEST_V0_1"
ORFMOS_INSTALLER_STAGE_ROOT = os.path.join(ORFMOS_RUNTIME_ROOT, "orfmos", "installer", "stage")
_ORFMOS_INSTALLER_LOCK = globals().get("_ORFMOS_INSTALLER_LOCK") or threading.RLock()
globals()["_ORFMOS_INSTALLER_LOCK"] = _ORFMOS_INSTALLER_LOCK


def _home_installer_initial_state(generation=0, events=None):
    return {
        "schema": ORFMOS_INSTALLER_SCHEMA,
        "state": "NO_TARGET",
        "selection_generation": int(generation),
        "target_armed": False,
        "selected_sha256": "",
        "selected_size": None,
        "staged_path": None,
        "commit_provider": "NONE",
        "route_revision": ORFMOS_INSTALLER_ROUTE_REVISION,
        "last_commit_status": "NONE",
        "last_commit_provider": "NONE",
        "last_commit_result": "",
        "commit_job_state": "IDLE",
        "commit_job_started_epoch": None,
        "commit_job_completed_epoch": None,
        "commit_job_generation": None,
        "commit_job_sha256": "",
        "commit_job_provider": "NONE",
        "consent_state": "NOT_REQUESTED",
        "consent_generation": None,
        "consent_sha256": "",
        "consent_provider": "NONE",
        "mps": {
            "schema": ORFMOS_MPS_SCHEMA,
            "provider": ORFMOS_MPS_PROVIDER,
            "service": ORFMOS_MPS_SERVICE,
            "intent": ORFMOS_MPS_INSTALL_INTENT,
            "sequence": list(ORFMOS_MPS_INSTALL_SEQUENCE),
            "operation": "IDLE",
            "interaction": "NONE",
            "reaction": "IDLE",
            "realization_provider": "NONE",
        },
        "executable_manifest": None,
        "events": list(events or []),
        "message": "SELECT A FILE IN FILES, THEN PREPARE IT HERE",
    }


def _home_installer_state():
    state = globals().get("__ORFMOS_INSTALLER_STATE__")
    if not isinstance(state, dict) or state.get("schema") != ORFMOS_INSTALLER_SCHEMA:
        state = _home_installer_initial_state()
        globals()["__ORFMOS_INSTALLER_STATE__"] = state
    prior_route_revision = str(state.get("route_revision") or "")
    if prior_route_revision and prior_route_revision != ORFMOS_INSTALLER_ROUTE_REVISION and str(state.get("commit_job_state") or "").upper() == "RUNNING":
        # A hot-loaded successor must not inherit transaction ownership from an
        # older route generation. Bump selection_generation so the predecessor
        # worker's cancellation contract becomes false, but preserve the staged
        # immutable target so the user can immediately retry through the successor.
        old_generation = int(state.get("selection_generation") or 0)
        state["selection_generation"] = old_generation + 1
        state["commit_job_state"] = "SUPERSEDED"
        state["commit_job_completed_epoch"] = time.time()
        state["last_commit_status"] = "SUPERSEDED_BY_MPS_SUCCESSOR"
        state["last_commit_result"] = f"route={prior_route_revision} -> {ORFMOS_INSTALLER_ROUTE_REVISION}"
        staged_ok = bool(state.get("staged_path") and os.path.isfile(str(state.get("staged_path"))) and state.get("selected_sha256"))
        state["target_armed"] = staged_ok
        state["state"] = "TARGET_READY" if staged_ok else "NO_TARGET"
        state["consent_state"] = "NOT_REQUESTED"
        state["consent_generation"] = None
        state["consent_sha256"] = ""
        state["consent_provider"] = "NONE"
        state["message"] = "PREDECESSOR INSTALL TRANSACTION SUPERSEDED; VERIFIED TARGET RE-ARMED FOR ORFMOS MPS" if staged_ok else "PREDECESSOR INSTALL TRANSACTION SUPERSEDED"
        events = list(state.get("events") or [])
        events.append({
            "utc": datetime.now(timezone.utc).isoformat(),
            "type": "MPS_PREDECESSOR_TRANSACTION_SUPERSEDED",
            "detail": f"route={prior_route_revision} old_generation={old_generation} new_generation={old_generation + 1} target_rearmed={staged_ok}",
        })
        state["events"] = events[-64:]
    state.setdefault("last_commit_status", "NONE")
    state.setdefault("last_commit_provider", "NONE")
    state.setdefault("last_commit_result", "")
    state.setdefault("commit_job_state", "IDLE")
    state.setdefault("commit_job_started_epoch", None)
    state.setdefault("commit_job_completed_epoch", None)
    state.setdefault("commit_job_generation", None)
    state.setdefault("commit_job_sha256", "")
    state.setdefault("commit_job_provider", "NONE")
    state.setdefault("consent_state", "NOT_REQUESTED")
    state.setdefault("consent_generation", None)
    state.setdefault("consent_sha256", "")
    state.setdefault("consent_provider", "NONE")
    mps = state.get("mps")
    if not isinstance(mps, dict):
        mps = {}
        state["mps"] = mps
    mps["schema"] = ORFMOS_MPS_SCHEMA
    mps["provider"] = ORFMOS_MPS_PROVIDER
    mps["service"] = ORFMOS_MPS_SERVICE
    mps["intent"] = ORFMOS_MPS_INSTALL_INTENT
    mps["sequence"] = list(ORFMOS_MPS_INSTALL_SEQUENCE)
    mps.setdefault("operation", "IDLE")
    mps.setdefault("interaction", "NONE")
    mps.setdefault("reaction", "IDLE")
    mps.setdefault("realization_provider", "NONE")
    state["route_revision"] = ORFMOS_INSTALLER_ROUTE_REVISION
    return state


def _home_installer_event(state, event_type, detail=""):
    events = list(state.get("events") or [])
    events.append({
        "utc": datetime.now(timezone.utc).isoformat(),
        "type": str(event_type or "EVENT"),
        "detail": str(detail or ""),
    })
    state["events"] = events[-64:]


def _home_installer_runtime_inventory():
    # Observation only. ORFMOS recovery may resolve more languages/toolchains into the
    # kernel later; absence from PATH is not classified as permanent incompatibility.
    import shutil
    android_root = str(os.environ.get("ANDROID_SDK_ROOT") or os.environ.get("ANDROID_HOME") or "").strip()
    return {
        "host": "ORFMOS_KERNEL_POLYGLOT",
        "extensible": True,
        "python": shutil.which("python3") or shutil.which("python"),
        "java": shutil.which("java"),
        "javac": shutil.which("javac"),
        "gradle": shutil.which("gradle"),
        "android_sdk_root": android_root or None,
        "library_policy": "DEPENDENCIES_MAY_BE_RESOLVED_OR_ADDED_TO_KERNEL",
    }


def _home_installer_detect_container(name, mime_type, data):
    lower = str(name or "").lower()
    mime = str(mime_type or "").lower()
    if lower.endswith(".apk") or mime == "application/vnd.android.package-archive":
        return "APK"
    # APKs are ZIP containers, but generic ZIP is deliberately not admitted yet because
    # an executable entrypoint/manifest contract has not been minted for it.
    if bytes(data or b"")[:4] == b"PK\x03\x04":
        return "ZIP_UNCLASSIFIED"
    return "UNCLASSIFIED"


def _home_installer_manifest_from_apk(profile):
    file_info = dict(profile.get("file") or {})
    return {
        "schema": ORFMOS_EXECUTABLE_MANIFEST_SCHEMA,
        "identity": {
            "name": file_info.get("name") or "selected.apk",
            "package_identity": None,
            "package_identity_state": "OXML_RESOLUTION_REQUIRED" if (profile.get("manifest") or {}).get("format") == "ANDROID_BINARY_AXML" else "NOT_YET_NORMALIZED",
        },
        "container": {
            "format": "APK",
            "adapter": "APK_MANIFEST_ADAPTER_V0_1",
            "source_semantics": "ANDROID_EXECUTABLE_CONTAINER",
        },
        "integrity": {
            "sha256": file_info.get("sha256"),
            "bytes": file_info.get("bytes"),
            "signing": dict(profile.get("signing") or {}),
        },
        "declared_manifest": dict(profile.get("manifest") or {}),
        "observed_contracts": [dict(item) for item in (profile.get("contracts") or [])],
        "execution": {
            "translation_posture": profile.get("translation_posture"),
            "candidate_providers": [
                {"id": "LOG_ONLY", "state": "READY", "role": "INSTALL_CONTRACT_TEST"},
                {"id": "ANDROID_VM_LAB", "state": _home_vm_lab_provider_state(), "role": "ANDROID_GUEST_EXECUTION"},
                {"id": "ORFMOS_KERNEL_POLYGLOT", "state": "TRANSLATION_OR_RUNTIME_BINDING_REQUIRED", "role": "LOCAL_CLOUD_EXECUTION"},
                {"id": "ANDROID_PACKAGE_MANAGER", "state": "DEVICE_PROVIDER_ONLY", "role": "ANDROID_DEVICE_COMMIT"},
            ],
            "kernel": _home_installer_runtime_inventory(),
        },
        "source": {
            "provider": file_info.get("provider"),
            "uri": file_info.get("uri"),
            "identity": file_info.get("identity"),
        },
        "normalization_limits": list(profile.get("profile_limits") or []),
        "generated_utc": datetime.now(timezone.utc).isoformat(),
    }


def _home_installer_state_http():
    with _ORFMOS_INSTALLER_LOCK:
        return json.loads(json.dumps(_home_installer_state()))


async def _home_installer_prepare_http(request: Request, provider: str = "", uri: str = "", identity: str = "", name: str = "", mime_type: str = ""):
    p = str(provider or "").strip().upper()
    with _ORFMOS_INSTALLER_LOCK:
        previous = _home_installer_state()
        generation = int(previous.get("selection_generation") or 0) + 1
        state = _home_installer_initial_state(generation=generation, events=previous.get("events"))
        state.update({"state": "TARGET_RECEIVED", "message": "INGESTING TARGET"})
        _home_installer_event(state, "TARGET_RECEIVED", f"generation={generation} provider={p or 'UNKNOWN'} name={name or 'UNNAMED'}")
        globals()["__ORFMOS_INSTALLER_STATE__"] = state

    try:
        if p == "ANDROID_ORF_DRIVE":
            data = await request.body()
            header_name = str(request.headers.get("x-orf-file-name") or "").strip()
            if header_name:
                name = header_name
            if not data:
                raise RuntimeError("ANDROID_BROWSER_FILE_BYTES_EMPTY")
            source_uri = "browser-file-object://selected"
        else:
            data = _home_read_normalized_file_bytes(p, uri, identity=identity)
            source_uri = str(uri or "")
        data = bytes(data or b"")
        if not data:
            raise RuntimeError("EXECUTABLE_CONTAINER_EMPTY")
        if len(data) > ORFMOS_APK_PROFILE_MAX_BYTES:
            raise RuntimeError("EXECUTABLE_CONTAINER_SIZE_LIMIT_EXCEEDED")

        container_format = _home_installer_detect_container(name, mime_type, data)
        if container_format != "APK":
            raise RuntimeError(f"EXECUTABLE_CONTAINER_ADAPTER_NOT_BOUND:{container_format}")

        profile = _home_profile_apk_bytes(data, provider=p, uri=source_uri, identity=identity, name=name)
        if profile.get("status") != "READY":
            raise RuntimeError(str(profile.get("message") or "APK_PROFILE_FAILED"))
        sha = hashlib.sha256(data).hexdigest()
        os.makedirs(ORFMOS_INSTALLER_STAGE_ROOT, exist_ok=True)
        final_path = os.path.join(ORFMOS_INSTALLER_STAGE_ROOT, sha + ".apk")
        temp_path = final_path + f".g{generation}.tmp"
        with open(temp_path, "wb") as handle:
            handle.write(data)
            handle.flush()
            try:
                os.fsync(handle.fileno())
            except Exception:
                pass
        with open(temp_path, "rb") as handle:
            staged_hash = hashlib.sha256(handle.read()).hexdigest()
        if staged_hash != sha:
            raise RuntimeError("STAGE_HASH_MISMATCH")
        os.replace(temp_path, final_path)
        manifest = _home_installer_manifest_from_apk(profile)

        with _ORFMOS_INSTALLER_LOCK:
            current = _home_installer_state()
            if int(current.get("selection_generation") or -1) != generation:
                raise RuntimeError("SELECTION_GENERATION_CHANGED_DURING_STAGE")
            current.update({
                "state": "TARGET_READY",
                "target_armed": True,
                "selected_sha256": sha,
                "selected_size": len(data),
                "staged_path": final_path,
                "commit_provider": "NONE",
                "last_commit_status": "READY",
                "last_commit_provider": "NONE",
                "last_commit_result": "",
                "consent_state": "NOT_REQUESTED",
                "consent_generation": None,
                "consent_sha256": "",
                "consent_provider": "NONE",
                "executable_manifest": manifest,
                "message": "EXECUTABLE MANIFEST NORMALIZED; COMMIT PROVIDER REQUIRED",
            })
            _home_installer_event(current, "TARGET_READY", f"generation={generation} bytes={len(data)} sha256={sha}")
            return json.loads(json.dumps(current))
    except Exception as exc:
        try:
            if 'temp_path' in locals() and os.path.exists(temp_path):
                os.remove(temp_path)
        except Exception:
            pass
        with _ORFMOS_INSTALLER_LOCK:
            current = _home_installer_state()
            if int(current.get("selection_generation") or -1) == generation:
                current.update({"state": "TARGET_INVALID", "target_armed": False, "message": f"{type(exc).__name__}: {exc}"})
                _home_installer_event(current, "TARGET_INGEST_FAILED", current["message"])
            return json.loads(json.dumps(current))


def _home_installer_consent_http(generation: int = -1, sha256: str = "", provider: str = "ANDROID_VM_LAB", action: str = "ACCEPT"):
    requested_provider = str(provider or "ANDROID_VM_LAB").strip().upper()
    requested_action = str(action or "ACCEPT").strip().upper()
    with _ORFMOS_INSTALLER_LOCK:
        state = _home_installer_state()
        try:
            if not state.get("target_armed") or state.get("state") != "TARGET_READY":
                raise RuntimeError("NO_ARMED_TARGET")
            if int(generation) != int(state.get("selection_generation") or -1):
                raise RuntimeError("SELECTION_GENERATION_CHANGED_BEFORE_CONSENT")
            expected = str(state.get("selected_sha256") or "").lower()
            if not expected or str(sha256 or "").lower() != expected:
                raise RuntimeError("CONSENT_HASH_IDENTITY_MISMATCH")
            if requested_provider != "ANDROID_VM_LAB":
                raise RuntimeError(f"CONSENT_PROVIDER_NOT_BOUND:{requested_provider}")
            if requested_action == "CANCEL":
                state["consent_state"] = "CANCELLED"
                state["consent_generation"] = int(generation)
                state["consent_sha256"] = expected
                state["consent_provider"] = requested_provider
                state["last_commit_status"] = "CANCELLED"
                state["last_commit_provider"] = requested_provider
                state["last_commit_result"] = "USER_CANCELLED_INSTALL"
                state["message"] = "INSTALL CANCELLED; VERIFIED TARGET REMAINS READY"
                _home_installer_event(state, "INSTALL_CONSENT_CANCELLED", f"provider={requested_provider} generation={generation} sha256={expected}")
                return json.loads(json.dumps(state))
            if requested_action != "ACCEPT":
                raise RuntimeError(f"CONSENT_ACTION_INVALID:{requested_action}")
            state["consent_state"] = "ACCEPTED"
            state["consent_generation"] = int(generation)
            state["consent_sha256"] = expected
            state["consent_provider"] = requested_provider
            state["last_commit_status"] = "CONSENT_ACCEPTED"
            state["last_commit_provider"] = requested_provider
            state["last_commit_result"] = "USER_AUTHORIZED_INSTALL"
            state["message"] = "INSTALL CONSENT ACCEPTED; COMMIT MAY PROCEED"
            _home_installer_event(state, "INSTALL_CONSENT_ACCEPTED", f"provider={requested_provider} generation={generation} sha256={expected}")
            return json.loads(json.dumps(state))
        except Exception as exc:
            state["consent_state"] = "BLOCKED"
            state["last_commit_status"] = "BLOCKED"
            state["last_commit_provider"] = requested_provider
            state["last_commit_result"] = f"{type(exc).__name__}: {exc}"
            state["message"] = state["last_commit_result"]
            _home_installer_event(state, "INSTALL_CONSENT_BLOCKED", state["message"])
            return json.loads(json.dumps(state))


def _home_installer_vm_commit_worker(generation: int, expected: str, path: str):
    def current_state_matches():
        with _ORFMOS_INSTALLER_LOCK:
            state = _home_installer_state()
            return (
                int(state.get("selection_generation") or -1) == int(generation)
                and str(state.get("selected_sha256") or "").lower() == str(expected or "").lower()
                and str(state.get("commit_job_state") or "").upper() == "RUNNING"
            )

    def cancelled():
        return not current_state_matches()

    def progress(status, detail=""):
        with _ORFMOS_INSTALLER_LOCK:
            state = _home_installer_state()
            if int(state.get("selection_generation") or -1) != int(generation) or str(state.get("selected_sha256") or "").lower() != str(expected or "").lower():
                return
            status = str(status or "").upper()
            detail = str(detail or "")[-500:]
            state["state"] = "COMMITTING_ANDROID_VM_LAB"
            state["commit_provider"] = "ANDROID_VM_LAB"
            state["commit_job_state"] = "RUNNING"
            state["last_commit_provider"] = "ANDROID_VM_LAB"
            state["last_commit_status"] = status or "COMMITTING"
            state["last_commit_result"] = detail[-240:]
            mps = state.get("mps") if isinstance(state.get("mps"), dict) else {}
            state["mps"] = mps
            mps.update({
                "schema": ORFMOS_MPS_SCHEMA,
                "provider": ORFMOS_MPS_PROVIDER,
                "service": ORFMOS_MPS_SERVICE,
                "intent": ORFMOS_MPS_INSTALL_INTENT,
                "sequence": list(ORFMOS_MPS_INSTALL_SEQUENCE),
                "realization_provider": ORFMOS_MPS_ANDROID_REALIZATION_PROVIDER,
            })
            if status == "MPS_LOCATE":
                mps.update({"operation": "LOCATE", "interaction": "TARGET_PROVIDER_RESOLUTION", "reaction": "RESOLVED"})
                state["message"] = "ORFMOS MPS INSTALL · LOCATING ANDROID REALIZATION PROVIDER"
            elif status == "MPS_READ":
                mps.update({"operation": "READ", "interaction": "ADB_GUEST_STAGE", "reaction": "TRANSFERRING"})
                state["message"] = "ORFMOS MPS INSTALL · READING VERIFIED APK INTO GUEST STAGE"
            elif status in {"MPS_VALIDATE", "MPS_VALIDATED"}:
                mps.update({"operation": "VALIDATE", "interaction": "GUEST_STAGE_INTEGRITY", "reaction": "VALIDATED" if status == "MPS_VALIDATED" else "VALIDATING"})
                state["message"] = "ORFMOS MPS INSTALL · VALIDATING GUEST-STAGED APK"
            elif status == "MPS_WRITE":
                mps.update({"operation": "WRITE", "interaction": "ANDROID_PM_INSTALL_GUEST_LOCAL", "reaction": "RUNNING"})
                state["message"] = "ORFMOS MPS INSTALL · ANDROID PACKAGE REALIZATION ACTIVE"
            elif status == "MPS_WRITE_STALLED":
                mps.update({"operation": "WRITE", "interaction": "ANDROID_PM_INSTALL_GUEST_LOCAL", "reaction": "PROVIDER_STALLED"})
                state["message"] = "ORFMOS MPS HEALTHY; ANDROID PACKAGE REALIZATION PROVIDER STALLED"
            elif status == "MPS_REACTION_INSTALLED":
                mps.update({"operation": "WRITE", "interaction": "ANDROID_PM_INSTALL_GUEST_LOCAL", "reaction": "INSTALLED"})
                state["message"] = "ORFMOS MPS INSTALL · REALIZATION VERIFIED ACCEPTED"
            elif status == "WAITING_FOR_PACKAGE_SERVICE":
                state["message"] = "ANDROID VM READY; WAITING FOR PACKAGE SERVICE CAPABILITY"
            elif status == "WAITING_FOR_VM_READY":
                state["message"] = "INSTALL COMMIT HELD; VM INSTANCE ALIVE AND STILL COMPLETING BOOT"
            elif status == "RETRYING_PACKAGE_SERVICE":
                state["message"] = "PACKAGE SERVICE TRANSIENT FAILURE; INSTALL RETRY WILL CONTINUE"
            elif status == "INSTALLING":
                state["message"] = "ANDROID PACKAGE INSTALL PROVIDER ACTIVE"
            elif status == "INSTALLED":
                state["message"] = "ANDROID PACKAGE INSTALL PROVIDER ACCEPTED"

    try:
        install_result = _home_vm_lab_install_apk(path, progress=progress, cancelled=cancelled)
        with _ORFMOS_INSTALLER_LOCK:
            state = _home_installer_state()
            if int(state.get("selection_generation") or -1) != int(generation) or str(state.get("selected_sha256") or "").lower() != str(expected or "").lower():
                _home_installer_event(state, "COMMIT_RESULT_ORPHANED", f"provider=ANDROID_VM_LAB generation={generation} sha256={expected} result={str(install_result or '')[-160:]}")
                return
            state["state"] = "COMMIT_ACCEPTED_ANDROID_VM_LAB"
            state["commit_provider"] = "ANDROID_VM_LAB"
            state["target_armed"] = False
            state["last_commit_status"] = "INSTALLED"
            state["last_commit_provider"] = "ANDROID_VM_LAB"
            state["last_commit_result"] = str(install_result or "")[-240:]
            state["commit_job_state"] = "COMPLETE"
            state["commit_job_completed_epoch"] = time.time()
            mps = state.get("mps") if isinstance(state.get("mps"), dict) else {}
            state["mps"] = mps
            mps.update({"operation": "WRITE", "interaction": "ANDROID_PM_INSTALL_GUEST_LOCAL", "reaction": "INSTALLED", "realization_provider": ORFMOS_MPS_ANDROID_REALIZATION_PROVIDER})
            state["message"] = "ORFMOS MPS INSTALL COMPLETE; APK REALIZED IN ANDROID VM LAB"
            _home_installer_event(state, "COMMIT_ACCEPTED", f"provider=ANDROID_VM_LAB generation={generation} sha256={expected} result={str(install_result or '')[-200:]}")
    except Exception as exc:
        with _ORFMOS_INSTALLER_LOCK:
            state = _home_installer_state()
            if int(state.get("selection_generation") or -1) == int(generation) and str(state.get("selected_sha256") or "").lower() == str(expected or "").lower():
                if str(exc) == "ANDROID_VM_LAB_INSTALL_ORPHANED":
                    _home_installer_event(state, "COMMIT_WORKER_ORPHANED", f"generation={generation} sha256={expected}")
                    return
                state["state"] = "TARGET_READY"
                state["target_armed"] = True
                state["last_commit_status"] = "FAILED"
                state["last_commit_provider"] = "ANDROID_VM_LAB"
                state["last_commit_result"] = f"{type(exc).__name__}: {exc}"
                state["commit_job_state"] = "FAILED"
                state["commit_job_completed_epoch"] = time.time()
                state["consent_state"] = "NOT_REQUESTED"
                state["consent_generation"] = None
                state["consent_sha256"] = ""
                state["consent_provider"] = "NONE"
                mps = state.get("mps") if isinstance(state.get("mps"), dict) else {}
                state["mps"] = mps
                mps.update({"operation": "WRITE", "interaction": "ANDROID_PACKAGE_REALIZATION", "reaction": "PROVIDER_FAILED", "realization_provider": ORFMOS_MPS_ANDROID_REALIZATION_PROVIDER})
                state["message"] = state["last_commit_result"]
                _home_installer_event(state, "COMMIT_FAILED", state["message"])


def _home_installer_commit_http(generation: int = -1, sha256: str = "", provider: str = "LOG_ONLY"):
    requested_provider = str(provider or "LOG_ONLY").strip().upper()
    with _ORFMOS_INSTALLER_LOCK:
        state = _home_installer_state()
        try:
            if not state.get("target_armed") or state.get("state") != "TARGET_READY":
                raise RuntimeError("NO_ARMED_TARGET")
            if int(generation) != int(state.get("selection_generation") or -1):
                raise RuntimeError("SELECTION_GENERATION_CHANGED_BEFORE_COMMIT")
            expected = str(state.get("selected_sha256") or "").lower()
            if not expected or str(sha256 or "").lower() != expected:
                raise RuntimeError("COMMIT_HASH_IDENTITY_MISMATCH")
            path = str(state.get("staged_path") or "")
            if not path or not os.path.isfile(path):
                raise RuntimeError("STAGED_TARGET_MISSING")
            with open(path, "rb") as handle:
                current_hash = hashlib.sha256(handle.read()).hexdigest()
            if current_hash != expected:
                raise RuntimeError("STAGED_TARGET_CHANGED_AFTER_INSPECTION")
            if requested_provider == "LOG_ONLY":
                state["state"] = "COMMIT_ACCEPTED_LOG_ONLY"
                state["commit_provider"] = "LOG_ONLY"
                state["last_commit_status"] = "ACCEPTED_LOG_ONLY"
                state["last_commit_provider"] = "LOG_ONLY"
                state["last_commit_result"] = "NO_EXECUTION_MUTATION"
                state["message"] = "CONTRACT COMMIT ACCEPTED; NO EXECUTION ENVIRONMENT MUTATED"
                _home_installer_event(state, "COMMIT_ACCEPTED", f"provider=LOG_ONLY generation={generation} sha256={expected}")
                return json.loads(json.dumps(state))
            if requested_provider == "ANDROID_VM_LAB":
                if str(state.get("commit_job_state") or "").upper() == "RUNNING":
                    raise RuntimeError("INSTALL_COMMIT_ALREADY_RUNNING")
                if str(state.get("consent_state") or "").upper() != "ACCEPTED":
                    raise RuntimeError("INSTALL_CONSENT_REQUIRED")
                if int(state.get("consent_generation") or -1) != int(generation):
                    raise RuntimeError("INSTALL_CONSENT_GENERATION_MISMATCH")
                if str(state.get("consent_sha256") or "").lower() != expected:
                    raise RuntimeError("INSTALL_CONSENT_HASH_MISMATCH")
                if str(state.get("consent_provider") or "").upper() != requested_provider:
                    raise RuntimeError("INSTALL_CONSENT_PROVIDER_MISMATCH")
                state["consent_state"] = "CONSUMED"
                state["state"] = "COMMITTING_ANDROID_VM_LAB"
                state["target_armed"] = False
                state["commit_provider"] = "ANDROID_VM_LAB"
                state["last_commit_status"] = "COMMITTING"
                state["last_commit_provider"] = "ANDROID_VM_LAB"
                state["last_commit_result"] = "ORFMOS MPS INSTALL RUNNING IN BACKGROUND"
                mps = state.get("mps") if isinstance(state.get("mps"), dict) else {}
                state["mps"] = mps
                mps.update({"operation": "LOCATE", "interaction": "TARGET_PROVIDER_RESOLUTION", "reaction": "RUNNING", "realization_provider": ORFMOS_MPS_ANDROID_REALIZATION_PROVIDER})
                state["commit_job_state"] = "RUNNING"
                state["commit_job_started_epoch"] = time.time()
                state["commit_job_completed_epoch"] = None
                state["commit_job_generation"] = int(generation)
                state["commit_job_sha256"] = expected
                state["commit_job_provider"] = requested_provider
                state["message"] = "INSTALL COMMIT ACCEPTED; ANDROID VM LAB INSTALL RUNNING"
                _home_installer_event(state, "INSTALL_CONSENT_CONSUMED", f"provider={requested_provider} generation={generation} sha256={expected}")
                _home_installer_event(state, "COMMIT_STARTED", f"provider=ANDROID_VM_LAB generation={generation} sha256={expected}")
                worker = threading.Thread(target=_home_installer_vm_commit_worker, args=(int(generation), expected, path), daemon=True, name=f"orfmos-installer-vm-{generation}")
                globals()["__ORFMOS_INSTALLER_COMMIT_THREAD__"] = worker
                worker.start()
                return json.loads(json.dumps(state))
            raise RuntimeError(f"COMMIT_PROVIDER_NOT_BOUND:{requested_provider}")
        except Exception as exc:
            state["last_commit_status"] = "BLOCKED"
            state["last_commit_provider"] = requested_provider
            state["last_commit_result"] = f"{type(exc).__name__}: {exc}"
            state["message"] = state["last_commit_result"]
            if state.get("state") == "TARGET_READY" and not state.get("target_armed"):
                state["state"] = "TARGET_REPREPARE_REQUIRED"
            _home_installer_event(state, "COMMIT_BLOCKED", state["message"])
            return json.loads(json.dumps(state))


def _home_installer_clear_http():
    with _ORFMOS_INSTALLER_LOCK:
        previous = _home_installer_state()
        generation = int(previous.get("selection_generation") or 0) + 1
        next_state = _home_installer_initial_state(generation=generation, events=previous.get("events"))
        _home_installer_event(next_state, "TARGET_CLEARED", f"generation={generation} reason=USER_CLEAR")
        globals()["__ORFMOS_INSTALLER_STATE__"] = next_state
        return json.loads(json.dumps(next_state))


def _home_install_installer_routes(app):
    if app is None or not hasattr(app, "add_api_route"):
        return False
    # The resident app outlives presentation successor namespaces.  Recover the narrow host
    # service contract before rebinding installer endpoints so Drive/provider access survives.
    _home_capture_host_service_context(app)
    marker = "__ORFMOS_HOME_INSTALLER_ROUTES_V0_1__"
    target_paths = {
        "/orfmos/installer/state",
        "/orfmos/installer/prepare",
        "/orfmos/installer/consent",
        "/orfmos/installer/commit",
        "/orfmos/installer/clear",
    }
    router = getattr(app, "router", None)
    routes = getattr(router, "routes", None) if router is not None else None
    migrated = None
    removed = 0
    if isinstance(routes, list):
        # Read the previous generation's state before removing its endpoints.
        for route in list(routes):
            if getattr(route, "path", None) == "/orfmos/installer/state":
                endpoint = getattr(route, "endpoint", None)
                if callable(endpoint):
                    try:
                        candidate = endpoint()
                        if isinstance(candidate, dict) and candidate.get("schema") == ORFMOS_INSTALLER_SCHEMA:
                            migrated = json.loads(json.dumps(candidate))
                    except Exception:
                        pass
                break
        kept = []
        for route in list(routes):
            if getattr(route, "path", None) in target_paths:
                removed += 1
                continue
            kept.append(route)
        routes[:] = kept

    if isinstance(migrated, dict):
        migrated["route_revision"] = ORFMOS_INSTALLER_ROUTE_REVISION
        migrated.setdefault("last_commit_status", "NONE")
        migrated.setdefault("last_commit_provider", "NONE")
        migrated.setdefault("last_commit_result", "")
        migrated.setdefault("commit_job_state", "IDLE")
        migrated.setdefault("commit_job_started_epoch", None)
        migrated.setdefault("commit_job_completed_epoch", None)
        migrated.setdefault("commit_job_generation", None)
        migrated.setdefault("commit_job_sha256", "")
        migrated.setdefault("commit_job_provider", "NONE")
        # Consent is deliberately non-transferable across executable Home generations.
        migrated["consent_state"] = "NOT_REQUESTED"
        migrated["consent_generation"] = None
        migrated["consent_sha256"] = ""
        migrated["consent_provider"] = "NONE"
        # Never claim an unarmed target is commit-ready after a generation handoff.
        if migrated.get("state") == "TARGET_READY" and not migrated.get("target_armed"):
            migrated["state"] = "TARGET_REPREPARE_REQUIRED"
            migrated["message"] = "INSTALLER GENERATION MIGRATED WITHOUT ARMED CONSENT; PREPARE SELECTED AGAIN"
        globals()["__ORFMOS_INSTALLER_STATE__"] = migrated
    else:
        _home_installer_state()

    app.add_api_route("/orfmos/installer/state", _home_installer_state_http, methods=["GET"], name="orfmos_installer_state")
    app.add_api_route("/orfmos/installer/prepare", _home_installer_prepare_http, methods=["POST"], name="orfmos_installer_prepare")
    app.add_api_route("/orfmos/installer/consent", _home_installer_consent_http, methods=["POST"], name="orfmos_installer_consent")
    app.add_api_route("/orfmos/installer/commit", _home_installer_commit_http, methods=["POST"], name="orfmos_installer_commit")
    app.add_api_route("/orfmos/installer/clear", _home_installer_clear_http, methods=["POST"], name="orfmos_installer_clear")
    setattr(app, marker, ORFMOS_INSTALLER_ROUTE_REVISION)
    setattr(app, "__ORFMOS_HOME_INSTALLER_ROUTE_REVISION__", ORFMOS_INSTALLER_ROUTE_REVISION)
    state = _home_installer_state()
    _home_installer_event(state, "INSTALLER_ROUTES_REBOUND", f"revision={ORFMOS_INSTALLER_ROUTE_REVISION} removed={removed} migrated={'YES' if migrated else 'NO'}")
    return True


def _home_files_list_http(provider: str = "DRIVE", uri: str = ""):
    try:
        p = str(provider or "DRIVE").strip().upper()
        if p == "DRIVE":
            return _home_files_drive_list(uri or "drive://")
        if p == "RUNTIME":
            return _home_files_runtime_list(uri or "runtime:///content/")
        if p == "GITHUB":
            return _home_files_github_list(uri or ORFMOS_GITHUB_ROOT_URI)
        return {
            "schema": ORFMOS_FILE_NAVIGATOR_SCHEMA,
            "status": "NATIVE_PICKER_REQUIRED",
            "provider": p,
            "current_uri": "content://",
            "current_name": "Android / ORF Drive",
            "parent_uri": None,
            "entries": [],
            "message": "USE_ORFMOS_NATIVE_FILE_PICKER",
        }
    except Exception as exc:
        return {
            "schema": ORFMOS_FILE_NAVIGATOR_SCHEMA,
            "status": "FAILED",
            "provider": str(provider or "UNKNOWN").upper(),
            "current_uri": str(uri or ""),
            "current_name": None,
            "parent_uri": None,
            "entries": [],
            "message": f"{type(exc).__name__}: {exc}",
        }


def _home_files_search_http(provider: str = "DRIVE", uri: str = "", query: str = ""):
    try:
        q = str(query or "").strip()
        if not q:
            raise RuntimeError("SEARCH_QUERY_REQUIRED")
        p = str(provider or "DRIVE").strip().upper()
        if p == "DRIVE":
            result = _home_files_drive_list(uri or "drive://", query=q)
        elif p == "GITHUB":
            result = _home_files_github_list(uri or ORFMOS_GITHUB_ROOT_URI, query=q)
        elif p == "RUNTIME":
            result = _home_files_runtime_list(uri or "runtime:///content/", query=q)
        else:
            return {
                "schema": ORFMOS_FILE_NAVIGATOR_SCHEMA,
                "status": "SEARCH_UNAVAILABLE",
                "provider": p,
                "current_uri": str(uri or ""),
                "current_name": None,
                "parent_uri": None,
                "entries": [],
                "query": q,
                "message": "PROVIDER_SEARCH_NOT_BOUND",
            }
        result["message"] = "SEARCH_READY"
        return result
    except Exception as exc:
        return {
            "schema": ORFMOS_FILE_NAVIGATOR_SCHEMA,
            "status": "FAILED",
            "provider": str(provider or "UNKNOWN").upper(),
            "current_uri": str(uri or ""),
            "current_name": None,
            "parent_uri": None,
            "entries": [],
            "query": str(query or "") or None,
            "message": f"{type(exc).__name__}: {exc}",
        }


def build_orfmos_home_demo():
    # Keep Home as the proven empty Gradio shell. The browser-visible surface is
    # JS-owned; manifest reload is served by a same-origin FastAPI route installed
    # after launch, so no dynamic Gradio Button/event graph is created inside the
    # BIOS Continue callback.
    with gr.Blocks(
        title="ORFMOS Home",
        fill_height=True,
        fill_width=True,
    ) as demo:
        demo.load(
            fn=None,
            inputs=None,
            outputs=None,
            js=_home_desktop_js(),
            queue=False,
        )
    return demo


def _home_manifest_reload_http():
    """Same-origin HTTP bridge for the resident Home presentation controller."""
    try:
        payload = _home_manifest_reload_payload()
        data = json.loads(payload) if isinstance(payload, str) else payload
        if isinstance(data, dict):
            return data
        return {
            "schema": "ORFMOS_HOME_PRESENTATION_RELOAD_RESULT_V0_1",
            "status": "FAILED",
            "message": "INVALID_RELOAD_PAYLOAD",
        }
    except Exception as exc:
        return {
            "schema": "ORFMOS_HOME_PRESENTATION_RELOAD_RESULT_V0_1",
            "status": "FAILED",
            "message": f"{type(exc).__name__}: {exc}",
        }



def _home_current_page_html():
    """Standalone same-origin Home shell generated by the resident Home itself."""
    css = str(HOME_CSS or "")
    js = str(_home_desktop_js() or "")
    version = str(ORFMOS_HOME_MODULE_VERSION or "")
    generation = str(ORFMOS_HOME_PRESENTATION_GENERATION or "")
    presentation_sha = str(globals().get("__ORFMOS_HOME_PRESENTATION_SHA__") or "")
    # JSON encoding prevents script/source characters from becoming HTML structure.
    css_json = json.dumps(css)
    js_json = json.dumps(js)
    identity_json = json.dumps({
        "schema": "ORFMOS_CURRENT_HOME_INTERFACE_V0_1",
        "version": version,
        "generation": generation,
        "presentation_sha256": presentation_sha,
    })
    return f"""<!doctype html>
<html>
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<meta name="theme-color" content="#05080b">
<title>ORFMOS Home {version}</title>
</head>
<body>
<script>
window.__ORFMOS_SELF_HOSTED_CURRENT_HOME__ = {identity_json};
const style=document.createElement("style");
style.id="orfHomeDynamicStyle";
style.textContent={css_json};
document.head.appendChild(style);
const factory=Function("return ("+{js_json}+")")();
if(typeof factory!=="function") throw new Error("ORFMOS_CURRENT_HOME_JS_NOT_FUNCTION");
factory();
</script>
</body>
</html>"""


def _home_current_http():
    return Response(
        content=_home_current_page_html(),
        status_code=200,
        media_type="text/html",
        headers={
            "Cache-Control": "no-store, max-age=0",
            "Pragma": "no-cache",
            "X-ORFMOS-Home-Version": str(ORFMOS_HOME_MODULE_VERSION),
            "X-ORFMOS-Home-Generation": str(ORFMOS_HOME_PRESENTATION_GENERATION),
        },
    )


async def _home_current_link_http(request: Request):
    base = str(request.base_url).rstrip("/")
    current_sha = str(globals().get("__ORFMOS_HOME_PRESENTATION_SHA__") or "")
    params = {
        "orf_home_version": str(ORFMOS_HOME_MODULE_VERSION),
        "orf_home_generation": str(ORFMOS_HOME_PRESENTATION_GENERATION),
    }
    if current_sha:
        params["orf_home_sha"] = current_sha
    url = base + "/orfmos/home/current?" + urllib.parse.urlencode(params)
    return {
        "schema": "ORFMOS_CURRENT_HOME_LINK_V0_1",
        "state": "READY",
        "url": url,
        "version": str(ORFMOS_HOME_MODULE_VERSION),
        "generation": str(ORFMOS_HOME_PRESENTATION_GENERATION),
        "presentation_sha256": current_sha,
        "authority": "RESIDENT_CURRENT_HOME",
        "cache_policy": "NO_STORE",
    }




def _home_chatgpt_temp_bridge_observation():
    state = globals().get("ORFMOS_CHATGPT_TEMP_WEB_BRIDGE_STATE")
    if not isinstance(state, dict):
        state = globals().get("__ORFMOS_CHATGPT_TEMP_WEB_BRIDGE__")
    if not isinstance(state, dict):
        state = {}

    record_fn = globals().get("orfmos_chatgpt_temp_bridge_record")
    if callable(record_fn):
        try:
            observed = record_fn(reveal_endpoint=False)
            if isinstance(observed, dict):
                state = {**state, **observed}
        except Exception:
            pass

    return {
        "state": str(state.get("state") or "NOT_RESIDENT"),
        "schema": str(state.get("schema") or ""),
        "realization": str(state.get("realization") or ""),
        "authority": str(state.get("authority") or ""),
        "temporary": bool(state.get("temporary")),
        "canonical_connector": str(state.get("canonical_connector") or ""),
        "operation_count": int(state.get("operation_count") or 0),
        "operations": [str(x) for x in (state.get("operations") or []) if isinstance(x, (str,int,float))],
        "public_origin_state": str(state.get("public_origin_state") or ""),
        "namespace_policy": str(state.get("namespace_policy") or ""),
        "shared_globals_safe": bool(state.get("shared_globals_safe")),
        "write_authority": str(state.get("write_authority") or "NONE"),
        "probe_execution": str(state.get("probe_execution") or "NOT_EXPOSED"),
        "arbitrary_execution": str(state.get("arbitrary_execution") or "NOT_EXPOSED"),
        "selector_mutation": str(state.get("selector_mutation") or "NOT_EXPOSED"),
        "discovery_url_masked": str(state.get("discovery_url") or ""),
    }


def _home_chatgpt_connector_state_payload():
    """Observe the independently resident MCP connector without revealing its capability secret."""
    connector_state = globals().get("ORFMOS_CHATGPT_MCP_CONNECTOR_STATE")
    if not isinstance(connector_state, dict):
        connector_state = globals().get("__ORFMOS_CHATGPT_MCP_CONNECTOR__")
    if not isinstance(connector_state, dict):
        connector_state = {}

    record_fn = globals().get("orfmos_chatgpt_mcp_connector_record")
    if callable(record_fn):
        try:
            observed = record_fn(reveal_endpoint=False)
            if isinstance(observed, dict):
                connector_state = {**connector_state, **observed}
        except Exception:
            pass

    current_sha = str(globals().get("__ORFMOS_HOME_PRESENTATION_SHA__") or "")
    home_origin = ""
    active = globals().get("__ORFMOS_HOME_ACTIVE__")
    if isinstance(active, dict):
        for key in ("share_url", "url"):
            raw = str(active.get(key) or "").strip()
            if raw.startswith("https://"):
                parsed = urllib.parse.urlsplit(raw)
                if parsed.netloc:
                    home_origin = urllib.parse.urlunsplit((parsed.scheme, parsed.netloc, "", "", "")).rstrip("/")
                    break

    tools = connector_state.get("tools")
    if not isinstance(tools, list):
        tools = []

    return {
        "schema": "ORFMOS_CHATGPT_CONNECTOR_LANDING_STATE_V0_1",
        "state": "READY",
        "surface": "CHATGPT_CONNECTOR",
        "connector": {
            "state": str(connector_state.get("state") or "NOT_RESIDENT"),
            "schema": str(connector_state.get("schema") or ""),
            "route": str(connector_state.get("route") or ""),
            "transport": str(connector_state.get("transport") or ""),
            "authority": str(connector_state.get("authority") or ""),
            "tool_count": int(connector_state.get("tool_count") or len(tools)),
            "tools": [str(item) for item in tools],
            "capability_token_sha256_prefix": str(connector_state.get("capability_token_sha256_prefix") or ""),
            "endpoint_path_masked": str(connector_state.get("endpoint_path_masked") or ""),
            "public_origin_state": str(connector_state.get("public_origin_state") or ("READY" if home_origin else "UNAVAILABLE")),
            "write_authority": str(connector_state.get("write_authority") or "NONE"),
            "probe_execution": str(connector_state.get("probe_execution") or "NOT_EXPOSED"),
            "arbitrary_execution": str(connector_state.get("arbitrary_execution") or "NOT_EXPOSED"),
        },
        "home": {
            "version": str(ORFMOS_HOME_MODULE_VERSION),
            "generation": str(ORFMOS_HOME_PRESENTATION_GENERATION),
            "presentation_sha256": current_sha,
            "link_state": "READY" if home_origin else "UNAVAILABLE",
        },
        "capability_disclosure": {
            "state": "MASKED",
            "intent_required": "REVEAL_MCP_ENDPOINT",
            "method": "POST",
            "authority": "EXPLICIT_DEVELOPMENT_PAIRING",
        },
        "temp_bridge": _home_chatgpt_temp_bridge_observation(),
    }


def _home_chatgpt_connector_state_http():
    return Response(
        content=json.dumps(_home_chatgpt_connector_state_payload(), sort_keys=True, default=str),
        status_code=200,
        media_type="application/json",
        headers={"Cache-Control": "no-store, max-age=0", "Pragma": "no-cache"},
    )


def _home_chatgpt_connector_endpoint_http(request: Request):
    """Reveal the capability URL only under an explicit pairing intent."""
    authorize = str(request.query_params.get("authorize") or "").strip()
    if authorize != "REVEAL_MCP_ENDPOINT":
        return Response(
            content=json.dumps({
                "schema": "ORFMOS_CHATGPT_CONNECTOR_ENDPOINT_V0_1",
                "state": "AUTHORIZATION_REQUIRED",
                "required": "REVEAL_MCP_ENDPOINT",
            }, sort_keys=True),
            status_code=403,
            media_type="application/json",
            headers={"Cache-Control": "no-store, max-age=0", "Pragma": "no-cache"},
        )

    record_fn = globals().get("orfmos_chatgpt_mcp_connector_record")
    if not callable(record_fn):
        return Response(
            content=json.dumps({
                "schema": "ORFMOS_CHATGPT_CONNECTOR_ENDPOINT_V0_1",
                "state": "CONNECTOR_NOT_RESIDENT",
                "message": "ORFMOS CHATGPT MCP CONNECTOR IS NOT RESIDENT",
            }, sort_keys=True),
            status_code=409,
            media_type="application/json",
            headers={"Cache-Control": "no-store, max-age=0", "Pragma": "no-cache"},
        )

    try:
        record = record_fn(reveal_endpoint=True)
    except Exception as exc:
        return Response(
            content=json.dumps({
                "schema": "ORFMOS_CHATGPT_CONNECTOR_ENDPOINT_V0_1",
                "state": "ERROR",
                "message": f"{type(exc).__name__}: {exc}",
            }, sort_keys=True),
            status_code=500,
            media_type="application/json",
            headers={"Cache-Control": "no-store, max-age=0", "Pragma": "no-cache"},
        )

    endpoint_url = str((record or {}).get("endpoint_url") or "").strip()
    if not endpoint_url.startswith("https://"):
        return Response(
            content=json.dumps({
                "schema": "ORFMOS_CHATGPT_CONNECTOR_ENDPOINT_V0_1",
                "state": "PUBLIC_ENDPOINT_UNAVAILABLE",
                "message": "CONNECTOR PUBLIC ORIGIN IS NOT READY",
            }, sort_keys=True),
            status_code=409,
            media_type="application/json",
            headers={"Cache-Control": "no-store, max-age=0", "Pragma": "no-cache"},
        )

    return Response(
        content=json.dumps({
            "schema": "ORFMOS_CHATGPT_CONNECTOR_ENDPOINT_V0_1",
            "state": "READY",
            "endpoint_url": endpoint_url,
            "authority": "READ_ONLY_OBSERVATION",
            "disclosure": "EXPLICIT_REVEAL_MCP_ENDPOINT",
        }, sort_keys=True),
        status_code=200,
        media_type="application/json",
        headers={"Cache-Control": "no-store, max-age=0", "Pragma": "no-cache"},
    )




def _home_chatgpt_temp_bridge_endpoint_http(request: Request):
    authorize = str(request.query_params.get("authorize") or "").strip()
    if authorize != "REVEAL_TEMP_WEB_BRIDGE":
        return Response(
            content=json.dumps({
                "schema": "ORFMOS_CHATGPT_TEMP_BRIDGE_ENDPOINT_V0_1",
                "state": "AUTHORIZATION_REQUIRED",
                "required": "REVEAL_TEMP_WEB_BRIDGE",
            }, sort_keys=True),
            status_code=403,
            media_type="application/json",
            headers={"Cache-Control":"no-store, max-age=0","Pragma":"no-cache"},
        )

    record_fn = globals().get("orfmos_chatgpt_temp_bridge_record")
    if not callable(record_fn):
        return Response(
            content=json.dumps({
                "schema": "ORFMOS_CHATGPT_TEMP_BRIDGE_ENDPOINT_V0_1",
                "state": "BRIDGE_NOT_RESIDENT",
            }, sort_keys=True),
            status_code=409,
            media_type="application/json",
            headers={"Cache-Control":"no-store, max-age=0","Pragma":"no-cache"},
        )
    try:
        record = record_fn(reveal_endpoint=True)
    except Exception as exc:
        return Response(
            content=json.dumps({
                "schema":"ORFMOS_CHATGPT_TEMP_BRIDGE_ENDPOINT_V0_1",
                "state":"ERROR",
                "message":f"{type(exc).__name__}: {exc}",
            }, sort_keys=True),
            status_code=500,
            media_type="application/json",
            headers={"Cache-Control":"no-store, max-age=0","Pragma":"no-cache"},
        )

    url = str((record or {}).get("discovery_url") or "").strip()
    if not url.startswith("https://"):
        return Response(
            content=json.dumps({
                "schema":"ORFMOS_CHATGPT_TEMP_BRIDGE_ENDPOINT_V0_1",
                "state":"PUBLIC_ENDPOINT_UNAVAILABLE",
            }, sort_keys=True),
            status_code=409,
            media_type="application/json",
            headers={"Cache-Control":"no-store, max-age=0","Pragma":"no-cache"},
        )

    return Response(
        content=json.dumps({
            "schema":"ORFMOS_CHATGPT_TEMP_BRIDGE_ENDPOINT_V0_1",
            "state":"READY",
            "discovery_url":url,
            "authority":"READ_ONLY_OBSERVATION",
            "temporary":True,
            "disclosure":"EXPLICIT_REVEAL_TEMP_WEB_BRIDGE",
        }, sort_keys=True),
        status_code=200,
        media_type="application/json",
        headers={"Cache-Control":"no-store, max-age=0","Pragma":"no-cache"},
    )


def _home_install_manifest_reload_route(app):
    """Install or replace resident Home runtime routes with the current 050 generation."""
    if app is None or not hasattr(app, "add_api_route"):
        return False
    marker = "__ORFMOS_HOME_RUNTIME_ROUTES_V0_8__"
    target_paths = {
        "/orfmos/home/manifest-reload",
        "/orfmos/home/device-state",
        "/orfmos/system/restart",
        "/orfmos/system/restart-state",
        "/orfmos/home/current",
        "/orfmos/home/current-link",
        "/orfmos/chatgpt-connector/state",
        "/orfmos/chatgpt-connector/endpoint",
        "/orfmos/chatgpt-connector/temp-bridge-endpoint",
    }
    router = getattr(app, "router", None)
    routes = getattr(router, "routes", None) if router is not None else None
    if isinstance(routes, list):
        routes[:] = [route for route in list(routes) if getattr(route, "path", None) not in target_paths]
    app.add_api_route(
        "/orfmos/home/manifest-reload",
        _home_manifest_reload_http,
        methods=["GET"],
        name="orfmos_home_manifest_reload",
    )
    app.add_api_route(
        "/orfmos/home/current",
        _home_current_http,
        methods=["GET"],
        name="orfmos_home_current",
    )
    app.add_api_route(
        "/orfmos/home/current-link",
        _home_current_link_http,
        methods=["GET"],
        name="orfmos_home_current_link",
    )
    app.add_api_route(
        "/orfmos/chatgpt-connector/state",
        _home_chatgpt_connector_state_http,
        methods=["GET"],
        name="orfmos_chatgpt_connector_state",
    )
    app.add_api_route(
        "/orfmos/chatgpt-connector/endpoint",
        _home_chatgpt_connector_endpoint_http,
        methods=["POST"],
        name="orfmos_chatgpt_connector_endpoint",
    )
    app.add_api_route(
        "/orfmos/chatgpt-connector/temp-bridge-endpoint",
        _home_chatgpt_temp_bridge_endpoint_http,
        methods=["POST"],
        name="orfmos_chatgpt_temp_bridge_endpoint",
    )
    app.add_api_route(
        "/orfmos/home/device-state",
        _home_device_state_http,
        methods=["GET"],
        name="orfmos_home_device_state_read",
    )
    app.add_api_route(
        "/orfmos/home/device-state",
        _home_device_state_write_http,
        methods=["POST"],
        name="orfmos_home_device_state_write",
    )
    app.add_api_route(
        "/orfmos/system/restart",
        _home_restart_http,
        methods=["POST"],
        name="orfmos_system_restart",
    )
    app.add_api_route(
        "/orfmos/system/restart-state",
        _home_restart_state_http,
        methods=["GET"],
        name="orfmos_system_restart_state",
    )
    app.add_api_route(
        "/orfmos/files/list",
        _home_files_list_http,
        methods=["GET"],
        name="orfmos_files_list",
    )
    app.add_api_route(
        "/orfmos/files/search",
        _home_files_search_http,
        methods=["GET"],
        name="orfmos_files_search",
    )
    app.add_api_route(
        "/orfmos/applications/apk-profile",
        _home_apk_profile_http,
        methods=["POST"],
        name="orfmos_apk_capability_profile",
    )
    setattr(app, marker, True)
    return True


def _home_extract_urls(demo_obj, result):
    extractor = globals().get("_extract_launch_urls")
    if callable(extractor):
        try:
            return extractor(demo_obj, result)
        except Exception:
            pass
    values = []
    if isinstance(result, (tuple, list)):
        values.extend(str(v) for v in result if isinstance(v, str) and v.startswith("http"))
    for attr in ("local_url", "share_url"):
        value = getattr(demo_obj, attr, None)
        if isinstance(value, str) and value.startswith("http"):
            values.append(value)
    local_url = next((v for v in values if "gradio.live" not in v), "")
    share_url = next((v for v in values if "gradio.live" in v), "")
    return local_url, share_url


def _home_url_is_live(url, timeout_seconds=4.0):
    """Reject expired gradio.live tunnel pages before browser handoff."""
    url = str(url or "").strip()
    if not url:
        return False
    try:
        request = urllib.request.Request(
            url,
            headers={"User-Agent": "Mozilla/5.0 ORFMOS-Home-Liveness/0.1"},
            method="GET",
        )
        with urllib.request.urlopen(request, timeout=float(timeout_seconds)) as response:
            status = int(getattr(response, "status", 200) or 200)
            sample = response.read(16384).decode("utf-8", errors="ignore").lower()
        if not (200 <= status < 400):
            return False
        dead_markers = (
            "no interface is running right now",
            "share link has expired",
            "this gradio app is not running",
        )
        return not any(marker in sample for marker in dead_markers)
    except Exception:
        return False


def _home_retire_stale_launch():
    demo = globals().get("__ORFMOS_HOME_DEMO__")
    if demo is not None:
        try:
            close_fn = getattr(demo, "close", None)
            if callable(close_fn):
                close_fn()
        except Exception:
            pass
    globals()["__ORFMOS_HOME_DEMO__"] = None
    globals()["__ORFMOS_HOME_ACTIVE__"] = {}


def orfmos_home_launch():
    """Return a live Home URL; stale share tunnels are retired and relaunched."""
    with _ORFMOS_HOME_LOCK:
        active = dict(globals().get("__ORFMOS_HOME_ACTIVE__") or {})
        active_url = str(active.get("url") or active.get("share_url") or "").strip()
        if str(active.get("status") or "").upper() == "READY" and active_url:
            if _home_url_is_live(active_url):
                active["liveness"] = "VERIFIED"
                active["verified_utc"] = datetime.now(timezone.utc).isoformat()
                globals()["__ORFMOS_HOME_ACTIVE__"] = active
                return active
            # The cached record can outlive its public Gradio tunnel across BIOS
            # reruns. Never navigate the user to that stale URL.
            _home_retire_stale_launch()

        demo = globals().get("__ORFMOS_HOME_DEMO__")
        if demo is None:
            demo = build_orfmos_home_demo()
            globals()["__ORFMOS_HOME_DEMO__"] = demo

        started = time.monotonic()
        try:
            result = demo.launch(
                share=True,
                prevent_thread_lock=True,
                show_error=True,
                quiet=True,
                css=HOME_CSS,
                head=HOME_HEAD,
            )
            app = result[0] if isinstance(result, (tuple, list)) and result else getattr(demo, "app", None)
            globals()["__ORFMOS_HOME_FASTAPI_APP__"] = app
            route_ready = _home_install_manifest_reload_route(app)
            vm_lab_route_ready = _home_install_vm_lab_routes(app)
            installer_route_ready = _home_install_installer_routes(app)
            local_url, share_url = _home_extract_urls(demo, result)
            url = share_url or local_url
            if not url:
                raise RuntimeError("HOME_LAUNCH_RETURNED_NO_URL")
            record = {
                "schema": ORFMOS_HOME_HANDOFF_SCHEMA,
                "status": "READY",
                "module_id": ORFMOS_HOME_MODULE_ID,
                "module_version": ORFMOS_HOME_MODULE_VERSION,
                "url": url,
                "share_url": share_url,
                "local_url": local_url,
                "launched_utc": datetime.now(timezone.utc).isoformat(),
                "launch_seconds": round(time.monotonic() - started, 3),
                "surface": "HOME_PLUS_APPLICATIONS_APK_PROFILE_PLUS_INSTALLER_PLUS_ANDROID_VM_LAB_PLUS_DEVELOPER_TOOLS_PLUS_RECENTS_PLUS_FILES_PLUS_SETTINGS_PLUS_GAME_LAB_LIBRARY_SUBDESKTOP",
                "liveness": "NEW_LAUNCH",
                "manifest_reload_route": "READY" if route_ready else "UNAVAILABLE",
                "installer_route": "READY" if installer_route_ready else "UNAVAILABLE",
                "vm_lab_route": "READY" if vm_lab_route_ready else "UNAVAILABLE",
                "surface_controller_schema": ORFMOS_HOME_SURFACE_CONTROLLER_SCHEMA,
                "development_selector_id": ORFMOS_HOME_DEVELOPMENT_SELECTOR_ID,
                "desktop_targets": [dict(item) for item in ORFMOS_HOME_DESKTOP_TARGETS],
                "developer_tools_targets": [dict(item) for item in ORFMOS_DEVELOPER_TOOLS_TARGETS],
                "application_targets": [dict(item) for item in ORFMOS_APPLICATION_TARGETS],
                "file_provider_targets": [dict(item) for item in ORFMOS_FILE_PROVIDER_TARGETS],
                "file_reader_handlers": [dict(item) for item in ORFMOS_FILE_READER_HANDLERS],
                "file_extractor_handlers": [dict(item) for item in ORFMOS_FILE_EXTRACTOR_HANDLERS],
                "settings_targets": [dict(item) for item in ORFMOS_SETTINGS_TARGETS],
                "game_lab_targets": [dict(item) for item in ORFMOS_GAME_LAB_TARGETS],
            }
        except Exception as exc:
            record = {
                "schema": ORFMOS_HOME_HANDOFF_SCHEMA,
                "status": "FAILED",
                "module_id": ORFMOS_HOME_MODULE_ID,
                "module_version": ORFMOS_HOME_MODULE_VERSION,
                "url": "",
                "reason": f"{type(exc).__name__}: {exc}",
                "failed_utc": datetime.now(timezone.utc).isoformat(),
                "launch_seconds": round(time.monotonic() - started, 3),
            }
        globals()["__ORFMOS_HOME_ACTIVE__"] = record
        return record


