# ========================================================================================================
# ORFMOS XML / ANDROID BINARY AXML RESOLVER v0.1 — RUNTIME PATCH
# ========================================================================================================
# Purpose:
#   TEXT XML --------------------\
#                                > ORFMOS NORMALIZED XML TREE -> MANIFEST SEMANTICS
#   ANDROID BINARY AXML --------/
#
# This is a parser / compatibility capability. It does not install packages, start Android, or mutate APKs.
# Contract promotion is intentionally deferred until the real-APK proof passes.
# ========================================================================================================

ORFMOS_XML_AXML_SCHEMA = "ORFMOS_XML_AXML_RESOLVER_V0_1"
ORFMOS_XML_AXML_REVISION = "XAR_V0_1_R85_NORMALIZED_XML_TREE"
ORFMOS_XML_AXML_ROUTE_PREFIX = "/orfmos/xml"
ORFMOS_ANDROID_NS = "http://schemas.android.com/apk/res/android"
ORFMOS_XML_NS = "http://www.w3.org/XML/1998/namespace"

RES_NULL_TYPE = 0x0000
RES_STRING_POOL_TYPE = 0x0001
RES_XML_TYPE = 0x0003
RES_XML_FIRST_CHUNK_TYPE = 0x0100
RES_XML_START_NAMESPACE_TYPE = 0x0100
RES_XML_END_NAMESPACE_TYPE = 0x0101
RES_XML_START_ELEMENT_TYPE = 0x0102
RES_XML_END_ELEMENT_TYPE = 0x0103
RES_XML_CDATA_TYPE = 0x0104
RES_XML_RESOURCE_MAP_TYPE = 0x0180

UTF8_FLAG = 0x00000100
NO_INDEX = 0xFFFFFFFF

TYPE_NULL = 0x00
TYPE_REFERENCE = 0x01
TYPE_ATTRIBUTE = 0x02
TYPE_STRING = 0x03
TYPE_FLOAT = 0x04
TYPE_DIMENSION = 0x05
TYPE_FRACTION = 0x06
TYPE_INT_DEC = 0x10
TYPE_INT_HEX = 0x11
TYPE_INT_BOOLEAN = 0x12
TYPE_INT_COLOR_ARGB8 = 0x1C
TYPE_INT_COLOR_RGB8 = 0x1D
TYPE_INT_COLOR_ARGB4 = 0x1E
TYPE_INT_COLOR_RGB4 = 0x1F

_ORFMOS_XML_AXML_LOCK = globals().get("_ORFMOS_XML_AXML_LOCK") or threading.RLock()
globals()["_ORFMOS_XML_AXML_LOCK"] = _ORFMOS_XML_AXML_LOCK
_ORFMOS_XML_AXML_EVENTS = globals().get("_ORFMOS_XML_AXML_EVENTS")
if not isinstance(_ORFMOS_XML_AXML_EVENTS, list):
    _ORFMOS_XML_AXML_EVENTS = []
globals()["_ORFMOS_XML_AXML_EVENTS"] = _ORFMOS_XML_AXML_EVENTS


def _xar_utc():
    return datetime.now(timezone.utc).isoformat()


def _xar_event(kind, detail):
    with _ORFMOS_XML_AXML_LOCK:
        _ORFMOS_XML_AXML_EVENTS.append({"utc": _xar_utc(), "type": str(kind), "detail": str(detail)})
        if len(_ORFMOS_XML_AXML_EVENTS) > 100:
            del _ORFMOS_XML_AXML_EVENTS[:-100]


def _xar_u16(data, off):
    if off < 0 or off + 2 > len(data):
        raise ValueError(f"AXML_U16_OOB:{off}")
    return struct.unpack_from("<H", data, off)[0]


def _xar_u32(data, off):
    if off < 0 or off + 4 > len(data):
        raise ValueError(f"AXML_U32_OOB:{off}")
    return struct.unpack_from("<I", data, off)[0]


def _xar_chunk_header(data, off):
    if off < 0 or off + 8 > len(data):
        raise ValueError(f"AXML_CHUNK_HEADER_OOB:{off}")
    ctype, header_size, size = struct.unpack_from("<HHI", data, off)
    if header_size < 8:
        raise ValueError(f"AXML_CHUNK_HEADER_TOO_SMALL:{header_size}")
    if size < header_size:
        raise ValueError(f"AXML_CHUNK_SIZE_INVALID:{size}:{header_size}")
    if off + size > len(data):
        raise ValueError(f"AXML_CHUNK_TRUNCATED:{off}:{size}:{len(data)}")
    return ctype, header_size, size


def _xar_len8(data, off):
    first = data[off]
    off += 1
    if first & 0x80:
        second = data[off]
        off += 1
        return ((first & 0x7F) << 8) | second, off
    return first, off


def _xar_len16(data, off):
    first = _xar_u16(data, off)
    off += 2
    if first & 0x8000:
        second = _xar_u16(data, off)
        off += 2
        return ((first & 0x7FFF) << 16) | second, off
    return first, off


class _XarStringPool:
    def __init__(self, strings=None, flags=0):
        self.strings = list(strings or [])
        self.flags = int(flags or 0)

    def get(self, idx):
        if idx in (None, NO_INDEX):
            return None
        idx = int(idx)
        if idx < 0 or idx >= len(self.strings):
            return None
        return self.strings[idx]

    @classmethod
    def parse(cls, data, off):
        ctype, header_size, size = _xar_chunk_header(data, off)
        if ctype != RES_STRING_POOL_TYPE:
            raise ValueError(f"AXML_EXPECTED_STRING_POOL:{ctype:#x}")
        if header_size < 28:
            raise ValueError(f"AXML_STRING_POOL_HEADER_TOO_SMALL:{header_size}")
        string_count = _xar_u32(data, off + 8)
        style_count = _xar_u32(data, off + 12)
        flags = _xar_u32(data, off + 16)
        strings_start = _xar_u32(data, off + 20)
        styles_start = _xar_u32(data, off + 24)
        offsets_base = off + header_size
        strings_base = off + strings_start
        chunk_end = off + size
        strings = []
        utf8 = bool(flags & UTF8_FLAG)
        for i in range(string_count):
            rel = _xar_u32(data, offsets_base + i * 4)
            pos = strings_base + rel
            if pos >= chunk_end:
                raise ValueError(f"AXML_STRING_OFFSET_OOB:{i}:{rel}")
            if utf8:
                _, pos = _xar_len8(data, pos)  # UTF-16 code-unit length
                byte_len, pos = _xar_len8(data, pos)
                end = pos + byte_len
                if end > chunk_end:
                    raise ValueError(f"AXML_UTF8_STRING_TRUNCATED:{i}")
                text = data[pos:end].decode("utf-8", errors="replace")
            else:
                char_len, pos = _xar_len16(data, pos)
                end = pos + char_len * 2
                if end > chunk_end:
                    raise ValueError(f"AXML_UTF16_STRING_TRUNCATED:{i}")
                text = data[pos:end].decode("utf-16le", errors="replace")
            strings.append(text)
        return cls(strings, flags), {
            "string_count": string_count,
            "style_count": style_count,
            "flags": flags,
            "utf8": utf8,
            "styles_start": styles_start,
            "chunk_size": size,
        }


def _xar_split_name(name):
    name = str(name or "")
    if name.startswith("{") and "}" in name:
        uri, local = name[1:].split("}", 1)
        return uri, local
    return None, name


def _xar_prefix_for_uri(uri, uri_to_prefix=None):
    if not uri:
        return None
    if uri == ORFMOS_ANDROID_NS:
        return "android"
    if uri == ORFMOS_XML_NS:
        return "xml"
    if isinstance(uri_to_prefix, dict):
        p = uri_to_prefix.get(uri)
        if p:
            return p
    return None


def _xar_qname(namespace, local, uri_to_prefix=None):
    prefix = _xar_prefix_for_uri(namespace, uri_to_prefix)
    return f"{prefix}:{local}" if prefix else str(local or "")


def _xar_decode_typed_value(pool, data_type, data_value, raw_value=None):
    if raw_value is not None:
        semantic = raw_value
    elif data_type == TYPE_STRING:
        semantic = pool.get(data_value)
    elif data_type == TYPE_NULL:
        semantic = None
    elif data_type == TYPE_INT_BOOLEAN:
        semantic = bool(data_value)
    elif data_type == TYPE_INT_DEC:
        semantic = int(data_value)
    elif data_type == TYPE_INT_HEX:
        semantic = f"0x{data_value:08x}"
    elif data_type == TYPE_REFERENCE:
        semantic = f"@0x{data_value:08x}"
    elif data_type == TYPE_ATTRIBUTE:
        semantic = f"?0x{data_value:08x}"
    elif data_type == TYPE_FLOAT:
        semantic = struct.unpack("<f", struct.pack("<I", data_value))[0]
    elif data_type in (TYPE_INT_COLOR_ARGB8, TYPE_INT_COLOR_RGB8, TYPE_INT_COLOR_ARGB4, TYPE_INT_COLOR_RGB4):
        semantic = f"#{data_value:08x}"
    elif data_type in (TYPE_DIMENSION, TYPE_FRACTION):
        semantic = f"0x{data_value:08x}"
    else:
        semantic = f"0x{data_value:08x}"
    return {
        "value": semantic,
        "raw_value": raw_value,
        "data_type": int(data_type),
        "data": int(data_value),
    }


def _xar_attr(namespace, name, value, *, prefix=None, raw_value=None, data_type=None, data=None):
    return {
        "namespace": namespace,
        "prefix": prefix,
        "name": str(name or ""),
        "qualified_name": f"{prefix}:{name}" if prefix else str(name or ""),
        "value": value,
        "raw_value": raw_value,
        "data_type": data_type,
        "data": data,
    }


def _xar_node(namespace, name, *, prefix=None, line=None, attributes=None, children=None, text=None):
    return {
        "namespace": namespace,
        "prefix": prefix,
        "name": str(name or ""),
        "qualified_name": f"{prefix}:{name}" if prefix else str(name or ""),
        "line": line,
        "attributes": list(attributes or []),
        "children": list(children or []),
        "text": text,
    }


def _xar_normalize_text_xml(raw):
    data = bytes(raw or b"")
    ns_pairs = []
    try:
        for event, payload in ET.iterparse(io.BytesIO(data), events=("start-ns",)):
            if event == "start-ns":
                prefix, uri = payload
                ns_pairs.append((prefix or None, uri))
    except Exception:
        ns_pairs = []
    uri_to_prefix = {}
    for prefix, uri in ns_pairs:
        if uri not in uri_to_prefix and prefix:
            uri_to_prefix[uri] = prefix
    uri_to_prefix.setdefault(ORFMOS_ANDROID_NS, "android")
    root_et = ET.fromstring(data)

    def convert(elem):
        ns, local = _xar_split_name(elem.tag)
        prefix = _xar_prefix_for_uri(ns, uri_to_prefix)
        attrs = []
        for key, value in elem.attrib.items():
            ans, aname = _xar_split_name(key)
            aprefix = _xar_prefix_for_uri(ans, uri_to_prefix)
            attrs.append(_xar_attr(ans, aname, value, prefix=aprefix, raw_value=value, data_type="TEXT", data=None))
        children = [convert(child) for child in list(elem)]
        text = elem.text.strip() if isinstance(elem.text, str) and elem.text.strip() else None
        return _xar_node(ns, local, prefix=prefix, attributes=attrs, children=children, text=text)

    return {
        "schema": ORFMOS_XML_AXML_SCHEMA,
        "state": "READY",
        "format": "TEXT_XML",
        "encoding": "TEXT",
        "root": convert(root_et),
        "namespaces": [{"prefix": p, "uri": u} for p, u in ns_pairs],
        "string_pool": None,
        "resource_map_count": 0,
        "node_count": sum(1 for _ in root_et.iter()),
        "bytes": len(data),
        "sha256": hashlib.sha256(data).hexdigest(),
    }


def _orfmos_axml_decode(raw):
    data = bytes(raw or b"")
    if len(data) < 8:
        raise ValueError("AXML_TOO_SMALL")
    ctype, header_size, total_size = _xar_chunk_header(data, 0)
    if ctype != RES_XML_TYPE:
        raise ValueError(f"AXML_ROOT_TYPE_INVALID:{ctype:#x}")
    if total_size > len(data):
        raise ValueError("AXML_DECLARED_SIZE_EXCEEDS_BUFFER")

    pool = None
    pool_meta = None
    resource_map = []
    namespace_stack = []
    uri_to_prefix = {ORFMOS_ANDROID_NS: "android"}
    element_stack = []
    root = None
    node_count = 0
    chunk_counts = {}
    off = header_size

    while off < total_size:
        ctype, cheader, csize = _xar_chunk_header(data, off)
        chunk_counts[f"0x{ctype:04x}"] = chunk_counts.get(f"0x{ctype:04x}", 0) + 1

        if ctype == RES_STRING_POOL_TYPE:
            pool, pool_meta = _XarStringPool.parse(data, off)

        elif ctype == RES_XML_RESOURCE_MAP_TYPE:
            count = max(0, (csize - cheader) // 4)
            resource_map = [_xar_u32(data, off + cheader + i * 4) for i in range(count)]

        elif ctype == RES_XML_START_NAMESPACE_TYPE:
            if pool is None:
                raise ValueError("AXML_NAMESPACE_BEFORE_STRING_POOL")
            ext = off + cheader
            prefix = pool.get(_xar_u32(data, ext))
            uri = pool.get(_xar_u32(data, ext + 4))
            namespace_stack.append((prefix, uri))
            if uri and prefix:
                uri_to_prefix[uri] = prefix

        elif ctype == RES_XML_END_NAMESPACE_TYPE:
            if pool is None:
                raise ValueError("AXML_NAMESPACE_END_BEFORE_STRING_POOL")
            ext = off + cheader
            prefix = pool.get(_xar_u32(data, ext))
            uri = pool.get(_xar_u32(data, ext + 4))
            for i in range(len(namespace_stack) - 1, -1, -1):
                if namespace_stack[i] == (prefix, uri):
                    del namespace_stack[i]
                    break

        elif ctype == RES_XML_START_ELEMENT_TYPE:
            if pool is None:
                raise ValueError("AXML_ELEMENT_BEFORE_STRING_POOL")
            if cheader < 16:
                raise ValueError(f"AXML_NODE_HEADER_TOO_SMALL:{cheader}")
            line = _xar_u32(data, off + 8)
            ext = off + cheader
            ns_idx = _xar_u32(data, ext)
            name_idx = _xar_u32(data, ext + 4)
            attr_start = _xar_u16(data, ext + 8)
            attr_size = _xar_u16(data, ext + 10)
            attr_count = _xar_u16(data, ext + 12)
            namespace = pool.get(ns_idx)
            name = pool.get(name_idx)
            prefix = _xar_prefix_for_uri(namespace, uri_to_prefix)
            attrs = []
            if attr_size and attr_size < 20:
                raise ValueError(f"AXML_ATTRIBUTE_SIZE_TOO_SMALL:{attr_size}")
            attr_base = ext + attr_start
            for i in range(attr_count):
                apos = attr_base + i * attr_size
                if apos + 20 > off + csize:
                    raise ValueError(f"AXML_ATTRIBUTE_TRUNCATED:{i}")
                ans_idx = _xar_u32(data, apos)
                aname_idx = _xar_u32(data, apos + 4)
                raw_idx = _xar_u32(data, apos + 8)
                value_size = _xar_u16(data, apos + 12)
                if value_size < 8:
                    raise ValueError(f"AXML_TYPED_VALUE_SIZE_INVALID:{value_size}")
                data_type = data[apos + 15]
                data_value = _xar_u32(data, apos + 16)
                ans = pool.get(ans_idx)
                aname = pool.get(aname_idx)
                raw_value = pool.get(raw_idx)
                typed = _xar_decode_typed_value(pool, data_type, data_value, raw_value=raw_value)
                attrs.append(_xar_attr(
                    ans,
                    aname,
                    typed["value"],
                    prefix=_xar_prefix_for_uri(ans, uri_to_prefix),
                    raw_value=typed["raw_value"],
                    data_type=typed["data_type"],
                    data=typed["data"],
                ))
            node = _xar_node(namespace, name, prefix=prefix, line=line, attributes=attrs)
            if element_stack:
                element_stack[-1]["children"].append(node)
            elif root is None:
                root = node
            else:
                raise ValueError("AXML_MULTIPLE_ROOT_ELEMENTS")
            element_stack.append(node)
            node_count += 1

        elif ctype == RES_XML_END_ELEMENT_TYPE:
            if pool is None:
                raise ValueError("AXML_END_ELEMENT_BEFORE_STRING_POOL")
            ext = off + cheader
            ns = pool.get(_xar_u32(data, ext))
            name = pool.get(_xar_u32(data, ext + 4))
            if not element_stack:
                raise ValueError("AXML_END_ELEMENT_WITHOUT_START")
            current = element_stack.pop()
            if str(current.get("name")) != str(name):
                raise ValueError(f"AXML_ELEMENT_MISMATCH:{current.get('name')}:{name}")
            if (current.get("namespace") or None) != (ns or None):
                raise ValueError("AXML_ELEMENT_NAMESPACE_MISMATCH")

        elif ctype == RES_XML_CDATA_TYPE:
            if pool is None:
                raise ValueError("AXML_CDATA_BEFORE_STRING_POOL")
            ext = off + cheader
            text = pool.get(_xar_u32(data, ext))
            if element_stack and text is not None:
                existing = element_stack[-1].get("text")
                element_stack[-1]["text"] = (existing or "") + text

        off += csize

    if root is None:
        raise ValueError("AXML_ROOT_ELEMENT_MISSING")
    if element_stack:
        raise ValueError("AXML_UNCLOSED_ELEMENTS")
    return {
        "schema": ORFMOS_XML_AXML_SCHEMA,
        "state": "READY",
        "format": "ANDROID_BINARY_AXML",
        "encoding": "ANDROID_BINARY_XML",
        "root": root,
        "namespaces": [{"prefix": p, "uri": u} for p, u in namespace_stack],
        "namespace_map": dict(uri_to_prefix),
        "string_pool": pool_meta,
        "resource_map_count": len(resource_map),
        "resource_map": resource_map,
        "node_count": node_count,
        "chunk_counts": chunk_counts,
        "bytes": len(data),
        "sha256": hashlib.sha256(data).hexdigest(),
    }


def _xar_attr_value(node, name, namespace=None, default=None):
    if not isinstance(node, dict):
        return default
    for attr in node.get("attributes") or []:
        if str(attr.get("name") or "") != str(name):
            continue
        if namespace is not None and (attr.get("namespace") or None) != namespace:
            continue
        return attr.get("value")
    return default


def _xar_children(node, name=None):
    items = list((node or {}).get("children") or [])
    if name is None:
        return items
    return [item for item in items if str(item.get("name") or "") == str(name)]


def _xar_expand_component_name(package_name, value):
    if not isinstance(value, str) or not value:
        return value
    if value.startswith(".") and package_name:
        return package_name + value
    if "." not in value and package_name:
        return package_name + "." + value
    return value


def _xar_intish(value):
    if isinstance(value, bool):
        return int(value)
    if isinstance(value, int):
        return value
    if isinstance(value, str):
        try:
            return int(value, 0)
        except Exception:
            return value
    return value


def _xar_manifest_semantics(decoded):
    root = (decoded or {}).get("root")
    if not isinstance(root, dict) or root.get("name") != "manifest":
        return {
            "schema": "ORFMOS_ANDROID_MANIFEST_SEMANTICS_V0_1",
            "state": "NOT_ANDROID_MANIFEST",
            "root_name": root.get("name") if isinstance(root, dict) else None,
        }
    package_name = _xar_attr_value(root, "package")
    version_code = _xar_attr_value(root, "versionCode", ORFMOS_ANDROID_NS)
    version_name = _xar_attr_value(root, "versionName", ORFMOS_ANDROID_NS)
    compile_sdk = _xar_attr_value(root, "compileSdkVersion", ORFMOS_ANDROID_NS)

    uses_sdk_node = next(iter(_xar_children(root, "uses-sdk")), None)
    sdk = {
        "min_sdk": _xar_intish(_xar_attr_value(uses_sdk_node, "minSdkVersion", ORFMOS_ANDROID_NS)),
        "target_sdk": _xar_intish(_xar_attr_value(uses_sdk_node, "targetSdkVersion", ORFMOS_ANDROID_NS)),
        "max_sdk": _xar_intish(_xar_attr_value(uses_sdk_node, "maxSdkVersion", ORFMOS_ANDROID_NS)),
        "compile_sdk": _xar_intish(compile_sdk),
    }

    requested_permissions = []
    for tag in ("uses-permission", "uses-permission-sdk-23", "uses-permission-sdk-m"):
        for item in _xar_children(root, tag):
            name = _xar_attr_value(item, "name", ORFMOS_ANDROID_NS)
            if name and name not in requested_permissions:
                requested_permissions.append(name)

    declared_permissions = []
    for item in _xar_children(root, "permission"):
        name = _xar_attr_value(item, "name", ORFMOS_ANDROID_NS)
        if name:
            declared_permissions.append({
                "name": name,
                "protection_level": _xar_attr_value(item, "protectionLevel", ORFMOS_ANDROID_NS),
            })

    uses_features = []
    for item in _xar_children(root, "uses-feature"):
        uses_features.append({
            "name": _xar_attr_value(item, "name", ORFMOS_ANDROID_NS),
            "required": _xar_attr_value(item, "required", ORFMOS_ANDROID_NS),
            "gl_es_version": _xar_attr_value(item, "glEsVersion", ORFMOS_ANDROID_NS),
        })

    application_node = next(iter(_xar_children(root, "application")), None)
    application = None
    components = []
    if application_node:
        app_name_raw = _xar_attr_value(application_node, "name", ORFMOS_ANDROID_NS)
        application = {
            "name": app_name_raw,
            "resolved_name": _xar_expand_component_name(package_name, app_name_raw),
            "label": _xar_attr_value(application_node, "label", ORFMOS_ANDROID_NS),
            "theme": _xar_attr_value(application_node, "theme", ORFMOS_ANDROID_NS),
            "debuggable": _xar_attr_value(application_node, "debuggable", ORFMOS_ANDROID_NS),
            "allow_backup": _xar_attr_value(application_node, "allowBackup", ORFMOS_ANDROID_NS),
            "uses_cleartext_traffic": _xar_attr_value(application_node, "usesCleartextTraffic", ORFMOS_ANDROID_NS),
            "network_security_config": _xar_attr_value(application_node, "networkSecurityConfig", ORFMOS_ANDROID_NS),
        }
        for tag in ("activity", "activity-alias", "service", "receiver", "provider"):
            for item in _xar_children(application_node, tag):
                raw_name = _xar_attr_value(item, "name", ORFMOS_ANDROID_NS)
                filters = []
                for ifilter in _xar_children(item, "intent-filter"):
                    actions = [
                        _xar_attr_value(a, "name", ORFMOS_ANDROID_NS)
                        for a in _xar_children(ifilter, "action")
                        if _xar_attr_value(a, "name", ORFMOS_ANDROID_NS)
                    ]
                    categories = [
                        _xar_attr_value(c, "name", ORFMOS_ANDROID_NS)
                        for c in _xar_children(ifilter, "category")
                        if _xar_attr_value(c, "name", ORFMOS_ANDROID_NS)
                    ]
                    data_specs = []
                    for dnode in _xar_children(ifilter, "data"):
                        spec = {}
                        for key in ("scheme", "host", "port", "path", "pathPrefix", "pathPattern", "mimeType"):
                            val = _xar_attr_value(dnode, key, ORFMOS_ANDROID_NS)
                            if val is not None:
                                spec[key] = val
                        data_specs.append(spec)
                    filters.append({
                        "priority": _xar_attr_value(ifilter, "priority", ORFMOS_ANDROID_NS),
                        "auto_verify": _xar_attr_value(ifilter, "autoVerify", ORFMOS_ANDROID_NS),
                        "actions": actions,
                        "categories": categories,
                        "data": data_specs,
                    })
                components.append({
                    "type": tag,
                    "name": raw_name,
                    "resolved_name": _xar_expand_component_name(package_name, raw_name),
                    "exported": _xar_attr_value(item, "exported", ORFMOS_ANDROID_NS),
                    "enabled": _xar_attr_value(item, "enabled", ORFMOS_ANDROID_NS),
                    "permission": _xar_attr_value(item, "permission", ORFMOS_ANDROID_NS),
                    "process": _xar_attr_value(item, "process", ORFMOS_ANDROID_NS),
                    "authorities": _xar_attr_value(item, "authorities", ORFMOS_ANDROID_NS),
                    "target_activity": _xar_attr_value(item, "targetActivity", ORFMOS_ANDROID_NS),
                    "intent_filters": filters,
                })

    launchers = []
    for component in components:
        for filt in component.get("intent_filters") or []:
            if (
                "android.intent.action.MAIN" in (filt.get("actions") or [])
                and "android.intent.category.LAUNCHER" in (filt.get("categories") or [])
            ):
                launchers.append(component.get("resolved_name") or component.get("name"))

    return {
        "schema": "ORFMOS_ANDROID_MANIFEST_SEMANTICS_V0_1",
        "state": "READY",
        "package": package_name,
        "version_code": _xar_intish(version_code),
        "version_name": version_name,
        "sdk": sdk,
        "requested_permissions": requested_permissions,
        "declared_permissions": declared_permissions,
        "uses_features": uses_features,
        "application": application,
        "components": components,
        "launcher_components": launchers,
        "counts": {
            "requested_permissions": len(requested_permissions),
            "declared_permissions": len(declared_permissions),
            "uses_features": len(uses_features),
            "components": len(components),
            "intent_filters": sum(len(c.get("intent_filters") or []) for c in components),
        },
    }


def _xar_xml_text(node, *, namespace_decls=None, depth=0):
    if not isinstance(node, dict):
        return ""
    qname = node.get("qualified_name") or node.get("name") or "node"
    attrs = []
    if depth == 0:
        seen = set()
        for entry in namespace_decls or []:
            prefix = entry.get("prefix")
            uri = entry.get("uri")
            if not uri or (prefix, uri) in seen:
                continue
            seen.add((prefix, uri))
            if prefix:
                attrs.append(f"xmlns:{prefix}={_xml_quoteattr(str(uri))}")
            else:
                attrs.append(f"xmlns={_xml_quoteattr(str(uri))}")
    for attr in node.get("attributes") or []:
        aq = attr.get("qualified_name") or attr.get("name") or "attr"
        val = attr.get("value")
        if val is None:
            val = ""
        if isinstance(val, bool):
            val = "true" if val else "false"
        attrs.append(f"{aq}={_xml_quoteattr(str(val))}")
    open_tag = "<" + qname + (" " + " ".join(attrs) if attrs else "")
    children = node.get("children") or []
    text = node.get("text")
    if not children and not text:
        return open_tag + "/>"
    pieces = [open_tag + ">"]
    if text:
        pieces.append(_xml_escape(str(text)))
    for child in children:
        pieces.append(_xar_xml_text(child, namespace_decls=None, depth=depth + 1))
    pieces.append(f"</{qname}>")
    return "".join(pieces)


def _orfmos_xml_resolve(raw, *, kind="AUTO", include_xml_text=False):
    data = bytes(raw or b"")
    kind = str(kind or "AUTO").strip().upper()
    stripped = data.lstrip()
    if kind in ("AUTO", "TEXT_XML") and stripped.startswith(b"<"):
        decoded = _xar_normalize_text_xml(data)
    elif kind in ("AUTO", "ANDROID_BINARY_AXML", "AXML") and data[:4] == b"\x03\x00\x08\x00":
        decoded = _orfmos_axml_decode(data)
    elif kind == "TEXT_XML":
        decoded = _xar_normalize_text_xml(data)
    elif kind in ("ANDROID_BINARY_AXML", "AXML"):
        decoded = _orfmos_axml_decode(data)
    else:
        raise ValueError("XML_FORMAT_UNRESOLVED")
    decoded = dict(decoded)
    decoded["manifest"] = _xar_manifest_semantics(decoded)
    if include_xml_text:
        ns = list(decoded.get("namespaces") or [])
        if decoded.get("format") == "ANDROID_BINARY_AXML":
            nmap = decoded.get("namespace_map") or {}
            ns = [{"prefix": p, "uri": u} for u, p in nmap.items()]
        decoded["xml_text"] = _xar_xml_text(decoded.get("root"), namespace_decls=ns)
    _xar_event("XML_RESOLVED", f"format={decoded.get('format')} sha256={decoded.get('sha256')} nodes={decoded.get('node_count')}")
    return decoded


def _orfmos_android_manifest_resolve(raw, *, include_tree=False, include_xml_text=False):
    decoded = _orfmos_xml_resolve(raw, kind="AUTO", include_xml_text=include_xml_text)
    result = {
        "schema": ORFMOS_XML_AXML_SCHEMA,
        "state": decoded.get("manifest", {}).get("state"),
        "format": decoded.get("format"),
        "bytes": decoded.get("bytes"),
        "sha256": decoded.get("sha256"),
        "node_count": decoded.get("node_count"),
        "string_pool": decoded.get("string_pool"),
        "resource_map_count": decoded.get("resource_map_count"),
        "manifest": decoded.get("manifest"),
    }
    if include_tree:
        result["root"] = decoded.get("root")
    if include_xml_text:
        result["xml_text"] = decoded.get("xml_text")
    return result


def _xar_state():
    return {
        "schema": ORFMOS_XML_AXML_SCHEMA,
        "revision": ORFMOS_XML_AXML_REVISION,
        "state": "READY",
        "provider": "ORFMOS",
        "service": "XML",
        "capabilities": {
            "TEXT_XML_READ": "READY",
            "NORMALIZED_XML_TREE": "READY",
            "ANDROID_BINARY_AXML_DECODE": "READY_UNPROMOTED",
            "ANDROID_MANIFEST_SEMANTICS": "READY_UNPROMOTED",
        },
        "android_vm_required": False,
        "events": list(_ORFMOS_XML_AXML_EVENTS[-20:]),
    }


async def _xar_state_http():
    return _xar_state()


async def _xar_resolve_http(request: Request, kind: str = "AUTO", include_tree: bool = True, include_xml_text: bool = False):
    body = await request.body()
    result = _orfmos_xml_resolve(body, kind=kind, include_xml_text=include_xml_text)
    if not include_tree:
        result = dict(result)
        result.pop("root", None)
    return result


async def _xar_manifest_http(request: Request, include_tree: bool = False, include_xml_text: bool = False):
    body = await request.body()
    return _orfmos_android_manifest_resolve(body, include_tree=include_tree, include_xml_text=include_xml_text)


def _xar_find_fastapi_app():
    helper = globals().get("_orfvm_find_fastapi_app")
    if callable(helper):
        try:
            app = helper()
            if app is not None:
                return app
        except Exception:
            pass
    for name, value in list(globals().items()):
        if hasattr(value, "router") and hasattr(getattr(value, "router", None), "routes") and hasattr(value, "add_api_route"):
            return value
    return None


def _xar_bind_routes():
    app = _xar_find_fastapi_app()
    if app is None:
        _xar_event("ROUTES_NOT_BOUND", "FASTAPI_APP_NOT_FOUND")
        return 0
    targets = {
        ORFMOS_XML_AXML_ROUTE_PREFIX + "/state",
        ORFMOS_XML_AXML_ROUTE_PREFIX + "/resolve",
        ORFMOS_XML_AXML_ROUTE_PREFIX + "/manifest",
    }
    kept = []
    removed = 0
    for route in list(app.router.routes):
        if str(getattr(route, "path", "")) in targets:
            removed += 1
            continue
        kept.append(route)
    app.router.routes[:] = kept
    app.add_api_route(ORFMOS_XML_AXML_ROUTE_PREFIX + "/state", _xar_state_http, methods=["GET"], name="orfmos_xml_state")
    app.add_api_route(ORFMOS_XML_AXML_ROUTE_PREFIX + "/resolve", _xar_resolve_http, methods=["POST"], name="orfmos_xml_resolve")
    app.add_api_route(ORFMOS_XML_AXML_ROUTE_PREFIX + "/manifest", _xar_manifest_http, methods=["POST"], name="orfmos_xml_manifest")
    setattr(app, "__ORFMOS_XML_AXML_REVISION__", ORFMOS_XML_AXML_REVISION)
    _xar_event("ROUTES_BOUND", f"removed={removed} bound=3")
    return 3


