# Synthetic AXML fixture for parser self-test only.
# --------------------------------------------------------------------------------------------------------
def _xar_pack_len8(n):
    n = int(n)
    if n < 0x80:
        return bytes([n])
    return bytes([0x80 | ((n >> 8) & 0x7F), n & 0xFF])


def _xar_build_string_pool(strings):
    offsets = []
    blob = bytearray()
    for text in strings:
        raw = str(text).encode("utf-8")
        utf16_len = len(str(text).encode("utf-16le")) // 2
        offsets.append(len(blob))
        blob.extend(_xar_pack_len8(utf16_len))
        blob.extend(_xar_pack_len8(len(raw)))
        blob.extend(raw)
        blob.append(0)
    while len(blob) % 4:
        blob.append(0)
    header_size = 28
    strings_start = header_size + len(strings) * 4
    size = strings_start + len(blob)
    out = bytearray(struct.pack("<HHI", RES_STRING_POOL_TYPE, header_size, size))
    out.extend(struct.pack("<IIIII", len(strings), 0, UTF8_FLAG, strings_start, 0))
    for rel in offsets:
        out.extend(struct.pack("<I", rel))
    out.extend(blob)
    return bytes(out)


def _xar_build_node_chunk(ctype, ext, body=b"", line=1):
    header_size = 16
    size = header_size + len(ext) + len(body)
    return struct.pack("<HHIII", ctype, header_size, size, line, NO_INDEX) + ext + body


def _xar_build_attr(ns_idx, name_idx, value, strings):
    raw_idx = NO_INDEX
    data_type = TYPE_STRING
    data_value = 0
    if isinstance(value, bool):
        data_type = TYPE_INT_BOOLEAN
        data_value = 1 if value else 0
    elif isinstance(value, int):
        data_type = TYPE_INT_DEC
        data_value = value
    else:
        value = str(value)
        raw_idx = strings.index(value)
        data_type = TYPE_STRING
        data_value = raw_idx
    return struct.pack("<IIIHBBI", ns_idx, name_idx, raw_idx, 8, 0, data_type, data_value)


def _xar_synthetic_axml():
    strings = [
        "manifest", "package", "com.example.synthetic", "android",
        ORFMOS_ANDROID_NS, "versionCode", "uses-sdk", "minSdkVersion", "targetSdkVersion",
        "application", "name", ".App", "activity", ".MainActivity", "exported",
        "intent-filter", "action", "android.intent.action.MAIN", "category",
        "android.intent.category.LAUNCHER", "uses-permission", "android.permission.INTERNET",
    ]
    idx = {s: i for i, s in enumerate(strings)}
    chunks = [_xar_build_string_pool(strings)]
    chunks.append(_xar_build_node_chunk(
        RES_XML_START_NAMESPACE_TYPE,
        struct.pack("<II", idx["android"], idx[ORFMOS_ANDROID_NS]),
    ))

    def start(name, attrs):
        abody = b"".join(_xar_build_attr(ns, idx[aname], value, strings) for ns, aname, value in attrs)
        ext = struct.pack("<IIHHHHHH", NO_INDEX, idx[name], 20, 20, len(attrs), 0, 0, 0)
        return _xar_build_node_chunk(RES_XML_START_ELEMENT_TYPE, ext, abody)

    def end(name):
        return _xar_build_node_chunk(RES_XML_END_ELEMENT_TYPE, struct.pack("<II", NO_INDEX, idx[name]))

    chunks.append(start("manifest", [
        (NO_INDEX, "package", "com.example.synthetic"),
        (idx[ORFMOS_ANDROID_NS], "versionCode", 7),
    ]))
    chunks.append(start("uses-sdk", [
        (idx[ORFMOS_ANDROID_NS], "minSdkVersion", 21),
        (idx[ORFMOS_ANDROID_NS], "targetSdkVersion", 34),
    ]))
    chunks.append(end("uses-sdk"))
    chunks.append(start("uses-permission", [
        (idx[ORFMOS_ANDROID_NS], "name", "android.permission.INTERNET"),
    ]))
    chunks.append(end("uses-permission"))
    chunks.append(start("application", [
        (idx[ORFMOS_ANDROID_NS], "name", ".App"),
    ]))
    chunks.append(start("activity", [
        (idx[ORFMOS_ANDROID_NS], "name", ".MainActivity"),
        (idx[ORFMOS_ANDROID_NS], "exported", True),
    ]))
    chunks.append(start("intent-filter", []))
    chunks.append(start("action", [
        (idx[ORFMOS_ANDROID_NS], "name", "android.intent.action.MAIN"),
    ]))
    chunks.append(end("action"))
    chunks.append(start("category", [
        (idx[ORFMOS_ANDROID_NS], "name", "android.intent.category.LAUNCHER"),
    ]))
    chunks.append(end("category"))
    chunks.append(end("intent-filter"))
    chunks.append(end("activity"))
    chunks.append(end("application"))
    chunks.append(end("manifest"))
    chunks.append(_xar_build_node_chunk(
        RES_XML_END_NAMESPACE_TYPE,
        struct.pack("<II", idx["android"], idx[ORFMOS_ANDROID_NS]),
    ))
    body = b"".join(chunks)
    return struct.pack("<HHI", RES_XML_TYPE, 8, 8 + len(body)) + body


def _xar_self_test():
    text_raw = b'''<manifest xmlns:android="http://schemas.android.com/apk/res/android" package="com.example.text" android:versionCode="3"><uses-sdk android:minSdkVersion="21" android:targetSdkVersion="34"/><uses-permission android:name="android.permission.INTERNET"/><application android:name=".App"><activity android:name=".Main" android:exported="true"><intent-filter><action android:name="android.intent.action.MAIN"/><category android:name="android.intent.category.LAUNCHER"/></intent-filter></activity></application></manifest>'''
    text_dec = _orfmos_xml_resolve(text_raw, kind="TEXT_XML")
    text_manifest = text_dec.get("manifest") or {}
    axml_raw = _xar_synthetic_axml()
    axml_dec = _orfmos_xml_resolve(axml_raw, kind="AXML")
    axml_manifest = axml_dec.get("manifest") or {}
    checks = {
        "text_xml_ready": text_dec.get("state") == "READY" and text_dec.get("format") == "TEXT_XML",
        "text_manifest_package": text_manifest.get("package") == "com.example.text",
        "text_launcher": "com.example.text.Main" in (text_manifest.get("launcher_components") or []),
        "axml_ready": axml_dec.get("state") == "READY" and axml_dec.get("format") == "ANDROID_BINARY_AXML",
        "axml_manifest_package": axml_manifest.get("package") == "com.example.synthetic",
        "axml_version_code": axml_manifest.get("version_code") == 7,
        "axml_sdk": (axml_manifest.get("sdk") or {}).get("min_sdk") == 21 and (axml_manifest.get("sdk") or {}).get("target_sdk") == 34,
        "axml_permission": "android.permission.INTERNET" in (axml_manifest.get("requested_permissions") or []),
        "axml_launcher": "com.example.synthetic.MainActivity" in (axml_manifest.get("launcher_components") or []),
    }
    return {
        "state": "PASS" if all(checks.values()) else "FAIL",
        "checks": checks,
        "synthetic_axml_bytes": len(axml_raw),
        "synthetic_axml_sha256": hashlib.sha256(axml_raw).hexdigest(),
    }


globals()["_orfmos_axml_decode"] = _orfmos_axml_decode
globals()["_orfmos_xml_resolve"] = _orfmos_xml_resolve
globals()["_orfmos_android_manifest_resolve"] = _orfmos_android_manifest_resolve
globals()["_orfmos_xml_axml_state"] = _xar_state

globals()["__ORFMOS_XML_AXML_SELF_TEST__"] = _xar_self_test()
globals()["__ORFMOS_XML_AXML_ROUTES_BOUND__"] = _xar_bind_routes()

