# ====================================================================================================
# R85 EMBEDDED OXML CONVERTER
# ====================================================================================================
import json
import hashlib
import threading
import xml.etree.ElementTree as ET
from datetime import datetime, timezone
from fastapi import Request

# ========================================================================================================
# ORFMOS OXML MANIFEST CONVERTER v0.1 — RUNTIME PATCH
# ========================================================================================================
# OXML = ORFMOS XML
#
# Input:
#   - ordinary text XML AndroidManifest.xml
#   - raw Android binary AXML AndroidManifest.xml
#
# Output:
#   - canonical OXML manifest document
#   - ORFMOS_EXECUTABLE_MANIFEST_V0_1 object suitable for MPS / Installer consumption
#
# Invariant:
#   Source encoding is normalized away before package semantics are consumed.
#   Android VM is not required.
# ========================================================================================================

ORFMOS_OXML_SCHEMA = "ORFMOS_OXML_MANIFEST_CONVERTER_V0_1"
ORFMOS_OXML_REVISION = "OXML_V0_1_1_R85_STABLE_MANIFEST_HASH"
ORFMOS_OXML_DOCUMENT_SCHEMA = "ORFMOS_OXML_MANIFEST_V0_1"
ORFMOS_OXML_NS = "urn:orfmos:oxml:1"
ORFMOS_OXML_ROUTE_PREFIX = "/orfmos/oxml"
ORFMOS_EXECUTABLE_MANIFEST_SCHEMA = globals().get(
    "ORFMOS_EXECUTABLE_MANIFEST_SCHEMA",
    "ORFMOS_EXECUTABLE_MANIFEST_V0_1",
)

_OXML_LOCK = globals().get("_ORFMOS_OXML_LOCK") or threading.RLock()
globals()["_ORFMOS_OXML_LOCK"] = _OXML_LOCK
_OXML_EVENTS = globals().get("_ORFMOS_OXML_EVENTS")
if not isinstance(_OXML_EVENTS, list):
    _OXML_EVENTS = []
globals()["_ORFMOS_OXML_EVENTS"] = _OXML_EVENTS


def _oxml_utc():
    return datetime.now(timezone.utc).isoformat()


def _oxml_event(kind, detail=""):
    item = {"utc": _oxml_utc(), "type": str(kind), "detail": str(detail)}
    _OXML_EVENTS.append(item)
    del _OXML_EVENTS[:-64]
    return item


def _oxml_required(name):
    value = globals().get(name)
    if not callable(value):
        raise RuntimeError(f"OXML_REQUIRED_RESIDENT_CAPABILITY_MISSING:{name}")
    return value


def _oxml_boolish(value):
    if isinstance(value, bool):
        return value
    if value is None:
        return None
    text = str(value).strip().lower()
    if text in {"true", "1", "yes"}:
        return True
    if text in {"false", "0", "no"}:
        return False
    return value


def _oxml_set_attr(node, key, value):
    if value is None:
        return
    if isinstance(value, bool):
        value = "true" if value else "false"
    node.set(str(key), str(value))


def _oxml_sub(parent, name, attrs=None):
    node = ET.SubElement(parent, f"{{{ORFMOS_OXML_NS}}}{name}")
    for key, value in (attrs or {}).items():
        _oxml_set_attr(node, key, value)
    return node


def _oxml_semantics_to_tree(semantics, *, source_format, source_sha256, source_bytes):
    semantics = dict(semantics or {})
    root = ET.Element(f"{{{ORFMOS_OXML_NS}}}manifest")
    _oxml_set_attr(root, "schema", ORFMOS_OXML_DOCUMENT_SCHEMA)
    _oxml_set_attr(root, "package", semantics.get("package"))
    _oxml_set_attr(root, "versionCode", semantics.get("version_code"))
    _oxml_set_attr(root, "versionName", semantics.get("version_name"))
    _oxml_set_attr(root, "sourceFormat", source_format)
    _oxml_set_attr(root, "sourceSha256", source_sha256)
    _oxml_set_attr(root, "sourceBytes", source_bytes)

    sdk = dict(semantics.get("sdk") or {})
    _oxml_sub(root, "sdk", {
        "min": sdk.get("min_sdk"),
        "target": sdk.get("target_sdk"),
        "max": sdk.get("max_sdk"),
        "compile": sdk.get("compile_sdk"),
    })

    requested = _oxml_sub(root, "requested-permissions")
    for name in semantics.get("requested_permissions") or []:
        _oxml_sub(requested, "permission", {"name": name})

    declared = _oxml_sub(root, "declared-permissions")
    for item in semantics.get("declared_permissions") or []:
        _oxml_sub(declared, "permission", {
            "name": item.get("name"),
            "protectionLevel": item.get("protection_level"),
        })

    features = _oxml_sub(root, "features")
    for item in semantics.get("uses_features") or []:
        _oxml_sub(features, "feature", {
            "name": item.get("name"),
            "required": item.get("required"),
            "glEsVersion": item.get("gl_es_version"),
        })

    app_sem = dict(semantics.get("application") or {})
    app = _oxml_sub(root, "application", {
        "name": app_sem.get("name"),
        "resolvedName": app_sem.get("resolved_name"),
        "label": app_sem.get("label"),
        "theme": app_sem.get("theme"),
        "debuggable": app_sem.get("debuggable"),
        "allowBackup": app_sem.get("allow_backup"),
        "usesCleartextTraffic": app_sem.get("uses_cleartext_traffic"),
        "networkSecurityConfig": app_sem.get("network_security_config"),
    })

    for comp in semantics.get("components") or []:
        cnode = _oxml_sub(app, "component", {
            "type": comp.get("type"),
            "name": comp.get("name"),
            "resolvedName": comp.get("resolved_name"),
            "exported": comp.get("exported"),
            "enabled": comp.get("enabled"),
            "permission": comp.get("permission"),
            "process": comp.get("process"),
            "authorities": comp.get("authorities"),
            "targetActivity": comp.get("target_activity"),
        })
        for filt in comp.get("intent_filters") or []:
            inode = _oxml_sub(cnode, "intent-filter", {
                "priority": filt.get("priority"),
                "autoVerify": filt.get("auto_verify"),
            })
            for action in filt.get("actions") or []:
                _oxml_sub(inode, "action", {"name": action})
            for category in filt.get("categories") or []:
                _oxml_sub(inode, "category", {"name": category})
            for spec in filt.get("data") or []:
                _oxml_sub(inode, "data", dict(spec))

    launchers = _oxml_sub(root, "launchers")
    for launcher in semantics.get("launcher_components") or []:
        _oxml_sub(launchers, "component", {"name": launcher})

    return ET.ElementTree(root)


def _oxml_canonical_bytes(tree):
    ET.register_namespace("oxml", ORFMOS_OXML_NS)
    return ET.tostring(
        tree.getroot(),
        encoding="utf-8",
        xml_declaration=True,
        short_empty_elements=True,
    )


def _oxml_parse_document(raw):
    data = bytes(raw or b"")
    root = ET.fromstring(data)
    if root.tag != f"{{{ORFMOS_OXML_NS}}}manifest":
        raise ValueError("OXML_ROOT_UNEXPECTED")
    if root.attrib.get("schema") != ORFMOS_OXML_DOCUMENT_SCHEMA:
        raise ValueError("OXML_SCHEMA_UNEXPECTED")

    def child(node, name):
        return node.find(f"{{{ORFMOS_OXML_NS}}}{name}")

    def children(node, name):
        return list(node.findall(f"{{{ORFMOS_OXML_NS}}}{name}"))

    sdk_node = child(root, "sdk")
    sdk = {
        "min_sdk": sdk_node.attrib.get("min") if sdk_node is not None else None,
        "target_sdk": sdk_node.attrib.get("target") if sdk_node is not None else None,
        "max_sdk": sdk_node.attrib.get("max") if sdk_node is not None else None,
        "compile_sdk": sdk_node.attrib.get("compile") if sdk_node is not None else None,
    }
    for key, value in list(sdk.items()):
        if value is not None:
            try:
                sdk[key] = int(value, 0)
            except Exception:
                pass

    req_node = child(root, "requested-permissions")
    requested = []
    if req_node is not None:
        requested = [
            n.attrib.get("name")
            for n in children(req_node, "permission")
            if n.attrib.get("name")
        ]

    decl_node = child(root, "declared-permissions")
    declared = []
    if decl_node is not None:
        for n in children(decl_node, "permission"):
            declared.append({
                "name": n.attrib.get("name"),
                "protection_level": n.attrib.get("protectionLevel"),
            })

    feat_node = child(root, "features")
    features = []
    if feat_node is not None:
        for n in children(feat_node, "feature"):
            features.append({
                "name": n.attrib.get("name"),
                "required": _oxml_boolish(n.attrib.get("required")),
                "gl_es_version": n.attrib.get("glEsVersion"),
            })

    app_node = child(root, "application")
    application = None
    components = []
    if app_node is not None:
        application = {
            "name": app_node.attrib.get("name"),
            "resolved_name": app_node.attrib.get("resolvedName"),
            "label": app_node.attrib.get("label"),
            "theme": app_node.attrib.get("theme"),
            "debuggable": _oxml_boolish(app_node.attrib.get("debuggable")),
            "allow_backup": _oxml_boolish(app_node.attrib.get("allowBackup")),
            "uses_cleartext_traffic": _oxml_boolish(app_node.attrib.get("usesCleartextTraffic")),
            "network_security_config": app_node.attrib.get("networkSecurityConfig"),
        }
        for cnode in children(app_node, "component"):
            filters = []
            for inode in children(cnode, "intent-filter"):
                actions = [
                    n.attrib.get("name")
                    for n in children(inode, "action")
                    if n.attrib.get("name")
                ]
                categories = [
                    n.attrib.get("name")
                    for n in children(inode, "category")
                    if n.attrib.get("name")
                ]
                data = [dict(n.attrib) for n in children(inode, "data")]
                filters.append({
                    "priority": inode.attrib.get("priority"),
                    "auto_verify": _oxml_boolish(inode.attrib.get("autoVerify")),
                    "actions": actions,
                    "categories": categories,
                    "data": data,
                })
            components.append({
                "type": cnode.attrib.get("type"),
                "name": cnode.attrib.get("name"),
                "resolved_name": cnode.attrib.get("resolvedName"),
                "exported": _oxml_boolish(cnode.attrib.get("exported")),
                "enabled": _oxml_boolish(cnode.attrib.get("enabled")),
                "permission": cnode.attrib.get("permission"),
                "process": cnode.attrib.get("process"),
                "authorities": cnode.attrib.get("authorities"),
                "target_activity": cnode.attrib.get("targetActivity"),
                "intent_filters": filters,
            })

    launch_node = child(root, "launchers")
    launchers = []
    if launch_node is not None:
        launchers = [
            n.attrib.get("name")
            for n in children(launch_node, "component")
            if n.attrib.get("name")
        ]

    version_code = root.attrib.get("versionCode")
    if version_code is not None:
        try:
            version_code = int(version_code, 0)
        except Exception:
            pass

    return {
        "schema": "ORFMOS_ANDROID_MANIFEST_SEMANTICS_V0_1",
        "state": "READY",
        "package": root.attrib.get("package"),
        "version_code": version_code,
        "version_name": root.attrib.get("versionName"),
        "sdk": sdk,
        "requested_permissions": requested,
        "declared_permissions": declared,
        "uses_features": features,
        "application": application,
        "components": components,
        "launcher_components": launchers,
        "counts": {
            "requested_permissions": len(requested),
            "declared_permissions": len(declared),
            "uses_features": len(features),
            "components": len(components),
            "intent_filters": sum(
                len(c.get("intent_filters") or []) for c in components
            ),
        },
    }


def _oxml_observed_contracts(semantics, source_format):
    contracts = [
        {
            "contract": "PACKAGE_IDENTITY",
            "state": "ORFMOS_NATIVE",
            "evidence": "OXML resolved manifest package/version identity",
        },
        {
            "contract": "PERMISSION_POLICY",
            "state": "ORFMOS_NATIVE",
            "evidence": "OXML normalized requested and declared permission semantics",
        },
    ]
    components = list(semantics.get("components") or [])
    if any(str(c.get("type") or "") in {"activity", "activity-alias"} for c in components):
        contracts.append({
            "contract": "ACTIVITY_LIFECYCLE",
            "state": "SHIM",
            "evidence": "OXML resolved Android activity component declarations",
        })
    if any(c.get("intent_filters") for c in components):
        contracts.append({
            "contract": "INTENT_ROUTING",
            "state": "SHIM",
            "evidence": "OXML resolved intent-filter actions/categories/data",
        })
    if semantics.get("uses_features"):
        contracts.append({
            "contract": "ANDROID_HARDWARE",
            "state": "SHIM",
            "evidence": "OXML resolved uses-feature declarations",
        })
    if str(source_format) == "ANDROID_BINARY_AXML":
        contracts.append({
            "contract": "ANDROID_MANIFEST_AXML",
            "state": "ORFMOS_COMPATIBILITY",
            "evidence": "OXML decoded Android binary AXML into canonical manifest semantics",
        })
    return contracts


def _oxml_executable_manifest(
    semantics,
    *,
    source_format,
    source_sha256,
    source_bytes,
    oxml_sha256,
    oxml_bytes,
    name=None,
    source_provider=None,
    source_uri=None,
    source_identity=None,
    source_container="MANIFEST_XML",
    container_sha256=None,
    container_bytes=None,
):
    package = semantics.get("package")
    launchers = list(semantics.get("launcher_components") or [])
    return {
        "schema": ORFMOS_EXECUTABLE_MANIFEST_SCHEMA,
        "identity": {
            "name": name or (
                str(package) + ".manifest" if package else "manifest.xml"
            ),
            "package_identity": package,
            "package_identity_state": "OXML_RESOLVED",
            "version_code": semantics.get("version_code"),
            "version_name": semantics.get("version_name"),
        },
        "container": {
            "format": source_container,
            "adapter": "OXML_MANIFEST_ADAPTER_V0_1",
            "source_semantics": "NORMALIZED_EXECUTABLE_MANIFEST",
        },
        "integrity": {
            "sha256": container_sha256 or source_sha256,
            "bytes": (
                container_bytes
                if container_bytes is not None
                else source_bytes
            ),
            "manifest_sha256": source_sha256,
            "manifest_bytes": source_bytes,
            "oxml_sha256": oxml_sha256,
            "oxml_bytes": oxml_bytes,
        },
        "declared_manifest": {
            "format": source_format,
            "state": "OXML_NORMALIZED",
            "semantics_schema": semantics.get("schema"),
            "package": package,
            "version_code": semantics.get("version_code"),
            "version_name": semantics.get("version_name"),
            "sdk": dict(semantics.get("sdk") or {}),
            "requested_permissions": list(
                semantics.get("requested_permissions") or []
            ),
            "declared_permissions": list(
                semantics.get("declared_permissions") or []
            ),
            "uses_features": list(semantics.get("uses_features") or []),
            "application": dict(semantics.get("application") or {}),
            "components": list(semantics.get("components") or []),
            "launcher_components": launchers,
        },
        "observed_contracts": _oxml_observed_contracts(
            semantics, source_format
        ),
        "execution": {
            "translation_posture": "ORFMOS_MANIFEST_NORMALIZED",
            "entrypoints": launchers,
            "candidate_providers": [
                {
                    "id": "ORFMOS",
                    "service": "ORFVM",
                    "intent": "EXECUTE",
                    "state": "CONTRACT_RESOLUTION_REQUIRED",
                },
                {
                    "id": "ANDROID_VM_FALLBACK",
                    "service": "ORFVM",
                    "intent": "EXECUTE",
                    "state": "FALLBACK_ONLY",
                },
            ],
        },
        "source": {
            "provider": source_provider,
            "uri": source_uri,
            "identity": source_identity,
            "manifest_format": source_format,
        },
        "normalization": {
            "provider": "ORFMOS",
            "service": "OXML",
            "intent": "CONVERT",
            "syntax": "ORFMOS OXML CONVERT XML MANIFEST NORMALIZE VERIFY",
            "source_manifest_sha256": source_sha256,
            "oxml_sha256": oxml_sha256,
            "android_vm_required": False,
        },
        "generated_utc": _oxml_utc(),
    }


def _orfmos_oxml_convert(
    raw,
    *,
    name=None,
    source_provider=None,
    source_uri=None,
    source_identity=None,
    source_container="MANIFEST_XML",
    container_sha256=None,
    container_bytes=None,
    include_oxml_text=True,
):
    resolver = _oxml_required("_orfmos_android_manifest_resolve")
    data = bytes(raw or b"")
    if not data:
        raise ValueError("OXML_SOURCE_EMPTY")

    resolved = resolver(
        data, include_tree=False, include_xml_text=False
    )
    semantics = dict(resolved.get("manifest") or {})
    if semantics.get("state") != "READY":
        raise ValueError(
            f"OXML_MANIFEST_SEMANTICS_NOT_READY:{semantics.get('state')}"
        )

    tree = _oxml_semantics_to_tree(
        semantics,
        source_format=resolved.get("format"),
        source_sha256=resolved.get("sha256"),
        source_bytes=resolved.get("bytes"),
    )
    oxml_raw = _oxml_canonical_bytes(tree)
    oxml_sha256 = hashlib.sha256(oxml_raw).hexdigest()

    roundtrip = _oxml_parse_document(oxml_raw)
    roundtrip_checks = {
        "package": roundtrip.get("package") == semantics.get("package"),
        "version_code": (
            roundtrip.get("version_code")
            == semantics.get("version_code")
        ),
        "version_name": (
            roundtrip.get("version_name")
            == semantics.get("version_name")
        ),
        "sdk": roundtrip.get("sdk") == semantics.get("sdk"),
        "permissions": (
            roundtrip.get("requested_permissions")
            == semantics.get("requested_permissions")
        ),
        "components": [
            (x.get("type"), x.get("resolved_name"))
            for x in roundtrip.get("components") or []
        ] == [
            (x.get("type"), x.get("resolved_name"))
            for x in semantics.get("components") or []
        ],
        "launchers": (
            roundtrip.get("launcher_components")
            == semantics.get("launcher_components")
        ),
    }
    if not all(roundtrip_checks.values()):
        raise RuntimeError("OXML_ROUNDTRIP_SEMANTICS_MISMATCH")

    executable_manifest = _oxml_executable_manifest(
        semantics,
        source_format=resolved.get("format"),
        source_sha256=resolved.get("sha256"),
        source_bytes=resolved.get("bytes"),
        oxml_sha256=oxml_sha256,
        oxml_bytes=len(oxml_raw),
        name=name,
        source_provider=source_provider,
        source_uri=source_uri,
        source_identity=source_identity,
        source_container=source_container,
        container_sha256=container_sha256,
        container_bytes=container_bytes,
    )

    canonical_manifest_object = json.loads(json.dumps(executable_manifest))
    canonical_manifest_object.pop("generated_utc", None)
    canonical_manifest_object.setdefault("normalization", {})["manifest_hash_policy"] = (
        "SEMANTIC_CANONICAL_JSON_V0_1__GENERATED_UTC_EXCLUDED"
    )
    executable_manifest.setdefault("normalization", {})["manifest_hash_policy"] = (
        "SEMANTIC_CANONICAL_JSON_V0_1__GENERATED_UTC_EXCLUDED"
    )
    canonical_manifest = json.dumps(
        canonical_manifest_object,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
    ).encode("utf-8")
    manifest_sha256 = hashlib.sha256(canonical_manifest).hexdigest()

    result = {
        "schema": ORFMOS_OXML_SCHEMA,
        "revision": ORFMOS_OXML_REVISION,
        "state": "READY",
        "provider": "ORFMOS",
        "service": "OXML",
        "intent": "CONVERT",
        "source": {
            "format": resolved.get("format"),
            "sha256": resolved.get("sha256"),
            "bytes": resolved.get("bytes"),
        },
        "oxml": {
            "schema": ORFMOS_OXML_DOCUMENT_SCHEMA,
            "sha256": oxml_sha256,
            "bytes": len(oxml_raw),
            "roundtrip": roundtrip_checks,
        },
        "semantics": semantics,
        "executable_manifest": executable_manifest,
        "executable_manifest_sha256": manifest_sha256,
        "android_vm_required": False,
    }
    if include_oxml_text:
        result["oxml"]["text"] = oxml_raw.decode("utf-8")

    _oxml_event(
        "MANIFEST_CONVERTED",
        (
            f"format={resolved.get('format')} "
            f"package={semantics.get('package')} "
            f"oxml_sha256={oxml_sha256}"
        ),
    )
    return result


def _oxml_state():
    resolver_state = {}
    helper = globals().get("_orfmos_xml_axml_state")
    if callable(helper):
        try:
            resolver_state = helper()
        except Exception:
            resolver_state = {}
    return {
        "schema": ORFMOS_OXML_SCHEMA,
        "revision": ORFMOS_OXML_REVISION,
        "state": "READY",
        "provider": "ORFMOS",
        "service": "OXML",
        "capabilities": {
            "TEXT_XML_TO_OXML": "READY",
            "ANDROID_AXML_TO_OXML": "READY",
            "OXML_ROUNDTRIP_VERIFY": "READY",
            "OXML_TO_EXECUTABLE_MANIFEST": "READY",
        },
        "output_schema": ORFMOS_EXECUTABLE_MANIFEST_SCHEMA,
        "android_vm_required": False,
        "xml_resolver": resolver_state.get("state"),
        "events": list(_OXML_EVENTS[-20:]),
    }


async def _oxml_state_http():
    return _oxml_state()


async def _oxml_convert_http(
    request: Request,
    name: str = "",
    source_provider: str = "",
    source_uri: str = "",
    source_identity: str = "",
    source_container: str = "MANIFEST_XML",
    include_oxml_text: bool = True,
):
    body = await request.body()
    return _orfmos_oxml_convert(
        body,
        name=name or None,
        source_provider=source_provider or None,
        source_uri=source_uri or None,
        source_identity=source_identity or None,
        source_container=source_container or "MANIFEST_XML",
        include_oxml_text=include_oxml_text,
    )


async def _oxml_manifest_http(request: Request):
    body = await request.body()
    result = _orfmos_oxml_convert(body, include_oxml_text=False)
    return {
        "schema": ORFMOS_OXML_SCHEMA,
        "state": result.get("state"),
        "executable_manifest": result.get("executable_manifest"),
        "executable_manifest_sha256": result.get(
            "executable_manifest_sha256"
        ),
        "oxml": result.get("oxml"),
    }


def _oxml_find_fastapi_app():
    for helper_name in ("_xar_find_fastapi_app", "_orfvm_find_fastapi_app"):
        helper = globals().get(helper_name)
        if callable(helper):
            try:
                app = helper()
                if app is not None:
                    return app
            except Exception:
                pass
    for value in list(globals().values()):
        if (
            hasattr(value, "router")
            and hasattr(getattr(value, "router", None), "routes")
            and hasattr(value, "add_api_route")
        ):
            return value
    return None


def _oxml_bind_routes():
    app = _oxml_find_fastapi_app()
    if app is None:
        _oxml_event("ROUTES_NOT_BOUND", "FASTAPI_APP_NOT_FOUND")
        return 0
    targets = {
        ORFMOS_OXML_ROUTE_PREFIX + "/state",
        ORFMOS_OXML_ROUTE_PREFIX + "/convert",
        ORFMOS_OXML_ROUTE_PREFIX + "/manifest",
    }
    kept = []
    removed = 0
    for route in list(app.router.routes):
        if str(getattr(route, "path", "")) in targets:
            removed += 1
            continue
        kept.append(route)
    app.router.routes[:] = kept
    app.add_api_route(
        ORFMOS_OXML_ROUTE_PREFIX + "/state",
        _oxml_state_http,
        methods=["GET"],
        name="orfmos_oxml_state",
    )
    app.add_api_route(
        ORFMOS_OXML_ROUTE_PREFIX + "/convert",
        _oxml_convert_http,
        methods=["POST"],
        name="orfmos_oxml_convert",
    )
    app.add_api_route(
        ORFMOS_OXML_ROUTE_PREFIX + "/manifest",
        _oxml_manifest_http,
        methods=["POST"],
        name="orfmos_oxml_manifest",
    )
    setattr(app, "__ORFMOS_OXML_REVISION__", ORFMOS_OXML_REVISION)
    _oxml_event("ROUTES_BOUND", f"removed={removed} bound=3")
    return 3


def _oxml_self_test():
    text = (
        b'<manifest xmlns:android="http://schemas.android.com/apk/res/android" '
        b'package="org.orf.oxml.test" android:versionCode="9" '
        b'android:versionName="0.1"><uses-sdk android:minSdkVersion="23" '
        b'android:targetSdkVersion="36"/><uses-permission '
        b'android:name="android.permission.INTERNET"/><application '
        b'android:label="OXML"><activity android:name=".MainActivity" '
        b'android:exported="true"><intent-filter><action '
        b'android:name="android.intent.action.MAIN"/><category '
        b'android:name="android.intent.category.LAUNCHER"/></intent-filter>'
        b'</activity></application></manifest>'
    )
    result = _orfmos_oxml_convert(
        text, name="oxml-test.xml", include_oxml_text=True
    )
    em = result.get("executable_manifest") or {}
    checks = {
        "text_xml_converted": result.get("state") == "READY",
        "package_identity": (
            (em.get("identity") or {}).get("package_identity")
            == "org.orf.oxml.test"
        ),
        "package_identity_state": (
            (em.get("identity") or {}).get("package_identity_state")
            == "OXML_RESOLVED"
        ),
        "launcher_entrypoint": (
            "org.orf.oxml.test.MainActivity"
            in ((em.get("execution") or {}).get("entrypoints") or [])
        ),
        "permission_policy": any(
            item.get("contract") == "PERMISSION_POLICY"
            for item in (em.get("observed_contracts") or [])
        ),
        "roundtrip_verified": all(
            (result.get("oxml") or {}).get("roundtrip", {}).values()
        ),
        "manifest_hash_present": bool(
            result.get("executable_manifest_sha256")
        ),
        "android_not_required": (
            result.get("android_vm_required") is False
        ),
    }
    return {
        "state": "PASS" if all(checks.values()) else "FAIL",
        "checks": checks,
    }


globals()["_orfmos_oxml_convert"] = _orfmos_oxml_convert
globals()["_orfmos_oxml_parse_document"] = _oxml_parse_document
globals()["_orfmos_oxml_state"] = _oxml_state
globals()["__ORFMOS_OXML_SELF_TEST__"] = _oxml_self_test()
globals()["__ORFMOS_OXML_ROUTES_BOUND__"] = _oxml_bind_routes()

