def _home_r85_bind_acf_oxml_contract():
    catalog = globals().get("ORFMOS_ANDROID_CONTRACTS")
    if not isinstance(catalog, dict):
        result = {
            "schema": "ORFMOS_HOME_R85_ACF_BIND_RESULT_V0_1",
            "state": "DEFERRED_ACF_NOT_RESIDENT",
        }
        globals()["__ORFMOS_HOME_R85_ACF_BIND_RESULT__"] = result
        return result
    previous = dict(catalog.get(ORFMOS_HOME_R85_AXML_CONTRACT) or {})
    entry = {
        "orf_syntax": "ORFMOS OXML CONVERT AXML MANIFEST NORMALIZE VERIFY",
        "provider": "ORFMOS_COMPATIBILITY",
        "readiness": "READY",
        "service": "OXML",
        "capability": "ANDROID_BINARY_AXML_TO_NORMALIZED_MANIFEST",
    }
    catalog[ORFMOS_HOME_R85_AXML_CONTRACT] = entry
    globals()["ORFMOS_ANDROID_CONTRACT_FRAMEWORK_ROUTE_REVISION"] = ORFMOS_HOME_R85_ACF_REVISION
    result = {
        "schema": "ORFMOS_HOME_R85_ACF_BIND_RESULT_V0_1",
        "state": "READY",
        "contract": ORFMOS_HOME_R85_AXML_CONTRACT,
        "previous": previous,
        "current": dict(entry),
        "contract_count": len(catalog),
    }
    globals()["__ORFMOS_HOME_R85_ACF_BIND_RESULT__"] = result
    return result

def _orfmos_acf_resolve_authoritative(object_hash, contract):
    fn = globals().get("_acf_resolve_contract")
    if not callable(fn):
        raise RuntimeError("ACF_PRIVATE_RESOLVER_NOT_RESIDENT")
    import inspect as _inspect
    sig = _inspect.signature(fn)
    names = list(sig.parameters.keys())
    if "contract" in sig.parameters and "object_hash" in sig.parameters:
        return fn(contract=contract, object_hash=object_hash)
    contract_name = next((n for n in names if n.lower() in {"contract","contract_name","contract_id"}), None)
    object_name = next((n for n in names if n.lower() in {"object_hash","hash","sha256","object_id"}), None)
    if contract_name and object_name:
        return fn(**{contract_name: contract, object_name: object_hash})
    if len(names) >= 2:
        first, second = names[0].lower(), names[1].lower()
        if "contract" in first and ("hash" in second or "object" in second):
            return fn(contract, object_hash)
        if ("hash" in first or "object" in first) and "contract" in second:
            return fn(object_hash, contract)
    raise RuntimeError("ACF_PRIVATE_RESOLVER_SIGNATURE_UNSUPPORTED:" + str(sig))

def _orfmos_mps_oxml_manifest_preflight(
    manifest_raw,
    *,
    name=None,
    source_provider=None,
    source_uri=None,
    source_identity=None,
    source_container="MANIFEST_XML",
    container_sha256=None,
    container_bytes=None,
):
    """MPS semantic VALIDATE gate. Never starts Android and never performs WRITE."""
    _home_r85_bind_acf_oxml_contract()
    converter = globals().get("_orfmos_oxml_convert")
    if not callable(converter):
        raise RuntimeError("OXML_CONVERTER_NOT_RESIDENT")
    converted = converter(
        manifest_raw,
        name=name,
        source_provider=source_provider,
        source_uri=source_uri,
        source_identity=source_identity,
        source_container=source_container,
        container_sha256=container_sha256,
        container_bytes=container_bytes,
        include_oxml_text=False,
    )
    executable_manifest = converted.get("executable_manifest") or {}
    observed = list(executable_manifest.get("observed_contracts") or [])
    contracts = []
    for item in observed:
        if isinstance(item, dict):
            contract = str(item.get("contract") or "").upper().strip()
            if contract and contract not in contracts:
                contracts.append(contract)
    object_hash = str(container_sha256 or "").lower().strip()
    if len(object_hash) != 64:
        object_hash = str((executable_manifest.get("integrity") or {}).get("sha256") or "").lower().strip()
    if len(object_hash) != 64:
        raise RuntimeError("MPS_OXML_CONTAINER_HASH_MISSING")

    register_result = None
    resolutions = []
    register = globals().get("_orfvm_contract_register_object")
    resolve = globals().get("_orfvm_contract_resolve")
    if callable(register) and callable(resolve):
        register_result = register(
            object_hash,
            contracts,
            source_name=name or "oxml-manifest",
            source_type="EXECUTABLE_MANIFEST",
            lineage_id="ORFMOS_MPS_OXML_R85",
            metadata={
                "oxml_sha256": (converted.get("oxml") or {}).get("sha256"),
                "manifest_object_sha256": converted.get("executable_manifest_sha256"),
                "package_identity": (executable_manifest.get("identity") or {}).get("package_identity"),
            },
        )
        resolutions = [resolve(object_hash, contract) for contract in contracts]
    else:
        direct = globals().get("_orfmos_acf_resolve_authoritative")
        if not callable(direct):
            raise RuntimeError("MPS_OXML_ACF_RESOLUTION_NOT_AVAILABLE")
        resolutions = [direct(object_hash, contract) for contract in contracts]

    axml = next((row for row in resolutions if row.get("contract") == "ANDROID_MANIFEST_AXML"), {})
    if not (
        axml.get("classification") == "MATCH"
        and axml.get("provider") == "ORFMOS_COMPATIBILITY"
        and axml.get("provider_state") == "READY"
    ):
        raise RuntimeError("MPS_OXML_AXML_CONTRACT_NOT_READY:" + json.dumps(axml, sort_keys=True))

    result = {
        "schema": "ORFMOS_MPS_OXML_PREFLIGHT_V0_2_R85",
        "state": "READY",
        "provider": "ORFMOS",
        "service": "MPS",
        "intent": "VALIDATE",
        "object_hash": object_hash,
        "contracts": contracts,
        "resolutions": resolutions,
        "register_result": register_result,
        "converted": converted,
        "android_vm_required": False,
    }
    globals()["__ORFMOS_MPS_OXML_LAST_PREFLIGHT__"] = result
    return result


