import asyncio
import hashlib
import inspect
import json
import os
import re
import threading
import time
from datetime import datetime, timezone
from fastapi import Request

# ========================================================================================================
# ORFMOS ORFVM CONTRACT PROVIDER BINDING v0.1 — RESIDENT RUNTIME PATCH
# ========================================================================================================
# Purpose
# -------
# Bind the already-resident ORFMOS Android Contract Framework as ORFVM's default
# compatibility-resolution provider without mutating the known-good Home artifact.
#
# Interaction model
# -----------------
# PROVIDER ORFMOS / SERVICE ORFVM / INTENT RESOLVE / TARGET <SHA256 + CONTRACT>
#   -> ORFMOS Android Contract Framework FIRST
#   -> native / compatibility / provider resolution
#   -> Android VM remains an explicit FALLBACK_ORACLE
#
# Explicit Android realization remains authoritative when the caller has specifically
# selected ANDROID_VM_LAB (for example ORFMOS MPS INSTALL after user consent). In that
# path this patch performs contract preflight first, records the resolution, then allows
# the explicitly requested Android realization provider to proceed.
#
# No VM start/provision action is performed by this binding.
# ========================================================================================================

ORFMOS_ORFVM_CONTRACT_BINDING_SCHEMA = "ORFMOS_ORFVM_CONTRACT_PROVIDER_BINDING_V0_1"
ORFMOS_ORFVM_CONTRACT_BINDING_REVISION = "OCPB_V0_1_ACF_FIRST_RESOLUTION"
ORFMOS_ORFVM_CONTRACT_BINDING_ROUTE_PREFIX = "/orfmos/orfvm-contract"
ORFMOS_ORFVM_CONTRACT_BINDING_PROVIDER = "ORFMOS"
ORFMOS_ORFVM_CONTRACT_BINDING_SERVICE = "ORFVM"
ORFMOS_ORFVM_CONTRACT_BINDING_INTENT = "RESOLVE"
ORFMOS_ORFVM_CONTRACT_BINDING_ANDROID_ROLE = "FALLBACK_ORACLE"

_ORFVM_BINDING_LOCK = globals().get("_ORFVM_BINDING_LOCK") or threading.RLock()
globals()["_ORFVM_BINDING_LOCK"] = _ORFVM_BINDING_LOCK


def _orfvm_binding_utc():
    return datetime.now(timezone.utc).isoformat()


def _orfvm_binding_events():
    events = globals().get("__ORFMOS_ORFVM_CONTRACT_BINDING_EVENTS__")
    if not isinstance(events, list):
        events = []
        globals()["__ORFMOS_ORFVM_CONTRACT_BINDING_EVENTS__"] = events
    return events


def _orfvm_binding_event(event_type, detail=""):
    with _ORFVM_BINDING_LOCK:
        events = list(_orfvm_binding_events())
        events.append({"utc": _orfvm_binding_utc(), "type": str(event_type), "detail": str(detail)})
        globals()["__ORFMOS_ORFVM_CONTRACT_BINDING_EVENTS__"] = events[-96:]


def _orfvm_jsonable(value):
    if isinstance(value, (str, int, float, bool)) or value is None:
        return value
    if isinstance(value, bytes):
        return value.decode("utf-8", "replace")
    if isinstance(value, dict):
        return {str(k): _orfvm_jsonable(v) for k, v in value.items()}
    if isinstance(value, (list, tuple, set)):
        return [_orfvm_jsonable(v) for v in value]
    body = getattr(value, "body", None)
    if isinstance(body, (bytes, bytearray)):
        try:
            return json.loads(bytes(body).decode("utf-8"))
        except Exception:
            return {"body": bytes(body).decode("utf-8", "replace")}
    return str(value)


def _orfvm_find_fastapi_app():
    candidates = []
    for name, value in list(globals().items()):
        if value is None or not hasattr(value, "routes") or not hasattr(value, "add_api_route"):
            continue
        try:
            paths = {str(getattr(route, "path", "")) for route in list(value.routes)}
        except Exception:
            continue
        score = 0
        if "/orfmos/vm-framework/state" in paths:
            score += 10
        if "/orfmos/vm-framework/transaction" in paths:
            score += 10
        if "/orfmos/vm-lab/state" in paths:
            score += 5
        candidates.append((score, name, value))
    if not candidates:
        return None
    candidates.sort(key=lambda item: (item[0], item[1]), reverse=True)
    return candidates[0][2]


def _orfvm_route(app, path, method=None):
    if app is None:
        return None
    wanted_method = str(method or "").upper().strip()
    for route in list(getattr(app, "routes", []) or []):
        if str(getattr(route, "path", "")) != path:
            continue
        methods = {str(x).upper() for x in (getattr(route, "methods", None) or [])}
        if wanted_method and methods and wanted_method not in methods:
            continue
        endpoint = getattr(route, "endpoint", None)
        if callable(endpoint):
            return endpoint
    return None


def _orfvm_run_coroutine_sync(coro, timeout=20.0):
    """Run a coroutine from ordinary code, including a Jupyter thread with a live loop."""
    try:
        asyncio.get_running_loop()
        running_here = True
    except RuntimeError:
        running_here = False
    if not running_here:
        return asyncio.run(coro)

    box = {"value": None, "error": None}

    def runner():
        try:
            box["value"] = asyncio.run(coro)
        except Exception as exc:
            box["error"] = exc

    worker = threading.Thread(target=runner, daemon=True, name="orfvm-acf-sync-bridge")
    worker.start()
    worker.join(timeout=max(0.1, float(timeout)))
    if worker.is_alive():
        raise TimeoutError("ORFVM_ACF_SYNC_BRIDGE_TIMEOUT")
    if box["error"] is not None:
        raise box["error"]
    return box["value"]


async def _orfvm_call_endpoint(endpoint, *args, **kwargs):
    value = endpoint(*args, **kwargs)
    if inspect.isawaitable(value):
        value = await value
    return _orfvm_jsonable(value)


def _orfvm_acf_endpoints():
    app = _orfvm_find_fastapi_app()
    return {
        "app": app,
        "state": _orfvm_route(app, "/orfmos/vm-framework/state", "GET"),
        "contracts": _orfvm_route(app, "/orfmos/vm-framework/contracts", "GET"),
        "object": _orfvm_route(app, "/orfmos/vm-framework/object", "GET"),
        "transaction": _orfvm_route(app, "/orfmos/vm-framework/transaction", "POST"),
    }


def _orfvm_acf_state():
    endpoint = _orfvm_acf_endpoints().get("state")
    if not callable(endpoint):
        return {"state": "UNAVAILABLE", "message": "ACF_STATE_ROUTE_NOT_BOUND"}
    try:
        return _orfvm_run_coroutine_sync(_orfvm_call_endpoint(endpoint))
    except Exception as exc:
        return {"state": "FAILED", "message": f"{type(exc).__name__}: {exc}"}


def _orfvm_acf_contracts():
    endpoint = _orfvm_acf_endpoints().get("contracts")
    if not callable(endpoint):
        return {"state": "UNAVAILABLE", "message": "ACF_CONTRACTS_ROUTE_NOT_BOUND", "contracts": []}
    try:
        return _orfvm_run_coroutine_sync(_orfvm_call_endpoint(endpoint))
    except Exception as exc:
        return {"state": "FAILED", "message": f"{type(exc).__name__}: {exc}", "contracts": []}


async def _orfvm_acf_transaction_async(payload):
    endpoint = _orfvm_acf_endpoints().get("transaction")
    if not callable(endpoint):
        raise RuntimeError("ACF_TRANSACTION_ROUTE_NOT_BOUND")
    body = json.dumps(_orfvm_jsonable(payload), separators=(",", ":")).encode("utf-8")
    delivered = False

    async def receive():
        nonlocal delivered
        if delivered:
            return {"type": "http.request", "body": b"", "more_body": False}
        delivered = True
        return {"type": "http.request", "body": body, "more_body": False}

    scope = {
        "type": "http",
        "asgi": {"version": "3.0", "spec_version": "2.3"},
        "http_version": "1.1",
        "method": "POST",
        "scheme": "http",
        "path": "/orfmos/vm-framework/transaction",
        "raw_path": b"/orfmos/vm-framework/transaction",
        "query_string": b"",
        "headers": [(b"content-type", b"application/json"), (b"accept", b"application/json")],
        "client": ("127.0.0.1", 0),
        "server": ("orfmos-resident", 80),
        "root_path": "",
    }
    request = Request(scope, receive)
    return await _orfvm_call_endpoint(endpoint, request)


def _orfvm_contract_transaction(payload):
    result = _orfvm_run_coroutine_sync(_orfvm_acf_transaction_async(payload), timeout=30.0)
    if not isinstance(result, dict):
        raise RuntimeError("ACF_TRANSACTION_NON_OBJECT_RESPONSE")
    return result


def _orfvm_contract_register_object(object_hash, contracts, *, source_name="orfvm-object", source_type="ORFVM_OBJECT", lineage_id="ORFMOS_ORFVM", metadata=None):
    payload = {
        "operation": "REGISTER_OBJECT",
        "object_hash": str(object_hash or "").lower(),
        "source_name": str(source_name or "orfvm-object"),
        "source_type": str(source_type or "ORFVM_OBJECT"),
        "lineage_id": str(lineage_id or "ORFMOS_ORFVM"),
        "metadata": _orfvm_jsonable(metadata or {}),
        "contracts": [str(item).upper().strip() for item in (contracts or []) if str(item).strip()],
    }
    return _orfvm_contract_transaction(payload)


def _orfvm_contract_resolve(object_hash, contract):
    return _orfvm_contract_transaction({
        "operation": "RESOLVE_CONTRACT",
        "object_hash": str(object_hash or "").lower(),
        "contract": str(contract or "").upper().strip(),
    })


def _orfvm_contract_read_object(object_hash):
    return _orfvm_contract_transaction({
        "operation": "READ_OBJECT",
        "object_hash": str(object_hash or "").lower(),
    })


def _orfvm_normalize_contracts(observed_contracts):
    names = ["OBJECT_IDENTITY", "PACKAGE_IDENTITY"]
    for item in observed_contracts or []:
        if isinstance(item, dict):
            name = str(item.get("contract") or "").upper().strip()
        else:
            name = str(item or "").upper().strip()
        if name and name not in names:
            names.append(name)
    return names


def _orfvm_apk_contract_preflight(path):
    path = str(path or "")
    if not path or not os.path.isfile(path):
        raise RuntimeError("ORFVM_PREFLIGHT_TARGET_MISSING")
    digest = hashlib.sha256()
    size = 0
    with open(path, "rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
            size += len(chunk)
    object_hash = digest.hexdigest()

    installer_state = globals().get("__ORFMOS_INSTALLER_STATE__")
    manifest = {}
    if isinstance(installer_state, dict) and str(installer_state.get("selected_sha256") or "").lower() == object_hash:
        maybe_manifest = installer_state.get("executable_manifest")
        if isinstance(maybe_manifest, dict):
            manifest = maybe_manifest
    observed = manifest.get("observed_contracts") if isinstance(manifest, dict) else []
    contracts = _orfvm_normalize_contracts(observed)

    register = _orfvm_contract_register_object(
        object_hash,
        contracts,
        source_name=os.path.basename(path) or "package.apk",
        source_type="APK",
        lineage_id="ORFMOS_MPS_INSTALL",
        metadata={
            "bytes": size,
            "binding_revision": ORFMOS_ORFVM_CONTRACT_BINDING_REVISION,
            "invocation": "ORFMOS MPS INSTALL",
            "explicit_realization_provider": "ANDROID_VM_LAB",
        },
    )
    resolutions = [_orfvm_contract_resolve(object_hash, contract) for contract in contracts]
    counts = {}
    fallback_contracts = []
    residual_contracts = []
    for item in resolutions:
        classification = str(item.get("classification") or "UNKNOWN")
        counts[classification] = counts.get(classification, 0) + 1
        provider = str(item.get("provider") or "")
        residual = item.get("residual")
        if provider == "ANDROID_VM_FALLBACK":
            fallback_contracts.append(str(item.get("contract") or "UNKNOWN"))
        if residual:
            residual_contracts.append({"contract": item.get("contract"), "residual": residual, "provider": provider, "classification": classification})

    result = {
        "schema": ORFMOS_ORFVM_CONTRACT_BINDING_SCHEMA,
        "state": "RESOLVED",
        "provider": ORFMOS_ORFVM_CONTRACT_BINDING_PROVIDER,
        "service": ORFMOS_ORFVM_CONTRACT_BINDING_SERVICE,
        "intent": ORFMOS_ORFVM_CONTRACT_BINDING_INTENT,
        "object_hash": object_hash,
        "contracts": contracts,
        "register": register,
        "resolutions": resolutions,
        "classification_counts": counts,
        "fallback_contracts": fallback_contracts,
        "residual_contracts": residual_contracts,
        "android_vm_role": ORFMOS_ORFVM_CONTRACT_BINDING_ANDROID_ROLE,
        "explicit_android_realization_requested": True,
        "generated_utc": _orfvm_binding_utc(),
    }
    globals()["__ORFMOS_ORFVM_LAST_CONTRACT_PREFLIGHT__"] = _orfvm_jsonable(result)
    _orfvm_binding_event(
        "APK_CONTRACT_PREFLIGHT",
        f"sha256={object_hash} contracts={len(contracts)} fallback={len(fallback_contracts)} residuals={len(residual_contracts)}",
    )
    return result


def _orfvm_binding_state():
    acf = _orfvm_acf_state()
    endpoints = _orfvm_acf_endpoints()
    acf_ready = str(acf.get("state") or "").upper() == "READY"
    return {
        "schema": ORFMOS_ORFVM_CONTRACT_BINDING_SCHEMA,
        "revision": ORFMOS_ORFVM_CONTRACT_BINDING_REVISION,
        "state": "READY" if acf_ready and callable(endpoints.get("transaction")) else "NOT_READY",
        "provider": ORFMOS_ORFVM_CONTRACT_BINDING_PROVIDER,
        "service": ORFMOS_ORFVM_CONTRACT_BINDING_SERVICE,
        "intent": ORFMOS_ORFVM_CONTRACT_BINDING_INTENT,
        "resolution_order": ["ORFMOS_CONTRACT_FRAMEWORK", "NATIVE_OR_COMPATIBILITY_PROVIDER", "ANDROID_VM_FALLBACK"],
        "framework": acf,
        "framework_transaction_bound": callable(endpoints.get("transaction")),
        "android_vm_role": ORFMOS_ORFVM_CONTRACT_BINDING_ANDROID_ROLE,
        "implicit_android_start": False,
        "mps_contract_preflight_bound": bool(globals().get("__ORFMOS_ORFVM_MPS_PREFLIGHT_BOUND__")),
        "vm_lab_state_projection_bound": bool(globals().get("__ORFMOS_ORFVM_VM_STATE_BOUND__")),
        "last_preflight": _orfvm_jsonable(globals().get("__ORFMOS_ORFVM_LAST_CONTRACT_PREFLIGHT__")),
        "events": list(_orfvm_binding_events()),
    }


async def _orfvm_binding_transaction_http(request: Request):
    payload = await request.json()
    return await _orfvm_acf_transaction_async(payload)


def _orfvm_binding_state_http():
    return _orfvm_binding_state()


def _orfvm_binding_contracts_http():
    payload = _orfvm_acf_contracts()
    return {
        "schema": ORFMOS_ORFVM_CONTRACT_BINDING_SCHEMA,
        "state": "READY" if str(payload.get("state") or "").upper() == "READY" else str(payload.get("state") or "UNKNOWN"),
        "provider": ORFMOS_ORFVM_CONTRACT_BINDING_PROVIDER,
        "service": ORFMOS_ORFVM_CONTRACT_BINDING_SERVICE,
        "framework": payload,
    }


def _orfvm_bind_routes():
    app = _orfvm_find_fastapi_app()
    if app is None:
        raise RuntimeError("RESIDENT_FASTAPI_APP_NOT_FOUND")
    target_paths = {
        ORFMOS_ORFVM_CONTRACT_BINDING_ROUTE_PREFIX + "/state",
        ORFMOS_ORFVM_CONTRACT_BINDING_ROUTE_PREFIX + "/contracts",
        ORFMOS_ORFVM_CONTRACT_BINDING_ROUTE_PREFIX + "/transaction",
    }
    kept = []
    removed = 0
    for route in list(getattr(app, "router").routes):
        if str(getattr(route, "path", "")) in target_paths:
            removed += 1
            continue
        kept.append(route)
    app.router.routes[:] = kept
    app.add_api_route(ORFMOS_ORFVM_CONTRACT_BINDING_ROUTE_PREFIX + "/state", _orfvm_binding_state_http, methods=["GET"], name="orfmos_orfvm_contract_state")
    app.add_api_route(ORFMOS_ORFVM_CONTRACT_BINDING_ROUTE_PREFIX + "/contracts", _orfvm_binding_contracts_http, methods=["GET"], name="orfmos_orfvm_contract_contracts")
    app.add_api_route(ORFMOS_ORFVM_CONTRACT_BINDING_ROUTE_PREFIX + "/transaction", _orfvm_binding_transaction_http, methods=["POST"], name="orfmos_orfvm_contract_transaction")
    setattr(app, "__ORFMOS_ORFVM_CONTRACT_BINDING_REVISION__", ORFMOS_ORFVM_CONTRACT_BINDING_REVISION)
    _orfvm_binding_event("ROUTES_BOUND", f"removed={removed} bound={len(target_paths)}")
    return len(target_paths)


def _orfvm_bind_vm_lab_state_projection():
    current = globals().get("_home_vm_lab_state_from_inventory")
    if not callable(current):
        globals()["__ORFMOS_ORFVM_VM_STATE_BOUND__"] = False
        return False
    original = globals().get("__ORFMOS_ORFVM_ORIGINAL_VM_STATE_FROM_INVENTORY__")
    if not callable(original):
        original = current
        globals()["__ORFMOS_ORFVM_ORIGINAL_VM_STATE_FROM_INVENTORY__"] = original

    def projected(inv=None):
        state = original(inv)
        if isinstance(state, dict):
            state = dict(state)
            state["contract_resolution"] = _orfvm_binding_state()
        return state

    projected.__name__ = "_home_vm_lab_state_from_inventory"
    globals()["_home_vm_lab_state_from_inventory"] = projected
    globals()["__ORFMOS_ORFVM_VM_STATE_BOUND__"] = True
    _orfvm_binding_event("VM_LAB_STATE_PROJECTED", "contract_resolution=ORFMOS_ORFVM_CONTRACT_PROVIDER_BINDING")
    return True


def _orfvm_bind_mps_preflight():
    current = globals().get("_home_vm_lab_install_apk")
    if not callable(current):
        globals()["__ORFMOS_ORFVM_MPS_PREFLIGHT_BOUND__"] = False
        return False
    original = globals().get("__ORFMOS_ORFVM_ORIGINAL_VM_INSTALL_APK__")
    if not callable(original):
        original = current
        globals()["__ORFMOS_ORFVM_ORIGINAL_VM_INSTALL_APK__"] = original

    def wrapped(path, progress=None, cancelled=None):
        if callable(progress):
            try:
                progress("MPS_CONTRACT_RESOLUTION", "ORFVM CONTRACT FRAMEWORK PRE-FLIGHT")
            except Exception:
                pass
        preflight = _orfvm_apk_contract_preflight(path)
        globals()["__ORFMOS_ORFVM_LAST_CONTRACT_PREFLIGHT__"] = _orfvm_jsonable(preflight)
        # The caller explicitly selected ANDROID_VM_LAB. Contract resolution is therefore
        # first, but it does not silently rewrite explicit realization intent.
        return original(path, progress=progress, cancelled=cancelled)

    wrapped.__name__ = "_home_vm_lab_install_apk"
    globals()["_home_vm_lab_install_apk"] = wrapped
    globals()["__ORFMOS_ORFVM_MPS_PREFLIGHT_BOUND__"] = True
    _orfvm_binding_event("MPS_PREFLIGHT_BOUND", "ORFMOS MPS INSTALL -> ORFVM CONTRACT RESOLUTION -> EXPLICIT ANDROID REALIZATION")
    return True


def _orfvm_binding_self_test():
    state = _orfvm_binding_state()
    contracts = _orfvm_acf_contracts()
    checks = {
        "framework_ready": str((state.get("framework") or {}).get("state") or "").upper() == "READY",
        "transaction_bound": bool(state.get("framework_transaction_bound")),
        "android_role_fallback_oracle": state.get("android_vm_role") == "FALLBACK_ORACLE",
        "implicit_android_start_false": state.get("implicit_android_start") is False,
        "contract_catalog_present": isinstance(contracts.get("contracts"), list) and len(contracts.get("contracts")) > 0,
    }
    return {"state": "PASS" if all(checks.values()) else "FAIL", "checks": checks}




def _home_r85_bind_orfvm_contract_provider():
    """Idempotently bind the proven ACF-first ORFVM compatibility provider when ACF is resident."""
    result = {
        "schema": "ORFMOS_HOME_R85_ORFVM_BIND_RESULT_V0_1",
        "state": "DEFERRED",
        "routes_bound": 0,
        "vm_state_projection_bound": False,
        "mps_preflight_bound": False,
    }
    try:
        endpoints = _orfvm_acf_endpoints()
        if not callable(endpoints.get("transaction")):
            result["state"] = "DEFERRED_ACF_TRANSACTION_NOT_BOUND"
            globals()["__ORFMOS_HOME_R85_ORFVM_BIND_RESULT__"] = result
            return result
        result["routes_bound"] = _orfvm_bind_routes()
        result["vm_state_projection_bound"] = _orfvm_bind_vm_lab_state_projection()
        result["mps_preflight_bound"] = _orfvm_bind_mps_preflight()
        self_test = _orfvm_binding_self_test()
        result["self_test"] = self_test
        result["state"] = "READY" if self_test.get("state") == "PASS" else "DEGRADED"
        state = _orfvm_binding_state()
        state["self_test"] = self_test
        state["routes_bound"] = result["routes_bound"]
        globals()["ORFMOS_ORFVM_CONTRACT_PROVIDER_BINDING_STATE"] = state
        globals()["_orfvm_contract_transaction"] = _orfvm_contract_transaction
        globals()["_orfvm_contract_register_object"] = _orfvm_contract_register_object
        globals()["_orfvm_contract_resolve"] = _orfvm_contract_resolve
        globals()["_orfvm_contract_read_object"] = _orfvm_contract_read_object
        globals()["_orfvm_apk_contract_preflight"] = _orfvm_apk_contract_preflight
        globals()["_orfvm_binding_state"] = _orfvm_binding_state
    except Exception as exc:
        result["state"] = "DEFERRED"
        result["error"] = f"{type(exc).__name__}: {exc}"
    globals()["__ORFMOS_HOME_R85_ORFVM_BIND_RESULT__"] = result
    return result


