import os
import io
import json
import zipfile
import hashlib
import inspect
from datetime import datetime, timezone

# ========================================================================================================
# ORFMOS MPS / INSTALLER OXML INTEGRATION v0.1 — RUNTIME PATCH
# ========================================================================================================
#
# Upgrades existing resident Home/Installer semantics without replacing Home:
#
#   APK profiler
#       -> AndroidManifest.xml
#       -> XML/AXML resolver
#       -> OXML
#       -> ORFMOS_EXECUTABLE_MANIFEST_V0_1
#
#   MPS INSTALL
#       LOCATE -> READ -> VALIDATE -> WRITE
#                          |
#                          +-> guest-stage integrity
#                          +-> OXML manifest semantics
#                          +-> contract preflight
#
# Android PackageManager remains WRITE realization provider only.
# This patch does not install anything on load.
# ========================================================================================================

INTEGRATION_SCHEMA = "ORFMOS_MPS_OXML_INSTALLER_INTEGRATION_V0_1"
INTEGRATION_REVISION = "MPS_OXML_V0_2_R85_PROFILE_MANIFEST_VALIDATE_BINDING"

_REQUIRED_CALLABLES = (
    "_home_profile_apk_bytes",
    "_home_installer_manifest_from_apk",
    "_home_mps_guest_stage_apk",
    "_orfmos_oxml_convert",
    "_orfmos_mps_oxml_manifest_preflight",
)

for _name in _REQUIRED_CALLABLES:
    if not callable(globals().get(_name)):
        raise RuntimeError(f"MPS_OXML_REQUIRED_RESIDENT_CAPABILITY_MISSING:{_name}")


def _mox_utc():
    return datetime.now(timezone.utc).isoformat()


def _mox_copy(value):
    return json.loads(json.dumps(value, default=str))


def _mox_extract_manifest(apk_bytes):
    data = bytes(apk_bytes or b"")
    with zipfile.ZipFile(io.BytesIO(data), "r") as archive:
        try:
            return bytes(archive.read("AndroidManifest.xml"))
        except KeyError as exc:
            raise RuntimeError("APK_ANDROID_MANIFEST_MISSING") from exc


def _mox_contract_merge(profile_contracts, oxml_contracts):
    merged = []
    index = {}

    for item in list(profile_contracts or []):
        if not isinstance(item, dict):
            continue
        row = dict(item)
        contract = str(row.get("contract") or "").upper().strip()
        if not contract:
            continue
        index[contract] = len(merged)
        merged.append(row)

    for item in list(oxml_contracts or []):
        if not isinstance(item, dict):
            continue
        row = dict(item)
        contract = str(row.get("contract") or "").upper().strip()
        if not contract:
            continue

        # OXML is authoritative for manifest-derived semantics.
        normalized = {
            "contract": contract,
            "state": row.get("state"),
            "evidence": row.get("evidence"),
        }
        if contract in index:
            merged[index[contract]] = normalized
        else:
            index[contract] = len(merged)
            merged.append(normalized)

    return merged


def _mox_enrich_profile(profile, apk_bytes, *, provider, uri, identity, name):
    result = dict(profile or {})
    if result.get("status") != "READY":
        return result

    data = bytes(apk_bytes or b"")
    manifest_raw = _mox_extract_manifest(data)
    apk_sha = hashlib.sha256(data).hexdigest()

    converter = globals().get("_orfmos_oxml_convert")
    converted = converter(
        manifest_raw,
        name=name or ((result.get("file") or {}).get("name")) or "selected.apk",
        source_provider=provider,
        source_uri=uri,
        source_identity=identity,
        source_container="APK",
        container_sha256=apk_sha,
        container_bytes=len(data),
        include_oxml_text=False,
    )

    executable_manifest = _mox_copy(converted.get("executable_manifest") or {})
    identity_block = executable_manifest.get("identity") or {}
    declared = executable_manifest.get("declared_manifest") or {}
    oxml = converted.get("oxml") or {}

    manifest = dict(result.get("manifest") or {})
    manifest.update({
        "decode_state": "OXML_RESOLVED",
        "semantics_state": "READY",
        "package_identity": identity_block.get("package_identity"),
        "version_code": identity_block.get("version_code"),
        "version_name": identity_block.get("version_name"),
        "sdk": _mox_copy(declared.get("sdk") or {}),
        "requested_permissions": _mox_copy(declared.get("requested_permissions") or []),
        "declared_permissions": _mox_copy(declared.get("declared_permissions") or []),
        "uses_features": _mox_copy(declared.get("uses_features") or []),
        "application": _mox_copy(declared.get("application") or {}),
        "components": _mox_copy(declared.get("components") or []),
        "launcher_components": _mox_copy(declared.get("launcher_components") or []),
        "oxml_schema": oxml.get("schema"),
        "oxml_sha256": oxml.get("sha256"),
        "oxml_bytes": oxml.get("bytes"),
        "executable_manifest_sha256": converted.get("executable_manifest_sha256"),
    })
    result["manifest"] = manifest

    result["contracts"] = _mox_contract_merge(
        result.get("contracts") or [],
        executable_manifest.get("observed_contracts") or [],
    )

    result["oxml"] = {
        "schema": oxml.get("schema"),
        "state": "READY",
        "sha256": oxml.get("sha256"),
        "bytes": oxml.get("bytes"),
        "roundtrip": _mox_copy(oxml.get("roundtrip") or {}),
        "executable_manifest": executable_manifest,
        "executable_manifest_sha256": converted.get("executable_manifest_sha256"),
        "android_vm_required": False,
    }

    limits = []
    for line in list(result.get("profile_limits") or []):
        if "Binary AndroidManifest.xml is detected but not decoded" in str(line):
            continue
        limits.append(line)
    limits.append(
        "AndroidManifest.xml is normalized through resident OXML; source XML/AXML encoding is not exposed as an MPS package-state dependency."
    )
    result["profile_limits"] = limits
    result["manifest_normalization"] = {
        "provider": "ORFMOS",
        "service": "OXML",
        "intent": "CONVERT",
        "state": "READY",
        "android_vm_required": False,
    }
