def _home_r90_12_verify_required_durable_dependencies():
    verified = []
    failures = []
    staged_exec = {}
    for spec in sorted(ORFMOS_R90_12_REQUIRED_DURABLE_ARTIFACTS, key=lambda row: int(row.get("order") or 0)):
        observed = {
            "id": spec["id"],
            "role": spec["role"],
            "drive_file_id": spec["drive_file_id"],
            "name": spec["name"],
            "expected_bytes": int(spec["bytes"]),
            "expected_sha256": spec["sha256"],
            "execution": spec.get("execution", "NONE"),
        }
        try:
            raw = _home_drive_read_bytes(spec["drive_file_id"])
            observed["observed_bytes"] = len(raw)
            observed["observed_sha256"] = hashlib.sha256(raw).hexdigest()
            observed["bytes_match"] = len(raw) == int(spec["bytes"])
            observed["sha256_match"] = observed["observed_sha256"] == spec["sha256"]
            if not observed["bytes_match"]:
                raise RuntimeError("DURABLE_ARTIFACT_BYTES_MISMATCH")
            if not observed["sha256_match"]:
                raise RuntimeError("DURABLE_ARTIFACT_SHA256_MISMATCH")
            if str(spec.get("name") or "").lower().endswith(".py"):
                compile(raw, f"drive://{spec['drive_file_id']}/{spec['name']}", "exec")
                observed["compile"] = "PASS"
            if spec.get("execution") == "SHARED_GLOBALS":
                staged_exec[spec["id"]] = raw
            observed["state"] = "DURABLE_VERIFIED"
            verified.append(observed)
        except Exception as exc:
            observed["state"] = "RESIDENT_ONLY_BLOCKING"
            observed["error"] = f"{type(exc).__name__}: {exc}"
            failures.append(observed)

    state = "READY" if not failures else "BLOCKED"
    result = {
        "schema": ORFMOS_R90_12_DURABILITY_SCHEMA,
        "state": state,
        "required_count": len(ORFMOS_R90_12_REQUIRED_DURABLE_ARTIFACTS),
        "verified_count": len(verified),
        "failure_count": len(failures),
        "verified": verified,
        "failures": failures,
        "machine_authority": "DRIVE_FILE_ID_PLUS_SHA256",
        "verify_all_before_execute": True,
        "checked_utc": datetime.now(timezone.utc).isoformat(),
    }
    globals()["__ORFMOS_HOME_R90_12_DURABILITY_GATE__"] = dict(result)
    if failures:
        details = ",".join(row["id"] for row in failures)
        raise RuntimeError("REQUIRED_DURABLE_DEPENDENCY_BLOCKING:" + details)
    return result, staged_exec


def _home_r90_12_service_ready(spec):
    version_name = str(spec.get("ready_version_global") or "")
    state_name = str(spec.get("ready_state_global") or "")
    if not version_name or not state_name:
        return False
    if str(globals().get(version_name) or "") != str(spec.get("ready_version") or ""):
        return False
    state = globals().get(state_name)
    return isinstance(state, dict) and state.get("state") == "READY"


def _home_r90_12_hydrate_durable_services():
    verification, staged_exec = _home_r90_12_verify_required_durable_dependencies()
    app = globals().get("__ORFMOS_HOME_FASTAPI_APP__")
    if app is None or not hasattr(app, "add_api_route"):
        result = {
            "schema": ORFMOS_R90_12_SERVICE_HYDRATION_SCHEMA,
            "state": "VERIFIED_WAITING_FOR_HOME_APP",
            "verification": verification,
            "execution_order": list(ORFMOS_R90_12_RUNTIME_EXECUTION_ORDER),
            "write_authority": "NONE_ON_HYDRATION",
            "checked_utc": datetime.now(timezone.utc).isoformat(),
        }
        globals()["__ORFMOS_HOME_R90_12_DURABLE_SERVICE_HYDRATION__"] = result
        return result

    specs = {
        row["id"]: row
        for row in ORFMOS_R90_12_REQUIRED_DURABLE_ARTIFACTS
        if row.get("execution") == "SHARED_GLOBALS"
    }

    executed = []
    already_ready = []
    for dependency_id in ORFMOS_R90_12_RUNTIME_EXECUTION_ORDER:
        spec = specs[dependency_id]
        if _home_r90_12_service_ready(spec):
            already_ready.append(dependency_id)
            continue
        raw = staged_exec[dependency_id]
        exec(
            compile(raw, f"drive://{spec['drive_file_id']}/{spec['name']}", "exec"),
            globals(),
            globals(),
        )
        if not _home_r90_12_service_ready(spec):
            raise RuntimeError("DURABLE_SERVICE_DID_NOT_REACH_READY:" + dependency_id)
        executed.append(dependency_id)

    result = {
        "schema": ORFMOS_R90_12_SERVICE_HYDRATION_SCHEMA,
        "state": "READY",
        "verification": verification,
        "execution_order": list(ORFMOS_R90_12_RUNTIME_EXECUTION_ORDER),
        "executed": executed,
        "already_ready": already_ready,
        "write_authority": "NONE_ON_HYDRATION",
        "loader_semantics": "exec(compile(...), globals(), globals())",
        "verify_all_before_execute": True,
        "completed_utc": datetime.now(timezone.utc).isoformat(),
    }
    globals()["__ORFMOS_HOME_R90_12_DURABLE_SERVICE_HYDRATION__"] = result
    return result


def _home_r90_12_preflight_durable_folder(create=True):
    parent_id = _home_runtime_recovery_development_parent_id()
    existing = _home_runtime_recovery_find_named_child(
        parent_id,
        ORFMOS_PREFLIGHT_DURABLE_ARTIFACT_FOLDER_NAME,
    )
    if existing:
        return str(existing.get("id") or "")
    if not create:
        return ""
    return str(
        _home_drive_ensure_folder(parent_id, ORFMOS_PREFLIGHT_DURABLE_ARTIFACT_FOLDER_NAME)
        or ""
    )


def _home_r90_12_materialize_preflight_record(record, raw):
    record = dict(record or {})
    raw = bytes(raw or b"")
    sha = str(record.get("sha256") or "").lower()
    expected_bytes = int(record.get("bytes") or 0)
    if not re.fullmatch(r"[0-9a-f]{64}", sha):
        raise RuntimeError("PREFLIGHT_DURABLE_SHA_REQUIRED")
    if hashlib.sha256(raw).hexdigest() != sha or len(raw) != expected_bytes:
        raise RuntimeError("PREFLIGHT_DURABLE_SOURCE_IDENTITY_MISMATCH")

    folder_id = _home_r90_12_preflight_durable_folder(create=True)
    if not folder_id:
        raise RuntimeError("PREFLIGHT_DURABLE_FOLDER_UNRESOLVED")

    safe_name = os.path.basename(str(record.get("name") or "artifact.bin"))
    artifact_name = f"{sha}__{safe_name}"
    existing_exact = None

    for item in _home_drive_list_children(folder_id):
        if str(item.get("mimeType") or "") == ORFMOS_DRIVE_FOLDER_MIME:
            continue
        name = str(item.get("name") or "")
        if name != artifact_name and not name.startswith(sha + "__"):
            continue
        file_id = str(item.get("id") or "")
        if not file_id:
            continue
        candidate = _home_drive_read_bytes(file_id)
        candidate_sha = hashlib.sha256(candidate).hexdigest()
        if candidate_sha == sha and len(candidate) == expected_bytes and candidate == raw:
            existing_exact = {
                "drive_file_id": file_id,
                "name": name,
                "bytes": len(candidate),
                "sha256": candidate_sha,
                "write_state": "ALREADY_PRESENT",
                "readback_verified": True,
            }
            break
        if name == artifact_name:
            raise RuntimeError("PREFLIGHT_DURABLE_HASH_NAME_COLLISION")

    if existing_exact:
        return existing_exact

    created = _home_drive_upsert_bytes(
        folder_id,
        artifact_name,
        raw,
        str(record.get("mime_type") or "application/octet-stream"),
    )
    artifact_id = _home_runtime_recovery_resolve_written_id(folder_id, artifact_name, created)
    if not artifact_id:
        raise RuntimeError("PREFLIGHT_DURABLE_CREATED_ID_UNRESOLVED")
    readback = _home_drive_read_bytes(artifact_id)
    if readback != raw:
        raise RuntimeError("PREFLIGHT_DURABLE_READBACK_BYTES_MISMATCH")
    observed_sha = hashlib.sha256(readback).hexdigest()
    if observed_sha != sha:
        raise RuntimeError("PREFLIGHT_DURABLE_READBACK_SHA_MISMATCH")
    return {
        "drive_file_id": artifact_id,
        "name": artifact_name,
        "bytes": len(readback),
        "sha256": observed_sha,
        "write_state": "CREATED",
        "readback_verified": True,
    }


# Wrap Preflight staging. Required Python execution targets gain a durable SHA object immediately.
__ORFMOS_HOME_R90_12_ORIGINAL_PREFLIGHT_STAGE_BYTES__ = _home_preflight_stage_bytes
def _home_preflight_stage_bytes(data, *, name="", mime_type="", source="DEVICE_LOCAL"):
    record = __ORFMOS_HOME_R90_12_ORIGINAL_PREFLIGHT_STAGE_BYTES__(
        data,
        name=name,
        mime_type=mime_type,
        source=source,
    )
    classification = str(record.get("classification") or "")
    record["durability_required"] = classification in {"SOURCE_STAGED", "PYTHON_STAGED"}
    record["durability_state"] = "OPTIONAL_RUNTIME_ONLY"
    if record["durability_required"]:
        try:
            durable = _home_r90_12_materialize_preflight_record(record, bytes(data or b""))
            record["durability_state"] = "DURABLE_VERIFIED"
            record["durable_artifact"] = durable
        except Exception as exc:
            record["durability_state"] = "RESIDENT_ONLY_BLOCKING"
            record["durability_error"] = f"{type(exc).__name__}: {exc}"
    with _ORFMOS_PREFLIGHT_LOCK:
        _home_preflight_stage_registry()[record["sha256"]] = dict(record)
    globals()["__ORFMOS_PREFLIGHT_LAST_STAGED__"] = dict(record)
    return json.loads(json.dumps(record, default=str))


# Wrap execution. A required runnable artifact can never execute from resident-only bytes.
__ORFMOS_HOME_R90_12_ORIGINAL_PREFLIGHT_EXECUTE_HTTP__ = _home_preflight_execute_http
def _home_preflight_execute_http(sha256: str = "", confirm_source: str = ""):
    record, raw = _home_preflight_lookup(sha256)
    classification = str(record.get("classification") or "")
    if classification in {"SOURCE_STAGED", "PYTHON_STAGED"}:
        try:
            durable = _home_r90_12_materialize_preflight_record(record, raw)
            record["durability_required"] = True
            record["durability_state"] = "DURABLE_VERIFIED"
            record["durable_artifact"] = durable
            record.pop("durability_error", None)
            with _ORFMOS_PREFLIGHT_LOCK:
                _home_preflight_stage_registry()[record["sha256"]] = dict(record)
        except Exception as exc:
            error = f"{type(exc).__name__}: {exc}"
            record["durability_required"] = True
            record["durability_state"] = "RESIDENT_ONLY_BLOCKING"
            record["durability_error"] = error
            with _ORFMOS_PREFLIGHT_LOCK:
                _home_preflight_stage_registry()[record["sha256"]] = dict(record)
            result = {
                "schema": ORFMOS_PREFLIGHT_SCHEMA,
                "state": "RESIDENT_ONLY_BLOCKING",
                "classification": classification,
                "name": record.get("name"),
                "bytes": record.get("bytes"),
                "sha256": record.get("sha256"),
                "durability_state": "RESIDENT_ONLY_BLOCKING",
                "durability_error": error,
                "execution_mode": ORFMOS_PREFLIGHT_EXECUTION_MODE,
                "executed": False,
                "message": "REQUIRED PYTHON ARTIFACT WAS NOT DURABLY MATERIALIZED; EXECUTION FORBIDDEN",
                "completed_utc": datetime.now(timezone.utc).isoformat(),
            }
            globals()["__ORFMOS_PREFLIGHT_LAST_EXECUTION__"] = dict(result)
            return result
    result = __ORFMOS_HOME_R90_12_ORIGINAL_PREFLIGHT_EXECUTE_HTTP__(
        sha256=sha256,
        confirm_source=confirm_source,
    )
    # The execution envelope itself is also durable evidence. It contains bounded
    # stdout/stderr and verification-report summaries, but never provider secrets
    # by contract; callers remain responsible for not printing secrets.
    try:
        report_raw = (
            json.dumps(result, sort_keys=True, indent=2, default=str, ensure_ascii=False) + "\n"
        ).encode("utf-8")
        report_sha = hashlib.sha256(report_raw).hexdigest()
        report_record = {
            "schema": ORFMOS_PREFLIGHT_SCHEMA,
            "state": "STAGED",
            "classification": "DATA_STAGED",
            "name": f"ORFMOS_PREFLIGHT_EXECUTION_{str(record.get('sha256') or '')[:16]}.json",
            "mime_type": "application/json",
            "bytes": len(report_raw),
            "sha256": report_sha,
        }
        result = dict(result or {})
        result["durable_execution_report"] = _home_r90_12_materialize_preflight_record(
            report_record,
            report_raw,
        )
        globals()["__ORFMOS_PREFLIGHT_LAST_EXECUTION__"] = dict(result)
    except Exception as exc:
        result = dict(result or {})
        result["durable_execution_report"] = {
            "state": "RESIDENT_ONLY_BLOCKING",
            "error": f"{type(exc).__name__}: {exc}",
        }
        globals()["__ORFMOS_PREFLIGHT_LAST_EXECUTION__"] = dict(result)
    return result


