# Hydrate all recovered required runtime services only after ALL source/verifier identities pass.
__ORFMOS_HOME_R90_12_ORIGINAL_LAUNCH__ = orfmos_home_launch
def orfmos_home_launch():
    record = __ORFMOS_HOME_R90_12_ORIGINAL_LAUNCH__()
    hydration = _home_r90_12_hydrate_durable_services()
    if hydration.get("state") != "READY":
        raise RuntimeError("HOME_REQUIRED_DURABLE_SERVICE_HYDRATION_NOT_READY")
    try:
        _home_r85_rebind_active_routes()
    except Exception:
        pass
    record = dict(record or {})
    record["durable_services"] = {
        "state": hydration.get("state"),
        "executed": list(hydration.get("executed") or []),
        "already_ready": list(hydration.get("already_ready") or []),
        "verify_all_before_execute": True,
    }
    globals()["__ORFMOS_HOME_ACTIVE__"] = record
    return record
globals()["orfmos_home_launch"] = orfmos_home_launch


