# R90.13 — PUBLISHER CURRENT-HOME APP REBIND GATE
#
# Corrective successor to R90.12 runtime verification failure.
# R90.12 proved durability/materialization/service recovery but exposed stale READY state:
# the recovered GitHub Publisher could remain marked READY while its routes were bound to an older
# Home FastAPI app. R90.13 makes current-app route ownership part of Publisher readiness.
# ====================================================================================================

ORFMOS_HOME_R90_13_IMMEDIATE_PARENT = {
    "name": "050_ORFMOS_HOME_DESKTOP_V0_2_93_R90_12_DURABLE_PREFLIGHT_SERVICE_HYDRATION_ANDROID_ZIP_COMPATIBILITY.py",
    "bytes": 942951,
    "sha256": "b5cefd735da1a31cc56214e407561cc820ed939687c6442b24af3f6ecc42ebe2",
    "revision": "R90_12_DURABLE_PREFLIGHT_SERVICE_HYDRATION_ANDROID_ZIP_COMPATIBILITY",
    "verification_state": "FAIL_PUBLISHER_ROUTES_BOUND",
    "selector_advanced": False,
}

ORFMOS_HOME_R90_13_PUBLISHER_REQUIRED_ROUTES = (
    "/orfmos/github-publisher/state",
    "/orfmos/github-publisher/stage-package",
    "/orfmos/github-publisher/verify-files",
    "/orfmos/github-publisher/arm-credential",
    "/orfmos/github-publisher/disarm-credential",
    "/orfmos/github-publisher/preflight",
    "/orfmos/github-publisher/publish",
)


def _home_r90_13_current_home_app_paths():
    app = globals().get("__ORFMOS_HOME_FASTAPI_APP__")
    routes = getattr(getattr(app, "router", None), "routes", None)
    if not isinstance(routes, list):
        return set()
    return {
        str(getattr(route, "path", "") or "")
        for route in routes
    }


def _home_r90_13_publisher_bound_to_current_home_app():
    state = globals().get("ORFMOS_GITHUB_PUBLISHER_RUNTIME_SERVICE_STATE")
    if not isinstance(state, dict) or state.get("state") != "READY":
        return False
    paths = _home_r90_13_current_home_app_paths()
    return all(
        route in paths
        for route in ORFMOS_HOME_R90_13_PUBLISHER_REQUIRED_ROUTES
    )


__ORFMOS_HOME_R90_13_PARENT_SERVICE_READY__ = _home_r90_12_service_ready


def _home_r90_13_service_ready(spec):
    version_name = str(spec.get("ready_version_global") or "")
    state_name = str(spec.get("ready_state_global") or "")
    if not version_name or not state_name:
        return False
    if str(globals().get(version_name) or "") != str(spec.get("ready_version") or ""):
        return False
    state = globals().get(state_name)
    if not isinstance(state, dict) or state.get("state") != "READY":
        return False

    # A Publisher READY flag is insufficient: routes must belong to the CURRENT Home app.
    if str(spec.get("id") or "") == "GITHUB_PUBLISHER_SERVICE":
        return _home_r90_13_publisher_bound_to_current_home_app()

    return True


# The existing durable hydrator resolves this name dynamically, so the stronger
# readiness contract is inherited without duplicating the verified R90.12 loader.
_home_r90_12_service_ready = _home_r90_13_service_ready


def _home_r90_13_rebind_required_services_to_current_home_app():
    result = _home_r90_12_hydrate_durable_services()
    if result.get("state") != "READY":
        raise RuntimeError("R90_13_DURABLE_SERVICE_HYDRATION_NOT_READY")
    if not _home_r90_13_publisher_bound_to_current_home_app():
        raise RuntimeError("R90_13_PUBLISHER_NOT_BOUND_TO_CURRENT_HOME_APP")
    return {
        "schema": "ORFMOS_HOME_R90_13_CURRENT_APP_SERVICE_BINDING_V0_1",
        "state": "READY",
        "publisher_bound_to_current_home_app": True,
        "publisher_routes": sorted(ORFMOS_HOME_R90_13_PUBLISHER_REQUIRED_ROUTES),
        "hydration": result,
        "machine_authority": "DRIVE_FILE_ID_PLUS_SHA256",
        "write_authority": "NONE_ON_HYDRATION",
        "completed_utc": datetime.now(timezone.utc).isoformat(),
    }


try:
    _r90_13_current_app_binding = _home_r90_13_rebind_required_services_to_current_home_app()
except Exception as exc:
    _r90_13_current_app_binding = {
        "schema": "ORFMOS_HOME_R90_13_CURRENT_APP_SERVICE_BINDING_V0_1",
        "state": "BLOCKED",
        "publisher_bound_to_current_home_app": False,
        "error": f"{type(exc).__name__}: {exc}",
        "write_authority": "NONE_ON_HYDRATION",
        "completed_utc": datetime.now(timezone.utc).isoformat(),
    }

globals()["__ORFMOS_HOME_R90_13_CURRENT_APP_SERVICE_BINDING__"] = dict(_r90_13_current_app_binding)

ORFMOS_HOME_MODULE_STATE["presentation_generation"] = ORFMOS_HOME_PRESENTATION_GENERATION
ORFMOS_HOME_MODULE_STATE["revision"] = "R90_13_PUBLISHER_CURRENT_HOME_APP_REBIND_GATE"
